function asyncReduce(arr, initialValue, callback, cb) {
  if (!Array.isArray(arr)) {
    return cb(new Error('Input must be an array'));
  }

  let result = initialValue;
  let processedCount = 0;

  function processNext() {
    if (processedCount >= arr.length) {
      return cb(null, result);
    }

    const currentNumber = arr[processedCount];
    callback(result, currentNumber, (err, value) => {
      if (err) {
        return cb(err);
      }
      result = value;
      processedCount++;
      processNext();
    });
  }

  if (arr.length === 0) {
    return cb(null, initialValue);
  }

  processNext();
}

// Example usage:
asyncReduce([1, 2, 3, 4], 0, (accumulator, number) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(accumulator + number);
    }, 100); // Simulate async operation
  });
}, (err, result) => {
  if (err) {
    console.error('Error:', err.message);
  } else {
    console.log('Result:', result); // Output: 10
  }
});
