function renderFooterScripts(scriptObjects) {
  const cache = {};

  function fetchScript(url) {
    if (cache[url]) return Promise.resolve(cache[url]);
    return fetch(url)
      .then(response => response.text())
      .then(text => {
        cache[url] = text;
        return text;
      })
      .catch(error => {
        console.error(`Failed to load script from ${url}:`, error);
        throw error;
      });
  }

  function renderScript(scriptObject) {
    if (!scriptObject.src && !scriptObject.code) {
      throw new Error('Script object must contain either src or code');
    }
    if (scriptObject.src) {
      return `<script type="${scriptObject.type}" key="${scriptObject.key}" src="${scriptObject.src}"></script>`;
    } else {
      return scriptObject.code;
    }
  }

  async function renderScripts() {
    const renderedScripts = await Promise.all(
      scriptObjects.map(async (script, index) => {
        if (script.src && script.cacheBust) {
          script.src += `?t=${Date.now()}`;
        }
        try {
          if (script.src) {
            return `<script type="${script.type}" key="${script.key}">${await fetchScript(script.src)}</script>`;
          } else {
            return renderScript(script);
          }
        } catch (error) {
          console.error(`Error rendering script ${index + 1}:`, error);
          return '';
        }
      })
    );
    return renderedScripts.join('\n');
  }

  return renderScripts();
}

// Example usage
const scripts = [
  { src: 'https://external-script.com/script.js', type: 'text/javascript', key: 'external-script' },
  { code: '<script>alert("Hello World!");</script>', type: 'text/javascript', key: 'inline-script' }
];

console.log(renderFooterScripts(scripts));
