<?php

class ClinicService {
    private $db;
    private static $lastUpdateIp = [];
    private static $lastUpdateTime = [];

    public function __construct($database) {
        $this->db = $database;
    }

    public function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
        $currentTime = date('Y-m-d H:i:s');
        $logMessage = "Clinic {$clinicId} status updated to {$newStatus}";

        if ($this->isRateLimited($ipAddress)) {
            return ['error' => 'Too many updates from this IP address. Please try again later.'];
        }

        try {
            $this->db->beginTransaction();

            $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?");
            $stmt->execute([$newStatus, $ipAddress, $currentTime, $clinicId]);

            if ($stmt->rowCount() > 0) {
                $logStmt = $this->db->prepare("INSERT INTO clinic_logs (message, timestamp) VALUES (?, ?)");
                $logStmt->execute([$logMessage, $currentTime]);

                if ($newStatus === 'closed' || $newStatus === 'emergency') {
                    $apiResponse = $this->notifyApiService($clinicId, $newStatus);
                    if ($apiResponse !== true) {
                        throw new Exception("API service error: " . json_encode($apiResponse));
                    }
                }

                self::$lastUpdateIp[$ipAddress] = time();
                self::$lastUpdateTime[$ipAddress] = $currentTime;

                $this->db->commit();
                return ['success' => 'Clinic status updated successfully.'];
            } else {
                throw new Exception("No clinic found with id {$clinicId}");
            }
        } catch (Exception $e) {
            $this->db->rollBack();
            return ['error' => $e->getMessage()];
        }
    }

    private function isRateLimited($ipAddress) {
        if (!isset(self::$lastUpdateIp[$ipAddress])) {
            return false;
        }

        $timeSinceLastUpdate = time() - self::$lastUpdateTime[$ipAddress];
        return $timeSinceLastUpdate < 3600; // Limit to once per hour
    }

    private function notifyApiService($clinicId, $status) {
        $apiUrl = "https://example.com/api/notify";
        $data = [
            'clinic_id' => $clinicId,
            'new_status' => $status
        ];

        try {
            $options = [
                'http' => [
                    'header'  => "Content-type: application/json\r\n",
                    'method'  => 'POST',
                    'content' => json_encode($data)
                ]
            ];
            $context  = stream_context_create($options);
            $result = file_get_contents($apiUrl, false, $context);

            if ($result === FALSE) {
                return ['error' => 'Failed to connect to API service'];
            }

            $response = json_decode($result, true);
            return $response;
        } catch (Exception $e) {
            return ['error' => 'API service exception: ' . $e->getMessage()];
        }
    }
}
