use std::fs;
use std::time::{Instant, Duration};
use std::process::{Command, Stdio};
use log::{info, error, set_max_level, LevelFilter};
use rustc_driver::{self, Compilation};
use libc;

fn get_resident_set_size() -> u64 {
    unsafe {
        let mut rusage: libc.rusage = std::mem::zeroed();
        if libc.getrusage(libc.RUSAGE_SELF, &mut rusage) == 0 {
            return rusage.ru_maxrss as u64 * libc.sysconf(libc._SC_PAGE_SIZE) as u64 / 1024;
        }
    }
    0
}

fn compile_rust_files_in_directory(dir_path: &str) -> Result<String, String> {
    let start_time = Instant::now();
    set_max_level(LevelFilter::Info);

    rustc_driver::catch_with_error(|| {
        let mut cfg = rustc_interface::Config::default();
        cfg.input = rustc_interface::Input::File(PathBuf::from("main.rs"));
        cfg.emit_output();

        let (result, output) = rustc_driver::run_compiler(
            &["--crate-type", "bin"],
            &cfg,
            None,
            |cx| Compilation::ToBeEvaluated(cx.to_session()),
            None,
        )?;

        match result {
            rustc_driver::CompilerExitCode::ExplainError => Err(format!("Compilation failed")),
            _ => Ok(()),
        }
    });

    let total_time = start_time.elapsed();
    let peak_memory_usage = get_resident_set_size();

    info!("Total compilation time: {:?}", total_time);
    info!("Peak memory usage: {} KB", peak_memory_usage);

    // Simulate remote build server API interaction
    let summary = format!("Compilation completed successfully in {:?}. Peak memory usage: {} KB.", total_time, peak_memory_usage);
    Ok(summary)
}
