<?php

class PasswordManager {
    private $hashedPassword;
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()';
    private $saltRoundCount = 12;

    public function generateRandomString($length) {
        if ($length < 1) {
            throw new InvalidArgumentException("Length must be greater than 0.");
        }
        $charactersLength = strlen($this->characterSet);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[random_int(0, $charactersLength - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        if (!$this->validateCharacterSet($this->characterSet)) {
            throw new Exception("Invalid character set. Must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.");
        }
        $salt = password_hash($this->generateRandomString(16), PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        $this->hashedPassword = password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        if (!$this->validateCharacterSet($this->characterSet)) {
            throw new Exception("Invalid character set. Must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.");
        }
        return password_verify($password . substr($this->hashedPassword, 0, 16), $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (preg_match('/[A-Z]/', $characterSet) && preg_match('/[a-z]/', $characterSet) && preg_match('/\d/', $characterSet) && preg_match('/[!@#$%^&*()]/', $characterSet)) {
            return true;
        }
        return false;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 4 || $rounds > 31) {
            throw new InvalidArgumentException("Salt round count must be between 4 and 31.");
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $this->hashPassword($this->generateRandomString(8));
    }
}

?>
