use std::env;
use std::fs::{self, DirEntry};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

struct DirectoryManager {
    lock: Arc<Mutex<()>>,
}

impl DirectoryManager {
    fn new() -> Self {
        DirectoryManager {
            lock: Arc::new(Mutex::new(())),
        }
    }

    fn manage_directory(&self, name: &str) -> Result<(), String> {
        let _lock = self.lock.lock().map_err(|_| "Failed to acquire lock")?;

        if let Ok(Some(path)) = env::var_os(name) {
            if Path::new(&path).exists() {
                return Ok(());
            }
        }

        let dir_path = format!("/tmp/{}", name);
        fs::create_dir_all(&dir_path)
            .map_err(|e| format!("Failed to create directory: {}", e))?;

        env::set_var(name, &dir_path)
            .map_err(|e| format!("Failed to set environment variable: {}", e))?;

        Ok(())
    }

    fn clean_old_directories(&self) {
        let _lock = self.lock.lock().unwrap();

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|_| "Failed to get current time")
            .unwrap_or_default();

        env::var_os("DIR_ENV_NAME").and_then(|env_var| {
            Path::new(&env_var).read_dir().ok()?.filter_map(|entry| {
                entry.ok()
            }).fold(None, |youngest, entry: DirEntry| {
                if let Ok(metadata) = entry.metadata() {
                    let metadata_time = metadata
                        .modified()
                        .map_err(|_| "Failed to get file metadata")
                        .unwrap_or_default();

                    if youngest.is_none() || metadata_time < now - 86400 {
                        return Some(entry.path());
                    }
                }

                youngest
            })
        }).and_then(|path| fs::remove_dir_all(&path).map_err(|e| format!("Failed to remove directory: {}", e)));

        Ok(())
    }
}

fn main() {
    let manager = DirectoryManager::new();

    manager.manage_directory("MY_DIR").unwrap();
    manager.clean_old_directories();
}
