use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use rayon::prelude::*;

fn generate_llvm_ir(directory: &str, optimize: bool) -> Result<(), Box<dyn std::error::Error>> {
    let mut paths = Vec::new();

    // Function to recursively find all .rs files
    fn find_rs_files(path: &Path, paths: &mut Vec<PathBuf>) {
        if path.is_dir() {
            for entry in fs::read_dir(path)? {
                let entry_path = entry?.path();
                find_rs_files(&entry_path, paths);
            }
        } else if path.extension().and_then(|ext| ext.to_str()) == Some("rs") {
            paths.push(path);
        }
    }

    // Find all .rs files in the given directory
    find_rs_files(Path::new(directory), &mut paths);

    let mut handles = Vec::new();

    for path in paths {
        let path = Arc::new(path);
        let optimize = optimize;

        handles.push(std::thread::spawn(move || {
            process_file(&path, optimize);
        }));
    }

    // Wait for all threads to finish
    for handle in handles {
        handle.join().expect("Thread panicked");
    }

    Ok(())
}

fn process_file(file_path: &Path, optimize: bool) {
    match fs::read_to_string(file_path) {
