#include <string.h>
#include <ctype.h>

char* trimAndCapitalize(const char* input, int limit, const char** wordsToRemove, int numWords) {
    if (input == NULL || limit < 0 || wordsToRemove == NULL || numWords < 0) {
        return NULL; // Invalid input
    }

    // Trim specified words from the beginning and end of the string
    char* trimmed = strdup(input);
    char* start = trimmed;
    char* end = trimmed + strlen(trimmed) - 1;

    for (int i = 0; i < numWords; ++i) {
        if (strncmp(start, wordsToRemove[i], strlen(wordsToRemove[i])) == 0) {
            start += strlen(wordsToRemove[i]);
        }
        if (end > trimmed && strncmp(end - strlen(wordsToRemove[i]), wordsToRemove[i], strlen(wordsToRemove[i])) == 0) {
            *end = '\0';
            end -= strlen(wordsToRemove[i]);
        }
    }

    // Check if the resulting string is within the size limit
    if ((int)(end - start + 1) > limit) {
        free(trimmed);
        return NULL; // Resulting string exceeds limit
    }

    // Capitalize the first letter of each word in the trimmed string
    char* result = (char*)malloc((end - start + 2) * sizeof(char));
    if (result == NULL) {
        free(trimmed);
        return NULL; // Memory allocation failed
    }

    int index = 0;
    while (*start != '\0') {
        while (*start != '\0' && isspace(*start)) {
            ++start;
        }
        char* wordStart = start;
        while (*end != '\0' && !isspace(*end)) {
            --end;
        }

        if (wordStart <= end) {
            result[index++] = toupper(*wordStart);
            for (char* p = wordStart + 1; p <= end; ++p) {
                result[index++] = *p;
            }
            result[index++] = ' ';
        } else {
            break; // No more words to process
        }

        start = end + 2; // Move past the space
    }
    result[index - 1] = '\0'; // Null-terminate the resulting string

    free(trimmed);
    return result;
}
