#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define SEM_NAME_LEN 256

typedef struct {
    sem_t *sem;
    char name[SEM_NAME_LEN];
} Semaphore;

Semaphore* create_semaphore(const char* name, unsigned int initial_value) {
    Semaphore *sem = malloc(sizeof(Semaphore));
    if (!sem) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }

    sem->sem = sem_open(name, O_CREAT, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to open semaphore");
        free(sem);
        return NULL;
    }
    strncpy(sem->name, name, SEM_NAME_LEN - 1);

    printf("Semaphore created: %s\n", sem->name);
    return sem;
}

int delete_semaphore(Semaphore *sem) {
    if (sem_close(sem->sem)) {
        perror("Failed to close semaphore");
        return -1;
    }
    if (sem_unlink(sem->name)) {
        perror("Failed to unlink semaphore");
        return -1;
    }
    free(sem);
    printf("Semaphore deleted: %s\n", sem->name);
    return 0;
}

int increment_semaphore(Semaphore *sem) {
    if (sem_post(sem->sem)) {
        perror("Failed to increment semaphore");
        return -1;
    }
    printf("Semaphore incremented: %s\n", sem->name);
    return 0;
}

int decrement_semaphore(Semaphore *sem) {
    if (sem_wait(sem->sem)) {
        perror("Failed to decrement semaphore");
        return -1;
    }
    printf("Semaphore decremented: %s\n", sem->name);
    return 0;
}
