import hashlib
from collections import namedtuple

HashFunction = namedtuple('HashFunction', ['name', 'function'])

def is_hash_available(hash_function):
    try:
        hashlib.new(hash_function)
        return True
    except ValueError:
        return False

def process_file(file_path):
    hash_functions = []
    max_sequence_number = 0

    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            lines.sort()

            for line in lines:
                sequence_number, name = line.strip().split(' ', 1)
                if is_hash_available(name):
                    hash_functions.append(HashFunction(name, hashlib.new))
                    max_sequence_number = int(sequence_number)

    except FileNotFoundError:
        print(f"Error: File '{file_path}' not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

    return hash_functions, max_sequence_number

# Example usage
hash_functions, max_sequence_number = process_file('crypto_functions.txt')
for func in hash_functions:
    print(func)
print(f"Max sequence number: {max_sequence_number}")
