#define CONFIG_FILE "crypto_primitives.conf"

typedef struct {
    const EVP_CIPHER *cipher;
    const EVP_MD *digest;
} CryptoPrimitive;

static CryptoPrimitive supported_primitives[] = {
    {EVP_aes_256_cbc(), NULL},
    {EVP_camellia_128_ecb(), NULL},
    {NULL, EVP_md5()},
    {NULL, EVP_sha256()}
};

static int initialized = 0;
static pthread_mutex_t init_lock = PTHREAD_MUTEX_INITIALIZER;

void add_crypto_primitives() {
    if (initialized) return;
    pthread_mutex_lock(&init_lock);

    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        fprintf(stderr, "Failed to open configuration file: %s\n", CONFIG_FILE);
        goto cleanup;
    }

    char line[256];
    while (fgets(line, sizeof(line), config_file)) {
        // Parse the line and add the corresponding cipher or digest
        // ...
    }
    fclose(config_file);

    for (size_t i = 0; supported_primitives[i].cipher != NULL || supported_primitives[i].digest != NULL; i++) {
        if (supported_primitives[i].cipher) {
            EVP_add_cipher(supported_primitives[i].cipher);
        } else if (supported_primitives[i].digest) {
            EVP_add_digest(supported_primitives[i].digest);
            if (strcmp("sha1", EVP_MD_name(supported_primitives[i].digest)) == 0) {
                EVP_add_digest_alias("sha1", "SHA-1");
            }
        }
    }

cleanup:
    initialized = 1;
    pthread_mutex_unlock(&init_lock);
}

void *crypto_thread_func(void *arg) {
    add_crypto_primitives();
    // Continue with the rest of the thread's functionality
    return NULL;
}

int main() {
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, crypto_thread_func, NULL) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
