use std::env;
use std::fs;

#[no_mangle]
pub extern "C" fn create_directory_and_set_env_var(dir_name: *const u8) {
    unsafe {
        let name = String::from_utf8_lossy(CStr::from_ptr(dir_name).to_bytes()).into_owned();
        if env::var(name.clone()).is_err() {
            fs::create_dir(&name).expect("Failed to create directory");
            env::set_var(name, &name);
        } else {
            println!("Environment variable already set for directory: {}", name);
        }
    }
}
