import java.io.IOException;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.TimeUnit;

public class DisjointPairs {

    // Union-Find data structure implementation
    static class UF {
        int[] parent;
        int[] rank;

        public UF(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int p) {
            if (parent[p] != p) {
                parent[p] = find(parent[p]);
            }
            return parent[p];
        }

        void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);
            if (rootP == rootQ) return;

            if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }

        boolean areDisjoint(int p, int q) {
            return find(p) != find(q);
        }
    }

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5}; // Example input
        UF uf = new UF(array.length);

        Set<String> predefinedRules = new HashSet<>(); // Predefined rules from external API

        try {
            for (int i = 0; i < array.length - 1; i++) {
                long startTime = System.nanoTime();
                boolean disjoint = uf.areDisjoint(i, i + 1);
                long endTime = System.nanoTime();

                if (disjoint) {
                    predefinedRules.add(array[i] + "," + array[i + 1]);
                }

                System.out.println("Pair (" + array[i] + ", " + array[i + 1] + ") is disjoint: "
                        + disjoint + " Time taken: " + TimeUnit.NANOSECONDS.toMillis(endTime - startTime) + " ms");
            }
        } catch (Exception e) {
            System.err.println("Error occurred while checking pairs: " + e.getMessage());
        }

        // Call external API to verify the disjoint pairs
        try {
            verifyDisjointPairsWithAPI(predefinedRules);
        } catch (IOException e) {
            System.err.println("Network latency or API failure detected.");
        }
    }

    private static void verifyDisjointPairsWithAPI(Set<String> rules) throws IOException {
        // Simulated external API call
        for (String rule : rules) {
            // Simulate network latency and potential failures
            Thread.sleep(10);
            if (Math.random() < 0.5) {
                throw new IOException("API failure");
            }
        }

        System.out.println("All disjoint pairs verified successfully with external API.");
    }
}
