#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function prototype for fetching words from an external data source
int fetchWords(char ***words, int *wordCount);

char* dynamicTrimAndCapitalize(const char *input) {
    if (input == NULL) {
        return NULL;
    }

    char **words = NULL;
    int wordCount = 0;

    // Fetch words to be trimmed from the external data source
    int result = fetchWords(&words, &wordCount);
    if (result != 0 || wordCount <= 0) {
        free(words);
        return NULL;
    }

    // Calculate the average word length
    double avgWordLength = 0.0;
    for (int i = 0; i < wordCount; i++) {
        avgWordLength += strlen(words[i]);
    }
    avgWordLength /= wordCount;

    // Estimate the adjusted size limit based on the average word length
    int estimatedSizeLimit = strlen(input) - (2 * wordCount * (int)avgWordLength);

    // Allocate memory for the resulting string with a safety margin
    char *resultString = (char *)malloc((estimatedSizeLimit + 1) * sizeof(char));
    if (resultString == NULL) {
        free(words);
        return NULL;
    }

    // Trim the specified words from the beginning and end of the input string
    const char *start = input;
    while (*start != '\0' && strchr(words[0], *start)) {
        start++;
    }
    int endIndex = strlen(input) - 1;
    while (endIndex > 0 && strchr(words[wordCount - 1], input[endIndex])) {
        endIndex--;
    }

    // Copy the trimmed string to the resultString buffer
    strncpy(resultString, start, endIndex - startIndex + 2);
    resultString[endIndex - startIndex + 2] = '\0';

    // Capitalize the first letter of each word in the resulting string
    char *token = strtok(resultString, " ");
    while (token != NULL) {
        token[0] = toupper(token[0]);
        token = strtok(NULL, " ");
    }

    // Free allocated memory for words and resultString if necessary
    free(words);
    return resultString;
}
