```go
package main

import (
	"errors"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
)

// CacheConfig holds the configuration for the caching mechanism.
type CacheConfig struct {
	CacheDir string
	S3Bucket string
	S3Region string
}

// ImageCache is responsible for managing the caching of profile images.
type ImageCache struct {
	config *CacheConfig
	sess   *session.Session
	svc    *s3.S3
}

// NewImageCache initializes a new image cache with the provided configuration.
func NewImageCache(config *CacheConfig) (*ImageCache, error) {
	if config.CacheDir == "" || config.S3Bucket == "" || config.S3Region == "" {
		return nil, errors.New("cache directory, S3 bucket, and region are required")
	}

	sess, err := session.NewSession(&aws.Config{
		Region: aws.String(config.S3Region),
	})
	if err != nil {
		return nil, err
	}

	svc := s3.New(sess)

	return &ImageCache{
		config: config,
		sess:   sess,
		svc:    svc,
	}, nil
}

// GetProfileImage retrieves a profile image from the cache or downloads it if not present.
func (ic *ImageCache) GetProfileImage(userID string, imageName string) ([]byte, error) {
	cachedPath := filepath.Join(ic.config.CacheDir, userID, imageName)

	_, err := os.Stat(cachedPath)
	if !os.IsNotExist(err) {
		return ioutil.ReadFile(cachedPath)
	}

	url := fmt.Sprintf("https://%s.s3.%s.amazonaws.com/%s", ic.config.S3Bucket, ic.config.S3Region, imageName)
	resp, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, errors.New("failed to download image")
	}

	data, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}

	err = os.MkdirAll(filepath.Join(ic.config.CacheDir, userID), 0755)
	if err != nil {
		return nil, err
	}

	err = ioutil.WriteFile(cachedPath, data, 0644)
	if err != nil {
		return nil, err
	}

	return data, nil
}

// InvalidateImage removes an image from the cache.
func (ic *ImageCache) InvalidateImage(userID string, imageName string) error {
	cachedPath := filepath.Join(ic.config.CacheDir, userID, imageName)
	err := os.Remove(cachedPath)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

// RefreshCacheInvalidates invalidates the cache for all users upon application startup.
func (ic *ImageCache) RefreshCacheInvalidates() error {
	files, err := ioutil.ReadDir(ic.config.CacheDir)
	if err != nil {
		return err
	}

	for _, file := range files {
		if !file.IsDir() {
			userID := filepath.Base(file.Name())
			err := ic.InvalidateImage(userID, file.Name())
			if err != nil {
				return err
			}
		}
	}

	return nil
}

func main() {
	cacheConfig := &CacheConfig{
		CacheDir: "cache/profile_images",
		S3Bucket: "your-s3-bucket",
		S3Region: "your-s3-region",
	}

	imageCache, err := NewImageCache(cacheConfig)
	if err != nil {
		fmt.Println("Error creating image cache:", err)
		return
	}

	err = imageCache.RefreshCacheInvalidates()
	if err != nil {
		fmt.Println("Error refreshing cache invalidates:", err)
		return
	}

	userID := "user123"
	imageName := "profile.jpg"
	imageData, err := imageCache.GetProfileImage(userID, imageName)
	if err != nil {
		fmt.Println("Error getting profile image:", err)
		return
	}

	fmt.Println("Profile image retrieved successfully:", len(imageData))
}
```

