function runModuleTests(moduleLabel, testLabels, testFunctions) {
  const module = require(moduleLabel);

  async function runTest(testName, testFunction) {
    console.log(`Running test: ${testName}`);

    try {
      await testFunction(module);
      console.log(`${testName} passed.`);
    } catch (error) {
      console.error(`Error in ${testName}:`, error);
    }

    blueslip.reset(); // Reset mocking library after each test
  }

  async function runAllTests() {
    for (let i = 0; i < testLabels.length; i++) {
      await runTest(testLabels[i], testFunctions[i]);
    }

    console.log(`All tests completed.`);
  }

  runAllTests();
}
