```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>          
#include <sys/stat.h>        
#include <errno.h>

// Function to create or open a named semaphore
sem_t* create_or_open_semaphore(const char* name, int initial_value) {
    sem_t *sem = sem_open(name, O_CREAT | O_RDWR, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Error creating or opening semaphore");
        return NULL;
    }
    return sem;
}

// Function to delete a named semaphore
int delete_semaphore(sem_t* sem, const char* name) {
    int result = sem_close(sem);
    if (result != 0) {
        perror("Error closing semaphore");
        return -1;
    }

    result = sem_unlink(name);
    if (result != 0) {
        perror("Error unlinking semaphore");
        return -1;
    }
    return 0;
}

// Function to acquire the semaphore
int acquire_semaphore(sem_t* sem) {
    int result = sem_wait(sem);
    if (result == -1) {
        perror("Error acquiring semaphore");
        return -1;
    }
    return 0;
}

// Function to release the semaphore
int release_semaphore(sem_t* sem) {
    int result = sem_post(sem);
    if (result == -1) {
        perror("Error releasing semaphore");
        return -1;
    }
    return 0;
}

// Function to get current value of the semaphore
int get_semaphore_value(sem_t* sem) {
    int value;
    int result = sem_getvalue(sem, &value);
    if (result == -1) {
        perror("Error getting semaphore value");
        return -1;
    }
    return value;
}

// Example usage
int main() {
    const char* semaphore_name = "/my_semaphore";
    int initial_value = 5;

    sem_t* my_semaphore = create_or_open_semaphore(semaphore_name, initial_value);
    if (my_semaphore == NULL) {
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 10; i++) {
        if (acquire_semaphore(my_semaphore) == -1) {
            continue;
        }
        printf("Semaphore acquired by process %d\n", getpid());

        // Critical section
        sleep(1);

        if (release_semaphore(my_semaphore) == -1) {
            continue;
        }
    }

    int value = get_semaphore_value(my_semaphore);
    if (value != -1) {
        printf("Final semaphore value: %d\n", value);
    }

    delete_semaphore(my_semaphore, semaphore_name);

    return 0;
}
```

This code provides a basic implementation of a named semaphore with error handling and synchronization mechanisms. It includes functions for creating, deleting, acquiring, releasing, and checking the value of the semaphore. The example usage demonstrates how to use these functions in a multi-threaded scenario. Note that this is a simplified version and might need adjustments based on specific requirements and platform considerations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define QUEUE_CAPACITY 5

typedef struct {
    int *items;
    int front, rear, size;
    sem_t mutex, empty, full;
} ThreadSafeQueue;

ThreadSafeQueue queue;

void initQueue(int capacity) {
    queue.items = (int*)malloc(capacity * sizeof(int));
    if (!queue.items) {
        fprintf(stderr, "Failed to allocate memory for queue.\n");
        exit(EXIT_FAILURE);
    }
    queue.front = 0;
    queue.rear = -1;
    queue.size = 0;
    sem_init(&queue.mutex, 0, 1);
    sem_init(&queue.empty, 0, capacity);
    sem_init(&queue.full, 0, 0);
}

void enqueue(int item) {
    sem_wait(&queue.empty);
    sem_wait(&queue.mutex);
    queue.rear = (queue.rear + 1) % QUEUE_CAPACITY;
    queue.items[queue.rear] = item;
    queue.size++;
    printf("Enqueued: %d\n", item);
    sem_post(&queue.mutex);
    sem_post(&queue.full);
}

int dequeue() {
    int item;
    sem_wait(&queue.full);
    sem_wait(&queue.mutex);
    if (queue.size > 0) {
        item = queue.items[queue.front];
        queue.front = (queue.front + 1) % QUEUE_CAPACITY;
        queue.size--;
        printf("Dequeued: %d\n", item);
    } else {
        item = -1; // Queue is empty
    }
    sem_post(&queue.mutex);
    sem_post(&queue.empty);
    return item;
}

int isQueueEmpty() {
    int isEmpty;
    sem_wait(&queue.mutex);
    isEmpty = (queue.size == 0);
    sem_post(&queue.mutex);
    return isEmpty;
}

void *producer(void *arg) {
    int item = *(int*)arg;
    enqueue(item);
    pthread_exit(NULL);
}

void *consumer(void *arg) {
    int item = dequeue();
    if (item != -1) { // Queue was not empty
        // Process the item
    }
    pthread_exit(NULL);
}

void cleanUp() {
    sem_destroy(&queue.mutex);
    sem_destroy(&queue.empty);
    sem_destroy(&queue.full);
    free(queue.items);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <producer_count> <consumer_count> <stop_signal>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int producerCount = atoi(argv[1]);
    int consumerCount = atoi(argv[2]);
    int stopSignal = atoi(argv[3]);

    initQueue(QUEUE_CAPACITY);

    pthread_t producers[producerCount];
    pthread_t consumers[consumerCount];

    for (int i = 0; i < producerCount; i++) {
        int item = rand() % 100;
        pthread_create(&producers[i], NULL, producer, &item);
    }

    for (int i = 0; i < consumerCount; i++) {
        pthread_create(&consumers[i], NULL, consumer, NULL);
    }

    // Simulate running until stop signal
    while (1) {
        if (rand() % 100 == stopSignal) {
            break;
        }
        sleep(1); // Sleep to simulate work
    }

    for (int i = 0; i < producerCount; i++) {
        pthread_join(producers[i], NULL);
    }

    for (int i = 0; i < consumerCount; i++) {
        pthread_join(consumers[i], NULL);
    }

    cleanUp();

    return EXIT_SUCCESS;
}
