```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define N 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8;

typedef struct {
    RX_UE_INFORMATION rxue;
    CRC_INDICATION_REL8 crcind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

void log_message(const char* message) {
    printf("%s\n", message);
}

int generate_unique_crc_flag(List* list, int max_attempts) {
    srand(time(NULL));
    int crcflag;
    int attempts = 0;

    while (attempts < max_attempts) {
        crcflag = rand() % (max_attempts * 2); // Randomize within a range
        Node* current = list->head;

        pthread_mutex_lock(&list->mutex);
        while (current != NULL) {
            if (current->data.crcind.CRCFLAG == crcflag) {
                break;
            }
            current = current->next;
        }

        if (current == NULL) {
            // CRC flag is unique
            pthread_mutex_unlock(&list->mutex);
            return crcflag;
        }

        pthread_mutex_unlock(&list->mutex);
        attempts++;
    }

    log_message("Failed to generate a unique CRC flag after maximum attempts.");
    return -1; // Error code for failure
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        log_message("Memory allocation failed for new node.");
        return;
    }

    new_node->data = data;
    new_node->next = list->head;
    pthread_mutex_lock(&list->mutex);
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) {
        log_message("Memory allocation failed for list.");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int populate_crc_indication_pdu_list(int N, List* list) {
    for (int i = 0; i < N; i++) {
        RX_UE_INFORMATION rxue_info = { i, rand() % 1024 }; // Random RNTI
        int crcflag = generate_unique_crc_flag(list, 10);

        if (crcflag == -1) {
            log_message("Failed to populate list due to CRC flag generation failure.");
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = { rxue_info, { crcflag } };
        add_to_list(list, pdu);
    }

    return 0; // Success
}

int main() {
    List* list = create_list();
    if (list == NULL) {
        log_message("Failed to create list.");
        return -1;
    }

    if (populate_crc_indication_pdu_list(N, list) != 0) {
        free_list(list);
        return -1;
    }

    // Further processing or cleaning up resources

    free_list(list);
    return 0;
}
