from flask import Flask, request, jsonify
import hashlib

app = Flask(__name__)

# Mock database for demonstration purposes
resources = {
    '1': {'data': 'Initial data'},
}

@app.route('/update_resource/<resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if resource_id not in resources:
        return jsonify({'error': 'Resource not found'}), 404

    updated_data = request.json
    resources[resource_id].update(updated_data)

    return jsonify(resources[resource_id]), 200

@app.route('/file_hash/<path:file_path>', methods=['GET'])
def calculate_file_hash(file_path):
    try:
        hash_md5 = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return jsonify({'hash': hash_md5.hexdigest()})
    except FileNotFoundError:
        return jsonify({'error': 'File not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
