#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

typedef struct {
    int value;
} Record;

void parse_range(char *range, long *max_value) {
    char *token = strtok(range, "-");
    *max_value = atol(token);
}

long* allocate_offset_array(long max_value, int *offset_count) {
    // Calculate the number of offsets needed
    *offset_count = (int)((log(max_value + 1) / log(2)) + 1);
    long *offsets = malloc(*offset_count * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    // Initialize offsets
    for (int i = 0; i < *offset_count; i++) {
        offsets[i] = max_value / (1 << i);
    }
    return offsets;
}

int* allocate_key_array(char *keys) {
    int key_count = 0;
    char *token = strtok(keys, ",");
    while (token != NULL) {
        key_count++;
        token = strtok(NULL, ",");
    }
    int *key_values = malloc(key_count * sizeof(int));
    if (key_values == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    // Initialize keys
    for (int i = 0; i < key_count; i++) {
        token = strtok(NULL, ",");
        key_values[i] = atoi(token);
    }
    return key_values;
}

Record* allocate_record_array(int record_count) {
    Record *records = malloc(record_count * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    // Initialize records
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand();
    }
    return records;
}

unsigned char* get_md5_hash(char *keys) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, keys, strlen(keys));
    MD5_Final(hash, &md5);
    return hash;
}

int main() {
    srand(time(NULL));

    char range[] = "1-100";
    char keys[] = "key1,key2,key3";

    long max_value;
    parse_range(range, &max_value);

    int offset_count;
    long *offsets = allocate_offset_array(max_value, &offset_count);

    int key_count;
    int *keys_array = allocate_key_array(keys);

    Record *records = allocate_record_array(key_count);

    unsigned char *hash = get_md5_hash(keys);

    // Print MD5 hash
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    // Free allocated memory
    free(offsets);
    free(keys_array);
    free(records);
    free(hash);

    return 0;
}
