#include <stdio.h>
#include <stdarg.h>
#include <time.h>

#define LOG_PATH "/path/to/error.log"
#define LOG_ERROR 1
#define LOG_WARNING 2
#define LOG_INFO 3

static FILE *logFile = NULL;

int openLogFile() {
    logFile = fopen(LOG_PATH, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_PATH);
        return -1;
    }
    return 0;
}

void writeLogEntry(int severity, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    if (logFile != NULL) {
        fprintf(logFile, "[%02d:%02d:%02d] [%d] %s\n", tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, severity, message);
    }
}

void closeLogFile() {
    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }
}

int logCondition(const char *condition, int severity, const char *format, ...) {
    va_list args;
    va_start(args, format);

    if (openLogFile() == 0) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), format, args);
        writeLogEntry(severity, buffer);
        closeLogFile();
    }

    va_end(args);
    return 0;
}
