class ImageConverter {
public:
    enum ConversionStatus { SUCCESS, FAILURE };

    ImageConverter(const std::string& inputPath, const std::string& outputPath, const std::string& format)
        : m_inputPath(inputPath), m_outputPath(outputPath), m_format(format) {}

    ConversionStatus convertAndSave() {
        // Command to convert image using ImageMagick
        std::string command = "convert \"" + m_inputPath + "\" -format \"" + m_format + "\" \"" + m_outputPath + "\"";

        int result = system(command.c_str()); // Execute the command

        return (result == 0) ? SUCCESS : FAILURE;
    }

private:
    std::string m_inputPath;
    std::string m_outputPath;
    std::string m_format;
};

int main() {
