```csharp
using System;
using System.Security.Cryptography;

public class HashGenerator
{
    private ILog logger;

    public HashGenerator(ILog logger)
    {
        this.logger = logger;
    }

    public string GenerateMd5(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }
        return GenerateHash(MD5.Create(), input);
    }

    public string GenerateSha1(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }
        return GenerateHash(SHA1.Create(), input);
    }

    public string GenerateSha256(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }
        return GenerateHash(SHA256.Create(), input);
    }

    public string GenerateMd5(byte[] input)
    {
        if (input == null || input.Length == 0)
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }
        return GenerateHash(MD5.Create(), input);
    }

    public string GenerateSha1(byte[] input)
    {
        if (input == null || input.Length == 0)
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }
        return GenerateHash(SHA1.Create(), input);
    }

    public string GenerateSha256(byte[] input)
    {
        if (input == null || input.Length == 0)
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }
        return GenerateHash(SHA256.Create(), input);
    }

    private string GenerateHash(HashAlgorithm algorithm, object input)
    {
        byte[] hashBytes;
        if (input is string strInput)
        {
            using (var stream = new System.IO.MemoryStream(System.Text.Encoding.UTF8.GetBytes(strInput)))
            {
                hashBytes = algorithm.ComputeHash(stream);
            }
        }
        else
        {
            hashBytes = algorithm.ComputeHash((byte[])input);
        }

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }
}

public interface ILog
{
    void LogError(string message);
    void LogWarning(string message);
}

// Example implementation of a simple logger
public class ConsoleLogger : ILog
{
    public void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }

    public void LogWarning(string message)
    {
        Console.WriteLine($"WARNING: {message}");
    }
}
```

This code snippet provides the implementation of the `HashGenerator` class with methods to generate MD5, SHA1, and SHA256 hashes for both string and byte array inputs. The class uses a factory pattern approach for hash generation by leveraging .NET's built-in `HashAlgorithm` classes. It includes error handling for null or empty inputs and logs errors using an injected logging interface.

The separation of concerns is maintained with the hashing logic kept within the `GenerateHash` method, and logging functionality provided through the `ILog` interface. This design allows for easy extension to other hash algorithms by simply adding new methods without modifying existing code.

Note that this solution assumes the existence of a simple logger implementation (`ConsoleLogger`) for demonstration purposes. In a real-world scenario, you would likely use a more robust logging framework such as NLog or Serilog.

