#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <openssl/evp.h>
#include <pthread.h>

#define MAX_CIPHERS 100
#define MAX_DIGESTS 50

typedef struct {
    EVP_CIPHER *cipher[MAX_CIPHERS];
    int cipher_count;
    EVP_MD *digest[MAX_DIGESTS];
    int digest_count;
} CryptoLibrary;

CryptoLibrary crypto_library = {0};
pthread_mutex_t crypto_lock = PTHREAD_MUTEX_INITIALIZER;

void add_cipher(const char *name) {
    pthread_mutex_lock(&crypto_lock);
    for (int i = 0; i < crypto_library.cipher_count; ++i) {
        if (!strcmp(EVP_CIPHER_name(crypto_library.cipher[i]), name)) {
            pthread_mutex_unlock(&crypto_lock);
            return;
        }
    }
    EVP_CIPHER *cipher = EVP_get_cipherbyname(name);
    if (cipher) {
        crypto_library.cipher[crypto_library.cipher_count++] = cipher;
    }
    pthread_mutex_unlock(&crypto_lock);
}

void add_digest(const char *name) {
    pthread_mutex_lock(&crypto_lock);
    for (int i = 0; i < crypto_library.digest_count; ++i) {
        if (!strcmp(EVP_MD_name(crypto_library.digest[i]), name)) {
            pthread_mutex_unlock(&crypto_lock);
            return;
        }
    }
    EVP_MD *digest = EVP_get_digestbyname(name);
    if (digest) {
        crypto_library.digest[crypto_library.digest_count++] = digest;
    }
    pthread_mutex_unlock(&crypto_lock);
}

void create_directory_and_set_env() {
    const char *dir_name = "my_crypto_dir";
    if (!mkdir(dir_name, 0755)) {
        setenv("CRYPTO_DIR", dir_name, 1);
    } else {
        perror("Failed to create directory");
    }
}

void load_primitives_from_config(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (file) {
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            char *cipher_name = strtok(line, ",");
            char *digest_name = strtok(NULL, "\n");
            if (cipher_name && digest_name) {
                add_cipher(cipher_name);
                add_digest(digest_name);
            }
        }
        fclose(file);
    } else {
        perror("Failed to open configuration file");
    }
}

void initialize_crypto_library() {
    create_directory_and_set_env();
    load_primitives_from_config("/path/to/config/file");
}

int main() {
    initialize_crypto_library();
    // Additional code for testing and validation
    return 0;
}
