function loadAndExecuteTests(moduleLabel, tests) {
  const blueslip = require('blueslip');
  let totalTests = tests.length;
  let passedTests = 0;

  function executeTest(testFunction) {
    try {
      testFunction();
      console.log(`${moduleLabel}: ${testFunction.name} passed`);
      passedTests++;
    } catch (error) {
      console.error(`${moduleLabel}: ${testFunction.name} failed`, error);
    } finally {
      blueslip.reset(); // Reset mocking library after each test
      if (--totalTests === 0) {
        const passRate = ((passedTests / tests.length) * 100).toFixed(2);
        console.log(`${moduleLabel}: All ${tests.length} tests completed. Pass rate: ${passRate}%`);
      }
    }
  }

  tests.forEach(executeTest);
}
