```cpp
#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>
#include <netdb.h>
#include <arpa/inet.h>
#include <thread>
#include <mutex>
#include <condition_variable>

class NetworkResolver {
public:
    void updateDNSServers(const std::vector<std::string>& servers) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& server : servers) {
            if (!isValidIP(server)) {
                throw std::invalid_argument("Invalid IP address: " + server);
            }
        }
        dnsServers_ = servers;
    }

    std::string resolveHostname(const std::string& hostname, int timeout, size_t maxRetries = 3) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t attempt = 0; attempt <= maxRetries; ++attempt) {
            try {
                struct addrinfo hints, *res;
                memset(&hints, 0, sizeof(hints));
                hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
                hints.ai_socktype = SOCK_STREAM;

                if (getaddrinfo(hostname.c_str(), nullptr, &hints, &res) != 0) {
                    throw std::runtime_error("DNS resolution failed");
                }

                char ipStr[INET6_ADDRSTRLEN];
                for (struct addrinfo *p = res; p != nullptr; p = p->ai_next) {
                    if (p->ai_family == AF_INET) { // IPv4
                        struct sockaddr_in* h = (struct sockaddr_in *)p->ai_addr;
                        inet_ntop(p->ai_family, h->sin_addr, ipStr, INET6_ADDRSTRLEN);
                    } else { // IPv6
                        struct sockaddr_in6* h = (struct sockaddr_in6 *)p->ai_addr;
                        inet_ntop(p->ai_family, h->sin6_addr, ipStr, INET6_ADDRSTRLEN);
                    }
                    freeaddrinfo(res);
                    return std::string(ipStr);
                }
            } catch (...) {
                if (attempt == maxRetries) {
                    throw;
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(timeout));
            }
        }
    }

private:
    bool isValidIP(const std::string& ip) {
        struct sockaddr_in sa4;
        struct sockaddr_in6 sa6;
        return inet_pton(AF_INET, ip.c_str(), &sa4.sin_addr) != 0 ||
               inet_pton(AF_INET6, ip.c_str(), &sa6.sin6_addr) != 0;
    }

    std::mutex mutex_;
    std::vector<std::string> dnsServers_;
};
```

