public class XmlParserService : IDisposable
{
    private readonly IXmlConfigurationLoader _xmlConfigLoader;
    private readonly IXmlCacheStorage _xmlCacheStorage;

    public XmlParserService(IXmlConfigurationLoader xmlConfigLoader, IXmlCacheStorage xmlCacheStorage)
    {
        _xmlConfigLoader = xmlConfigLoader ?? throw new ArgumentNullException(nameof(xmlConfigLoader));
        _xmlCacheStorage = xmlCacheStorage ?? throw new ArgumentNullException(nameof(xmlCacheStorage));
    }

    public XPathNavigator ParseAndFindElement(string xpathExpression, string namespaceURI)
    {
        var xmlFilePath = _xmlConfigLoader.LoadXmlDocumentPath();
        var xPathDoc = _xmlCacheStorage.GetCachedXPathDocument(xmlFilePath);

        if (xPathDoc == null)
        {
            xPathDoc = new XPathDocument(xmlFilePath);
            _xmlCacheStorage.CacheXPathDocument(xmlFilePath, xPathDoc);
        }

        var nav = xPathDoc.CreateNavigator();
        var nsManager = new XmlNamespaceManager(nav.NameTable);
        nsManager.AddNamespace("ns", namespaceURI);

        var nodes = nav.Select(xpathExpression, nsManager);

        if (nodes.Count == 0)
            throw new InvalidOperationException($"No element found with the given name '{xpathExpression}'.");

        if (nodes.Count > 1)
            throw new InvalidOperationException($"Multiple elements found with the given name '{xpathExpression}'.");

        return nodes.Current;
    }

    public void Dispose()
    {
        // Logic to dispose of any resources used by the service
        _xmlCacheStorage.Dispose();
    }
}
