#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_QUERY_CONCURRENCY 10
#define DNS_QUERY_TIMEOUT 5

typedef struct {
    u_char ip[4];
    int errorCode;
} ResolveResult;

sem_t querySemaphore;

ResolveResult resolveHostname(const char *hostname) {
    sem_wait(&querySemaphore);
    if (pthread_self() == 0) {
        printf("Failed to acquire semaphore for DNS resolution.\n");
        return (ResolveResult){.errorCode = -1};
    }

    struct addrinfo hints, *res;
    ResolveResult result = {.errorCode = 0};

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        printf("getaddrinfo error: %s\n", gai_strerror(status));
        result.errorCode = -2;
        goto cleanup;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(result.ip, &(ipv4->sin_addr), sizeof(ipv4->sin_addr));

cleanup:
    freeaddrinfo(res);
    sem_post(&querySemaphore);

    return result;
}

void *logQuery(void *arg) {
    const char *hostname = (const char *)arg;
    ResolveResult result = resolveHostname(hostname);

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    printf("DNS Query Log: %s, Hostname: %s, Result IP: ", asctime(tm_info), hostname);

    if (result.errorCode == 0) {
        for (int i = 0; i < 4; ++i) {
            printf("%d.", result.ip[i]);
        }
        printf("\n");
    } else {
        printf("Error Code: %d\n", result.errorCode);
    }

    return NULL;
}

int main() {
    sem_init(&querySemaphore, 0, MAX_QUERY_CONCURRENCY);

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        const char *hostnames[] = {"google.com", "nonexistentdomain.example"};
        pthread_create(&threads[i], NULL, logQuery, (void *)hostnames[i % 2]);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&querySemaphore);

    return 0;
}
