// JavaScript code for collectAndHandleStream
function collectAndHandleStream(stream) {
  let dataArray = [];
  let paused = false;
  const mutex = new Mutex();

  function logIssue(issue) {
    console.error(`ISSUE: ${issue}`);
  }

  async function processData() {
    while (!stream.isFinished()) {
      if (paused) continue;

      try {
        await mutex.lock();
        dataArray.push(stream.read());
      } finally {
        mutex.unlock();
      }
    }
  }

  return {
    pause: () => {
      paused = true;
    },
    resume: () => {
      paused = false;
      processData();
    },
    getData: () => dataArray,
  };
}

// C code for expandStringWithSlash
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* expandStringWithSlash(const char* input, size_t maxSize) {
  if (input == NULL || *input == '\0' || maxSize == 0) {
    return NULL;
  }

  // Check if the string needs an additional character
  size_t length = strlen(input);
  if (length >= maxSize - 1) {
    return NULL;
  }

  char* expandedString = (char*)malloc((length + 2) * sizeof(char));
  if (expandedString == NULL) {
    fprintf(stderr, "Memory allocation failed\n");
    return NULL;
  }

  // Copy the input string and append a slash
  strcpy(expandedString, input);
  expandedString[length] = '/';
  expandedString[length + 1] = '\0';

  return expandedString;
}
