import java.util.*;

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]); // Path compression
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP == rootQ) return;

        // Union by rank
        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
        } else if (rank[rootP] < rank[rootQ]) {
            parent[rootP] = rootQ;
        } else {
            parent[rootQ] = rootP;
            rank[rootP]++;
        }
    }

    public boolean areDisjoint(int p, int q) {
        return find(p) != find(q);
    }
}

class UnionFindDisjointPairs {
    private UnionFind unionFind;
    private long startTime;
    private long endTime;

    public UnionFindDisjointPairs(int[] array) throws IllegalArgumentException {
        if (array == null || array.length == 0) {
            throw new IllegalArgumentException("Input array cannot be null or empty.");
        }
        Set<Integer> uniqueElements = new HashSet<>();
        for (int num : array) {
            if (!uniqueElements.add(num)) {
                throw new IllegalArgumentException("Input array contains duplicate elements.");
            }
        }
        unionFind = new UnionFind(array.length);
    }

    public void addNewElement(int element) throws IllegalArgumentException {
        if (unionFind == null) {
            throw new IllegalStateException("Union-Find structure is not initialized.");
        }
        if (!unionFind.parent[element]) {
            throw new IllegalArgumentException("Input element is out of the expected range.");
        }
        unionFind.union(element, array.length); // Assuming all elements are disjoint initially
    }

    public int countDisjointPairs() {
        startTime = System.currentTimeMillis();
        int result = 0;
        for (int i = 0; i < unionFind.parent.length; i++) {
            if (unionFind.areDisjoint(i, unionFind.find(array.length))) {
                result++;
            }
        }
        endTime = System.currentTimeMillis();
        logResult(result);
        return result;
    }

    private void logResult(int result) {
        long timeTaken = endTime - startTime;
        // Assuming a logging system is available
        // LogSystem.log("Number of disjoint pairs: " + result + ", Time taken: " + timeTaken + " ms");
    }
}

class Main {
    public static void main(String[] args) {
        try {
            int[] array = {1, 2, 3, 4, 5, 6};
            UnionFindDisjointPairs disjointPairs = new UnionFindDisjointPairs(array);
            disjointPairs.addNewElement(7);
            disjointPairs.addNewElement(8);
            long startTime = System.currentTimeMillis();
            int result = disjointPairs.countDisjointPairs();
            long endTime = System.currentTimeMillis();
            System.out.println("Number of disjoint pairs: " + result + ", Time taken: " + (endTime - startTime) + " ms");
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
