import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ConnectionManager {

    private static final String MESSAGE_QUEUE_URL = "kafka://localhost:9092";
    private static final int POOL_SIZE = 10;
    private static final long TIMEOUT = 5000;

    private AsynchronousChannelGroup channelGroup;
    private ExecutorService executorService;
    private KafkaMessageSender messageSender;

    public ConnectionManager() {
        try {
            executorService = Executors.newFixedThreadPool(POOL_SIZE);
            channelGroup = AsynchronousChannelGroup.withCachedThreadPool(executorService, POOL_SIZE);
            messageSender = new KafkaMessageSender(MESSAGE_QUEUE_URL);
        } catch (IOException e) {
            throw new RuntimeException("Failed to initialize connection manager", e);
        }
    }

    public void connectAndSendMessage(String host, int port, String message) {
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(channelGroup);

        channel.connect(new InetSocketAddress(host, port), null, new CompletionHandler<Void, Void>() {
            @Override
            public void completed(Void result, Void attachment) {
                try {
                    System.out.println("Connected to " + host + ":" + port);
                    ByteBuffer buffer = ByteBuffer.wrap(message.getBytes());
                    channel.write(buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {
                        @Override
                        public void completed(Integer bytesWritten, ByteBuffer buffer) {
                            System.out.println("Message sent: " + message);
                            // Asynchronously send to Kafka
                            messageSender.sendMessageAsync(message);
                        }

                        @Override
                        public void failed(Throwable exc, ByteBuffer attachment) {
                            handleFailure(exc, channel);
                        }
                    });
                } catch (Exception e) {
                    handleFailure(e, channel);
                }
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                handleFailure(exc, channel);
            }
        });

        // Set connection timeout and retry mechanism
        try {
            if (!channel.get(1000, TimeUnit.MILLISECONDS).isOpen()) {
                System.out.println("Connection timed out. Retrying...");
                connectAndSendMessage(host, port, message);
            }
        } catch (Exception e) {
            handleFailure(e, channel);
        }
    }

    private void handleFailure(Throwable exc, AsynchronousSocketChannel channel) {
        try {
            channel.close();
        } catch (IOException e) {
            System.err.println("Failed to close channel: " + e.getMessage());
        }
        System.err.println("Connection failed: " + exc.getMessage());
    }

    public void shutdown() {
        try {
            channelGroup.shutdownNow().awaitTermination(5, TimeUnit.SECONDS);
            executorService.shutdownNow();
            messageSender.shutdown();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Failed to shutdown connection manager: " + e.getMessage());
        }
    }

    // KafkaMessageSender class and other utility methods can be implemented here
}
