async function asyncArrayReduce(arr, initialValue, callback) {
    let accumulator = initialValue;
    const semaphore = new Semaphore(2); // Limit concurrency level

    for (let i = 0; i < arr.length; i++) {
        await semaphore.acquire(); // Acquire semaphore slot

        Promise.resolve(callback(accumulator, arr[i]))
            .then(result => {
                accumulator = result;
                semaphore.release(); // Release semaphore slot
            })
            .catch(error => {
                semaphore.release(); // Release semaphore slot
                throw error; // Propagate the error
            });
    }

    return accumulator;
}

class Semaphore {
    constructor(concurrency) {
        this.concurrency = concurrency;
        this.count = 0;
        this.queue = [];
    }

    async acquire() {
        while (this.count >= this.concurrency) {
            await new Promise(resolve => this.queue.push(resolve));
        }
        this.count++;
    }

    release() {
        if (this.queue.length > 0) {
            const resolve = this.queue.shift();
            resolve();
        } else {
            this.count--;
        }
    }
}

// Example usage:
const sampleArray = [1, 2, 3, 4, 5];
async function asyncCallback(acc, num) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            try {
                resolve(acc + num);
            } catch (error) {
                reject(error);
            }
        }, Math.random() * 1000); // Simulate asynchronous operation
    });
}

asyncArrayReduce(sampleArray, 0, asyncCallback)
    .then(result => console.log('Final Result:', result))
    .catch(error => console.error('Error:', error));
