class JSONParser {
  constructor() {
    this.registry = {};
  }

  registerFactory(id, factoryFunction) {
    this.registry[id] = factoryFunction;
  }

  toJSON(data) {
    return JSON.stringify(data);
  }

  fromJSON(jsonString) {
    const data = JSON.parse(jsonString);
    if (this.registry[data.type]) {
      return this.registry[data.type](data);
    }
    throw new Error(`Unknown type: ${data.type}`);
  }
}

function runTests(moduleLabel, testLabels, testFunctions) {
  function loadModule() {
    return require(moduleLabel);
  }

  function runTest(index) {
    const label = testLabels[index];
    const testFunction = testFunctions[index];

    if (index < testLabels.length - 1) {
      blueslip.reset(); // Reset mocking library for each test
    } else {
      Promise.all(promises).then(() => blueslip.reset()); // Ensure cleanup after all tests
    }

    return new Promise((resolve, reject) => {
      console.log(`Running ${label}`);
      testFunction().then(resolve, (error) => {
        console.error(`${label} failed:`, error);
        reject(error);
      });
    });
  }

  const promises = testLabels.map(runTest);
  Promise.all(promises).then(() => {
    console.log("All tests completed successfully.");
  }).catch((error) => {
    console.error("One or more tests failed:", error);
  });
}
