global $db_pool;

function handleUserRequest() {
    // Initialize response
    $response = [
        "status" => "success",
        "message" => "",
        "data" => []
    ];

    // Check for rate limiting
    if (!rateLimitCheck($_SERVER['REMOTE_ADDR'])) {
        $response["status"] = "error";
        $response["message"] = "Too many requests. Please try again later.";
        return json_encode($response);
    }

    // Validate input data
    $id = isset($_POST['id']) ? intval($_POST['id']) : null;
    $name = isset($_POST['name']) ? $_POST['name'] : '';
    $email = isset($_POST['email']) ? $_POST['email'] : '';
    $password = isset($_POST['password']) ? $_POST['password'] : '';
    $confirm_password = isset($_POST['confirm_password']) ? $_POST['confirm_password'] : '';

    if (empty($name) || empty($email)) {
        $response["status"] = "error";
        $response["message"] = "Name and email are required.";
        return json_encode($response);
    }

    if ($password !== $confirm_password) {
        $response["status"] = "error";
        $response["message"] = "Passwords do not match.";
        return json_encode($response);
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        $response["status"] = "error";
        $response["message"] = "Invalid email format.";
        return json_encode($response);
    }

    // Check for password complexity (minimum length, presence of letters and numbers)
    if (strlen($password) < 8 || !preg_match('/[A-Za-z]/', $password) || !preg_match('/\d/', $password)) {
        $response["status"] = "error";
        $response["message"] = "Password must be at least 8 characters long and include both letters and numbers.";
        return json_encode($response);
    }

    // Check if email is unique
    if ($id === null) { // New user
        $stmt = $db_pool->prepare("SELECT * FROM users WHERE email = ?");
        $stmt->bind_param("s", $email);
        $stmt->execute();
        $result = $stmt->get_result();
        if ($result->num_rows > 0) {
            $response["status"] = "error";
            $response["message"] = "Email already exists.";
            return json_encode($response);
        }
    }

    // Hash password
    $hashed_password = password_hash($password, PASSWORD_DEFAULT);

    // Perform database operation based on action
    if (isset($_POST['sub_action']) && $_POST['sub_action'] === 'delete') {
        if ($id === null) {
            $response["status"] = "error";
            $response["message"] = "User ID is required for deletion.";
            return json_encode($response);
        }
        $stmt = $db_pool->prepare("DELETE FROM users WHERE id = ?");
    } else {
        // Insert or update user
        if ($id === null) { // New user
            $stmt = $db_pool->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
        } else {
            $stmt = $db_pool->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
        }
        $stmt->bind_param("sssss", $name, $email, $hashed_password, $id);
    }

    // Execute statement and handle errors
    if ($stmt->execute()) {
        $user_id = ($id === null) ? $stmt->insert_id : $id;
        $response["data"] = [
            "id" => $user_id,
            "name" => $name,
            "email" => $email
        ];
        logAction("User {$user_id} created/updated", $_SERVER['REMOTE_ADDR']);
    } else {
        $response["status"] = "error";
        $response["message"] = "Database error: " . $stmt->error;
        logAction("Failed to create/update user: " . $stmt->error, $_SERVER['REMOTE_ADDR']);
    }

    return json_encode($response);
}

