public class PacketFilter {
    private final int windowSize;
    private final Queue<Packet> slidingWindow = new LinkedList<>();
    private int totalPackets = 0;
    private int filteredPackets = 0;
    private long totalPacketSize = 0;

    public PacketFilter(int windowSize) {
        this.windowSize = windowSize;
    }

    public void processPacket(Packet packet) {
        if (slidingWindow.size() >= windowSize) {
            Packet oldestPacket = slidingWindow.poll();
            totalPacketSize -= oldestPacket.getSize();
        }
        slidingWindow.add(packet);
        totalPackets++;
        totalPacketSize += packet.getSize();

        if (!isPacketValid(packet)) {
