        std::cout << "Disconnecting from database..." << std::endl;
    }
};

class FileRecorder : public TransactionRecorder {
public:
    int recordTransaction(const std::string& details) override {
        // Simulate log file writing
        if (!openLogFile()) {
            return -2; // Error code for log file failure
        }
        writeToFile(details);
        closeLogFile();
        return 0;
    }

private:
