    def wrapper(*args, **kwargs):
        user_token = request.headers.get('Authorization')
        if not ThirdPartyAuthService().is_authenticated(user_token):
            return jsonify({"error": "Unauthorized"}), 401
        return f(*args, **kwargs)
    return wrapper

