def update_metadata():
    file_path = request.form.get('file_path')
    if not os.path.exists(file_path):
        return jsonify({"error": "File not found"}), 404

    # Simulate getting metadata from external service
    metadata = ExternalMetadataService().get_file_metadata(file_path)

    # Update metadata (simulated here)
    new_size = request.form.get('size')
    if new_size and int(new_size) != metadata['size']:
        metadata['size'] = int(new_size)

    return jsonify({"message": "Metadata updated", "new_metadata": metadata})

# Endpoint for calculating and comparing MD5 hash
@app.route('/check_hash', methods=['POST'])
def check_hash():
    file_path = request.form.get('file_path')
    if not os.path.exists(file_path):
        return jsonify({"error": "File not found"}), 404

    def calculate_md5(file_path):
        hash_md5 = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    try:
        file_hash = executor.submit(calculate_md5, file_path).result(timeout=30)

        # Simulate getting stored checksum from external service
        metadata = ExternalMetadataService().get_file_metadata(file_path)
        if not metadata['checksum']:
            metadata['checksum'] = file_hash

        return jsonify({"message": "Hash checked", "file_hash": file_hash, "stored_checksum": metadata['checksum']})

    except Exception as e:
        return jsonify({"error": f"Error during hash calculation: {str(e)}"}), 500

if __name__ == '__main__':
    app.run(debug=True)
