```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SecureEncryptionService
{
    private readonly KeyManager _keyManager;

    public SecureEncryptionService(KeyManager keyManager)
    {
        _keyManager = keyManager ?? throw new ArgumentNullException(nameof(keyManager));
    }

    public byte[] Encrypt(string data, string keySeed)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = GenerateKeyFromSeed(keySeed);
            aes.IV = GenerateIV();
            var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            using (var msEncrypt = new MemoryStream())
            {
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    using (var swEncrypt = new StreamWriter(csEncrypt))
                    {
                        swEncrypt.Write(data);
                    }
                    return msEncrypt.ToArray();
                }
            }
        }
    }

    public string Decrypt(byte[] ciphertext, string keySeed)
    {
        var key = GenerateKeyFromSeed(keySeed);
        var iv = GetIV(ciphertext);

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (var msDecrypt = new MemoryStream(ciphertext))
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (var srDecrypt = new StreamReader(csDecrypt))
                    {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }

    private byte[] GenerateKeyFromSeed(string seed)
    {
        using (var sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(seed));
        }
    }

    private byte[] GenerateIV()
    {
        var iv = new byte[16];
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(iv);
        }
        return iv;
    }

    private byte[] GetIV(byte[] ciphertext)
    {
        // Assuming IV is the first 16 bytes of the ciphertext
        return ciphertext.Take(16).ToArray();
    }
}

public class KeyManager
{
    public byte[] GenerateKey()
    {
        var key = new byte[32];
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(key);
        }
        return key;
    }

    public void StoreKey(byte[] key)
    {
        // Implement secure storage logic here
    }

    public bool ValidateKey(byte[] key)
    {
        // Implement key validation logic here
        return true;
    }

    public byte[] RetrieveKey()
    {
        // Implement secure retrieval logic here
        return new byte[32];
    }
}

// Example usage:
