#include <openssl/ssl.h>
#include <openssl/err.h>
#include <openssl/pem.h>

typedef struct {
    SSL_CTX *ctx;
    BIO *bio;
} SecureConnection;

SecureConnection* init_secure_connection(const char *password, const char *cert_file, const char *key_file) {
    SecureConnection *conn = (SecureConnection *)malloc(sizeof(SecureConnection));
    conn->ctx = NULL;
    conn->bio = NULL;

    // Initialize OpenSSL
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    // Create a new TLS context using TLSv1.3
    conn->ctx = SSL_CTX_new(TLS_client_method());
    if (conn->ctx == NULL) {
        fprintf(stderr, "Failed to create TLS context\n");
        return NULL;
    }

    // Set the cipher suite
    if (!SSL_CTX_set_cipher_list(conn->ctx, "TLS_AES_256_GCM_SHA384")) {
        fprintf(stderr, "Failed to set cipher list\n");
        SSL_CTX_free(conn->ctx);
        return NULL;
    }

    // Enable client certificate authentication
    SSL_CTX_load_verify_locations(conn->ctx, "/path/to/ca_cert.pem", NULL);
    SSL_CTX_set_verify(conn->ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

    // Load the client certificate and private key
    if (!SSL_CTX_use_certificate_file(conn->ctx, cert_file, SSL_FILETYPE_PEM) ||
        !SSL_CTX_use_PrivateKey_file(conn->ctx, key_file, SSL_FILETYPE_PEM)) {
        fprintf(stderr, "Failed to load certificate or private key\n");
        SSL_CTX_free(conn->ctx);
        return NULL;
    }

    // Derive encryption key from the password
    if (!PKCS5_pbe2_encrypt(password, strlen(password), EVP_aes_256_gcm(), NULL, 0, 
                            (unsigned char *)"Salt", sizeof("Salt") - 1, 
                            conn->ctx->cert->key->pkey.pkey.rsa->n.d, 8)) {
        fprintf(stderr, "Failed to derive encryption key\n");
        SSL_CTX_free(conn->ctx);
        return NULL;
    }

    // Create a new BIO
    conn->bio = BIO_new_ssl_connect(conn->ctx);
    if (conn->bio == NULL) {
        fprintf(stderr, "Failed to create BIO\n");
        SSL_CTX_free(conn->ctx);
        return NULL;
    }

    // Set the connect string for the BIO
    BIO_set_conn_hostname(conn->bio, "example.com:443");

    return conn;
}

void cleanup_secure_connection(SecureConnection *conn) {
    if (conn->bio != NULL) {
        BIO_free_all(conn->bio);
    }
    if (conn->ctx != NULL) {
        SSL_CTX_free(conn->ctx);
    }
    free(conn);
}
