def process_chunk(chunk, ip_data, log_stats):
    try:
        for line in chunk.decode('utf-8').split('\n'):
            if line:
                data = parse_log_line(line)
                ip_data[data['ip']].append(data['response_time'])
                log_stats['total_requests'] += 1
                log_stats['total_response_time'] += data['response_time']
    except Exception as e:
        logging.error(f"Error processing chunk: {e}")

def aggregate_data(ip_data):
    avg_times = {}
    for ip, times in ip_data.items():
        avg_times[ip] = sum(times) / len(times)
    return avg_times

def report_to_api(stats):
    # Implement API reporting logic
    pass

def main(log_file_path):
    ip_data = defaultdict(list)
    log_stats = {'total_requests': 0, 'total_response_time': 0}

    chunk_size = 1024 * 1024  # 1MB

    try:
        if log_file_path.endswith('.gz'):
            with gzip.open(log_file_path, 'rb') as f:
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break
                    process_chunk(chunk, ip_data, log_stats)
        else:
            with open(log_file_path, 'rb') as f:
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break
                    process_chunk(chunk, ip_data, log_stats)
    except Exception as e:
        logging.error(f"Error processing file: {e}")

    avg_times = aggregate_data(ip_data)
    report_to_api(avg_times)

if __name__ == "__main__":
    log_file_path = 'path_to_your_log_file.log'
    main(log_file_path)
