    // Simulate the response from the external service
    if (strcmp(base_filename, "image") == 0) {
        *type = strdup("jpg");
        *num_digits = 4;
    } else if (strcmp(base_filename, "video") == 0) {
        *type = strdup("mp4");
        *num_digits = 5;
    } else {
