    }

    return 0;
}

// Callback function for libcurl to handle response data
size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((char*)userp)[size * nmemb] = '\0';
    return size * nmemb;
}

// Function to generate a unique filename
char* generateUniqueFilename(const char* base_filename) {
    CURL* curl;
    CURLcode res;
    char error_buffer[CURL_ERROR_SIZE];

    // Allocate memory for the new filename
    char* new_filename = (char*)malloc(256 * sizeof(char));
    if (!new_filename) {
        return NULL; // Handle memory allocation failure
    }

    // Simulate external service call or HTTP request to fetch metadata
    int status;
    char* type = NULL;
    int num_digits;
    do {
        status = fetchMetadata(base_filename, &type, &num_digits);
        if (status == -1) {
            sleep(1); // Wait before retrying
        }
    } while (status != 0);

    // Generate the new filename
    snprintf(new_filename, 256, "%s_%d.%s", base_filename, rand() % 100000, type);

    // Free dynamically allocated memory
    free(type);

    return new_filename;
}

// Example usage
int main() {
    char* filename = generateUniqueFilename("image");
    if (filename) {
        printf("Generated filename: %s\n", filename);
        free(filename); // Remember to free the allocated memory
    } else {
