class OAuth2Authenticator {
    private $client;
    private $cache;
    private $rateLimiter;

    public function __construct($clientId, $clientSecret, $redirectUri, $redisHost, $redisPort, $rateLimit) {
        $this->client = new OAuth2Client($clientId, $clientSecret, $redirectUri);
        $this->cache = new Redis();
        $this->cache->connect($redisHost, $redisPort);
        $this->rateLimiter = new RateLimiter($rateLimit);
    }

    public function authenticate($code) {
        if (!$this->rateLimiter->isAllowed()) {
            throw new Exception("Too many requests. Please try again later.");
        }

        try {
            $accessToken = $this->client->getAccessToken($code);

            session_start();
            $_SESSION['access_token'] = $accessToken;

            $userData = $this->getUserInfo($accessToken);

            $this->cache->set('user_info', serialize($userData), 3600);

            return $userData;
        } catch (Exception $e) {
            error_log("Authentication failed: " . $e->getMessage());
            throw new Exception("Authentication failed. Please try again.");
        }
    }

    private function getUserInfo($accessToken) {
        if ($this->cache->exists('user_info')) {
            return unserialize($this->cache->get('user_info'));
        } else {
            $response = $this->client->getUserInfo($accessToken);
            $userData = [
                'id' => $response['id'],
                'name' => $response['name'],
                'email' => $response['email']
            ];
            return $userData;
        }
    }
}

class OAuth2Client {
    private $clientId;
    private $clientSecret;
