extern crate reqwest;
use std::time::Duration;
use reqwest::{Client, Error};
use tokio::task;
use async_trait::async_trait;

#[async_trait]
pub trait HttpClient {
    async fn get(&self, url: &str) -> Result<String, Error>;
    async fn post(&self, url: &str, body: String) -> Result<String, Error>;
}

pub struct RobustHttpClient {
    client: Client,
    logger: Box<dyn Logger>,
}

impl RobustHttpClient {
    pub fn new(cert_path: Option<&str>, logger: Box<dyn Logger>) -> Self {
        let mut builder = Client::builder()
            .timeout(Duration::from_secs(10))
            .default_headers(reqwest::header::HeaderMap::new());

        if let Some(path) = cert_path {
            builder = builder.dangerously_insecure_skip_tls_verify(true);
            // TODO: Implement secure TLS verification
        }

        RobustHttpClient {
            client: builder.build().unwrap(),
            logger,
        }
    }

    async fn handle_request(&self, url: &str, method: reqwest::Method) -> Result<String, Error> {
        let response = self.client.request(method, url).send().await?;
        let text = response.text().await?;

        // Log request and response
        self.logger.log(url, &text);

        Ok(text)
    }
}

#[async_trait]
impl HttpClient for RobustHttpClient {
    async fn get(&self, url: &str) -> Result<String, Error> {
        self.handle_request(url, reqwest::Method::GET).await
    }

    async fn post(&self, url: &str, body: String) -> Result<String, Error> {
        self.client.post(url).body(body).send().await?;
        // Assuming POST requests do not have a response body to log directly
        Ok("POST request sent successfully".to_string())
    }
}

pub trait Logger {
    fn log(&self, url: &str, data: &str);
}

struct ConsoleLogger;

impl Logger for ConsoleLogger {
    fn log(&self, url: &str, data: &str) {
        println!("Request to {}:\n{}", url, data);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct MockLogger {
        logs: Vec<(String, String)>,
    }

    impl Logger for MockLogger {
        fn log(&self, url: &str, data: &str) {
            self.logs.push((url.to_string(), data.to_string()));
        }
    }

    #[tokio::test]
    async fn test_get_request() {
        let mock_logger = Box::new(MockLogger { logs: Vec::new() });
        let client = RobustHttpClient::new(None, mock_logger);

        // Mock a successful GET request
        let response = client.get("https://httpbin.org/get").await.unwrap();
        assert_eq!(response, r#"{"args":{},"headers":{"Accept":"*/*","Host":"httpbin.org","User-Agent":"reqwest/0.11.6","X-Amzn-Trace-Id":"Root=1-5f4c8b6d-000000000000000000000000"},"origin":"xx.xxx.xx.xx","url":"https://httpbin.org/get"}"#);

        // Check if the request was logged
        assert_eq!(mock_logger.logs.len(), 1);
        assert_eq!(mock_logger.logs[0].0, "https://httpbin.org/get");
    }

    #[tokio::test]
    async fn test_post_request() {
        let mock_logger = Box::new(MockLogger { logs: Vec::new() });
        let client = RobustHttpClient::new(None, mock_logger);

        // Mock a successful POST request
        let response = client.post("https://httpbin.org/post", String::from("{\"key\":\"value\"}")).await.unwrap();
        assert_eq!(response, "POST request sent successfully");

        // Check if the request was logged (Note: No direct body logging for POST)
        assert_eq!(mock_logger.logs.len(), 1);
        assert_eq!(mock_logger.logs[0].0, "https://httpbin.org/post");
    }
}
