from flask import Flask, request, jsonify, abort
from flask_httpauth import HTTPBasicAuth
import hashlib
import os
import requests
import asyncio

app = Flask(__name__)
auth = HTTPBasicAuth()

# Dummy user database for demonstration purposes
users = {
    "admin": "secret",
    "user": "pass"
}

@auth.verify_password
def verify_password(username, password):
    if username in users and users[username] == password:
        return username

@app.route('/update-resource', methods=['PUT'])
@auth.login_required
async def update_resource():
    resource_id = request.json.get('id')
    new_data = request.json.get('data')

    if not (resource_id and new_data):
        abort(400, description="Missing data")

    # Simulate updating a resource
    await asyncio.sleep(1)  # Delay to simulate I/O operation

    return jsonify({"message": "Resource updated successfully"})

@app.route('/hash-file', methods=['POST'])
@auth.login_required
async def hash_file():
    file_path = request.form.get('path')

    if not file_path:
        abort(400, description="Missing file path")

    # Simulate fetching file metadata from external storage service
    try:
        response = requests.head(file_path)
        response.raise_for_status()
    except requests.RequestException as e:
        abort(503, description=f"Failed to fetch file metadata: {str(e)}")

    # Calculate MD5 hash in chunks
    md5_hash = hashlib.md5()
    chunk_size = 8192
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            md5_hash.update(data)

    return jsonify({"md5": md5_hash.hexdigest()})

@app.route('/access-control', methods=['POST'])
@auth.login_required
async def access_control():
    user_role = request.json.get('role')

    if not user_role:
        abort(400, description="Missing user role")

    # Simulate access control logic
    if user_role == "admin":
        return jsonify({"message": "Access granted"})
    else:
        abort(403, description="Permission denied")

if __name__ == '__main__':
    app.run(debug=True)
```

