#include <forward_list>
#include <string>
#include <algorithm>
#include <memory>

// Function to insert a string after the first occurrence of another string in a forward list
template<typename Allocator = std::allocator<std::string>>
void insertAfterOrEnd(std::forward_list<std::string, Allocator>& list,
                       const std::string& searchStr,
                       const std::string& insertStr,
                       typename std::forward_list<std::string>::iterator pos = nullptr,
                       bool (*customFind)(const std::string&, const std::string&) = nullptr) {
    // Default find function is case-sensitive
    auto defaultFind = [](const std::string& a, const std::string& b) { return a == b; };

    // Use the custom find function or the default one
    auto findFunc = customFind ? customFind : defaultFind;

    if (!pos) {
        pos = std::find_if(list.begin(), list.end(), [searchStr, &findFunc](const std::string& str) {
            return findFunc(str, searchStr);
        });
    }

    if (pos != list.end()) {
        list.insert_after(pos, insertStr);
    } else {
        list.push_back(insertStr);
    }
}

// Custom comparison function for case-insensitive search
bool caseInsensitiveFind(const std::string& a, const std::string& b) {
    return std::equal(a.begin(), a.end(), b.begin(), b.end(),
                      [](char ch1, char ch2) { return std::tolower(ch1) == std::tolower(ch2); });
}

// Example usage
int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertAfterOrEnd(myList, "banana", "grape", nullptr, caseInsensitiveFind);
    // myList should now be {"apple", "banana", "grape", "cherry"}
    return 0;
}
