```javascript
const asyncArrayReduce = (array, initialValue, callback) => {
  return new Promise((resolve, reject) => {
    if (!Array.isArray(array)) {
      reject(new Error('Input must be an array'));
    }
    if (typeof initialValue !== 'number') {
      reject(new Error('Initial value must be a number'));
    }
    if (typeof callback !== 'function') {
      reject(new Error('Callback must be a function'));
    }

    const result = initialValue;
    let currentIndex = 0;
    let activeOperations = 0;
    const semaphore = () => {
      if (currentIndex < array.length && activeOperations < 10) {
        const currentNumber = array[currentIndex];
        currentIndex++;
        activeOperations++;
        callback(result, currentNumber)
          .then(value => {
            result += value;
            activeOperations--;
            semaphore();
          })
          .catch(error => {
            reject(error);
          });
      } else if (currentIndex === array.length) {
        resolve(result);
      }
    };
    semaphore();
  });
};
