```csharp
using System;
using System.Xml.XPath;

public class XmlParserService : IXmlParserService
{
    private readonly IConfigurationLoader _configLoader;
    private readonly ICachingService _cacheService;

    public XmlParserService(IConfigurationLoader configLoader, ICachingService cacheService)
    {
        _configLoader = configLoader;
        _cacheService = cacheService;
    }

    public XPathNavigator GetElement(string xpathQuery, string namespaceUri)
    {
        var xmlDocumentPath = _configLoader.GetXmlDocumentPath();

        if (string.IsNullOrEmpty(xmlDocumentPath))
            throw new ArgumentException("Invalid configuration: XML document path is missing.");

        var cachedResult = _cacheService.Get<XPathNavigator>(xmlDocumentPath);

        if (cachedResult == null)
        {
            using (var xmlReader = XmlReader.Create(xmlDocumentPath))
            {
                var doc = new XPathDocument(xmlReader);
                cachedResult = doc.CreateNavigator();
                _cacheService.Set(xmlDocumentPath, cachedResult, TimeSpan.FromMinutes(10));
            }
        }

        try
        {
            var namespaceManager = new XmlNamespaceManager(cachedResult.NameTable);
            namespaceManager.AddNamespace("ns", namespaceUri);

            var nodeIterator = cachedResult.Select(xpathQuery, namespaceManager);

            if (!nodeIterator.MoveNext())
                throw new InvalidOperationException($"No element found with the XPath query: {xpathQuery}");

            if (nodeIterator.MoveNext())
                throw new InvalidOperationException($"Multiple elements found with the XPath query: {xpathQuery}");

            return nodeIterator.Current;
        }
        catch (XPathException ex)
        {
            throw new InvalidOperationException("Invalid XPath query.", ex);
        }
    }
}
