#include <iostream>
#include <fstream>
#include <sstream>
#include <cstdarg>
#include <mutex>
#include <thread>
#include <chrono>

enum RecorderType { DATABASE, FILE, PAYMENT_PROCESSOR };

class DatabaseRecorder {
public:
    int record(const std::string& details) {
        // Simulate database connection and recording
        if (/* database connection failure */) {
            return -1; // Error code for database connection failure
        }
        std::cout << "Recording to database: " << details << std::endl;
        return 0; // Success
    }
};

class LogFileRecorder {
public:
    int record(const std::string& details) {
        static std::ofstream logFile("transaction.log", std::ios::app);
        if (!logFile.is_open()) {
            return -2; // Error code for log file opening failure
        }
        logFile << "Recording to log: " << details << std::endl;
        return 0; // Success
    }
};

class PaymentProcessor {
public:
    int process(const std::string& details) {
        // Simulate payment processing API call
        if (/* API call failure */) {
            return -3; // Error code for API failure
        }
        std::cout << "Processing payment: " << details << std::endl;
        return 0; // Success
    }
};

class TransactionRecorder {
private:
    DatabaseRecorder dbRecorder;
    LogFileRecorder fileRecorder;
    PaymentProcessor paymentProcessor;

    static std::mutex mutex;

public:
    int recordTransaction(bool shouldRecord, RecorderType type, const std::string& details) {
        if (!shouldRecord) return 0; // No recording needed

        switch (type) {
            case DATABASE: {
                std::lock_guard<std::mutex> lock(mutex);
                return dbRecorder.record(details);
            }
            case FILE: {
                std::lock_guard<std::mutex> lock(mutex);
                return fileRecorder.record(details);
            }
            case PAYMENT_PROCESSOR: {
                std::lock_guard<std::mutex> lock(mutex);
                return paymentProcessor.process(details);
            }
        }
        return -4; // Invalid recorder type
    }
};

std::mutex TransactionRecorder::mutex;

int recordTransaction(bool shouldRecord, RecorderType type, const std::string& details, ...) {
    static TransactionRecorder recorder;
    va_list args;
    va_start(args, details);
    int result = recorder.recordTransaction(shouldRecord, type, details);
    va_end(args);
    return result;
}
