<?php

class ClinicManager {
    private $db;
    private $weatherAPIKey;
    private $notificationService;
    private $sensorSystem;

    public function __construct($databaseConnection, $weatherAPIKey, $notificationService, $sensorSystem) {
        $this->db = $databaseConnection;
        $this->weatherAPIKey = $weatherAPIKey;
        $this->notificationService = $notificationService;
        $this->sensorSystem = $sensorSystem;
    }

    public function manageClinicOperations($operation, $data) {
        try {
            switch ($operation) {
                case 'create':
                    return $this->createClinicRecord($data);
                case 'update':
                    return $this->updateClinicRecord($data);
                case 'delete':
                    return $this->deleteClinicRecord($data['id']);
                default:
                    throw new Exception("Invalid operation");
            }
        } catch (Exception $e) {
            // Log the error and handle it gracefully
            error_log($e->getMessage());
            return false;
        }
    }

    private function createClinicRecord($data) {
        // SQL query to insert a new clinic record into the database
        // Example: INSERT INTO clinics (name, location, capacity) VALUES (:name, :location, :capacity)
        $stmt = $this->db->prepare("INSERT INTO clinics (name, location, capacity) VALUES (:name, :location, :capacity)");
        $stmt->execute($data);
        return $stmt->rowCount() > 0;
    }

    private function updateClinicRecord($data) {
        // SQL query to update clinic record in the database
        // Example: UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = :date WHERE id = :id
        $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = :date WHERE id = :id");
        $stmt->execute($data);

        if ($stmt->rowCount() > 0) {
            $this->handleStatusChange($data['id'], $data['status']);
            return true;
        }
        return false;
    }

    private function deleteClinicRecord($id) {
        // SQL query to delete clinic record and associated data from the database
        // Example: DELETE FROM clinics WHERE id = :id
        $stmt = $this->db->prepare("DELETE FROM clinics WHERE id = :id");
        $stmt->execute(['id' => $id]);

        if ($stmt->rowCount() > 0) {
            $this->sensorSystem->cleanupSensorData($id);
            return true;
        }
        return false;
    }

    private function handleStatusChange($clinicId, $newStatus) {
        $currentStatus = $this->getClinicStatus($clinicId);

        if ($newStatus != $currentStatus) {
            if ($newStatus == 'closed' || $newStatus == 'emergency') {
                $this->notifyExternalAPI($clinicId, $newStatus);
                $this->notificationService->sendEmailToEmergencyTeam($clinicId, $newStatus);

                // Update clinic's occupancy levels based on IoT sensor data
                $occupancyData = $this->sensorSystem->getOccupancyData($clinicId);
                $this->updateClinicOccupancy($clinicId, $occupancyData);

                if ($newStatus == 'closed' && $currentStatus == 'open') {
                    // Re-schedule all previously canceled appointments
                    $this->reScheduleCancellations($clinicId);
                }
            } elseif ($newStatus == 'open') {
                // Automatically re-schedule all previously canceled appointments based on the available slots
                $this->reScheduleCancellations($clinicId);
            }
        }
    }

    private function getClinicStatus($id) {
        // SQL query to retrieve the current status of a clinic
        // Example: SELECT status FROM clinics WHERE id = :id
        $stmt = $this->db->prepare("SELECT status FROM clinics WHERE id = :id");
        $stmt->execute(['id' => $id]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);
        return $result ? $result['status'] : null;
    }

    private function notifyExternalAPI($clinicId, $status) {
        // Code to send a notification to an external API about the clinic's status change
    }

    private function updateClinicOccupancy($id, $occupancyData) {
        // SQL query to update the clinic's occupancy levels in the database
        // Example: UPDATE clinics SET occupancy = :occupancy WHERE id = :id
        $stmt = $this->db->prepare("UPDATE clinics SET occupancy = :occupancy WHERE id = :id");
        $stmt->execute(['id' => $id, 'occupancy' => $occupancyData['capacity'], 'last_modified_ip' => $_SERVER['REMOTE_ADDR'], 'last_modified_date' => date('Y-m-d H:i:s')]);
    }

    private function reScheduleCancellations($clinicId) {
        // Code to automatically re-schedule all previously canceled appointments based on the available slots
    }
}
