using System;
using System.Diagnostics;
using System.IO;
using System.Net.NetworkInformation;
using System.Text.RegularExpressions;

public class SiteManager
{
    private static readonly string LogFilePath = "C:\\Logs\\SiteManager.log";
    private static readonly int MaxRetries = 3;
    private static readonly int RetryDelay = 5000; // milliseconds

    public void AddAndStartSite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            LogError($"Invalid path: {directoryPath}");
            return;
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            LogError("Web.config file is missing.");
            return;
        }

        string uniqueSiteName = GetUniqueSiteName(siteName, directoryPath);

        try
        {
            var processInfo = new ProcessStartInfo
            {
                FileName = "iisexpress",
                Arguments = $"path=\"{directoryPath}\" apphostconfig=\"{uniqueSiteName}.xml\"",
                RedirectStandardOutput = true,
                UseShellExecute = false
            };

            using (var process = new Process { StartInfo = processInfo })
            {
                LogInformation($"Starting site '{uniqueSiteName}' from directory '{directoryPath}'");
                for (int attempt = 0; attempt < MaxRetries; attempt++)
                {
                    try
                    {
                        process.Start();
                        LogInformation("Site started successfully.");
                        return;
                    }
                    catch (Exception ex)
                    {
                        if (attempt == MaxRetries - 1)
                        {
                            LogError($"Failed to start site after {MaxRetries} attempts: {ex.Message}");
                        }
                        else
                        {
                            LogWarning($"Attempt {attempt + 1} failed, retrying in {RetryDelay / 1000}s...");
                            System.Threading.Thread.Sleep(RetryDelay);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError($"Error occurred: {ex.Message}");
        }
    }

    private string GetUniqueSiteName(string siteName, string directoryPath)
    {
        if (!Directory.EnumerateDirectories(directoryPath, $"*{siteName}*").Any())
        {
            return siteName;
        }

        int counter = 1;
        while (true)
        {
            string uniqueName = $"{siteName}_{counter}";
            if (!Directory.EnumerateDirectories(directoryPath, $"*{uniqueName}*").Any())
            {
                return uniqueName;
            }
            counter++;
        }
    }

    private void LogInformation(string message)
    {
        File.AppendAllText(LogFilePath, $"{DateTime.Now}: [INFO] {message}\n");
    }

    private void LogWarning(string message)
    {
        File.AppendAllText(LogFilePath, $"{DateTime.Now}: [WARNING] {message}\n");
    }

    private void LogError(string message)
    {
        File.AppendAllText(LogFilePath, $"{DateTime.Now}: [ERROR] {message}\n");
    }
}
