```java
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;

public class MD5Hasher {
    private final ExecutorService executor;
    private final LoadingCache<String, String> cache;
    private static final int DEFAULT_MAX_THREADS = 10;
    private static final int DEFAULT_CACHE_SIZE = 1000;

    public MD5Hasher(int maxThreads, int cacheSize) {
        this.executor = Executors.newFixedThreadPool(maxThreads);
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(cacheSize)
                .build(new CacheLoader<String, String>() {
                    @Override
                    public String load(String key) throws Exception {
                        return computeHash(key);
                    }
                });
    }

    public String getMD5Hash(String input) throws InterruptedException, ExecutionException {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Input must not be null and must not exceed 1000 characters");
        }
        return cache.get(input);
    }

    private String computeHash(String key) throws NoSuchAlgorithmException, IOException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(key.getBytes());
        byte[] digest = md.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        executor.shutdownNow();
    }

    // Unit tests can be added here to test the functionality
}
```

This code snippet provides a basic structure for implementing an MD5 hash computation service with caching and asynchronous processing. It uses the `ConcurrentHashMap` and `ExecutorService` to manage caching and threading, respectively. The `CacheLoader` is used to compute MD5 hashes when they are not already cached. Error handling and validation are also included, along with a method to shut down the thread pool when it's no longer needed.

