#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>

// Function to dynamically extend OpenSSL library with support for AES, Camellia, MD5, SHA, and RSA
int extend_openssl_library() {
    // Initialize OpenSSL library
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    // Load AES cipher
    EVP_CIPHER *aes_cipher = EVP_aes_256_cbc();
    if (!aes_cipher) {
        return -1;
    }

    // Load Camellia cipher
    EVP_CIPHER *camellia_cipher = EVP_camellia_256_cbc();
    if (!camellia_cipher) {
        return -1;
    }

    // Load MD5 hash function
    EVP_MD *md5_md = EVP_md5();
    if (!md5_md) {
        return -1;
    }

    // Load SHA hash functions
    EVP_MD *sha1_md = EVP_sha1();
    EVP_MD *sha256_md = EVP_sha256();
    if (!sha1_md || !sha256_md) {
        return -1;
    }

    // Load RSA with SHA1 primitives
    EVP_PKEY_CTX *rsa_ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL);
    if (!rsa_ctx || EVP_PKEY_keygen_init(rsa_ctx) != 1) {
        return -1;
    }
    EVP_PKEY *rsa_key = NULL;
    if (EVP_PKEY_generate_key(rsa_ctx, &rsa_key) != 1) {
        EVP_PKEY_CTX_free(rsa_ctx);
        return -1;
    }

    // Clean up
    EVP_CIPHER_free(aes_cipher);
    EVP_CIPHER_free(camellia_cipher);
    EVP_MD_free(md5_md);
    EVP_MD_free(sha1_md);
    EVP_MD_free(sha256_md);
    EVP_PKEY_CTX_free(rsa_ctx);

    return 0;
}
