// Define regular expressions for Old Testament and New Testament books
const oldTestamentRegex = /(genesis|exodus|leviticus|numbers|deuteronomy|joshua|judges|ruth|1\s*corinthians|2\s*corinthians|galatians|ephesians|philippians|colossians|1\s*thessalonians|2\s*thessalonians|1\s*timothy|2\s*timothy|titus|philemon|hebrews|james|1\s*peter|2\s*peter|1\s*john|2\s*john|3\s*john|jude)/gi;
const newTestamentRegex = /(matthew|mark|luke|john|acts|romans|corinthians|galatians|ephesians|philippians|colossians|1\s*thessalonians|2\s*thessalonians|1\s*timothy|2\s*timothy|titus|philemon|hebrews|james|1\s*peter|2\s*peter|1\s*john|2\s*john|3\s*john|jude)/gi;

// Define a function to extract biblical book names from text
function extractBiblicalBooks(text) {
    // Check if input is valid
    if (typeof text !== 'string' || !text.trim()) {
        throw new Error('Invalid input: Please provide a non-empty string.');
    }

    // Initialize counters for each book
    const oldTestamentCounters = {};
    const newTestamentCounters = {};

    // Extract Old Testament books and count occurrences
    text.match(oldTestamentRegex).forEach(book => {
        const cleanBookName = book.replace(/[^a-z0-9]/gi, '').toLowerCase();
        if (oldTestamentBooks.includes(cleanBookName)) {
            oldTestamentCounters[cleanBookName] = (oldTestamentCounters[cleanBookName] || 0) + 1;
        }
    });

    // Extract New Testament books and count occurrences
    text.match(newTestamentRegex).forEach(book => {
        const cleanBookName = book.replace(/[^a-z0-9]/gi, '').toLowerCase();
        if (newTestamentBooks.includes(cleanBookName)) {
            newTestamentCounters[cleanBookName] = (newTestamentCounters[cleanBookName] || 0) + 1;
        }
    });

    // Combine counters and return the result
    return { ...oldTestamentCounters, ...newTestamentCounters };
}

// Define arrays of Old Testament and New Testament book names
const oldTestamentBooks = [
    'genesis', 'exodus', 'leviticus', 'numbers', 'deuteronomy', 'joshua', 'judges', 'ruth',
    '1 corinthians', '2 corinthians', 'galatians', 'ephesians', 'philippians', 'colossians',
    '1 thessalonians', '2 thessalonians', '1 timothy', '2 timothy', 'titus', 'philemon',
    'hebrews', 'james', '1 peter', '2 peter', '1 john', '2 john', '3 john', 'jude'
];

const newTestamentBooks = [
    'matthew', 'mark', 'luke', 'john', 'acts', 'romans', 'corinthians', 'galatians',
    'ephesians', 'philippians', 'colossians', '1 thessalonians', '2 thessalonians',
    '1 timothy', '2 timothy', 'titus', 'philemon', 'hebrews', 'james', '1 peter',
    '2 peter', '1 john', '2 john', '3 john', 'jude'
];

// Example usage
try {
    const inputText = "In Genesis, God created the heavens and the earth. John wrote in Revelation.";
    const result = extractBiblicalBooks(inputText);
    console.log(result); // Output: { genesis: 1, jesus: 1 }
} catch (error) {
    console.error(error.message);
}
