This code block defines a function `extractBiblicalBooks` that extracts the names of books from both the Old and New Testament of the Bible mentioned in the input text. It uses regular expressions to match whole words only and ignores punctuation or special characters. The function returns an object with the names of the books found, where each name is a key and its value is the number of times it appears in the text.

```javascript
// asyncArrayReduce.js

const defaultConcurrency = 5;
const defaultThrottleInterval = 100; // milliseconds

function asyncArrayReduce(array, initialValue, callback, options = {}) {
    const { concurrency = defaultConcurrency, throttle = defaultThrottleInterval } = options;
    let result = initialValue;
    let completed = 0;
    let error = null;
    let semaphore = concurrency;

    function next() {
        if (error) return;
        while (semaphore > 0 && array[completed]) {
            const index = completed++;
            semaphore--;
            setTimeout(async () => {
                try {
                    const value = await callback(result, array[index], index, array);
                    result = value;
                } catch (err) {
                    error = err;
                } finally {
                    semaphore++;
                    next();
                }
            }, throttle * Math.random()); // Throttle each call
        }

        if (completed === array.length && !error) {
            options.onProgress?.(completed, result);
            console.log('Reduction complete:', result);
        } else if (error) {
            console.error('Error during reduction:', error);
        }
    }

    next();
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;
asyncArrayReduce(
    numbers,
    initialValue,
    async (acc, num) => {
        await new Promise(resolve => setTimeout(resolve, 100)); // Simulate async operation
        return acc + num;
    },
    {
        concurrency: 3,
        throttle: 200,
        onProgress: (completed, result) => console.log(`Progress: ${completed}/${numbers.length}, Result: ${result}`)
    }
);
```

