      return Promise.all(cleanupFunctions.map((fn, i) => fn(i))).then(() => Promise.resolve());
    }
    return new Promise((resolve, reject) => {
      dataSources[index]((err, data) => {
        if (err) {
          reject(err);
        } else {
          resolve(data);
        }
      });
    }).then(data => fetchData(index + 1));
  }

  function runTest(index) {
    if (index >= testLabels.length) {
      return Promise.resolve();
    }
    const testLabel = testLabels[index];
    const testFunction = testFunctions[index];

    console.log(`Running test ${testLabel}`);

    return new Promise((resolve, reject) => {
      const startTime = Date.now();
      testFunction(blueslip, dataSources, (err, result) => {
        if (err) {
          console.error(`Test ${testLabel} failed:`, err);
          reject(err);
        } else {
          const endTime = Date.now();
          console.log(`Test ${testLabel} passed in ${endTime - startTime}ms`);
          resolve(result);
        }
      });
    }).then(runTest.bind(null, index + 1));
  }

  fetchData(0)
    .then(runTest.bind(null, 0))
    .then(() => {
      blueslip.reset();
    })
    .catch(err => {
      console.error(`Test failed:`, err);
      blueslip.reset();
    });
}
