public class TripleDesDecryptor : IDisposable
{
    private ConcurrentDictionary<string, KeyIvPair> _keyCache = new ConcurrentDictionary<string, KeyIvPair>();
    private ICryptoServiceProvider _csp;

    public TripleDesDecryptor(ICryptoServiceProvider csp)
    {
        _csp = csp ?? throw new ArgumentNullException(nameof(csp));
    }

    ~TripleDesDecryptor()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _csp.Dispose();
        }
    }

    public string DecryptMessage(string base64EncodedMessage, string context)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage) || string.IsNullOrEmpty(context))
        {
            throw new ArgumentException("Base64 encoded message and context cannot be null or empty.");
        }

        try
        {
            var keyIvPair = _keyCache.GetOrAdd(context, FetchKeyAndIV);
            using (TripleDES tripleDes = TripleDES.Create())
            {
                tripleDes.Key = keyIvPair.Key;
                tripleDes.IV = keyIvPair.IV;
                tripleDes.Mode = CipherMode.CBC;
                tripleDes.Padding = PaddingMode.PKCS7;

                byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
                ICryptoTransform decryptor = tripleDes.CreateDecryptor();
                using (MemoryStream ms = new MemoryStream(encryptedBytes))
                {
                    using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader sr = new StreamReader(cs))
                        {
                            return sr.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private KeyIvPair FetchKeyAndIV(string context)
    {
        // Implement logic to fetch key and IV from the custom CSP API
        // For example:
        byte[] key = _csp.GetExportedKey("TripleDES", true);
        byte[] iv = _csp.GetExportedKey("TripleDESIV", true);
        return new KeyIvPair(key, iv);
    }

    private void LogError(Exception ex)
    {
        // Implement logging logic here
        Console.WriteLine($"Error: {ex.Message}");
    }
}

internal struct KeyIvPair
{
    public byte[] Key;
    public byte[] IV;

    public KeyIvPair(byte[] key, byte[] iv)
    {
        Key = key;
        IV = iv;
    }
