#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define SEMAPHORE_MAX_VALUE 100
#define NUM_SEMAPHORES 100

typedef struct {
    char name[256];
    sem_t semaphore;
} Semaphore;

Semaphore semaphores[NUM_SEMAPHORES];

void init_semaphore_system() {
    for (int i = 0; i < NUM_SEMAPHORES; i++) {
        snprintf(semaphores[i].name, sizeof(semaphores[i].name), "semaphore_%d", i);
        sem_init(&semaphores[i].semaphore, 0, SEMAPHORE_MAX_VALUE);
    }
}

void destroy_semaphore_system() {
    for (int i = 0; i < NUM_SEMAPHORES; i++) {
        sem_destroy(&semaphores[i].semaphore);
    }
}

Semaphore* create_semaphore(const char* name) {
    for (int i = 0; i < NUM_SEMAPHORES; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            return &semaphores[i];
        }
    }
    return NULL;
}

void delete_semaphore(Semaphore* semaphore) {
    sem_destroy(&semaphore->semaphore);
}

int increment_semaphore(Semaphore* semaphore) {
    if (semaphore == NULL) {
        return -1;
    }
    if (sem_post(&semaphore->semaphore) != 0) {
        return -1;
    }
    return 0;
}

int decrement_semaphore(Semaphore* semaphore) {
    if (semaphore == NULL) {
        return -1;
    }
    if (sem_wait(&semaphore->semaphore) != 0) {
        return -1;
    }
    return 0;
}
