```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicTripleDesDecryptor
{
    private readonly ICspService _cspService;
    private readonly IKeyCache _keyCache;
    private readonly ILogger _logger;

    public DynamicTripleDesDecryptor(ICspService cspService, IKeyCache keyCache, ILogger logger)
    {
        _cspService = cspService ?? throw new ArgumentNullException(nameof(cspService));
        _keyCache = keyCache ?? throw new ArgumentNullException(nameof(keyCache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public string DecryptMessage(string base64EncodedMessage, string contextId)
    {
        try
        {
            var (key, iv) = FetchKeys(contextId);
            using (var decryptor = CreateDecryptor(key, iv))
            {
                var decryptedBytes = decryptor.TransformFinalBlock(Convert.FromBase64String(base64EncodedMessage), 0, Convert.FromBase64String(base64EncodedMessage).Length);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to decrypt message");
            throw;
        }
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId)
    {
        try
        {
            var (key, iv) = await FetchKeysAsync(contextId);
            using (var decryptor = CreateDecryptor(key, iv))
            {
                var decryptedBytes = decryptor.TransformFinalBlock(Convert.FromBase64String(base64EncodedMessage), 0, Convert.FromBase64String(base64EncodedMessage).Length);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to decrypt message asynchronously");
            throw;
        }
    }

    private SymmetricAlgorithm CreateDecryptor(byte[] key, byte[] iv)
    {
        using (var tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = key;
            tdes.IV = iv;
            tdes.Mode = CipherMode.CBC;
            return tdes.CreateDecryptor();
        }
    }

    private (byte[], byte[]) FetchKeys(string contextId)
    {
        if (_keyCache.TryGetValue(contextId, out var cachedKey))
        {
            return cachedKey;
        }

        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                var keyAndIv = _cspService.GetKeysForContext(contextId);
                _keyCache.Add(contextId, keyAndIv);
                return keyAndIv;
            }
            catch (Exception ex)
            {
                if (attempt == 2)
                {
                    _logger.LogError(ex, "Failed to fetch keys after multiple attempts");
                    throw;
                }

                Task.Delay(100 * (int)Math.Pow(2, attempt)).Wait();
            }
        }

        throw new InvalidOperationException("Fetching keys failed despite retries");
    }

    private async Task<(byte[], byte[])> FetchKeysAsync(string contextId)
    {
        if (_keyCache.TryGetValue(contextId, out var cachedKey))
        {
            return cachedKey;
        }

        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                var keyAndIv = await _cspService.GetKeysForContextAsync(contextId);
                _keyCache.Add(contextId, keyAndIv);
                return keyAndIv;
            }
            catch (Exception ex)
            {
                if (attempt == 2)
                {
                    _logger.LogError(ex, "Failed to fetch keys asynchronously after multiple attempts");
                    throw;
                }

                await Task.Delay(100 * (int)Math.Pow(2, attempt));
            }
        }

        throw new InvalidOperationException("Fetching keys failed despite retries");
    }
}

public interface ICspService
{
    (byte[] key, byte[] iv) GetKeysForContext(string contextId);
    Task<(byte[] key, byte[] iv)> GetKeysForContextAsync(string contextId);
}

public interface IKeyCache
{
    bool TryGetValue(string contextId, out (byte[], byte[]) cachedKey);
    void Add(string contextId, (byte[] key, byte[] iv) keyAndIv);
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
