import java.util.HashMap;
import java.util.Map;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;

public class ThemeCacheManager {
    private static final int MAX_CACHED_BITMAPS = 100;
    private static final String DEFAULT_THEME_DIR = "/default_theme";
    private Map<String, Bitmap> cacheMap;
    private File themeDir;

    public ThemeCacheManager() {
        cacheMap = new HashMap<>();
        themeDir = new File(getDefaultThemeDir());
    }

    private String getDefaultThemeDir() {
        // Implement fallback logic here
        return DEFAULT_THEME_DIR;
    }

    private boolean isDirectoryAvailable(File dir) {
        return dir.exists() && dir.isDirectory();
    }

    public Bitmap getThemeBitmap(String themeName) throws IOException {
        if (cacheMap.containsKey(themeName)) {
            return cacheMap.get(themeName);
        } else if (!isDirectoryAvailable(themeDir)) {
            throw new IOException("Theme directory is not available.");
        }
        File bitmapFile = new File(themeDir, themeName + ".png");
        if (!bitmapFile.exists()) {
            throw new IOException("Bitmap file does not exist.");
        }
        Bitmap bitmap = BitmapFactory.decodeFile(bitmapFile.getAbsolutePath());
        cacheMap.put(themeName, bitmap);
        evictLeastRecentlyUsed();
        return bitmap;
    }

    private void evictLeastRecentlyUsed() {
        // Implement LRU eviction logic here
        if (cacheMap.size() > MAX_CACHED_BITMAPS) {
            String[] keys = new String[cacheMap.keySet().size()];
            cacheMap.keySet().toArray(keys);
            for (int i = 0; i < MAX_CACHED_BITMAPS - cacheMap.size(); i++) {
                cacheMap.remove(keys[i]);
            }
        }
    }

    public void clearCache() {
        cacheMap.clear();
    }
}
