using System;
using System.Collections.Generic;
using System.Xml.XPath;

public class XmlParser
{
    private Dictionary<string, XPathNodeIterator> cache = new Dictionary<string, XPathNodeIterator>();

    public List<string> ExtractData(string xml, string xpathExpression)
    {
        if (cache.ContainsKey(xpathExpression))
        {
            return ParseCachedData(cache[xpathExpression]);
        }

        try
        {
            XPathDocument doc = new XPathDocument(new System.IO.StringReader(xml));
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select(xpathExpression);

            List<string> data = new List<string>();
            while (nodes.MoveNext())
            {
                data.Add(nodes.Current.Value);
            }

            if (data.Count == 0)
            {
                throw new InvalidOperationException("No data found for the specified XPath expression.");
            }
            else if (data.Count > 1)
            {
                throw new InvalidOperationException("Multiple matching nodes found. Please specify a more specific XPath expression.");
            }

            cache[xpathExpression] = navigator.Select(xpathExpression);
            return ParseCachedData(cache[xpathExpression]);
        }
        catch (Exception ex)
        {
            throw new Exception("Error parsing XML or executing XPath query: " + ex.Message);
        }
    }

    private List<string> ParseCachedData(XPathNodeIterator nodes)
    {
        List<string> data = new List<string>();
        while (nodes.MoveNext())
        {
            data.Add(nodes.Current.Value);
        }
        return data;
    }

    public void ValidateData(string xml, string xpathExpression, string expectedValue)
    {
        try
        {
            XPathDocument doc = new XPathDocument(new System.IO.StringReader(xml));
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select(xpathExpression);

            if (!nodes.MoveNext() || nodes.Current.Value != expectedValue)
            {
                throw new InvalidOperationException("Data validation failed. Expected: " + expectedValue + ", Found: " + (nodes.MoveNext() ? nodes.Current.Value : "null"));
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Error validating XML data: " + ex.Message);
        }
    }
}
