import java.util.HashMap;
import java.util.Map;
import java.util.Random;

// Base class for JSON object parsing and creation
class JsonObjectParser {
    private static final Map<String, FactoryFunction> factoryRegistry = new HashMap<>();
    private static final Random random = new Random();
    private static final int MIN_DELAY = 5000; // Minimum delay in milliseconds
    private static final int MAX_DELAY = 10000; // Maximum delay in milliseconds
    private static boolean isServiceRunning = false;

    public static void addFactoryFunction(String id, FactoryFunction factory) {
        factoryRegistry.put(id, factory);
    }

    public static <T> T createInstanceFromJsonString(String id, String json) {
        FactoryFunction factory = factoryRegistry.get(id);
        if (factory != null) {
            return factory.create(json);
        }
        throw new IllegalArgumentException("No factory function found for ID: " + id);
    }

    public static void startService() {
        synchronized (JsonObjectParser.class) {
            if (!isServiceRunning) {
                isServiceRunning = true;
                Thread serviceThread = new Thread(() -> {
                    while (isServiceRunning) {
                        try {
                            int delay = random.nextInt(MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
                            Thread.sleep(delay);
                            System.out.println("Service started. Delay: " + delay + " ms");
                            // Simulate work
                            Thread.sleep(2000);
                            System.out.println("Service stopped.");
                            // Log stop event
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                            break;
                        }
                    }
                });
                serviceThread.start();
            }
        }
    }

    public static void stopService() {
        synchronized (JsonObjectParser.class) {
            isServiceRunning = false;
            try {
                System.out.println("Shutting down service gracefully.");
                // Perform graceful shutdown
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    @FunctionalInterface
    public interface FactoryFunction<T> {
        T create(String json);
    }
}

