public class JsonServiceRunner {
    public static void main(String[] args) {
        JsonObjectParser.addFactoryFunction("user", UserObjectParser::new);
        JsonObjectParser.startService();
        try {
            Thread.sleep(20000); // Run for 20 seconds
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        JsonObjectParser.stopService();
    }
}
