[ApiController]
[Route("api/[controller]")]
public class ConfigurationController : ControllerBase
{
    private readonly IConfigurationService _configurationService;
    private static readonly ConcurrentDictionary<string, string> Cache = new();
    private readonly IVersionControlApi _versionControlApi;
    private readonly ILogger<ConfigurationController> _logger;

    public ConfigurationController(IConfigurationService configurationService,
                                  IVersionControlApi versionControlApi,
                                  ILogger<ConfigurationController> logger)
    {
        _configurationService = configurationService;
        _versionControlApi = versionControlApi;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateUserConfiguration(int userId, string configName, string newValue)
    {
        try
        {
            if (userId <= 0 || string.IsNullOrEmpty(configName) || string.IsNullOrEmpty(newValue))
            {
                return BadRequest("Invalid input parameters.");
            }

            var cacheKey = $"{userId}_{configName}";
            var cachedValue = Cache.TryGetValue(cacheKey, out _);

            // Check if the configuration exists and update it
            var updateResult = await _configurationService.UpdateConfigurationAsync(userId, configName, newValue);
            if (updateResult)
            {
                Cache.TryUpdate(cacheKey, newValue, cachedValue ? newValue : null);
                _versionControlApi.LogChange($"User {userId} updated config '{configName}' to '{newValue}'.");
                _logger.LogInformation("Configuration updated successfully.");
                return Ok(new { message = "Configuration updated." });
            }
            else
            {
                _logger.LogWarning("Failed to update configuration.");
                return StatusCode(500, "Internal server error.");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating the configuration.");
            return StatusCode(500, "Internal server error.");
        }
    }
}
