```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SSHCommandExecutor {
    private ExecutorService executorService;
    private ConfigurationManager configManager;
    private LogSystem logSystem;

    public SSHCommandExecutor() {
        this.executorService = Executors.newFixedThreadPool(10);
        this.configManager = new ConfigurationManager();
        this.logSystem = new LogSystem();
    }

    public void executeCommands(List<String> serverIds, List<String> commands) throws InterruptedException {
        for (String serverId : serverIds) {
            executorService.submit(() -> processServer(serverId, commands));
        }
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.HOURS);
    }

    private void processServer(String serverId, List<String> commands) {
        ServerDetails server = configManager.getServerDetails(serverId);
        for (String command : commands) {
            try {
                executeCommandWithTimeout(server, command, 30);
                logSystem.logSuccess(server.getId(), command);
            } catch (Exception e) {
                handleFailure(server, command, e);
            }
        }
    }

    private void executeCommandWithTimeout(ServerDetails server, String command, int timeout)
            throws InterruptedException {
        Process process = Runtime.getRuntime().exec(command);
        if (!process.waitFor(timeout, TimeUnit.SECONDS)) {
            process.destroy();
            throw new RuntimeException("Command timed out");
        }
    }

    private void handleFailure(ServerDetails server, String command, Exception e) {
        logSystem.logFailure(server.getId(), command, e.getMessage());
        int retries = 3;
        for (int attempt = 1; attempt <= retries; attempt++) {
            try {
                TimeUnit.SECONDS.sleep((long) Math.pow(2, attempt));
                executeCommandWithTimeout(server, command, 30);
                logSystem.logSuccess(server.getId(), command);
                return;
            } catch (InterruptedException | RuntimeException ex) {
                continue;
            }
        }
        // Fallback to backup server
        ServerDetails backupServer = configManager.getBackupServer(server.getId());
        if (backupServer != null) {
            try {
                executeCommandWithTimeout(backupServer, command, 30);
                logSystem.logSuccess(backupServer.getId(), command);
            } catch (Exception ex) {
                logSystem.logFailure(backupServer.getId(), command, ex.getMessage());
            }
        }
    }

    // Additional methods for web interface integration and maintenance
}
