        _logger = logger;
        _cacheService = cacheService;
        _rateLimiter = rateLimiter;
    }

    public async Task<string> UpdateContentAsync(int pageSectionId, string elementId, string htmlContent)
    {
        if (!_rateLimiter.AllowRequest(pageSectionId))
        {
            return "Rate limit exceeded.";
        }

        try
        {
            var isValidPageSection = await ValidatePageSectionAsync(pageSectionId);
            if (!isValidPageSection)
                return "Invalid page section ID.";

            var isValidElement = await ValidateElementAsync(elementId);
            if (!isValidElement)
                return "Invalid element ID.";

            var contentManagementResponse = await UpdateContentInServiceAsync(htmlContent);

            _logger.LogInformation($"Content updated for {pageSectionId}-{elementId}: {contentManagementResponse}");

            // Cache the updated content
            await _cacheService.SetContentAsync(pageSectionId, elementId, htmlContent);

            return "Content updated successfully.";
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to update content in service.");
            return "Transient error occurred. Please try again later.";
        }
    }

    private async Task<bool> ValidatePageSectionAsync(int pageSectionId)
    {
        // Logic to validate if the page section ID is valid
        // This might involve checking a database or an external service
        return await _cacheService.PageSectionExistsAsync(pageSectionId);
    }

    private async Task<bool> ValidateElementAsync(string elementId)
    {
        // Logic to validate if the element ID is valid
        // This might involve checking a database or an external service
        return await _cacheService.ElementExistsAsync(elementId);
    }

    private async Task<string> UpdateContentInServiceAsync(string htmlContent)
    {
        // Logic to update content in the external content management service
        // Use versioning and transactions for data consistency
        // Implement retry logic for transient failures
        var url = "https://externalcontentmanager.com/update";
        var content = new StringContent(htmlContent, System.Text.Encoding.UTF8, "application/json");

        var response = await _httpClient.PostAsync(url, content);
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadAsStringAsync();
        else
            throw new HttpRequestException($"Failed to update content in service: {response.StatusCode}");
    }
}
