public class XmlParser
{
    private XPathDocument _xmlDocument;
    private Dictionary<string, XPathDocument> _cache = new Dictionary<string, XPathDocument>();

    public XmlParser(string configFilePath)
    {
        LoadConfig(configFilePath);
    }

    private void LoadConfig(string filePath)
    {
        // Load and parse the configuration file to get the XML document path
    }

    public XPathNodeIterator GetElementByXPath(string xpath, string namespaceURI)
    {
        if (_cache.TryGetValue(_xmlDocument.DocumentUri.AbsoluteUri, out var cachedDoc))
            _xmlDocument = cachedDoc;

        try
        {
            var nav = _xmlDocument.CreateNavigator();
            var nodes = nav.Select(xpath);

            if (!nodes.MoveNext())
                throw new InvalidOperationException("No element found.");

            if (nodes.MoveNext())
                throw new InvalidOperationException("Multiple elements found.");

            return nodes;
        }
        catch (XPathException ex)
        {
            throw new InvalidOperationException("Invalid XPath query.", ex);
        }
    }

    public void CacheXmlDocument(XPathDocument doc, string key)
    {
        _cache[key] = doc;
    }

    public void EvictCacheEntry(string key)
    {
        if (_cache.ContainsKey(key))
            _cache.Remove(key);
    }
}
