import json
import importlib
from collections import defaultdict, OrderedDict
from threading import Lock
import time

class JSONBase:
    _registry = defaultdict(OrderedDict)
    _lock = Lock()

    @classmethod
    def register_factory(cls, factory_func):
        with cls._lock:
            subclass_name = factory_func.__name__
            if subclass_name not in cls._registry[cls]:
                cls._registry[cls][subclass_name] = factory_func

    @classmethod
    def get_registry(cls):
        return cls

    @classmethod
    def discover_subclasses(cls, directory):
        with cls._lock:
            for file_name in os.listdir(directory):
                if file_name.endswith('.py'):
                    module_name = file_name[:-3]
                    module_path = f"{directory}.{module_name}"
                    spec = importlib.util.spec_from_file_location(module_name, f"{module_path}.py")
                    module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(module)

    @classmethod
    def from_json(cls, json_string):
        try:
            data = json.loads(json_string)
            subclass_id = data.get('subclass_id')
            if subclass_id in cls._registry[cls]:
                factory_func = cls._registry[cls][subclass_id]
                instance = factory_func(subclass_id)
                instance.load_data(data)
                return instance
            else:
                raise ValueError("Invalid subclass ID in JSON string")
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON format") from e

    def to_json(self):
        data = self.to_dict()
        data['subclass_id'] = type(self).__name__
        return json.dumps(data)

    def load_data(self, data):
        pass

    def to_dict(self):
        return {}

# Example of subclass registration and usage
from json_base import JSONBase

@JSONBase.register_factory
def create_custom_instance(subclass_id):
    if subclass_id == 'CustomClass':
        return CustomClass()

class CustomClass(JSONBase):
    def __init__(self, data=None):
        self.data = data or {}

    def load_data(self, data):
        self.data.update(data)

    def to_dict(self):
        return {'data': self.data}

# Usage
registry = JSONBase.get_registry()
registry.discover_subclasses(directory='path_to_subclasses_directory')

json_string = '{"subclass_id": "CustomClass", "data": {"key": "value"}}'
instance = JSONBase.from_json(json_string)
print(instance.to_dict())
