```javascript
const fetch = require('node-fetch');
const Semaphore = require('semaphore-async-await');

// Define a semaphore to control the concurrency level
const semaphore = new Semaphore(5);

async function asyncArrayReduce(arr, initialValue, callback) {
    if (!Array.isArray(arr) || typeof initialValue !== 'number' || typeof callback !== 'function') {
        return Promise.reject(new Error('Invalid input'));
    }

    let result = initialValue;
    let completedOperations = 0;

    const throttlingDelay = 200; // Delay between operations to prevent hitting rate limits
    const apiToken = 'your-auth-token'; // Replace with actual token

    for (let i = 0; i < arr.length; ++i) {
        await semaphore.acquire();
        try {
            const response = await fetch('https://api.example.com/external', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${apiToken}` },
                body: JSON.stringify(arr[i]),
            });

            if (!response.ok) {
                return Promise.reject(new Error(`API request failed with status ${response.status}`));
            }

            const data = await response.json();
            result = callback(result, data);
        } catch (error) {
            semaphore.release();
            throw error;
        }

        completedOperations++;
        setTimeout(() => semaphore.release(), throttlingDelay);

        // Report progress
        if (typeof progressCallback === 'function') {
            progressCallback(completedOperations, result);
        }
    }

    return result;
}
