cache = {}
last_used = {}

def lru_cache(max_size):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            key = f"{args[0]}:{args[1]}"
            if key in last_used:
                last_used[key] = time()
            elif len(cache) >= max_size:
                lru_key = min(last_used, key=lambda k: last_used[k])
                del cache[lru_key]
                del last_used[lru_key]
            return f(*args, **kwargs)
        return wrapper
    return decorator

@app.before_request
def refresh_cache():
    user_id = request.headers.get('user-id')
    if user_id:
        invalidate_user_cache(user_id)

@lru_cache(max_size=1024)  # Adjust max_size as needed
@app.route('/profile-image', methods=['GET'])
def get_profile_image():
    user_id = request.args.get('user_id')
    image_key = f"images/{user_id}.jpg"

    if image_key in cache:
        return cache[image_key]

    try:
        response = s3_client.download_file(BUCKET_NAME, image_key, 'temp.jpg')
        with open('temp.jpg', 'rb') as file:
            image_data = file.read()

        cache[image_key] = image_data
        last_used[image_key] = time()

        os.remove('temp.jpg')
        return image_data, 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/invalidate-cache/<user_id>', methods=['POST'])
def invalidate_user_cache(user_id):
    image_key = f"images/{user_id}.jpg"
    if image_key in cache:
        del cache[image_key]
        del last_used[image_key]
    return jsonify({'message': 'Cache invalidated for user'}), 200

@app.route('/invalidate-cache', methods=['POST'])
def invalidate_all_cache():
    global cache, last_used
    cache = {}
    last_used = {}
    return jsonify({'message': 'All cache invalidated'}), 200

if __name__ == '__main__':
    app.run(debug=True)
