from io import BytesIO
import hashlib
import time

class StreamingMerger:
    def __init__(self, chunk_size=1024*1024, checksum_type='md5'):
        self.chunk_size = chunk_size
        self.checksum_type = hashlib.new(checksum_type)
        self.merged_checksum = hashlib.new(checksum_type)

    def merge_streams(self, *streams):
        start_time = time.time()
        for stream in streams:
            while True:
                data = stream.read(self.chunk_size)
                if not data:
                    break
                yield data

        end_time = time.time()
        print(f"Merge completed in {end_time - start_time:.2f} seconds")

    def update_checksums(self, data):
        self.checksum.update(data)
        self.merged_checksum.update(data)

    def get_checksums(self):
        return self.checksum.hexdigest(), self.merged_checksum.hexdigest()

    def handle_interruption(self):
        print("Handling interruption...")
        # Logic to resume merging from where it left off

# Example usage:
if __name__ == "__main__":
    merger = StreamingMerger(checksum_type='sha256')
    stream1 = BytesIO(b'Hello, ')
    stream2 = BytesIO(b'world!')

    for chunk in merger.merge_streams(stream1, stream2):
        merger.update_checksums(chunk)

    checksums = merger.get_checksums()
    print(f"Checksum of individual streams: {checksums[0]}")
    print(f"Merged checksum: {checksums[1]}")
```

