<?php

class UserManagement {
    private $dbConnection;

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function handleRequest($_REQUEST) {
        // Rate limiting logic here

        if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
            return $this->deleteUser($_REQUEST['id']);
        } else {
            $data = [
                'name' => $_REQUEST['name'],
                'email' => $_REQUEST['email'],
                'password' => $_REQUEST['password']
            ];

            if (!isset($_REQUEST['id'])) {
                return $this->createUser($data);
            } else {
                $data['id'] = $_REQUEST['id'];
                return $this->updateUser($data);
            }
        }
    }

    private function createUser($data) {
        // Validate data here

        if ($this->emailExists($data['email'])) {
            return json_encode(['message' => 'error', 'reason' => 'Email already exists']);
        }

        // Hash password and insert into database using parameterized queries
        $hashedPassword = password_hash($data['password'], PASSWORD_DEFAULT);
        $sql = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
        $stmt = $this->dbConnection->prepare($sql);
        $stmt->bind_param("sss", $data['name'], $data['email'], $hashedPassword);

        if ($stmt->execute()) {
            $this->log('User created successfully');
            return json_encode(['message' => 'success']);
        } else {
            $this->log('Failed to create user', true);
            return json_encode(['message' => 'error']);
        }
    }

    private function updateUser($data) {
        // Validate data here

        // Update database using parameterized queries
        $sql = "UPDATE users SET name = ?, email = ? WHERE id = ?";
        $stmt = $this->dbConnection->prepare($sql);
        $stmt->bind_param("ssi", $data['name'], $data['email'], $data['id']);

        if ($stmt->execute()) {
            $this->log('User updated successfully');
            return json_encode(['message' => 'success']);
        } else {
            $this->log('Failed to update user', true);
            return json_encode(['message' => 'error']);
        }
    }

    private function deleteUser($id) {
        // Delete database entry using parameterized queries
        $sql = "DELETE FROM users WHERE id = ?";
        $stmt = $this->dbConnection->prepare($sql);
        $stmt->bind_param("i", $id);

        if ($stmt->execute()) {
            $this->log('User deleted successfully');
            return json_encode(['message' => 'success']);
        } else {
            $this->log('Failed to delete user', true);
            return json_encode(['message' => 'error']);
        }
    }

    private function emailExists($email) {
        // Check if email already exists in the database using parameterized queries
        $sql = "SELECT * FROM users WHERE email = ?";
        $stmt = $this->dbConnection->prepare($sql);
        $stmt->bind_param("s", $email);
        $stmt->execute();
        $result = $stmt->get_result();

        return $result->num_rows > 0;
    }

    private function log($message, $error = false) {
        // Log successful or failed operations
        error_log($message . ($error ? ' - Error' : ''), 3, '/path/to/logfile.log');
    }
}

