import os
import tempfile
import time
from threading import Lock

log = None  # Assume this is a predefined logger object from a logging module

def initialize_config_directory(custom_parent=None):
    lock = Lock()
    config_dir = None
    attempts = 3
    delay = 2  # seconds

    def create_directory(parent, name):
        try:
            path = os.path.join(parent, name)
            if not os.path.exists(path):
                os.makedirs(path)
                return path
            else:
                log.warning(f"Directory {path} already exists.")
        except PermissionError as e:
            log.error(f"Permission denied creating directory {path}: {e}")

    for _ in range(attempts):
        if custom_parent is not None and create_directory(custom_parent, 'user_settings'):
            config_dir = os.path.join(custom_parent, 'user_settings')
            break
        elif create_directory(os.getenv('APPDATA'), 'user_settings'):
            config_dir = os.path.join(os.getenv('APPDATA'), 'user_settings')
            break
        elif create_directory(os.path.expanduser('~/.config'), 'user_settings'):
            config_dir = os.path.join(os.path.expanduser('~/.config'), 'user_settings')
            break
        else:
            time.sleep(delay)

    if config_dir is not None and lock.acquire(blocking=False):
        try:
            os.environ['USER_CONFIG_DIR'] = config_dir
        finally:
            lock.release()

    if config_dir is None:
        log.error("Failed to create user configuration directory after multiple attempts.")

    return config_dir
