angular.module('myApp').service('DialogFieldService', ['$http', '$q', 'CacheFactory', function($http, $q, CacheFactory) {
    var service = {};
    var cache = CacheFactory.createCache('dialogFieldCache');

    service.refreshFields = function(fieldNames, resourceId, url, pageLimit) {
        var promises = [];

        fieldNames.forEach(function(fieldName) {
            if (!cache.get(fieldName)) {
                promises.push(refreshField(fieldName, resourceId, url, pageLimit));
            }
        });

        return $q.all(promises);
    };

    function refreshField(fieldName, resourceId, url, pageLimit, page = 1) {
        var cacheKey = fieldName + '_' + resourceId;
        if (cache.get(cacheKey)) {
            return $q.when({ data: cache.get(cacheKey), status: 'success' });
        }

        var params = { 
            resourceId: resourceId,
            field: fieldName,
            page: page,
            limit: pageLimit
        };

        return $http.get(url, { params: params })
            .then(function(response) {
                if (response.data && response.data.status === 'success') {
                    cache.put(cacheKey, response.data.data);
                    sendRefreshStatus(fieldName, 'success');
                    return refreshField(fieldName, resourceId, url, pageLimit, page + 1);
                } else {
                    sendRefreshStatus(fieldName, 'failure');
                    return $q.reject(new Error('Failed to refresh field: ' + fieldName));
                }
            })
            .catch(function(error) {
                sendRefreshStatus(fieldName, 'failure');
                return $q.reject(error);
            });
    }

    function sendRefreshStatus(fieldName, status) {
        window.parent.postMessage({ fieldName: fieldName, status: status }, '*');
    }

    return service;
}]);
