// Asynchronous reduce() method implementation in JavaScript
async function asyncReduce(arr, initialValue, callback, concurrency = 5) {
    let result = initialValue;
    let promises = [];
    let index = 0;

    const convertToNumber = (value) => {
        const num = parseInt(value);
        if (isNaN(num)) {
            throw new Error(`Invalid number: ${value}`);
        }
        return num;
    };

    const handleCallbackError = (error, callbackIndex) => {
        console.error(`Error at index ${callbackIndex}:`, error);
        // Handle the error appropriately
    };

    while (index < arr.length) {
        for (let i = 0; i < concurrency && index < arr.length; i++, index++) {
            const currentValue = arr[index];
            const numberValue = convertToNumber(currentValue);
            promises.push(
                new Promise((resolve, reject) => {
                    callback(result, numberValue, (err, value) => {
                        if (err) {
                            reject(err);
                        } else {
                            result = value;
                            resolve();
                        }
                    }, index);
                }).catch(error => handleCallbackError(error, index))
            );
        }

        await Promise.all(promises);
        promises = [];
    }

    return result;
}

// Example usage
const array = [1, 2, '3', '4', 5];
const initialValue = 0;

asyncReduce(array, initialValue, (acc, num, callback, index) => {
    if (num === 0) {
        const error = new Error('Division by zero');
        console.error(error.message);
        return callback(error);
    }
    const result = acc + num;
    console.log(`Index ${index}:`, `Accumulated value: ${acc}, Current number: ${num}, New accumulated value: ${result}`);
    return callback(null, result);
}).then(result => {
    console.log('Final reduced value:', result);
}).catch(error => {
    console.error('Error during reduction:', error);
});
