const AWS = require('aws-sdk');
const fs = require('fs');
const path = require('path');
const Promise = require('bluebird');
const logger = require('winston');

AWS.config.update({
  accessKeyId: 'YOUR_AWS_ACCESS_KEY_ID',
  secretAccessKey: 'YOUR_AWS_SECRET_ACCESS_KEY',
  region: 'us-west-2' // Replace with your desired AWS region
});

const s3 = new AWS.S3();

function uploadFileToS3(url) {
  return Promise.resolve()
    .then(() => downloadFileFromURL(url))
    .then((fileBuffer) => uploadFileToS3Bucket(fileBuffer, path.basename(url)))
    .then((s3Response) => {
      logger.info('File uploaded successfully:', s3Response.Location);
      return s3Response.Location;
    })
    .catch((error) => {
      logger.error('Error uploading file:', error);
      throw new Error(`Failed to upload file: ${error.message}`);
    });
}

function downloadFileFromURL(url) {
  return new Promise((resolve, reject) => {
    const fileStream = fs.createWriteStream('temp-file');
    const request = require('https').get(url, (response) => {
      response.pipe(fileStream);
      fileStream.on('finish', () => {
        fileStream.close();
        resolve(fs.readFileSync('temp-file'));
      });
    }).on('error', (err) => {
      reject(err);
    });
  });
}

function uploadFileToS3Bucket(fileBuffer, fileName) {
  return new Promise((resolve, reject) => {
    const params = {
      Bucket: 'YOUR_S3_BUCKET_NAME',
      Key: fileName,
      Body: fileBuffer
    };

    s3.upload(params, (err, data) => {
      if (err) {
        reject(err);
      } else {
        resolve(data);
      }
    });
  });
}

module.exports = uploadFileToS3;
```

