    // Use PEM_read_bio_RSAPrivateKey with a passphrase callback
    rsa = PEM_read_bio_RSAPrivateKey(NULL, fp, NULL, (void*)password);
    fclose(fp);

    if (rsa == NULL) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    return rsa;
}

void cleanup_rsa_context(RSA *rsa) {
    if (rsa != NULL) {
        RSA_free(rsa);
    }
}
