#define MAX_RESOURCE_LINE_LENGTH 256

typedef struct ResourceItem {
    char* key;
    char* value;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem** items;
    int itemCount;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Failed to open resource bundle file");
        return NULL;
    }

    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return NULL;
    }
    bundle->items = NULL;
    bundle->itemCount = 0;

    char line[MAX_RESOURCE_LINE_LENGTH];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Process each line and add to the bundle
        // ...
    }

    fclose(file);
    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (int i = 0; i < bundle->itemCount; i++) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}
