import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.HashMap;
import java.util.Map;
public class JsonParser {
    private final Map<String, JsonNode> cache = new HashMap<>();
    private final ObjectMapper mapper = new ObjectMapper();
    private final HttpClient client = HttpClient.newHttpClient();

    public JsonNode parseJson(String json) throws IOException {
        JsonNode node = mapper.readTree(json);
        return cache.computeIfAbsent(json, key -> node);
    }

    public JsonNode extractData(String path, String json) throws IOException {
        JsonNode node = parseJson(json);
        JsonNode result = null;

        try {
            result = evaluatePath(path.split("\\."), node);
        } catch (Exception e) {
            throw new IOException("Error evaluating JSON path: " + path, e);
        }

        if (result == null) {
            throw new IOException("No data found at path: " + path);
        } else if (result.isArray()) {
            ArrayNode array = mapper.createArrayNode();

            for (JsonNode item : result) {
                array.add(item);
            }

            return array;
        } else {
            return result;
        }
    }

    private JsonNode evaluatePath(String[] path, JsonNode node) throws IOException {
        if (path.length == 0) {
            return node;
        }

        String key = path[0];
        JsonNode child = node.path(key);

        if (child.isMissingNode()) {
            throw new IOException("No child node found with key: " + key);
        } else if (path.length == 1) {
            return child;
        } else {
            return evaluatePath(Arrays.copyOfRange(path, 1, path.length), child);
        }
    }

    public void validateData(String url, JsonNode data) throws IOException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(data)))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            throw new IOException("Error validating data: " + response.body());
        }
    }
}
