using System;
using System.Collections.Generic;

public class RandomValueGenerator : MonoBehaviour
{
    private float minValue;
    private float maxValue;
    private int maxGenerations = 1000; // Maximum number of generations to prevent infinite loops

    public RandomValueGenerator(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        minValue = min;
        maxValue = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public List<int> GetUniqueRandomInts(int n)
    {
        if (n > (maxValue - minValue + 1))
            throw new ArgumentException("Cannot generate more unique numbers than the range allows.");

        HashSet<int> uniqueNumbers = new HashSet<int>();
        int generations = 0;

        while (uniqueNumbers.Count < n && generations < maxGenerations)
        {
            int number = GetRandomInt();
            if (!uniqueNumbers.Contains(number))
                uniqueNumbers.Add(number);
            generations++;
        }

        if (generations == maxGenerations)
            throw new InvalidOperationException("Failed to generate all unique numbers within the allowed generation limit.");

        return new List<int>(uniqueNumbers);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
