            try
            {
                // Step 7: Validate web.config content
                if (!ValidateWebConfigContent(Path.Combine(directoryPath, "web.config")))
                {
                    throw new InvalidOperationException("Invalid web.config file content.");
                }

                // Step 8-9: Retry mechanism for starting the site
