```c
FilteredTransactionResult filterAndAuthenticateTransactions(TransactionRequest request) {
    // Step 1: Authenticate the user using OAuth 2.0 client
    const char* oauthClient = authenticate(request.client_id, request.client_secret);
    if (oauthClient == NULL) {
        return (FilteredTransactionResult){NULL, -1, NULL};
    }

    // Step 2: Update session with the access token
    globalSessionAccessToken = oauthClient;

    // Step 3: Filter transactions based on criteria
    FilteredTransactionResult result = filterTransactions(request.transactionAge, request.transactionCountLast3Seconds, request.weightedSum);

    // Step 4: Combine the private key and certificate into a single PEM file
    const char* privateKeyPath = result.privateKeyPath;
    const char* certificatePath = result.certificatePath;

    FILE *privateKeyFile = fopen(privateKeyPath, "r");
    FILE *certificateFile = fopen(certificatePath, "r");

    if (privateKeyFile == NULL || certificateFile == NULL) {
        return (FilteredTransactionResult){NULL, -1, NULL};
    }

    fseek(privateKeyFile, 0, SEEK_END);
    long privateKeySize = ftell(privateKeyFile);
    fseek(privateKeyFile, 0, SEEK_SET);
    char* privateKeyBuffer = malloc((size_t)privateKeySize + 1);
    fread(privateKeyBuffer, (size_t)privateKeySize, 1, privateKeyFile);
    privateKeyBuffer[privateKeySize] = '\0';
    fclose(privateKeyFile);

    fseek(certificateFile, 0, SEEK_END);
    long certificateSize = ftell(certificateFile);
    fseek(certificateFile, 0, SEEK_SET);
    char* certificateBuffer = malloc((size_t)certificateSize + 1);
    fread(certificateBuffer, (size_t)certificateSize, 1, certificateFile);
    certificateBuffer[certificateSize] = '\0';
    fclose(certificateFile);

    // Step 5: Combine the private key and certificate into a single PEM file
    char* combinedPem = malloc((size_t)(privateKeySize + certificateSize + 6) * sizeof(char));
    snprintf(combinedPem, (size_t)(privateKeySize + certificateSize + 6), "-----BEGIN PRIVATE KEY-----\n%s\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n%s\n-----END CERTIFICATE-----", privateKeyBuffer, certificateBuffer);
    free(privateKeyBuffer);
    free(certificateBuffer);

    // Step 6: Encode the combined PEM file in base64
    char* base64Pem = b64_encode(combinedPem);

    // Step 7: Return the maximum weighted sum and corresponding transaction ID
    return (FilteredTransactionResult){base64Pem, result.maxWeightedSum, result.transactionId};
}
