                LogSuccess(source, clearanceLevel, "Decryption successful.");
                return System.Text.Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (Exception ex)
        {
            LogError($"Decryption failed: {ex.Message}");
            return $"Decryption failed: {ex.Message}";
        }
