        if (!_keyCache.TryGetValue(keyId, out var key))
        {
            try
            {
                key = FetchKeyFromCsp(_primaryCspUrl, keyId);
                _keyCache.TryAdd(keyId, key);
            }
            catch (Exception)
            {
                key = FetchKeyFromCsp(_backupCspUrl, keyId);
                _keyCache[keyId] = key;
            }
        }
