using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class AsyncDataCopier
{
    private readonly HttpClient _httpClient;
    private readonly IKeyIVProvider _keyIVProvider;
    private readonly int _maxConcurrentOperations;
    private readonly ConcurrentDictionary<string, (byte[], byte[])> _cache = new();
    private readonly SemaphoreSlim _semaphore;

    public AsyncDataCopier(IKeyIVProvider keyIVProvider, int maxConcurrentOperations = 10)
    {
        _httpClient = new HttpClient();
        _keyIVProvider = keyIVProvider;
        _maxConcurrentOperations = maxConcurrentOperations;
        _semaphore = new SemaphoreSlim(_maxConcurrentOperations);
    }

    public async Task<byte[]> CopyDataAsync(string[] chunkIds, int bytesToCopy)
    {
        var result = new byte[bytesToCopy];
        var tasks = chunkIds.Select(id => LoadChunkAsync(id)).ToArray();

        for (int i = 0; i < bytesToCopy; i++)
        {
            await Task.WhenAny(tasks);
            for (int j = 0; j < tasks.Length; j++)
            {
                if (!tasks[j].IsCompleted)
                    continue;
                result[i] = tasks[j].Result[i];
                tasks[j] = LoadChunkAsync(chunkIds[j]);
            }
        }

        return result;
    }

    private async Task<byte> LoadChunkAsync(string chunkId)
    {
        await _semaphore.WaitAsync();
        try
        {
            var dataChunk = await FetchDataFromSource(chunkId);
            var decryptedChunk = await DecryptMessage(dataChunk, chunkId);
            return decryptedChunk[0]; // Assuming each chunk is 1 byte for simplicity
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Error loading chunk {chunkId}: {ex.Message}");
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private async Task<byte[]> FetchDataFromSource(string chunkId)
    {
        // Implement logic to fetch data from the source using chunkId
        return await Task.FromResult(Encoding.UTF8.GetBytes(chunkId));
    }

    public async Task<string> DecryptMessage(string base64EncodedMessage, string contextId)
    {
        var keyIVPair = _cache.GetOrAdd(contextId, k => FetchKeyIVFromCSP(k));

        try
        {
            byte[] decryptedBytes;
            using (var msDecrypt = new MemoryStream(Convert.FromBase64String(base64EncodedMessage)))
            {
                using (var tdesAlg = TripleDES.Create())
                {
                    tdesAlg.Key = keyIVPair.Item1;
                    tdesAlg.IV = keyIVPair.Item2;
                    tdesAlg.Mode = CipherMode.CBC;
                    tdesAlg.Padding = PaddingMode.PKCS7;

                    using (var csDecrypt = new CryptoStream(msDecrypt, tdesAlg.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        decryptedBytes = await ReadFullyAsync(csDecrypt);
                    }
                }
            }

            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Error decrypting message: {ex.Message}");
            throw;
        }
    }

    private async Task<byte[]> ReadFullyAsync(Stream input)
    {
        using (var ms = new MemoryStream())
        {
            await input.CopyToAsync(ms);
            return ms.ToArray();
        }
    }

    private async Task<(byte[], byte[])> FetchKeyIVFromCSP(string contextId)
    {
        var retryCount = 0;
        while (true)
        {
            try
            {
                // Implement logic to fetch key and IV from CSP using contextId
                return (_keyIVProvider.GetKey(contextId), _keyIVProvider.GetIV(contextId));
            }
            catch (Exception ex)
            {
                if (++retryCount >= 3)
                    throw;
                await Task.Delay((int)Math.Pow(2, retryCount) * 100); // Exponential backoff
            }
        }
    }

    public void Dispose()
    {
        _httpClient.Dispose();
        _semaphore.Dispose();
    }
}

public interface IKeyIVProvider
{
    byte[] GetKey(string contextId);
    byte[] GetIV(string contextId);
}
