#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <cpr/cpr.h>

class DynamicNetworkResolver {
private:
    std::vector<std::string> dnsServers;
    std::mutex mtx;
    std::condition_variable cv;
    bool isFetching = false;

public:
    DynamicNetworkResolver(const std::vector<std::string>& servers) : dnsServers(servers) {}

    std::string resolveHostname(const std::string& hostname) {
        std::unique_lock<std::mutex> lock(mtx);
        while (isFetching) {
            cv.wait(lock);
        }

        isFetching = true;
        lock.unlock();

        auto future = std::async(std::launch::async, [this, hostname]() -> std::string {
            return fetchIP(hostname);
        });

        std::future_status status = future.wait_for(std::chrono::seconds(5));
        if (status == std::future_status::ready) {
            isFetching = false;
            lock.lock();
            cv.notify_all();
            lock.unlock();

            return future.get();
        } else {
            isFetching = false;
            lock.lock();
            cv.notify_all();
            lock.unlock();

            return "Timeout";
        }
    }

private:
    std::string fetchIP(const std::string& hostname) {
        for (const auto& server : dnsServers) {
            try {
                cpr::Response r = cpr::Get(cpr::Url{server + "/" + hostname});
                if (r.status_code == 200) {
                    return r.text;
                }
            } catch (...) {
                // Handle exception
            }
        }
        return "Failed";
    }

public:
    void updateDNS Servers(const std::vector<std::string>& servers) {
        std::unique_lock<std::mutex> lock(mtx);
        dnsServers = servers;
        cv.notify_all();
    }

    static DynamicNetworkResolver* getInstance() {
        static DynamicNetworkResolver instance({"8.8.8.8", "8.8.4.4", "1.1.1.1"}); // Example DNS servers
        return &instance;
    }
};

int main() {
    DynamicNetworkResolver* resolver = DynamicNetworkResolver::getInstance();
    std::cout << resolver->resolveHostname("google.com") << std::endl;

    // Update DNS servers from external configuration service
    resolver->updateDNS Servers({"8.8.4.4", "1.1.1.1"}); // Example new DNS servers

    return 0;
}
