char* expandWithSlash(const char* input, size_t sizeLimit, size_t bufferSize) {
    size_t inputLen = strlen(input);
    if (inputLen + 1 < sizeLimit && inputLen + 2 <= bufferSize) {
        // Append slash in place if possible
        char* result = malloc((inputLen + 2) * sizeof(char));
        if (!result) return NULL; // Memory allocation failed
        strcpy(result, input);
        result[inputLen] = '/';
        result[inputLen + 1] = '\0';
        return result;
    } else {
        // Allocate and copy truncated string if necessary
        size_t maxLen = (sizeLimit < bufferSize ? sizeLimit : bufferSize) - 1;
        char* result = malloc((maxLen + 1) * sizeof(char));
        if (!result) return NULL; // Memory allocation failed
        strncpy(result, input, maxLen);
        result[maxLen] = '\0';
        return result;
    }
}

// Example usage and testing function
int main() {
    const char* testStr = "Hello, 世界";
    size_t sizeLimit = 13;
    size_t bufferSize = 20;

    char* expanded = expandWithSlash(testStr, sizeLimit, bufferSize);
    if (expanded) {
        printf("Expanded string: %s\n", expanded);
        free(expanded); // Don't forget to free allocated memory
    } else {
        printf("Memory allocation failed or no change needed.\n");
    }

    return 0;
}
