        if (!preg_match('/[A-Z]/', $characterSet) || !preg_match('/[a-z]/', $characterSet) ||
            !preg_match('/\d/', $characterSet) || !preg_match('/[^A-Za-z\d]/', $characterSet)) {
            return false;
        }
        // Check for common patterns
        if (preg_match('/^(.)\1+$/', $characterSet) || preg_match('/^([0-9])\1+$/', $characterSet)) {
            return false;
        }
        return true;
    }

    public function setSaltRoundCount($rounds) {
        $this->saltRoundCount = max(4, min(31, (int)$rounds));
