const fs = require('fs').promises;
const path = require('path');
const pLimit = require('p-limit');

async function readDirectoryFiles(directory, extension, bufferSize, maxSize) {
  const cache = new Map();
  const limit = pLimit(10); // Limit to 10 concurrent file reads
  let totalContent = '';

  async function readFileContents(filePath) {
    if (cache.has(filePath)) {
      console.log(`Using cached content for ${filePath}`);
      return cache.get(filePath);
    }

    try {
      console.log(`Reading ${filePath}`);
      const stats = await fs.stat(filePath);
      if (stats.size > maxSize) {
        console.warn(`Skipping large file ${filePath} due to size.`);
        return '';
      }

      let content = '';
      const stream = fs.createReadStream(filePath, { highWaterMark: bufferSize });
      for await (const chunk of stream) {
        content += chunk.toString();
      }
      cache.set(filePath, content);
      console.log(`Read ${content.length} bytes from ${filePath}`);
      return content;
    } catch (error) {
      console.error(`Failed to read file ${filePath}:`, error);
      return '';
    }
  }

  try {
    const files = await fs.readdir(directory);
    const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === extension.toLowerCase());
    for (const file of filteredFiles) {
      totalContent += await limit(readFileContents, path.join(directory, file));
    }
  } catch (error) {
    console.error(`Failed to read directory ${directory}:`, error);
  }

  return totalContent;
}

// Example usage
(async () => {
  const result = await readDirectoryFiles('./example', '.txt', 1024 * 1024, 10 * 1024 * 1024); // 1 MB buffer, 10 MB max file size
  console.log(`Total content length: ${result.length}`);
})();
