class ConfigLoader
{
    public static void LoadConfig(string filePath, string decryptionKey)
    {
        try
        {
            // Decrypt the XML file using the provided decryption key
            byte[] encryptedXml = File.ReadAllBytes(filePath);
            byte[] decryptedXml = Decrypt(encryptedXml, decryptionKey);

            // Parse the decrypted XML to extract configuration settings
            XDocument configDoc = XDocument.Parse(Encoding.UTF8.GetString(decryptedXml));
            int tileSize = (int)configDoc.Root.Element("TileSize").Value;
            int worldWidth = (int)configDoc.Root.Element("WorldWidth").Value;
            int worldHeight = (int)configDoc.Root.Element("WorldHeight").Value;
            double cameraSpeed = (double)configDoc.Root.Element("CameraSpeed").Value;

            // Use the configuration settings to set tile, world size, and camera speed
            SetTileSize(tileSize);
            SetWorldSize(worldWidth, worldHeight);
            SetCameraSpeed(cameraSpeed);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading config: {ex.Message}");
        }
    }

    private static byte[] Decrypt(byte[] encryptedData, string decryptionKey)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = Encoding.UTF8.GetBytes(decryptionKey);
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    return csDecrypt.ToArray();
                }
            }
        }
    }

