use std::env;
use std::fs::{self, DirBuilder};
use std::io;

fn create_directory(directory_name: &str) -> io::Result<()> {
    if env::var("MY_DIRECTORY").is_err() {
        let path = env::current_dir()?.join(directory_name);
        DirBuilder::new()
            .recursive(true)
            .mode(0o755)
            .create(path)?;
        env::set_var("MY_DIRECTORY", path.display().to_string());
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: {} <config_file_path> <decryption_key> <directory_name>", args[0]);
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Incorrect number of arguments"));
    }

    let config_file_path = &args[1];
    let decryption_key = &args[2];
    let directory_name = &args[3];

    ConfigLoader::load_config(config_file_path, decryption_key);
    create_directory(directory_name)?;

    Ok(())
}
