using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.XPath;

public class XmlParser : IDisposable
{
    private XPathDocument _xmlDoc;
    private Dictionary<string, List<string>> _cache = new Dictionary<string, List<string>>();
    private ILogger _logger;

    public XmlParser(string xmlFilePath, ILogger logger)
    {
        _xmlDoc = new XPathDocument(xmlFilePath);
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public string GetSingleElementValue(string xpathExpression)
    {
        var nodes = _xmlDoc.CreateNavigator().Select(xpathExpression);
        if (nodes.Count == 0)
        {
            LogException(new FileNotFoundException($"No element found for XPath: {xpathExpression}"));
            throw new FileNotFoundException($"No element found for XPath: {xpathExpression}");
        }
        else if (nodes.Count > 1)
        {
            LogException(new MultipleElementException($"Multiple elements found for XPath: {xpathExpression}"));
            throw new MultipleElementException($"Multiple elements found for XPath: {xpathExpression}");
        }

        return nodes.Current.Value;
    }

    public List<string> GetElementsValues(string xpathExpression)
    {
        if (_cache.TryGetValue(xpathExpression, out var cachedValues))
        {
            return cachedValues;
        }

        var values = new List<string>();
        foreach (XPathNavigator node in _xmlDoc.CreateNavigator().Select(xpathExpression))
        {
            values.Add(node.Value);
        }

        _cache[xpathExpression] = values;
        return values;
    }

    public void Dispose()
    {
        _xmlDoc?.Dispose();
        _cache.Clear();
    }

    private void LogException(Exception ex)
    {
        _logger.Log(ex);
    }
}

public class FileNotFoundException : Exception
{
    public FileNotFoundException(string message) : base(message)
    {
    }
}

public class MultipleElementException : Exception
{
    public MultipleElementException(string message) : base(message)
    {
    }
}

public interface ILogger
{
    void Log(Exception ex);
}
