#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <stdexcept>
#include <boost/serialization/access.hpp>
#include <boost/serialization/string.hpp>
#include <boost/serialization/vector.hpp>

// Define a simple class for demonstration purposes
class MyResource {
public:
    std::string name;
    int value;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & name & value;
    }
};

// Function to deserialize the resource bundle
std::shared_ptr<MyResource> deserializeResourceBundle(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open resource file");
    }

    // Count the number of items in the bundle
    int itemCount;
    file.read(reinterpret_cast<char*>(&itemCount), sizeof(itemCount));

    // Read the byte array containing the serialized data
    std::vector<char> buffer(itemCount);
    file.read(buffer.data(), itemCount);

    if (file.fail()) {
        throw std::runtime_error("Failed to read resource bundle data");
    }

    // Deserialize the object using ObjectInputStream
    try {
        boost::archive::binary_iarchive ia(std::istringstream(std::string(buffer.begin(), buffer.end())));
        auto resource = std::make_shared<MyResource>();
        ia >> *resource;
        return resource;
    } catch (const boost::archive::archive_exception& e) {
        throw std::runtime_error("Failed to deserialize resource bundle: " + std::string(e.what()));
    }
}

int main() {
    try {
        auto resource = deserializeResourceBundle("path_to_resource_file");
        std::cout << "Deserialized resource: " << resource->name << ", Value: " << resource->value << std::endl;
    } catch (const std::runtime_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
