extern crate tokio;
extern crate serde_json;

use std::collections::{HashMap, HashSet};
use std::env;
use std::fs::{self, File};
use std::io::{Write, BufReader, Read};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::task;
use tokio::sync::mpsc;
use serde::{Deserialize, Serialize};
use warp::Filter;

#[derive(Serialize, Deserialize)]
struct Config {
    max_log_files: usize,
    cleanup_interval: u64,
    path_format: String,
}

fn main() {
    // Load configuration from a file
    let config_path = PathBuf::from("config.json");
    let mut file = File::open(config_path).expect("Failed to open config file");
    let mut contents = String::new();
    file.read_to_string(&mut contents).expect("Failed to read config file");
    let config: Config = serde_json::from_str(&contents).expect("Failed to parse config");

    // Initialize shared state
    let log_files = Arc::new(Mutex::new(HashMap::<String, PathBuf>::new()));
    let cleanup_interval = Duration::from_secs(config.cleanup_interval);

    // Start background cleanup process
    {
        let log_files = Arc::clone(&log_files);
        task::spawn(async move {
            loop {
                clean_up_old_logs(Arc::clone(&log_files), &config).await;
                tokio::time::sleep(cleanup_interval).await;
            }
        });
    }

    // Set up API endpoints
    let log_files = Arc::clone(&log_files);
    let app = warp::post()
        .and(warp::body::json())
        .and(warp::path!("logs"))
        .and_then(move |server_id: String| {
            create_log_file(Arc::clone(&log_files), server_id, &config)
        });

    // Start the API server
    warp::serve(app).run(([127, 0, 0, 1], 3030));
}

async fn clean_up_old_logs(log_files: Arc<Mutex<HashMap<String, PathBuf>>>, config: &Config) {
    let mut log_file_map = log_files.lock().unwrap();
    let current_log_files: HashSet<&Path> = log_file_map.values().collect();
    for path in fs::read_dir(".").expect("Failed to read directory") {
        if let Ok(entry) = path {
            let path = entry.path();
            if !current_log_files.contains(&path.as_path()) && path.is_file() {
                if log_file_map.len() > config.max_log_files {
                    fs::remove_file(path).expect("Failed to remove old log file");
                    log_file_map.remove_entry(&path.to_string_lossy());
                }
            }
        }
    }
}

async fn create_log_file(log_files: Arc<Mutex<HashMap<String, PathBuf>>>, server_id: String, config: &Config) -> Result<impl warp::Reply, warp::Rejection> {
    let mut log_file_map = log_files.lock().unwrap();

    // Generate a filename based on the configuration and server ID
    let timestamp = chrono::Utc::now();
    let filename = format!(config.path_format, server_id = server_id, timestamp = timestamp.format("%Y%m%d%H%M%S").to_string());
    let path = PathBuf::from(filename);

    // Create the log file atomically
    File::create(&path).expect("Failed to create log file");

    // Update the environment variable if necessary
    if let Ok(old_path) = env::var("LOG_FILE") {
        if old_path != path.to_str().unwrap() {
            env::set_var("LOG_FILE", &path.to_str().unwrap());
        }
    } else {
        env::set_var("LOG_FILE", &path.to_str().unwrap());
    }

    // Add the new log file to the map
    log_file_map.insert(server_id, path);

    Ok(warp::reply::json(&serde_json::json!({"message": "Log file created successfully"})))
}
