```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomValueGenerator : MonoBehaviour
{
    private float minValue;
    private float maxValue;

    public void SetRange(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Min value must be less than max value.");

        minValue = min;
        maxValue = max;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt()
    {
        return Mathf.RoundToInt(UnityEngine.Random.Range(minValue, maxValue));
    }

    public List<int> GenerateRandomUniqueInts(int count)
    {
        if (count < 0 || count > (int)(maxValue - minValue))
            throw new ArgumentException("Count must be non-negative and less than the range size.");

        HashSet<int> randomInts = new HashSet<int>(count);
        while (randomInts.Count < count)
        {
            int randInt = GenerateRandomInt();
            if (!randomInts.Contains(randInt))
                randomInts.Add(randInt);
        }

        return new List<int>(randomInts);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Generated List: {GenerateRandomUniqueInts(5)}";
    }
}
