int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int result = 0;

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        return -1; // Memory allocation failed
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &(*nfalist)[i];
        structure->RX_UE_INFORMATION_TAG = i + 1; // Example unique tag
        structure->RNTI = rand(); // Example RNTI

        if (crc_flag_rules[i] == 1) {
            structure->CRCFLAG = 1;
        } else {
            structure->CRCFLAG = 0;
        }

        log_structure_creation(structure);

        // Validation against predefined rules
        if (structure->CRCFLAG != crc_flag_rules[i]) {
            result = -2; // CRC flag does not match the rule
        }
    }
    pthread_mutex_unlock(&mutex);

    return result;
