#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_RECORDS 10

typedef struct {
    long value;
    long timestamp;
} Record;

Record* init_arrays(long offset_range, int key_range, long delay_min, long delay_max) {
    if (offset_range <= 0 || key_range <= 0 || delay_min < 0 || delay_max < 0 || delay_min > delay_max) {
        fprintf(stderr, "Invalid input ranges.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(NUM_RECORDS * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records array.");
        return NULL;
    }

    long* offsets = (long*)calloc(NUM_RECORDS, sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed for offsets array.");
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(NUM_RECORDS * sizeof(int));
    if (!keys) {
        perror("Memory allocation failed for keys array.");
        free(offsets);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < NUM_RECORDS; ++i) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;

        records[i].value = offsets[i];
        records[i].timestamp = time(NULL) + delay_min + rand() % (delay_max - delay_min + 1);
    }

    free(offsets);
    free(keys);

    return records;
}

void free_arrays(Record* records) {
    if (records) {
        free(records);
    }
}
