int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char **ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char **plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

void hash_data(const unsigned char *data, int data_len, unsigned char **digest) {
    SHA256(data, data_len, *digest);
}

void md5_hash(const unsigned char *data, int data_len, unsigned char **digest) {
    MD5(data, data_len, *digest);
}

RSA *generate_rsa_key(int bits) {
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);

    RSA *rsa = RSA_new();
    if (1 != RSA_generate_key_ex(rsa, bits, e, NULL)) {
        BN_free(e);
        RSA_free(rsa);
        return NULL;
    }

    BN_free(e);
    return rsa;
}

void save_rsa_key(RSA *rsa, const char *filename) {
    FILE *fp = fopen(filename, "w");
    PEM_write_RSA_PUBKEY(fp, rsa);
    fclose(fp);
}

RSA *load_rsa_key(const char *filename) {
    FILE *fp = fopen(filename, "r");
    RSA *rsa = PEM_read_RSA_PUBKEY(fp, NULL, NULL, NULL);
    fclose(fp);
    return rsa;
}
