class ScriptLoader {
  constructor(fileList = [], configManager) {
    this.fileList = fileList;
    this.configManager = configManager;
    this.queue = [];
    this.loading = false;
  }

  addFiles(newFiles) {
    this.fileList.push(...newFiles);
    this.loadNext();
  }

  removeFile(filePath) {
    const index = this.fileList.indexOf(filePath);
    if (index !== -1) {
      this.fileList.splice(index, 1);
    }
    this.loadNext();
  }

  loadNext() {
    if (!this.loading && this.queue.length > 0) {
      const fileToLoad = this.queue.shift();
      this.loadScript(fileToLoad);
    }
  }

  loadScript(filePath) {
    this.loading = true;
    fetch(filePath)
      .then(response => response.text())
      .then(scriptText => {
        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.appendChild(document.createTextNode(scriptText));
        document.head.appendChild(script);
        this.loading = false;
        this.loadNext();
      })
      .catch(error => {
        console.error(`Failed to load ${filePath}:`, error);
        // Fallback mechanism can be implemented here
        this.loading = false;
        this.loadNext();
      });
  }

  updateConfig(newFiles) {
    this.fileList = newFiles;
    this.queue = [];
    this.loadNext();
  }
}

// Example usage:
const configManager = {
  getScriptPaths: () => ['script1.js', 'script2.js']
};

const scriptLoader = new ScriptLoader([], configManager);

scriptLoader.configManager.getScriptPaths().forEach(file => {
  scriptLoader.queue.push(file);
});

setInterval(() => {
  const newFiles = configManager.getScriptPaths();
  if (newFiles.length > scriptLoader.fileList.length) {
    scriptLoader.updateConfig(newFiles);
  }
}, 5000); // Check for updates every 5 seconds
