<?php

// Define constants
define('PRIVATE_KEY', 'path/to/private_key.pem');
define('CERTIFICATE', 'path/to/certificate.pem');

// Database connection parameters
$host = 'localhost';
$dbname = 'your_database_name';
$username = 'your_username';
$password = 'your_password';

// Rate limiting settings
$max_requests_per_minute = 10;
$request_window = 60; // in seconds

session_start();

// Function to authenticate user and update clinic status
function authenticateUserAndUpdateClinicStatus($clientId, $clientSecret, $accessToken, $clinicId, $status) {
    global $host, $dbname, $username, $password, $max_requests_per_minute, $request_window;

    // Check rate limiting
    if (isset($_SESSION['last_request_time']) && time() - $_SESSION['last_request_time'] < $request_window) {
        return "Rate limit exceeded. Please try again later.";
    }

    // Update last request time in session
    $_SESSION['last_request_time'] = time();

    // Authenticate user using OAuth 2.0 client
    $ch = curl_init("https://oauth2.example.com/token");
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'grant_type' => 'client_credentials'
    ]));
    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        return "Failed to authenticate with third-party service.";
    }
    curl_close($ch);

    // Parse response and update clinic status
    $data = json_decode($response, true);
    $_SESSION['access_token'] = $data['access_token'];

    try {
        $pdo = new PDO("mysql:host=$host;dbname=$dbname", $username, $password);
        $stmt = $pdo->prepare("UPDATE clinics SET status=:status, last_modified_ip=:ip, last_modified_date=:date WHERE id=:id");
        $stmt->execute([
            ':status' => $status,
            ':ip' => $_SERVER['REMOTE_ADDR'],
            ':date' => date('Y-m-d H:i:s'),
            ':id' => $clinicId
        ]);
    } catch (PDOException $e) {
        return "Failed to update clinic status in database: " . $e->getMessage();
    }

    return "Clinic status updated successfully.";
}

// Function to calculate MD5 hash of a file
function hashFile($filePath) {
    global $max_requests_per_minute, $request_window;

    // Check rate limiting
    if (isset($_SESSION['last_request_time']) && time() - $_SESSION['last_request_time'] < $request_window) {
        return "Rate limit exceeded. Please try again later.";
    }

    // Update last request time in session
    $_SESSION['last_request_time'] = time();

    $pemFile = file_get_contents(PRIVATE_KEY . "\n" . CERTIFICATE);
    if ($pemFile === false) {
        return "Failed to read PEM file.";
    }

    $hash = md5_file($filePath, true);
    if ($hash === false) {
        return "Failed to calculate MD5 hash of the file.";
    }

    return bin2hex($hash);
}

// Example usage
$clientId = 'your_client_id';
$clientSecret = 'your_client_secret';
$accessToken = 'your_access_token';
$clinicId = 1;
$status = 'active';

echo authenticateUserAndUpdateClinicStatus($clientId, $clientSecret, $accessToken, $clinicId, $status);

$filePath = 'path/to/your/file.txt';
echo hashFile($filePath);
?>
