int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, const char *rules_config_file) {
    int result = 0;
    json_object *root = NULL, *item = NULL;
    size_t i;

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Load and parse the JSON file
    root = json_load_file(rules_config_file, 0, NULL);
    if (root == NULL || !json_is_array(root)) {
        fprintf(stderr, "Failed to load or parse rules configuration file\n");
        free(*nfalist);
        return -1;
    }

    for (i = 0; i < num_structures; i++) {
        (*nfalist)[i].rx_ue_information_tag = rand() % MAX_RX_UE_INFORMATION_TAG;
        (*nfalist)[i].rnti = rand() % NFAPI_RNTI_MAX;

        item = json_object_array_get_idx(root, (int)i);
        if (item != NULL && json_is_boolean(item)) {
            (*nfalist)[i].crc_indication_rel8.flag = json_is_true(item) ? 1 : 0;
        } else {
            fprintf(stderr, "Invalid CRC flag rule for RNTI: %d\n", (*nfalist)[i].rnti);
            result = -1;
        }

        // Log the creation of each structure
        log_structure_creation(&(*nfalist)[i]);
    }

    json_object_put(root);

    return result;
}
