class PDFCompressor {
public:
    enum class CompressionStatus { Success, Failure };

    PDFCompressor(const std::string& inputPath, const std::string& outputPath, int level)
        : inputPath(inputPath), outputPath(outputPath), compressionLevel(level) {}

    void compressAndSave() {
        auto document = poppler::document::load_from_file(inputPath);
        if (!document) {
            status = CompressionStatus::Failure;
            return;
        }

        document->set_compression_level(static_cast<poppler::compression_level>(compressionLevel));
        if (document->save(outputPath)) {
            status = CompressionStatus::Success;
        } else {
            status = CompressionStatus::Failure;
        }
    }

    CompressionStatus getCompressionStatus() const { return status; }

private:
    std::string inputPath;
    std::string outputPath;
    int compressionLevel;
    CompressionStatus status;
};

int main(int argc, char* argv[]) {
    if (argc != 4) {
        std::cerr << "Usage: " << argv[0] << " <input.pdf> <output.pdf> <compression_level>" << std::endl;
        return 1;
    }

    PDFCompressor compressor(argv[1], argv[2], std::stoi(argv[3]));
    compressor.compressAndSave();

    if (compressor.getCompressionStatus() == PDFCompressor::CompressionStatus::Success) {
        std::cout << "PDF compressed successfully!" << std::endl;
    } else {
        std::cerr << "Failed to compress PDF." << std::endl;
    }

    return 0;
}
```

