            System.err.println("Failed to load state object from file: " + filePath);
            e.printStackTrace();
            throw e;
        } finally {
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (IOException e) {
                    System.err.println("Failed to close ObjectInputStream");
                    e.printStackTrace();
                }
            }
            if (fileInputStream != null) {
                try {
                    fileInputStream.close();
                } catch (IOException e) {
                    System.err.println("Failed to close FileInputStream");
                    e.printStackTrace();
                }
            }
        }
    }

    public void updateCache(String key, Object value) {
        synchronized (cache) {
            if (cache.size() >= maxSize) {
                cache.remove(cache.keySet().iterator().next());
            }
            cache.put(key, value);
        }
    }

