public String analyzePokemon(Pokemon pokemon, String directoryPath) {
    File configFile = new File(directoryPath + "/web.config");
    if (!configFile.exists()) {
        return null;
    }

    String type = Pokemon.getType(pokemon);
    StringBuilder weaknesses = new StringBuilder();

    switch (type) {
        case "Fire":
            weaknesses.append("Water, Ground, Rock");
            break;
        case "Water":
            weaknesses.append("Electric, Grass");
            break;
        case "Grass":
            weaknesses.append("Fire, Ice, Bug, Flying, Rock");
            break;
        // Add cases for other types as needed
        default:
            weaknesses.append("No known weaknesses");
    }

    ProcessBuilder processBuilder = new ProcessBuilder();
    processBuilder.directory(new File(directoryPath));
    try {
        Process process = processBuilder.start();
        int exitCode = process.waitFor();
        if (exitCode == 0) {
            return "Analysis successful: " + Pokemon.getName(pokemon) + " weaknesses are " + weaknesses.toString();
        } else {
            return "Analysis failed with exit code: " + exitCode;
        }
    } catch (IOException | InterruptedException e) {
        e.printStackTrace();
        return null;
    }
}
