use std::env;
use std::fs;
use std::path::Path;

fn create_log_directory(log_dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let home_dir = env::var("HOME")?;
    let log_path = Path::new(&home_dir).join("logs").join(log_dir_name);

    if log_path.exists() {
        eprintln!("Log directory already exists.");
        return Ok(());
    }

    fs::create_dir_all(&log_path)?;
    env::set_var("LOG_DIRECTORY", &log_path)?;

    println!("Log directory created at: {:?}", log_path);
    Ok(())
}

fn main() {
    match create_log_directory("app_logs") {
        Ok(_) => println!("Successfully created log directory."),
        Err(e) => eprintln!("Failed to create log directory: {}", e),
    }
}
