public class SecureMessageHandler
{
    private readonly ConcurrentDictionary<string, ICryptoServiceProviderAdapter> _cspAdapters;
    private readonly ConcurrentDictionary<string, Tuple<byte[], byte[]>> _keyCache;

    public SecureMessageHandler()
    {
        _cspAdapters = new ConcurrentDictionary<string, ICryptoServiceProviderAdapter>();
        _keyCache = new ConcurrentDictionary<string, Tuple<byte[], byte[]>>();
    }

    public string DecryptMessage(string base64EncodedMessage, string contextId)
    {
