        var keyIvPair = await GetKeyAndIVAsync(contextId);

        return Encoding.UTF8.GetString(keyIvPair.Item1);
    }

    private Tuple<byte[], byte[]> GetKeyAndIV(string contextId)
    {
        if (_keyCache.TryGetValue(contextId, out var cached))
            return cached;

        // Simulate key retrieval from CSP
        var key = Encoding.UTF8.GetBytes("Key");
        var iv = Encoding.UTF8.GetBytes("IV");

        _keyCache.TryAdd(contextId, new Tuple<byte[], byte[]>(key, iv));

        return new Tuple<byte[], byte[]>(key, iv);
    }

    private async Task<Tuple<byte[], byte[]>> GetKeyAndIVAsync(string contextId)
    {
        if (_keyCache.TryGetValue(contextId, out var cached))
            return cached;

        // Simulate key retrieval from CSP
        var key = Encoding.UTF8.GetBytes("Key");
        var iv = Encoding.UTF8.GetBytes("IV");

        _keyCache.TryAdd(contextId, new Tuple<byte[], byte[]>(key, iv));

        return new Tuple<byte[], byte[]>(key, iv);
    }
}
```

