<?php

use GuzzleHttp\Client;
use Illuminate\Database\ConnectionPool;
use Monolog\Logger;
use Redis;

class UserAccountManager {

    private $dbPool;
    private $authSystemClient;
    private $paymentGatewayClient;
    private $logger;
    private $redisCache;

    public function __construct(ConnectionPool $dbPool, Client $authSystemClient, Client $paymentGatewayClient, Logger $logger, Redis $redisCache) {
        $this->dbPool = $dbPool;
        $this->authSystemClient = $authSystemClient;
        $this->paymentGatewayClient = $paymentGatewayClient;
        $this->logger = $logger;
        $this->redisCache = $redisCache;
    }

    public function createUser($email, $password, $confirmPassword) {
        // Validate email and passwords
        if ($this->isEmailExists($email)) {
            return $this->errorResponse("Email already exists.");
        }
        if ($password !== $confirmPassword) {
            return $this->errorResponse("Passwords do not match.");
        }

        // Insert user into database
        $userId = $this->dbPool->run(function ($conn) use ($email, $password) {
            $stmt = $conn->prepare("INSERT INTO users (email, password) VALUES (?, ?)");
            $stmt->execute([$email, $password]);
            return $conn->lastInsertId();
        });

        // Log user creation
        $this->logger->info('User created', ['user_id' => $userId]);

        // Send email notification
        $this->sendEmail($userId, "Welcome to our platform!");

        return $this->successResponse($userId);
    }

    public function updateUser($userId, $email, $password, $confirmPassword) {
        // Validate email and passwords
        if ($this->isEmailExists($email)) {
            return $this->errorResponse("Email already exists.");
        }
        if ($password !== $confirmPassword) {
            return $this->errorResponse("Passwords do not match.");
        }

        // Update user in database
        $result = $this->dbPool->run(function ($conn) use ($userId, $email, $password) {
            $stmt = $conn->prepare("UPDATE users SET email = ?, password = ? WHERE id = ?");
            return $stmt->execute([$email, $password, $userId]);
        });

        // Log user update
        if ($result) {
            $this->logger->info('User updated', ['user_id' => $userId]);
            $this->sendEmail($userId, "Your account has been updated!");
        }

        return $this->successResponse($userId);
    }

    public function deleteUser($userId) {
        // Delete user from database
        $result = $this->dbPool->run(function ($conn) use ($userId) {
            $stmt = $conn->prepare("DELETE FROM users WHERE id = ?");
            return $stmt->execute([$userId]);
        });

        // Log user deletion
        if ($result) {
            $this->logger->info('User deleted', ['user_id' => $userId]);
            $this->sendEmail($userId, "Your account has been deleted.");
        }

        return $this->successResponse($userId);
    }

    private function isEmailExists($email) {
        // Check if email exists in database
        return $this->dbPool->run(function ($conn) use ($email) {
            $stmt = $conn->prepare("SELECT COUNT(*) FROM users WHERE email = ?");
            $stmt->execute([$email]);
            return (int)$stmt->fetchColumn() > 0;
        });
    }

    private function sendEmail($userId, $subject) {
        // Send email using SMTP
        $this->redisCache->lpush('send_email_queue', json_encode([
            'user_id' => $userId,
            'subject' => $subject
        ]));
    }

    private function successResponse($userId) {
        return [
            "status" => "success",
            "message" => "User account updated successfully",
            "data" => [
                "id" => $userId,
                "name" => "John Doe", // Example user name
                "email" => "john.doe@example.com", // Example email
                "subscription_status" => "active" // Example subscription status
            ]
        ];
    }

    private function errorResponse($message) {
        return [
            "status" => "error",
            "message" => $message
        ];
    }
}
?>
