// Define error codes for different failure scenarios
enum class ErrorCode {
    Success,
    DatabaseFailure,
    LogFileWriteError,
    PaymentProcessorFailure
};

// Base class for transaction recorders
class TransactionRecorder {
public:
    virtual void recordTransaction(const std::string& message) = 0;
    virtual ~TransactionRecorder() = default;
};

// Class for recording transactions to a database
class DatabaseRecorder : public TransactionRecorder {
public:
    void recordTransaction(const std::string& message) override {
        // Simulate database operation
        if (/* database connection failed */) {
            throw ErrorCode::DatabaseFailure;
        }
        // Log transaction to database
    }
};

// Class for recording transactions to a log file
class LogFileRecorder : public TransactionRecorder {
public:
    void recordTransaction(const std::string& message) override {
        std::ofstream logFile("transaction.log", std::ios::app);
        if (!logFile.is_open()) {
            throw ErrorCode::LogFileWriteError;
        }
        // Write transaction to log file
    }
};

// Class for recording transactions via external payment processing system API
class PaymentProcessorRecorder : public TransactionRecorder {
public:
    void recordTransaction(const std::string& message) override {
        // Simulate payment processor operation
        if (/* API call failed */) {
            throw ErrorCode::PaymentProcessorFailure;
        }
        // Process transaction through payment processor
    }
};

// Factory class to create transaction recorders based on configuration
class TransactionRecorderFactory {
public:
    static std::unique_ptr<TransactionRecorder> createRecorder(const std::string& recorderType) {
        if (recorderType == "database") {
            return std::make_unique<DatabaseRecorder>();
        } else if (recorderType == "log_file") {
            return std::make_unique<LogFileRecorder>();
        } else if (recorderType == "payment_processor") {
            return std::make_unique<PaymentProcessorRecorder>();
        }
        throw std::invalid_argument("Invalid recorder type");
    }
};

// Class for managing transaction recording with error handling and fallback mechanisms
class TransactionManager {
public:
    TransactionManager(const std::string& recorderType) : recorder(TransactionRecorderFactory::createRecorder(recorderType)) {}

    ErrorCode recordTransaction(const std::string& message, int retryCount = 3, std::chrono::milliseconds delay = std::chrono::seconds(1)) {
        for (int i = 0; i < retryCount; ++i) {
            try {
                recorder->recordTransaction(message);
                return ErrorCode::Success;
            } catch (const ErrorCode& error) {
                if (error == ErrorCode::DatabaseFailure || error == ErrorCode::LogFileWriteError) {
                    std::this_thread::sleep_for(delay);
                } else if (error == ErrorCode::PaymentProcessorFailure) {
                    // Implement retry and exponential backoff for payment processor
                    std::this_thread::sleep_for(delay);
                }
            }
        }
        return ErrorCode::DatabaseFailure; // Fallback to database if all retries fail
    }

private:
    std::unique_ptr<TransactionRecorder> recorder;
};

// Example usage
int main() {
    TransactionManager manager("database");
    auto errorCode = manager.recordTransaction("Processing transaction...");
    if (errorCode != ErrorCode::Success) {
        std::cerr << "Failed to record transaction: " << static_cast<int>(errorCode) << std::endl;
    }
    return 0;
}
