class JsonParser {
  static registry = {};

  constructor(data) {
    this.data = data;
  }

  toJsonString() {
    return JSON.stringify(this.data);
  }

  static fromJsonString(jsonStr) {
    const data = JSON.parse(jsonStr);
    return new this(data);
  }

  static registerFactory(id, factoryFn) {
    if (this.registry[id]) {
      throw new Error(`Factory with id ${id} already exists.`);
    }
    this.registry[id] = factoryFn;
  }
}

function runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
  const module = require(moduleLabel);
  let allData = {};
  let startTime;

  async function fetchData(dataSource) {
    // Optimize data fetching here
    return dataSource.fetch();
  }

  async function runTest(testLabel, testFunction, testData) {
    try {
      await testFunction(testData);
      console.log(`${testLabel}: Passed`);
    } catch (error) {
      console.error(`${testLabel}: Failed - ${error.message}`);
    }
  }

  async function runAllTests() {
    startTime = Date.now();
    for (let i = 0; i < testLabels.length; i++) {
      const testLabel = testLabels[i];
      const testFunction = testFunctions[i];
      const dataSource = dataSources[i];
      const testData = await fetchData(dataSource);
      await runTest(testLabel, testFunction, testData);
    }
    console.log(`All tests completed in ${Date.now() - startTime}ms`);
  }

  async function cleanUp() {
    for (let i = cleanupFunctions.length - 1; i >= 0; i--) {
      try {
        await cleanupFunctions[i]();
      } catch (error) {
        console.error(`Cleanup failed - ${error.message}`);
      }
    }
  }

  blueslip.reset(); // Assuming blueslip is a mocking library

  runAllTests().finally(cleanUp);
}
