    // Convert images to PDF and track progress
    std::vector<std::future<void>> pdfFutures;
    for (const auto& file : imageAssets) {
        pdfFutures.push_back(std::async(std::launch::async, convertToPDF, file, "output_" + file));
        progressMutex.lock();
        std::cout << "Converted " << file << " to PDF" << std::endl;
        progressMutex.unlock();
    }

    // Convert images to PNG and track progress
    std::vector<std::future<void>> pngFutures;
    for (const auto& file : imageAssets) {
        pngFutures.push_back(std::async(std::launch::async, convertToPNG, file, "output_" + file));
        progressMutex.lock();
        std::cout << "Converted " << file << " to PNG" << std::endl;
        progressMutex.unlock();
    }

    // Convert images to SVG and track progress
    std::vector<std::future<void>> svgFutures;
    for (const auto& file : imageAssets) {
        svgFutures.push_back(std::async(std::launch::async, convertToSVG, file, "output_" + file));
        progressMutex.lock();
        std::cout << "Converted " << file << " to SVG" << std::endl;
        progressMutex.unlock();
    }

    // Render JavaScript modules and track progress
    auto scriptTags = renderJavaScriptModules(moduleFiles);
    for (const auto& tag : scriptTags) {
        std::cout << "Rendered script: " << tag << std::endl;
    }

    // Wait for all conversions to complete and check for failures
    for (auto& future : pdfFutures) {
        if (!future.get()) {
            failedConversions++;
        }
    }
    for (auto& future : pngFutures) {
        if (!future.get()) {
            failedConversions++;
        }
    }
    for (auto& future : svgFutures) {
        if (!future.get()) {
            failedConversions++;
        }
    }

    return failedConversions;
}

int main() {
    std::string directory = "path/to/images";
    std::vector<std::string> moduleFiles = {"module1.js", "module2.js"};
    int result = integrateScriptsAndConvertImages(directory, moduleFiles);
    if (result == 0) {
        std::cout << "All conversions and script integrations were successful." << std::endl;
    } else {
        std::cout << result << " conversion(s) failed." << std::endl;
    }
    return 0;
}
