        file_put_contents($pemFile, openssl_pkey_export($privateKey) . "\n" . openssl_x509_export($certificate));

        // Read file in chunks to manage memory usage
        $fileHandle = fopen($filePath, 'rb');
        $fileHash = hash_init('sha256');
        while (!feof($fileHandle)) {
            $chunk = fread($fileHandle, 8192);
            hash_update($fileHash, $chunk);
        }
        fclose($fileHandle);

        // Clean up temporary file
        unlink($pemFile);

        return ['success' => true, 'hash' => hash_final($fileHash)];
    }

