use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use chrono::Local;

static LOGGER: Mutex<()> = Mutex::new(());

fn log(message: &str) -> io::Result<()> {
    let mut logger = LOGGER.lock().unwrap();
    writeln!(File::create("/tmp/app.log")?, "{} - {}", Local::now(), message)?;
    Ok(())
}

fn create_directory(name: &str) -> io::Result<PathBuf> {
    let dir_path = env::var("DIR_PATH").map_or_else(
        |_| {
            log(&format!("Creating new directory: {}", name)).unwrap();
            fs::create_dir_all(&name)?;
            PathBuf::from(name)
        },
        |path| {
            let subdir_name = format!("run_{}", Local::now().timestamp());
            let full_path = Path::new(&path).join(&subdir_name);
            log(&format!("Using existing directory: {}", path)).unwrap();
            fs::create_dir_all(&full_path)?;
            full_path
        },
    );

    env::set_var("DIR_PATH", dir_path.display());

    Ok(dir_path)
}

fn main() -> io::Result<()> {
    let mut args = std::env::args().skip(1);
    if let Some(name) = args.next() {
        create_directory(&name)?;
        println!("Directory created successfully.");
    } else {
        eprintln!("Usage: {} <directory_name>", env::args().next().unwrap());
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "No directory name provided"));
    }
    Ok(())
}
