#include <stdbool.h>
#include <string.h>
#include "json-c/json.h"

bool is_valid_oauth_token(const char *json_str) {
    struct json_object *parsed_json;
    struct json_object *access_token, *expires_in, *token_type, *refresh_token;
    int expires_in_value;

    parsed_json = json_tokener_parse(json_str);
    if (!parsed_json || !json_is_object(parsed_json)) return false;

    if (json_object_object_get_ex(parsed_json, "access_token", &access_token) != true ||
        json_object_object_get_ex(parsed_json, "expires_in", &expires_in) != true ||
        json_object_object_get_ex(parsed_json, "token_type", &token_type) != true) {
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_get_string(access_token) == NULL || strlen(json_object_get_string(access_token)) == 0) {
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_get_int(expires_in, &expires_in_value) != true || expires_in_value <= 0) {
        json_object_put(parsed_json);
        return false;
    }

    if (strcmp(json_object_get_string(token_type), "Bearer") != 0) {
        json_object_put(parsed_json);
        return false;
    }

    // Optionally, check for refresh_token if present
    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token)) {
        if (json_object_get_string(refresh_token) == NULL || strlen(json_object_get_string(refresh_token)) == 0) {
            json_object_put(parsed_json);
            return false;
        }
    }

    json_object_put(parsed_json);
    return true;
}
