// Function to update clinic status, last modified IP address, and date for a given clinic ID
function updateClinicStatus($clinicID, $newStatus, $lastModifiedIP) {
    // Connect to the MySQL database
    try {
        $db = new PDO('mysql:host=localhost;dbname=hospital', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    } catch (PDOException $e) {
        error_log("Database connection failed: " . $e->getMessage());
        return "Error updating clinic status.";
    }

    // Check for rate limiting
    if (isRateLimited($lastModifiedIP)) {
        return "Too many updates from this IP. Please try again later.";
    }

    // Update the clinic's status and last modified details
    $stmt = $db->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=NOW() WHERE id=?");
    if (!$stmt->execute([$newStatus, $lastModifiedIP, $clinicID])) {
        error_log("Update failed: " . print_r($stmt->errorInfo(), true));
        return "Error updating clinic status.";
    }

    // Check for potential closure due to weather conditions
    if (isWeatherEmergency($newStatus)) {
        notifyExternalAPI($clinicID);
        sendEmailNotification($clinicID);
    }

    // Ensure no overlapping appointments
    if (!checkAppointments($clinicID, $newStatus)) {
        return "Cannot update clinic status. Overlapping appointments exist.";
    }

    // Commit the transaction
    try {
        $db->beginTransaction();
        // Perform additional database operations if necessary
        $db->commit();
    } catch (PDOException $e) {
        $db->rollBack();
        error_log("Transaction rollback failed: " . $e->getMessage());
        return "Error updating clinic status.";
    }

    return "Clinic status updated successfully.";
}

