```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public interface IHashAlgorithm
{
    string GenerateHash(string input);
    Task<string> GenerateHashAsync(string input);
}

public class DynamicTextProcessor : IDynamicTextProcessor, IDisposable
{
    private readonly IExternalAPIClient _apiClient;
    private readonly ILogger _logger;
    private const int MaxInputSize = 1073741824; // 1GB in bytes

    public DynamicTextProcessor(IExternalAPIClient apiClient, ILogger logger)
    {
        _apiClient = apiClient ?? throw new ArgumentNullException(nameof(apiClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public string GenerateMD5(string input) => HashHelper.GenerateHash(input, HashAlgorithm.Create("MD5"));
    public Task<string> GenerateMD5Async(string input) => HashHelper.GenerateHashAsync(input, HashAlgorithm.Create("MD5"));

    public string GenerateSHA1(string input) => HashHelper.GenerateHash(input, HashAlgorithm.Create("SHA1"));
    public Task<string> GenerateSHA1Async(string input) => HashHelper.GenerateHashAsync(input, HashAlgorithm.Create("SHA1"));

    public string GenerateSHA256(string input) => HashHelper.GenerateHash(input, HashAlgorithm.Create("SHA256"));
    public Task<string> GenerateSHA256Async(string input) => HashHelper.GenerateHashAsync(input, HashAlgorithm.Create("SHA256"));

    public void Dispose() { }

    public string ProcessUserInput(string input, UserSettings settings)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));
        if (settings == null) throw new ArgumentNullException(nameof(settings));

        // Validate and adjust input based on user settings
        input = AdjustInput(input, settings);

        try
        {
            return GenerateSHA256(input);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex.Message);
            throw;
        }
    }

    private string AdjustInput(string input, UserSettings settings)
    {
        if (input.Length > MaxInputSize) throw new ArgumentException("Input exceeds maximum allowed size.");

        if (settings.TrimEnabled) input = input.Trim();
        if (settings.Capitalize) input = input.ToUpper();

        return input.Substring(0, Math.Min(input.Length, settings.MaxStringLength));
    }
}

public interface IDynamicTextProcessor
{
    string GenerateMD5(string input);
    Task<string> GenerateMD5Async(string input);

    string GenerateSHA1(string input);
    Task<string> GenerateSHA1Async(string input);

    string GenerateSHA256(string input);
    Task<string> GenerateSHA256Async(string input);

    string ProcessUserInput(string input, UserSettings settings);
}

public class HashHelper
{
    public static string GenerateHash(string input, HashAlgorithm algorithm)
    {
        byte[] hashBytes = algorithm.ComputeHash(Encoding.UTF8.GetBytes(input));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    public static async Task<string> GenerateHashAsync(string input, HashAlgorithm algorithm)
    {
        byte[] hashBytes = await Task.Run(() => algorithm.ComputeHash(Encoding.UTF8.GetBytes(input)));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}

public class UserSettings
{
    public int MaxStringLength { get; set; } = 1024;
    public bool TrimEnabled { get; set; } = true;
    public bool Capitalize { get; set; } = false;
}
