#include <stdio.h>
#include <stdarg.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_LENGTH 1024
#define LOG_FILE_PATH "/var/log/error.log"

enum Severity {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
};

typedef struct LogConfig {
    char *logFilePath;
    int maxLogLength;
    enum Severity defaultSeverity;
} LogConfig;

static LogConfig config = {LOG_FILE_PATH, MAX_LOG_LENGTH, LOG_ERROR};
static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void setLogConfig(const char *filePath, int maxLength, enum Severity severity) {
    config.logFilePath = strdup(filePath);
    config.maxLogLength = maxLength;
    config.defaultSeverity = severity;
}

const char* getSeverityString(enum Severity severity) {
    switch (severity) {
        case LOG_DEBUG:   return "DEBUG";
        case LOG_INFO:    return "INFO";
        case LOG_WARNING: return "WARNING";
        case LOG_ERROR:   return "ERROR";
        default:          return "UNKNOWN";
    }
}

void logMessage(const char *format, va_list args) {
    pthread_mutex_lock(&logMutex);
    FILE *file = fopen(config.logFilePath, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", config.logFilePath);
        pthread_mutex_unlock(&logMutex);
        return;
    }

    char buffer[MAX_LOG_LENGTH];
    vsnprintf(buffer, MAX_LOG_LENGTH, format, args);

    fprintf(file, "%s [%s] %s\n", getSeverityString(config.defaultSeverity), getCurrentTimestamp(), buffer);
    fclose(file);
    pthread_mutex_unlock(&logMutex);
}

int logCondition(bool condition, int severity, const char *format, ...) {
    if (!condition) return 0;

    va_list args;
    va_start(args, format);
    logMessage(format, args);
    va_end(args);

    return 1;
}
