{
    private readonly HttpClient _httpClient;
    private readonly Random _random;
    private readonly Dictionary<string, object> _configurations;
    private int _requestCount;
    private int _cacheHits;
    private int _networkTimeouts;

    public WeatherDataFetcher(HttpClient httpClient, Random random, Dictionary<string, object> configurations)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _random = random ?? throw new ArgumentNullException(nameof(random));
        _configurations = configurations ?? throw new ArgumentNullException(nameof(configurations));
    }

    public int GetRandomInt(int minInclusive, int maxExclusive)
    {
        return _random.Next(minInclusive, maxExclusive);
    }

    public List<int> GetUniqueRandomIntList(int size, int minInclusive, int maxExclusive)
    {
        var list = new HashSet<int>();
        while (list.Count < size && list.Count < maxExclusive - minInclusive)
        {
            list.Add(_random.Next(minInclusive, maxExclusive));
        }
        return new List<int>(list);
    }

    public override string ToString()
    {
        return $"Range: {_configurations["min"]} to {_configurations["max"]}, Generated Lists: {GetUniqueRandomIntList(10, (int)_configurations["min"], (int)_configurations["max"]).Count}";
    }
}

