<?php

// Define constants for different environments
define('ENV_DEVELOPMENT', 'development');
define('ENV_STAGING', 'staging');
define('ENV_PRODUCTION', 'production');

// External API URL
$apiUrl = 'https://api.example.com/config';

// Cache directory and file name
$cacheDir = __DIR__ . '/cache';
$cacheFile = $cacheDir . '/config.json';
$cacheDuration = 3600; // Cache duration in seconds (1 hour)

// Function to fetch configuration from API or cache
function getConfig($env) {
    global $apiUrl, $cacheDir, $cacheFile, $cacheDuration;

    if (!is_dir($cacheDir)) {
        mkdir($cacheDir, 0755, true);
    }

    // Check if cached data is available and not expired
    if (file_exists($cacheFile) && time() - filemtime($cacheFile) < $cacheDuration) {
        return json_decode(file_get_contents($cacheFile), true);
    }

    // Make API request to fetch configuration
    $ch = curl_init();
    curl_setopt_array($ch, [
        CURLOPT_URL => $apiUrl . '?env=' . urlencode($env),
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 10, // Set timeout for API call
        CURLOPT_CONNECTTIMEOUT => 5, // Set connection timeout for API call
    ]);

    $response = curl_exec($ch);
    if ($response === false) {
        error_log('API request failed: ' . curl_error($ch));
        return null;
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    // Check API response
    if ($httpCode == 200) {
        $config = json_decode($response, true);
        if ($config === null || json_last_error() !== JSON_ERROR_NONE) {
            error_log('Failed to parse API response: ' . json_last_error_msg());
            return null;
        }

        // Save fetched configuration to cache
        file_put_contents($cacheFile, json_encode($config));

        return $config;
    } else {
        error_log('API request failed with HTTP code: ' . $httpCode);
        return null;
    }
}

// Function to apply configuration to the application
function applyConfig($config) {
    // Apply configuration settings to the application
    // Example:
    if (isset($config['database'])) {
        define('DB_HOST', $config['database']['host']);
        define('DB_USER', $config['database']['user']);
        define('DB_PASS', $config['database']['pass']);
        define('DB_NAME', $config['database']['name']);
    }

    // Additional configuration settings can be applied here
}

// Main script execution
$env = $_SERVER['ENV'] ?? ENV_DEVELOPMENT; // Default to development if not set
$config = getConfig($env);

if ($config !== null) {
    applyConfig($config);
} else {
    error_log('Failed to fetch and apply configuration');
}

?>
```

