public class StateLoader {

    private final Cache<String, State> cache;
    private final ExecutorService executorService;

    public StateLoader(int maxCacheSize) {
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(maxCacheSize)
                .expireAfterWrite(10, TimeUnit.MINUTES)
                .build();
        this.executorService = Executors.newCachedThreadPool();
    }

    public State loadState(String stateId) throws Exception {
        try {
            if (cache.getIfPresent(stateId).isRecent()) {
                log("Cache hit: " + stateId);
                return cache.getIfPresent(stateId);
            } else {
                Future<State> future = executorService.submit(() -> {
                    log("Fetching from file: " + stateId);
                    State stateFromDisk = fetchStateFromFile(stateId);
                    cache.put(stateId, stateFromDisk);
                    return stateFromDisk;
                });

                try {
                    State state = future.get(5, TimeUnit.SECONDS);
                    log("Cache miss: " + stateId);
                    return state;
                } catch (TimeoutException e) {
                    State stateFromService = fetchStateFromService(stateId);
                    cache.put(stateId, stateFromService);
                    return stateFromService;
                }
            }
        } catch (Exception e) {
            log("Failed to load state: " + stateId, e);
            throw e;
        }
    }

