        try (InputStream inputStream = new URL("http://example.com/" + stateId).openStream()) {
            // Implement state loading from file
            return new State(stateId);
        }
    }

    private State fetchStateFromService(String stateId) throws Exception {
        // Implement state fetching from external service
        return new State(stateId);
    }

    private void log(String message, Exception e) {
        System.err.println(message + " - " + e.getMessage());
    }

    private void log(String message) {
        System.out.println(message);
    }

    private static class State {
        private final String id;
        private final LocalDateTime lastUpdated;

        public State(String id) {
            this.id = id;
            this.lastUpdated = LocalDateTime.now();
        }

        public boolean isRecent() {
            return lastUpdated.isAfter(LocalDateTime.now().minusMinutes(5));
        }
    }

    public static void main(String[] args) {
        try {
            StateLoader stateLoader = new StateLoader(100);
            State state = stateLoader.loadState("state123");
            System.out.println(state.id + " is recent: " + state.isRecent());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
