import java.util.Map;
import java.util.HashMap;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class KafkaLogProcessor {
    private Map<String, Metric> metricDefinitions = new HashMap<>();
    private CacheManager cacheManager;

    public KafkaLogProcessor(CacheManager cacheManager) {
        this.cacheManager = cacheManager;
    }

    public void addMetricDefinition(String metricName, Metric metric) {
        metricDefinitions.put(metricName, metric);
    }

    public Map<String, Object> processLogs(ConsumerRecord<String, String> record) {
        try {
            ObjectMapper mapper = new ObjectMapper();
            JsonNode jsonNode = mapper.readTree(record.value());
            Map<String, Object> extractedMetrics = new HashMap<>();

            for (Map.Entry<String, Metric> entry : metricDefinitions.entrySet()) {
                String metricName = entry.getKey();
                Metric metric = entry.getValue();
                Object value = metric.extract(jsonNode);
                if (value != null) {
                    cacheManager.put(metricName, value);
                    extractedMetrics.put(metricName, value);
                }
            }

            return extractedMetrics;
        } catch (Exception e) {
            handleProcessingError(e);
            return null;
        }
    }

    private void handleProcessingError(Exception e) {
        // Implement robust error handling logic here
        // Log the error, notify administrators, etc.
    }
}

