package configurable_component;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.File;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public abstract class ConfigurableComponent {
    private static final Map<String, Constructor<? extends ConfigurableComponent>> factoryRegistry = new ConcurrentHashMap<>();
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public static void registerFactory(String id, Class<? extends ConfigurableComponent> clazz) {
        try {
            factoryRegistry.put(id, clazz.getConstructor(Map.class));
        } catch (NoSuchMethodException e) {
            throw new RuntimeException("Class does not have a constructor that takes a Map<String, Object>", e);
        }
    }

    public static ConfigurableComponent createFromJson(String id, String json) throws IOException {
        Constructor<? extends ConfigurableComponent> constructor = factoryRegistry.get(id);
        if (constructor == null) {
            throw new IllegalArgumentException("Unknown component ID: " + id);
        }
        ObjectMapper mapper = new ObjectMapper();
        Map<String, Object> config = mapper.readValue(json, Map.class);
        return constructor.newInstance(config);
    }

    public void saveToJson(String jsonFilePath) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.writeValue(new File(jsonFilePath), this.getConfig());
    }

    protected abstract Map<String, Object> getConfig();

    static {
        scheduler.scheduleAtFixedRate(() -> {
            factoryRegistry.entrySet().removeIf(entry -> System.currentTimeMillis() - entry.getValue().newInstance().getLastAccessTime() > TimeUnit.HOURS.toMillis(1));
        }, 0, 1, TimeUnit.HOURS);
    }

    private long lastAccessTime = System.currentTimeMillis();

    public long getLastAccessTime() {
        return lastAccessTime;
    }
}
