<?php

class ClinicManager {
    private $db;
    private $weatherAPI;
    private $patientSchedulingSystem;
    private $notificationService;

    public function __construct($db, $weatherAPI, $patientSchedulingSystem, $notificationService) {
        $this->db = $db;
        $this->weatherAPI = $weatherAPI;
        $this->patientSchedulingSystem = $patientSchedulingSystem;
        $this->notificationService = $notificationService;
    }

    public function handleClinicOperations($operation, $data) {
        switch ($operation) {
            case 'create':
                return $this->createClinicRecord($data);
            case 'update':
                return $this->updateClinicStatus($data);
            case 'delete':
                return $this->deleteClinicRecord($data);
            default:
                throw new Exception('Invalid operation');
        }
    }

    private function createClinicRecord($data) {
        // Validate clinic name and location
        if (strlen($data['name']) > 50 || in_array(strtolower($data['name']), $this->prohibitedTerms)) {
            throw new Exception('Invalid clinic name');
        }

        // Create new record in database
        $stmt = $this->db->prepare("INSERT INTO clinics (name, location, capacity) VALUES (:name, :location, :capacity)");
        $stmt->execute($data);

        return $stmt->rowCount() > 0;
    }

    private function updateClinicStatus($data) {
        // Update clinic status in database
        $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
        $stmt->execute($data);

        if ($data['status'] !== 'open') {
            // Trigger weather API check
            $weatherData = $this->weatherAPI->checkClosureRisk($data['location']);
            // Update patient scheduling system and notify patients
            $this->patientSchedulingSystem->clearRescheduleAppointments($data['id'], $weatherData);
            $this->notificationService->sendEmailsToPatients($data['id'], $weatherData);
        }

        return $stmt->rowCount() > 0;
    }

    private function deleteClinicRecord($data) {
        // Check if clinic is in use
        $stmt = $this->db->prepare("SELECT COUNT(*) FROM appointments WHERE clinic_id = :id");
        $stmt->execute(['id' => $data['id']]);
        if ($stmt->fetchColumn() > 0) {
            throw new Exception('Clinic cannot be deleted as it is in use');
        }

        // Delete record from database
        $stmt = $this->db->prepare("DELETE FROM clinics WHERE id = :id");
        $stmt->execute(['id' => $data['id']]);

        if ($stmt->rowCount() > 0) {
            // Notify patients with upcoming appointments and suggest alternatives
            $this->patientSchedulingSystem->suggestAlternativeClinics($data['id']);
        }

        return true;
    }
}

// Usage example
$db = new PDO('mysql:host=localhost;dbname=hospital', 'user', 'password');
$weatherAPI = new WeatherAPI();
$schedulingSystem = new PatientSchedulingSystem();
$notificationService = new NotificationService();

$manager = new ClinicManager($db, $weatherAPI, $schedulingSystem, $notificationService);
$result = $manager->handleClinicOperations('create', ['name' => 'New Clinic', 'location' => '123 Main St', 'capacity' => 50]);
?>
