    // Handle messages and reconnections in separate threads
    websocketpp::lib::thread message_handler([&c]() {
        while (true) {
            websocketpp::lib::error_code ec;
            client::message_ptr msg = c.receive_message(c.get_con_from_hdl(c.get_next_connection(ec)), ec);
            if (!ec) on_message(&c, c.get_con_from_hdl(msg->get_handle()), msg);
        }
    });

    websocketpp::lib::thread heartbeat_handler([&c]() {
        while (true) {
            // Call start_heartbeat as needed
            websocketpp::lib::this_thread::sleep_for(websocketpp::lib::chrono::seconds(30));
        }
    });

    // Wait for messages and reconnections here

    message_handler.join();
    heartbeat_handler.join();

    return 0;
}
