#define MAX_DESCRIPTION_LENGTH 256

typedef struct {
    int key;
    long timestamp;
    char description[MAX_DESCRIPTION_LENGTH];
} record;

void* initialize_records(void* arg) {
    int record_count;
    record* records;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Connect to the external SQL database
    if (connect_to_database() != 0) {
        log_error("Failed to connect to the database");
        return NULL;
    }

    // Query the number of records required
    if (get_record_count(&record_count) != 0) {
        log_error("Failed to get record count from the database");
        disconnect_from_database();
        return NULL;
    }

    // Allocate memory for arrays and structures
    records = malloc(record_count * sizeof(record));
    if (records == NULL) {
        log_error("Memory allocation failed for records array");
        disconnect_from_database();
        return NULL;
    }

    int* keys = malloc(record_count * sizeof(int));
    long* timestamps = malloc(record_count * sizeof(long));
    char** descriptions = malloc(record_count * sizeof(char*));
    if (keys == NULL || timestamps == NULL || descriptions == NULL) {
        log_error("Memory allocation failed for arrays");
        free(records);
        disconnect_from_database();
        return NULL;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        keys[i] = rand() % 10001;
        timestamps[i] = time(NULL) + (rand() % 365 * 24 * 60 * 60);
        descriptions[i] = malloc(MAX_DESCRIPTION_LENGTH);
        snprintf(descriptions[i], MAX_DESCRIPTION_LENGTH, "Description for record %d", i);
    }

    // Set up records structures
    for (int i = 0; i < record_count; i++) {
        pthread_mutex_lock(&lock);
        records[i].key = keys[i];
        records[i].timestamp = timestamps[i];
        strncpy(records[i].description, descriptions[i], MAX_DESCRIPTION_LENGTH - 1);
        records[i].description[MAX_DESCRIPTION_LENGTH - 1] = '\0';
        pthread_mutex_unlock(&lock);
    }

    // Free allocated memory
    for (int i = 0; i < record_count; i++) {
        free(descriptions[i]);
    }
    free(records);
    free(keys);
    free(timestamps);
    free(descriptions);

    disconnect_from_database();
    return NULL;
}

