// Import necessary libraries
use std::process::Command;
use std::fs::{self, DirBuilder};
use std::path::Path;
use reqwest::Error as ReqwestError;

// Define a struct to hold configuration details
struct Config {
    remote_repo_url: String,
    branch: String,
}

// Function to check if directory exists remotely and clone it locally
fn sync_config_directory(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    // Check if the directory exists in the remote repository
    let client = reqwest::blocking::Client::new();
    let response = client.get(&config.remote_repo_url).send()?;
    if response.status().is_success() {
        // Clone the directory locally
        Command::new("git")
            .args(&["clone", &config.remote_repo_url, "."])
            .output()?;
    } else {
        // Create a new local directory and initialize it
        DirBuilder::new()
            .recursive(true)
            .create(".")?;
        Command::new("git")
            .args(&["init"])
            .current_dir(".")
            .output()?;
        // Push the new directory to the remote repository
        Command::new("git")
            .args(&["remote", "add", "origin", &config.remote_repo_url])
            .current_dir(".")
            .output()?;
        Command::new("git")
            .args(&["push", "-u", "origin", &config.branch])
            .current_dir(".")
            .output()?;
    }
    Ok(())
}

// Main function to demonstrate usage
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = Config {
        remote_repo_url: "https://github.com/user/config-repo.git".to_string(),
        branch: "main".to_string(),
    };
    sync_config_directory(&config)?;
    Ok(())
}
