// main.js

import FileLoader from './FileLoader';
import APIClient from './APIClient';

const fileLoader = new FileLoader();
const apiClient = new APIClient();

async function loadFiles(files) {
  for (const file of files) {
    try {
      await fileLoader.load(file);
      console.log(`Successfully loaded and executed ${file}`);
    } catch (error) {
      console.error(`Failed to load or execute ${file}:`, error);
    }
  }
}

async function fetchFileList() {
  try {
    const fileList = await apiClient.getFileList();
    return fileList;
  } catch (error) {
    console.error('Failed to fetch file list:', error);
    return [];
  }
}

async function updateFileQueue() {
  while (true) {
    try {
      const fileList = await fetchFileList();
      await loadFiles(fileList);
    } catch (error) {
      console.error('Error updating file queue:', error);
    }
    setTimeout(updateFileQueue, 60000); // Update every minute
  }
}

updateFileQueue();
