#include <iostream>
#include <list>

template<typename T>
void insertAfter(std::forward_list<T>& list, const T& searchValue, const T& valueToInsert) {
    auto it = std::find(list.begin(), list.end(), searchValue);

    if (it == list.end()) {
        // If searchValue is not found, insert at the end
        list.insert_after(std::prev(list.before_begin()), valueToInsert);
    } else {
        // Insert after the first occurrence of searchValue
        list.insert_after(it, valueToInsert);
    }
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertAfter(myList, "banana", "orange");

    for (const auto& item : myList) {
        std::cout << item << " ";
    }

    return 0;
}
