// Define a function to load external JavaScript files dynamically
function loadScript(url, callback) {
    const script = document.createElement('script');
    script.src = url;
    script.onload = () => {
        if (callback) callback();
    };
    script.onerror = (err) => {
        console.error(`Failed to load ${url}:`, err);
        if (callback) callback(err);
    };
    document.head.appendChild(script);
}

// Define a function to manage named semaphores
class NamedSemaphore {
    constructor(name, initialValue) {
        this.name = name;
        this.value = initialValue;
        this.waitingQueue = [];
    }

    acquire() {
        while (this.value <= 0 && this.waitingQueue.length > 0) {
            const waitingThread = this.waitingQueue.shift();
            clearTimeout(waitingThread.timer);
            waitingThread.resolve();
        }
        if (this.value > 0) {
            this.value--;
            return Promise.resolve();
        } else {
            return new Promise((resolve, reject) => {
                const timer = setTimeout(() => {
                    reject(new Error(`Semaphore ${this.name} timed out`));
                }, 1000);
                this.waitingQueue.push({ resolve, reject, timer });
            });
        }
    }

    release() {
        if (this.value < Number.MAX_SAFE_INTEGER) {
            this.value++;
        } else {
            throw new Error(`Semaphore ${this.name} value overflow`);
        }
    }

    getValue() {
        return this.value;
    }
}

// Define a function to log application events
function log(event, details = {}) {
    console.log(new Date().toISOString(), event, JSON.stringify(details));
}

// Example usage of the NamedSemaphore class
async function exampleUsage() {
    const semaphore = new NamedSemaphore('mySemaphore', 2);
    try {
        await semaphore.acquire();
        log('Semaphore acquired');
        // Perform critical section operations here
        semaphore.release();
        log('Semaphore released');
    } catch (error) {
        log('Error acquiring semaphore', { error });
    }
}

// Example usage of the loadScript function
function exampleLoadScripts() {
    loadScript('https://example.com/file1.js', () => {
        log('File 1 loaded and executed');
    });

    loadScript('https://example.com/file2.js', (err) => {
        if (err) {
            log('Error loading file 2', { error: err });
        } else {
            log('File 2 loaded and executed');
        }
    });
}

// Call the example functions
exampleUsage();
exampleLoadScripts();
