```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public abstract class HashAlgorithmFactory
{
    public static IHashAlgorithm CreateInstance(string algorithmName)
    {
        switch (algorithmName)
        {
            case "MD5":
                return new MD5HashAlgorithm();
            case "SHA1":
                return new SHA1HashAlgorithm();
            case "SHA256":
                return new SHA256HashAlgorithm();
            default:
                throw new ArgumentException("Unsupported algorithm");
        }
    }

    public abstract string ComputeHash(string input);
}

public interface IHashAlgorithm
{
    string ComputeHash(string input);
}

public class MD5HashAlgorithm : IHashAlgorithm
{
    public string ComputeHash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }
}

public class SHA1HashAlgorithm : IHashAlgorithm
{
    public string ComputeHash(string input)
    {
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = sha1.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }
}

public class SHA256HashAlgorithm : IHashAlgorithm
{
    public string ComputeHash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = sha256.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }
}

public class DynamicTextProcessor
{
    private IHashAlgorithm _hashAlgorithm;
    private int _maxInputLength;

    public DynamicTextProcessor(string algorithmName, int maxInputLength)
    {
        _hashAlgorithm = HashAlgorithmFactory.CreateInstance(algorithmName);
        _maxInputLength = maxInputLength;
    }

    public string ComputeHashSync(string input)
    {
        ValidateInput(input);
        return _hashAlgorithm.ComputeHash(input);
    }

    public async Task<string> ComputeHashAsync(string input)
    {
        ValidateInput(input);
        return await Task.Run(() => _hashAlgorithm.ComputeHash(input));
    }

    private void ValidateInput(string input)
    {
        if (input == null || input.Length > _maxInputLength)
        {
            throw new ArgumentException("Invalid input");
        }
    }
}

public class TextProcessingService
{
    public string processUserInput(string input, int maxLength, bool trim, bool capitalize)
    {
        if (input.Length > maxLength)
        {
            input = trim ? input.Substring(0, maxLength) : input;
        }

        if (capitalize)
        {
            input = input.ToUpper();
        }

        return input;
    }
}
