using System;
using System.IO;
using System.Threading.Tasks;

public class ConfigManager
{
    private readonly IConfigService _configService;
    private readonly IDatabaseContext _databaseContext;
    private readonly ILogger _logger;
    private readonly ICacheManager _cacheManager;
    private readonly IVersionControlService _versionControlService;

    public ConfigManager(IConfigService configService, IDatabaseContext databaseContext, ILogger logger, ICacheManager cacheManager, IVersionControlService versionControlService)
    {
        _configService = configService;
        _databaseContext = databaseContext;
        _logger = logger;
        _cacheManager = cacheManager;
        _versionControlService = versionControlService;
    }

    public async Task<string> UpdateUserConfigAsync(int userId, string configName, string newValue)
    {
        try
        {
            if (userId <= 0 || string.IsNullOrEmpty(configName) || string.IsNullOrEmpty(newValue))
            {
                return "Invalid input";
            }

            var existingConfig = await _configService.GetConfigAsync(userId, configName);
            if (existingConfig == null)
            {
                return "Configuration not found";
            }

            existingConfig.Value = newValue;
            await _databaseContext.SaveChangesAsync();

            _cacheManager.UpdateThemeBitmap(userId);

            await ParsePngFileFromCacheRootDirectoryAsync(userId);

            var changeLog = $"Updated config for user {userId}: {configName} = {newValue}";
            _versionControlService.LogChange(changeLog);
            _logger.Info(changeLog);

            return "Update successful";
        }
        catch (Exception ex)
        {
            _logger.Error(ex.Message, ex);
            return "An error occurred";
        }
    }

    private async Task ParsePngFileFromCacheRootDirectoryAsync(int userId)
    {
        var cacheRoot = _cacheManager.GetCacheRootPath(userId);
        if (!Directory.Exists(cacheRoot))
        {
            Directory.CreateDirectory(cacheRoot);
        }

        var pngFilePath = Path.Combine(cacheRoot, "theme.png");
        if (File.Exists(pngFilePath))
        {
            await Task.Run(() =>
            {
                using (var bitmap = new System.Drawing.Bitmap(pngFilePath))
                {
                    // Manage recycling and setting null for theme bitmaps
                    bitmap.Dispose();
                }
            });
        }

        // Ensure thread safety when checking if a theme bitmap is recycled
        lock (_cacheManager)
        {
            _cacheManager.ThemeBitmapRecycled = false;
        }
    }
}
