// Function to check rate limiting
function isRateLimited($ip) {
    // Implement your rate limiting logic here
    return false; // Return true if the user has exceeded the limit, otherwise false
}

// Function to handle database operations using prepared statements
function dbQuery($sql, $params = []) {
    global $pdo;
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    return $stmt->fetchAll(PDO::FETCH_ASSOC);
}

// Main function to handle user requests
function handleUserRequest() {
    if (isRateLimited($_SERVER['REMOTE_ADDR'])) {
        echo json_encode(['status' => 'error', 'message' => 'Too many requests from this IP']);
        exit;
    }

    $postData = $_POST;

    // Validate input
    if (!isset($postData['name']) || !isset($postData['email']) || !isset($postData['password'])) {
        echo json_encode(['status' => 'error', 'message' => 'Missing required fields']);
        return;
    }

    if (isset($postData['confirm_password']) && $postData['password'] !== $postData['confirm_password']) {
        echo json_encode(['status' => 'error', 'message' => 'Passwords do not match']);
        return;
    }

    if (strlen($postData['password']) < 8) {
        echo json_encode(['status' => 'error', 'message' => 'Password must be at least 8 characters long']);
        return;
    }

    $email = filter_var($postData['email'], FILTER_VALIDATE_EMAIL);
    if (!$email) {
        echo json_encode(['status' => 'error', 'message' => 'Invalid email address']);
        return;
    }

    // Check for unique email
    $userExists = dbQuery('SELECT * FROM users WHERE email = :email', ['email' => $email]);
    if (isset($postData['id']) && count($userExists) > 1) {
        echo json_encode(['status' => 'error', 'message' => 'Email already exists']);
        return;
    }
    if (!isset($postData['id']) && count($userExists) > 0) {
        echo json_encode(['status' => 'error', 'message' => 'Email already exists']);
        return;
    }

    $passwordHash = password_hash($postData['password'], PASSWORD_DEFAULT);

    if (isset($postData['sub_action']) && $postData['sub_action'] === 'delete') {
        // Delete user
        dbQuery('DELETE FROM users WHERE id = :id', ['id' => $postData['id']]);
        echo json_encode(['status' => 'success', 'message' => 'User deleted successfully']);
    } else {
        // Create or update user
        if (isset($postData['id'])) {
            // Update user
            dbQuery('UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id', [
                ':name' => $postData['name'],
                ':email' => $email,
                ':password' => $passwordHash,
                ':id' => $postData['id']
            ]);
            echo json_encode(['status' => 'success', 'message' => 'User updated successfully']);
        } else {
            // Create user
            dbQuery('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)', [
                ':name' => $postData['name'],
                ':email' => $email,
                ':password' => $passwordHash
            ]);
            echo json_encode(['status' => 'success', 'message' => 'User created successfully']);
        }
    }
}

// Call the function to handle user request
handleUserRequest();
?>
