    // Fetch current stock level from database or cache
    const cachedStock = await redisClient.get(`stock:${productId}`);
    let currentStock = cachedStock ? parseInt(cachedStock) : 0;

    // Update stock level
    currentStock += quantityChange;
    if (currentStock < 0) {
        return { status: 'error', message: 'Negative stock not allowed', data: null };
    }

    // Save new stock level to cache and database
    await redisClient.set(`stock:${productId}`, currentStock);
    const response = await axios.post(`${userManagementSystemUrl}/update-stock`, { productId, quantityChange });

    return { status: 'success', message: 'Inventory updated successfully', data: { product_id: productId, stock_level: currentStock, revenue: response.data.revenue, last_updated_by: userName } };
