    int energy;
    int distanceToEnemy;

    Character(int h, int e, int d) : health(h), energy(e), distanceToEnemy(d) {}

    void updateState(int newHealth, int newEnergy, int newDistance) {
        health = newHealth;
        energy = newEnergy;
        distanceToEnemy = newDistance;
    }
};

class AttackSelector {
private:
    std::atomic<int> cooldowns[3]{5, 7, 10};
    bool isCooldownExpired(int attackIndex) {
        return cooldowns[attackIndex] <= 0;
    }

public:
    void selectAttack(Character& character) {
        // Simulate time passing
        std::this_thread::sleep_for(std::chrono::seconds(1));

        int selectedAttack = -1;
        if (character.energy > 0 && isCooldownExpired(0)) {
            selectedAttack = 1;
        } else if (character.health < 50 && isCooldownExpired(1)) {
            selectedAttack = 2;
        } else if (character.distanceToEnemy < 10 && isCooldownExpired(2)) {
            selectedAttack = 3;
        }

        if (selectedAttack != -1) {
            std::cout << "Attacking with Attack " << selectedAttack
                      << ". Remaining cooldown: " << cooldowns[selectedAttack - 1] << " seconds." << std::endl;
            // Decrease energy based on attack cost and reset cooldown
            character.energy -= (selectedAttack == 1 ? 5 : 3);
            cooldowns[selectedAttack - 1] = selectedAttack == 1 ? 5 : (selectedAttack == 2 ? 7 : 10);
        } else {
            std::cout << "All attacks are on cooldown. Performing default action." << std::endl;
        }
    }

    void decrementCooldowns() {
        for (auto& cd : cooldowns) {
            if (cd > 0) {
                cd--;
            }
        }
    }
};

// Unit tests
void testAttackSelector() {
    Character character(100, 50, 2);
    AttackSelector selector;

    // Test attack selection based on health and energy
    selector.selectAttack(character); // Should choose Attack 3

    // Simulate cooldown passing
    for (int i = 0; i < 10; ++i) {
        selector.decrementCooldowns();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    // Test attack selection based on energy
    character.updateState(100, 5, 2);
    selector.selectAttack(character); // Should choose Attack 1

    // Simulate cooldown passing
    for (int i = 0; i < 6; ++i) {
        selector.decrementCooldowns();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    // Test no attack available
    character.updateState(100, 5, 2);
    selector.selectAttack(character); // Should perform default action

    // Simulate cooldown passing and test all on cooldown
    for (int i = 0; i < 17; ++i) {
        selector.decrementCooldowns();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    character.updateState(100, 5, 2);
    selector.selectAttack(character); // Should perform default action
}

int main() {
    testAttackSelector();
    return 0;
}
