using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class GameSettings
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public double CameraSpeed { get; set; }
}

public interface IConfigurationService
{
    Task<GameSettings> GetGameSettingsAsync();
    Task UpdateGameSettingsAsync(GameSettings settings);
}

public class ConfigurationClient : IConfigurationService
{
    private readonly HttpClient _httpClient;
    private GameSettings _cachedSettings;

    public ConfigurationClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<GameSettings> GetGameSettingsAsync()
    {
        if (_cachedSettings != null)
            return _cachedSettings;

        try
        {
            var response = await _httpClient.GetAsync("https://api.configservice.com/game/settings");
            response.EnsureSuccessStatusCode();
            _cachedSettings = await response.Content.ReadAsAsync<GameSettings>();
            return _cachedSettings;
        }
        catch (HttpRequestException ex)
        {
            // Handle network failure or invalid configuration
            Console.WriteLine($"Error fetching settings: {ex.Message}");
            throw new InvalidOperationException("Failed to fetch game settings", ex);
        }
    }

    public async Task UpdateGameSettingsAsync(GameSettings settings)
    {
        try
        {
            var response = await _httpClient.PutAsJsonAsync("https://api.configservice.com/game/settings", settings);
            response.EnsureSuccessStatusCode();
        }
        catch (HttpRequestException ex)
        {
            // Handle network failure or unexpected data format
            Console.WriteLine($"Error updating settings: {ex.Message}");
            throw new InvalidOperationException("Failed to update game settings", ex);
        }

        // Invalidate cache after successful update
        _cachedSettings = null;
    }
}

public class GameManager : IDisposable
{
    private readonly IConfigurationService _configService;
    private GameSettings _currentSettings;

    public GameManager(IConfigurationService configService)
    {
        _configService = configService;
        LoadSettings();
    }

    public int TileSize => _currentSettings.TileSize;
    public int WorldWidth => _currentSettings.WorldWidth;
    public int WorldHeight => _currentSettings.WorldHeight;
    public double CameraSpeed => _currentSettings.CameraSpeed;

    private async void LoadSettings()
    {
        try
        {
            _currentSettings = await _configService.GetGameSettingsAsync();
        }
        catch (InvalidOperationException ex)
        {
            // Handle error and possibly fallback to default settings
            Console.WriteLine(ex.Message);
        }
    }

    public async Task UpdateSettings(GameSettings newSettings)
    {
        try
        {
            await _configService.UpdateGameSettingsAsync(newSettings);
            LoadSettings();
        }
        catch (InvalidOperationException ex)
        {
            // Handle error and possibly notify user
            Console.WriteLine(ex.Message);
        }
    }

    public void Dispose()
    {
        // Clean up resources if necessary
    }
}

public class GameConfigUI
{
    private readonly GameManager _gameManager;

    public GameConfigUI(GameManager gameManager)
    {
        _gameManager = gameManager;
    }

    public void DisplaySettings()
    {
        Console.WriteLine($"Tile Size: {_gameManager.TileSize}");
        Console.WriteLine($"World Width: {_gameManager.WorldWidth}");
        Console.WriteLine($"World Height: {_gameManager.WorldHeight}");
        Console.WriteLine($"Camera Speed: {_gameManager.CameraSpeed}");
    }

    public async Task UpdateSettingsAsync(int tileSize, int worldWidth, int worldHeight, double cameraSpeed)
    {
        var newSettings = new GameSettings
        {
            TileSize = tileSize,
            WorldWidth = worldWidth,
            WorldHeight = worldHeight,
            CameraSpeed = cameraSpeed
        };

        await _gameManager.UpdateSettings(newSettings);
    }
}

// Usage example
public class Program
{
    public static async Task Main(string[] args)
    {
        var httpClient = new HttpClient();
        var configService = new ConfigurationClient(httpClient);
        var gameManager = new GameManager(configService);
        var ui = new GameConfigUI(gameManager);

        // Display current settings
        ui.DisplaySettings();

        // Update settings via UI (example input)
        await ui.UpdateSettingsAsync(32, 1024, 768, 0.5);

        // Display updated settings
        ui.DisplaySettings();
    }
}
