public class SiteManager
{
    public static string AddAndStartSite(string directoryPath, string siteName, string mode = "release", int maxRetries = 3, int timeout = 60)
    {
        if (!Directory.Exists(directoryPath) || !Directory.HasFileSystemInfos(directoryPath))
        {
            return "Error: Directory does not exist or is inaccessible.";
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            return null;
        }

        var siteSettings = GetSiteSettingsFromService(siteName);
        if (siteSettings == null)
        {
            return "Error: Failed to retrieve settings from configuration service.";
        }

        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                var processInfo = new ProcessStartInfo
                {
                    FileName = "dotnet",
                    Arguments = $"run --project {directoryPath} --configuration {mode}",
                    WorkingDirectory = directoryPath,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                if (!string.IsNullOrEmpty(siteSettings.Arguments))
                {
                    processInfo.Arguments += $" {siteSettings.Arguments}";
                }

                using (var process = new Process { StartInfo = processInfo })
                {
                    process.Start();

                    if (!process.WaitForExit(timeout * 1000))
                    {
                        return "Error: Site start timed out.";
                    }

                    var output = process.StandardOutput.ReadToEnd();
                    var error = process.StandardError.ReadToEnd();

                    if (string.IsNullOrEmpty(error) && string.IsNullOrEmpty(output))
                    {
                        return $"Site '{siteName}' started successfully in {mode} mode.";
                    }
                    else
                    {
                        return $"Error: Failed to start site. Output: {output}, Error: {error}";
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.LogError($"Failed to start site. Attempt {attempt + 1}: {ex.Message}");
            }
        }

        return "Error: Maximum retry attempts reached.";
    }

