#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// Define semaphore structure
typedef struct {
    sem_t *sem;
    char *name;
    int value;
} Semaphore;

// Initialize a semaphore
Semaphore* create_semaphore(const char *name, int initial_value) {
    Semaphore *s = malloc(sizeof(Semaphore));
    if (s == NULL) return NULL; // Handle memory allocation failure

    s->name = strdup(name);
    sem_init(&s->sem, 0, initial_value);

    return s;
}

// Destroy a semaphore
void destroy_semaphore(Semaphore *s) {
    sem_destroy(s->sem);
    free(s->name);
    free(s);
}

// Acquire (wait on) the semaphore
int acquire_semaphore(Semaphore *s) {
    int err = sem_wait(s->sem);
    if (err != 0) return -1; // Handle error condition

    return 0;
}

// Release (post) the semaphore
int release_semaphore(Semaphore *s) {
    int err = sem_post(s->sem);
    if (err != 0) return -1; // Handle error condition

    return 0;
}

// Example usage of the semaphore library
int main() {
    Semaphore *my_sem = create_semaphore("my_semaphore", 1); // Create a semaphore with initial value 1
    if (my_sem == NULL) {
        perror("Failed to create semaphore");
        return EXIT_FAILURE;
    }

    if (acquire_semaphore(my_sem) != 0) {
        perror("Failed to acquire semaphore");
        destroy_semaphore(my_sem);
        return EXIT_FAILURE;
    }

    printf("Semaphore acquired\n");

    if (release_semaphore(my_sem) != 0) {
        perror("Failed to release semaphore");
    } else {
        printf("Semaphore released\n");
    }

    destroy_semaphore(my_sem); // Destroy the semaphore
    return EXIT_SUCCESS;
}
