// Function to log a message with dynamic formatting and variable arguments
void asyncLogCondition(int severity, const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Get the current time for timestamping
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    // Format the message with timestamp and severity level
    char logMessage[256];
    snprintf(logMessage, sizeof(logMessage), "[%s] [%d] ", buffer, severity);

    // Append the formatted user input to the log message
    vsnprintf(logMessage + strlen(logMessage), sizeof(logMessage) - strlen(logMessage), format, args);

    va_end(args);

    // Log the message to a file or external logging system
    FILE* logFile = fopen("error_log.txt", "a");
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", logMessage);
