function asyncArrayReduce(numbers, initialValue, callback) {
    let accumulator = initialValue;
    const promises = numbers.map((number) => 
        new Promise((resolve, reject) => {
            callback(accumulator, number)
                .then((value) => {
                    accumulator = value;
                    resolve();
                })
                .catch((error) => {
                    reject(error);
                });
        })
    );
    return Promise.all(promises).then(() => accumulator);
}
