async fn fetch_weather(location: &str, config: &Config) -> Result<WeatherData, Error> {
    let client = reqwest::Client::new();
    let url = format!("https://api.weather.com/data/2.5/weather?q={}&appid={}", location, config.api_key);
    let response = client.get(&url).send().await?;
    response.json::<WeatherData>().await
}

async fn update_weather_cache(client: &RedisClient, location: &str, weather_data: WeatherData) -> Result<(), redis::Error> {
    client.set_ex(location, serde_json::to_string(&weather_data)?, config.update_interval as usize).await?;
    Ok(())
}

async fn get_cached_weather(client: &RedisClient, location: &str) -> Result<Option<WeatherData>, Error> {
    let cache_key = format!("weather_{}", location);
    if let Some(cache_data) = client.get::<&str, String>(&cache_key).await? {
        return Ok(Some(serde_json::from_str(&cache_data)?));
    }
    Ok(None)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config: Config = serde_json::from_str(r#"{"api_key": "your_api_key", "update_interval": 3600}"#)?;
    let redis_client = Client::open("redis://127.0.0.1/").await?;
    let location = "New York";

    loop {
        if let Some(weather_data) = get_cached_weather(&redis_client, location).await? {
            println!("Cached weather data: {:?}", weather_data);
        } else {
            match fetch_weather(location, &config).await {
                Ok(weather_data) => {
                    update_weather_cache(&redis_client, location, weather_data.clone()).await?;
                    println!("Fetched and cached weather data: {:?}", weather_data);
                }
                Err(e) => eprintln!("Failed to fetch weather data: {}", e),
            }
        }
        tokio::time::sleep(tokio::time::Duration::from_secs(config.update_interval)).await;
    }
}
