<?php

class Clinic {
    public $id;
    public $status;
    public $location;
    public $capacity;
    public $lastModifiedIP;
    public $lastModifiedDate;

    public function __construct($id, $status, $location, $capacity) {
        $this->id = $id;
        $this->status = $status;
        $this->location = $location;
        $this->capacity = $capacity;
        $this->lastModifiedIP = $_SERVER['REMOTE_ADDR'];
        $this->lastModifiedDate = date('Y-m-d H:i:s');
    }
}

class ClinicManager {
    private $database;

    public function __construct($dbConnection) {
        $this->database = $dbConnection;
    }

    public function createClinic($id, $status, $location, $capacity) {
        $clinic = new Clinic($id, $status, $location, $capacity);
        $query = "INSERT INTO clinics (id, status, location, capacity, last_modified_ip, last_modified_date)
                  VALUES (:id, :status, :location, :capacity, :lastModifiedIP, :lastModifiedDate)";
        $stmt = $this->database->prepare($query);
        return $stmt->execute([
            'id' => $clinic->id,
            'status' => $clinic->status,
            'location' => $clinic->location,
            'capacity' => $clinic->capacity,
            'lastModifiedIP' => $clinic->lastModifiedIP,
            'lastModifiedDate' => $clinic->lastModifiedDate
        ]);
    }

    public function updateClinic($id, $newStatus) {
        $query = "SELECT * FROM clinics WHERE id = :id";
        $stmt = $this->database->prepare($query);
        $stmt->execute(['id' => $id]);
        $clinic = $stmt->fetchObject(Clinic::class);

        if ($clinic) {
            $clinic->status = $newStatus;
            $clinic->lastModifiedIP = $_SERVER['REMOTE_ADDR'];
            $clinic->lastModifiedDate = date('Y-m-d H:i:s');

            if ($newStatus === 'closed' || $newStatus === 'emergency') {
                $this->notifyExternalServices($newStatus, $clinic);
                $this->updateOccupancyLevels($newStatus, $clinic);
            }

            $query = "UPDATE clinics SET status = :status, last_modified_ip = :lastModifiedIP, last_modified_date = :lastModifiedDate
                      WHERE id = :id";
            $stmt = $this->database->prepare($query);
            return $stmt->execute([
                'status' => $clinic->status,
                'lastModifiedIP' => $clinic->lastModifiedIP,
                'lastModifiedDate' => $clinic->lastModifiedDate,
                'id' => $clinic->id
            ]);
        }

        return false;
    }

