```javascript
async function loadAndExecuteTests(moduleLabel, testSuites, config, loggingLevel) {
  const { concurrency, timeout, resourceLimits } = config;
  let totalTests = 0;
  let passedTests = 0;
  let failedTests = 0;

  for (const suite of testSuites) {
    for (const testCase of suite) {
      totalTests++;
      try {
        await testCase();
        passedTests++;
        console.log(`[${moduleLabel}] ${testCase.name} passed`);
      } catch (error) {
        failedTests++;
        console.error(`[${moduleLabel}] ${testCase.name} failed:`, error);
      }
    }
  }

  const passRate = ((passedTests / totalTests) * 100).toFixed(2);
  const failRate = ((failedTests / totalTests) * 100).toFixed(2);

  console.log(`Test Summary: ${totalTests} tests executed`);
  console.log(`Pass Rate: ${passRate}%`);
  console.log(`Fail Rate: ${failRate}%`);

  if (loggingLevel === 'detailed') {
    console.log(`Passed Tests:`, passedTests);
    console.log(`Failed Tests:`, failedTests);
  }
}
