const axios = require('axios');
const { v4: uuidv4 } = require('uuid');
const _ = require('lodash');

class PaymentGateway {
  constructor(gatewayConfig) {
    this.gatewayConfig = gatewayConfig;
    this.accessTokenCache = {};
  }

  async authenticate() {
    const tokenKey = `auth_token_${this.gatewayConfig.id}`;
    if (!this.accessTokenCache[tokenKey]) {
      try {
        const response = await axios.post(this.gatewayConfig.authUrl, {
          client_id: this.gatewayConfig.clientId,
          client_secret: this.gatewayConfig.clientSecret,
          grant_type: 'client_credentials',
        });
        this.accessTokenCache[tokenKey] = {
          token: response.data.access_token,
          expiresAt: Date.now() + (response.data.expires_in * 1000),
        };
      } catch (error) {
        throw new Error(`Authentication failed for ${this.gatewayConfig.name}`);
      }
    }
    return this.accessTokenCache[tokenKey].token;
  }

  async verifyTransaction(transactionId, orderId) {
    try {
      const token = await this.authenticate();
      const response = await axios.get(`${this.gatewayConfig.baseUrl}/transactions/${transactionId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return {
        status: response.data.status,
        customerDetails: response.data.customer_details,
        orderID: orderId,
      };
    } catch (error) {
      if (axios.isAxiosError(error)) {
        if (error.response && error.response.status === 429) {
          // Handle rate limiting
          await this.handleRateLimiting();
        }
      }
      throw new Error(`Transaction verification failed for ${this.gatewayConfig.name}`);
    }
  }

  async handleRateLimiting() {
    return new Promise((resolve, reject) => {
      setTimeout(() => resolve(), 1000); // Example delay
    });
  }

  static log(message, level = 'info') {
    console.log(`[${level.toUpperCase()}] ${message}`);
  }
}

// Usage example:
const paymentGatewayConfig = {
  id: 'stripe',
  name: 'Stripe',
  authUrl: 'https://api.stripe.com/oauth/token',
  clientId: 'your_client_id',
  clientSecret: 'your_client_secret',
  baseUrl: 'https://api.stripe.com/v1',
};

const stripeGateway = new PaymentGateway(paymentGatewayConfig);

async function verifyTransactionExample() {
  try {
    const transactionId = 'txn_1234567890';
    const orderId = 'order_1234567890';
    const result = await stripeGateway.verifyTransaction(transactionId, orderId);
    PaymentGateway.log(`Transaction ${transactionId} verified. Status: ${result.status}`);
  } catch (error) {
    PaymentGateway.log(error.message, 'error');
  }
}

verifyTransactionExample();
