// server.js
const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const redis = require('redis');
const rateLimit = require('express-rate-limit');

const app = express();
const port = process.env.PORT || 3000;

app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

const redisClient = redis.createClient();

redisClient.on('error', (err) => {
  console.log('Redis error:', err);
});

async function getOldTestamentBooks() {
  const response = await axios.get(process.env.OLD_TESTAMENT_BOOKS_URL);
  return response.data;
}

function matchBookNames(text, books) {
  const regex = new RegExp(`\\b(${books.join('|')})\\b`, 'gi');
  const matches = text.match(regex);
  return matches ? matches.map(match => match.toLowerCase()) : [];
}

app.post('/process', async (req, res) => {
  try {
    const text = req.body.text;
    if (!text) {
      return res.status(400).send('No text provided');
    }

    const books = await getOldTestamentBooks();
    const matches = matchBookNames(text, books);
    const bookCounts = {};

    for (const book of matches) {
      bookCounts[book] = (bookCounts[book] || 0) + 1;
    }

    res.json(bookCounts);
  } catch (error) {
    console.error('Error processing text:', error);
    res.status(500).send('Internal server error');
  }
});

app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});
