enum RecorderType { DATABASE, FILE, PAYMENT_PROCESSOR };

struct TransactionDetails {
    std::string id;
    std::string amount;
    std::string status;
    // Add more fields as needed
};

class DatabaseRecorder {
public:
    bool record(const TransactionDetails& details) {
        // Simulate database recording
        std::cout << "Recording to database: " << details.id << ", " << details.amount << ", " << details.status << std::endl;
        return true; // Simulated success
    }
};

class FileRecorder {
public:
    bool record(const TransactionDetails& details) {
        // Simulate file recording
        std::cout << "Recording to file: " << details.id << ", " << details.amount << ", " << details.status << std::endl;
        return true; // Simulated success
    }
};

class PaymentProcessor {
public:
    bool processPayment(const TransactionDetails& details) {
        // Simulate payment processing
        std::cout << "Processing payment: " << details.id << ", " << details.amount << std::endl;
        return true; // Simulated success
    }
};

class TransactionLogger {
private:
    RecorderType currentRecorderType;
    std::unique_ptr<DatabaseRecorder> dbRecorder;
    std::unique_ptr<FileRecorder> fileRecorder;
    std::unique_ptr<PaymentProcessor> paymentProcessor;

    static std::mutex loggerMutex;

public:
    TransactionLogger(RecorderType type) : currentRecorderType(type), dbRecorder(new DatabaseRecorder()), fileRecorder(new FileRecorder()), paymentProcessor(new PaymentProcessor()) {}

    void setRecorderType(RecorderType type) {
        currentRecorderType = type;
    }

    std::optional<int> recordTransaction(const std::string& transactionId, const TransactionDetails& details) {
        std::lock_guard<std::mutex> lock(loggerMutex);

        switch (currentRecorderType) {
            case DATABASE:
                if (dbRecorder->record(details)) {
                    return 0; // Success
                } else {
                    std::cerr << "Failed to record to database" << std::endl;
                    return -1; // Error
                }
            case FILE:
                if (fileRecorder->record(details)) {
                    return 0; // Success
                } else {
                    std::cerr << "Failed to record to file" << std::endl;
                    return -2; // Error
                }
            case PAYMENT_PROCESSOR:
                if (paymentProcessor->processPayment(details)) {
                    return 0; // Success
                } else {
                    std::cerr << "Failed to process payment" << std::endl;
                    return -3; // Error
                }
            default:
                std::cerr << "Unknown recorder type" << std::endl;
                return -4; // Error
        }
    }
};

std::mutex TransactionLogger::loggerMutex;

int main() {
    TransactionLogger logger(DATABASE);
    TransactionDetails details = {"123", "100.00", "Completed"};
    auto result = logger.recordTransaction("123456789", details, DATABASE);
    if (result) {
        std::cout << "Transaction recorded successfully" << std::endl;
    } else {
        std::cerr << "Failed to record transaction: " << *result << std::endl;
    }
    return 0;
}
