#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    sem_t *sem;
    char *log_file_path;
} SemaphoreManager;

SemaphoreManager* semaphore_manager_create(int initial_value, const char *log_file_path) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!manager) {
        perror("Failed to allocate memory for semaphore manager");
        return NULL;
    }

    manager->sem = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, initial_value);
    if (manager->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }

    manager->log_file_path = strdup(log_file_path);
    if (!manager->log_file_path) {
        perror("Failed to allocate memory for log file path");
        sem_close(manager->sem);
        sem_unlink("/my_semaphore");
        free(manager);
        return NULL;
    }

    printf("Semaphore created successfully\n");
    return manager;
}

void semaphore_manager_increment(SemaphoreManager *manager) {
    if (sem_post(manager->sem) == -1) {
        perror("Failed to increment semaphore");
    }
    printf("Semaphore incremented\n");
}

void semaphore_manager_decrement(SemaphoreManager *manager) {
    if (sem_wait(manager->sem) == -1) {
        perror("Failed to decrement semaphore");
    }
    printf("Semaphore decremented\n");
}

void semaphore_manager_delete(SemaphoreManager *manager) {
    if (sem_close(manager->sem) == -1) {
        perror("Failed to close semaphore");
    }

    if (sem_unlink("/my_semaphore") == -1) {
        perror("Failed to unlink semaphore");
    }

    free(manager->log_file_path);
    free(manager);

    printf("Semaphore deleted\n");
}

void log_semaphore_operation(const char *operation, const char *result) {
    FILE *log_file = fopen("semaphore_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: %s\n", operation, result);
    fclose(log_file);
}

// Example usage
int main() {
    SemaphoreManager *manager = semaphore_manager_create(1, "semaphore_log.txt");
    if (manager) {
        semaphore_manager_increment(manager);
        semaphore_manager_decrement(manager);
        semaphore_manager_delete(manager);
    }

    return 0;
}
```

This code defines a `SemaphoreManager` structure to manage a semaphore and its associated operations. It includes functions to create, increment, decrement, and delete the semaphore, as well as log semaphore operations. The code uses RAII principles by managing memory allocation and deallocation within the manager's creation and deletion functions. Error handling is included for creating, deleting, and manipulating the semaphore. The `log_semaphore_operation` function demonstrates how to log semaphore operations to a file.

