using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public abstract class HashAlgorithmFactory
{
    public static IHashAlgorithm Create(string algorithmName)
    {
        switch (algorithmName.ToLower())
        {
            case "md5":
                return new MD5HashAlgorithm();
            case "sha1":
                return new SHA1HashAlgorithm();
            case "sha256":
                return new SHA256HashAlgorithm();
            default:
                throw new ArgumentException("Unsupported hash algorithm.");
        }
    }
}

public interface IHashAlgorithm
{
    Task<string> GenerateAsync(string input);
    Task<string> GenerateAsync(byte[] input);
    Task<byte[]> GenerateBytesAsync(string input);
    Task<byte[]> GenerateBytesAsync(byte[] input);
}

public class MD5HashAlgorithm : IHashAlgorithm
{
    public async Task<string> GenerateAsync(string input)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = await GenerateBytesAsync(input);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public async Task<string> GenerateAsync(byte[] input)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = await GenerateBytesAsync(input);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public async Task<byte[]> GenerateBytesAsync(string input)
    {
        using (var md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            return await GenerateBytesAsync(inputBytes);
        }
    }

    public async Task<byte[]> GenerateBytesAsync(byte[] input)
    {
        using (var md5 = MD5.Create())
        {
            return await Task.Run(() => md5.ComputeHash(input));
        }
    }
}

public class SHA1HashAlgorithm : IHashAlgorithm
{
    // Similar implementation to MD5HashAlgorithm but with SHA1
}

public class SHA256HashAlgorithm : IHashAlgorithm
{
    // Similar implementation to MD5HashAlgorithm but with SHA256
}

public class SecureDataProcessor
{
    private readonly ILogger _logger;

    public SecureDataProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public async Task<string> GenerateMd5Async(string input)
    {
        var hashAlgorithm = HashAlgorithmFactory.Create("md5");
        var stopwatch = Stopwatch.StartNew();
        try
        {
            string result = await hashAlgorithm.GenerateAsync(input);
            stopwatch.Stop();
            _logger.LogInfo($"MD5 generated in {stopwatch.ElapsedMilliseconds} ms.");
            return result;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating MD5 hash.");
            throw;
        }
    }

    // Implement other methods similarly...
}

public interface ILogger
{
    void LogInfo(string message);
    void LogWarning(string message);
    void LogError(Exception exception, string message);
}

public class ConsoleLogger : ILogger
{
    public void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    public void LogWarning(string message)
    {
        Console.WriteLine($"WARNING: {message}");
    }

    public void LogError(Exception exception, string message)
    {
        Console.WriteLine($"ERROR: {message} - Exception: {exception.Message}");
    }
}
