```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Function prototypes
void* semaphore_manager(void* arg);
void create_semaphore(int initial_value);
void delete_semaphore(sem_t* sem);

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <initial_value>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int initial_value = atoi(argv[1]);

    pthread_t manager_thread;
    if (pthread_create(&manager_thread, NULL, semaphore_manager, &initial_value) != 0) {
        perror("Failed to create manager thread");
        return EXIT_FAILURE;
    }

    pthread_join(manager_thread, NULL);
    return EXIT_SUCCESS;
}

void* semaphore_manager(void* arg) {
    int initial_value = *(int*)arg;

    sem_t* my_semaphore = malloc(sizeof(sem_t));
    if (my_semaphore == NULL) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }

    // Initialize the semaphore
    if (sem_init(my_semaphore, 0, initial_value) != 0) {
        perror("Failed to initialize semaphore");
        free(my_semaphore);
        return NULL;
    }

    printf("Semaphore created with initial value %d\n", initial_value);

    // Simulate some operations
    for (int i = 0; i < 5; i++) {
        if (sem_wait(my_semaphore) != 0) {
            perror("Failed to wait on semaphore");
            sem_destroy(my_semaphore);
            free(my_semaphore);
            return NULL;
        }

        printf("Semaphore value: %ld\n", sem_getvalue(my_semaphore, NULL));

        // Simulate some processing time
        sleep(1);

        if (sem_post(my_semaphore) != 0) {
            perror("Failed to post on semaphore");
            sem_destroy(my_semaphore);
            free(my_semaphore);
            return NULL;
        }
    }

    // Clean up
    delete_semaphore(my_semaphore);
