```javascript
class BibleTextAnalyzer {
    constructor() {
        this.oldTestamentBooks = [
            "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
            // ... (other Old Testament book names)
        ];
        this.newTestamentBooks = [
            "Matthew", "Mark", "Luke", "John", "Acts", "Romans", 
            // ... (other New Testament book names)
        ];

        this.oldTestamentRegex = new RegExp(this.createBookPattern(this.oldTestamentBooks), 'gi');
        this.newTestamentRegex = new RegExp(this.createBookPattern(this.newTestamentBooks), 'gi');

        this.bookRegistry = {};
    }

    static createFactoryFunction(bookType, books) {
        return function() {
            const analyzer = new BibleTextAnalyzer();
            analyzer[`${bookType}Regex`] = new RegExp(analyzer.createBookPattern(books), 'gi');
            return analyzer;
        };
    }

    createBookPattern(books) {
        return books.map(book => `\\b${book}\\b`).join('|');
    }

    extractBooks(text) {
        if (typeof text !== 'string' || text.trim() === '') {
            throw new Error('Invalid input: Text must be a non-empty string.');
        }

        const oldTestamentBooks = text.match(this.oldTestamentRegex) || [];
        const newTestamentBooks = text.match(this.newTestamentRegex) || [];

        return [...new Set([...oldTestamentBooks, ...newTestamentBooks])];
    }
}

class Old TestamentAnalyzer extends BibleTextAnalyzer {
    constructor() {
        super();
        this.bookRegistry['old'] = BibleTextAnalyzer.createFactoryFunction('old', this.oldTestamentBooks);
    }
}

class New TestamentAnalyzer extends BibleTextAnalyzer {
    constructor() {
        super();
        this.bookRegistry['new'] = BibleTextAnalyzer.createFactoryFunction('new', this.newTestamentBooks);
    }
}

