```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public class MessageDecryptor
{
    private static readonly byte[] Key = Encoding.UTF8.GetBytes("YourKeyHere");
    private static readonly byte[] IV = Encoding.UTF8.GetBytes("YourIVHere");

    public string DecryptAndValidateMessage(string base64EncodedEncryptedMessage)
    {
        try
        {
            // Decode the Base64-encoded message
            byte[] encryptedData = Convert.FromBase64String(base64EncodedEncryptedMessage);

            // Extract the HMAC SHA256 part and the encrypted data part
            int hmacLength = 32; // Length of HMAC SHA256 hash in bytes
            byte[] hmacBytes = new byte[hmacLength];
            Array.Copy(encryptedData, hmacBytes, hmacLength);
            byte[] encryptedMessageBytes = new byte[encryptedData.Length - hmacLength];
            Array.Copy(encryptedData, hmacLength, encryptedMessageBytes, 0, encryptedMessageBytes.Length);

            // Create the HMAC SHA256 validator
            using (HMACSHA256 hmacValidator = new HMACSHA256(Key))
            {
                byte[] computedHash = hmacValidator.ComputeHash(encryptedMessageBytes);
                if (!computedHash.SequenceEqual(hmacBytes))
                {
                    throw new AuthenticationException("HMAC validation failed.");
                }
            }

            // Decrypt the message using Triple DES
            using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
            {
                tripleDES.Key = Key;
                tripleDES.IV = IV;
                tripleDES.Mode = CipherMode.CBC;

                ICryptoTransform decryptor = tripleDES.CreateDecryptor(tripleDES.Key, tripleDES.IV);
                using (MemoryStream msDecrypt = new MemoryStream(encryptedMessageBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Error: {ex.Message}");
            throw;
        }
    }
}
