        {
            string dynamicSqlQuery = GenerateDynamicSqlQuery(byteArray);

            sqlCommand = new SqlCommand(dynamicSqlQuery, sqlConnection);
            sqlCommand.CommandTimeout = 3600; // Set a timeout for the query

            sqlDataReader = await sqlCommand.ExecuteReaderAsync();

            dataTable = new DataTable();
            dataTable.Load(sqlDataReader);

            return dataTable.CreateDataReader();
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            throw;
        }
