        if weather_description:
            new_line = f"employee_name={emp_data['name']},city={emp_data['city']},address={emp_data['address']},dept_name={emp_data['dept_name']},manager_id={emp_data['manager_id']},manager_name={emp_data['manager_name']},weather={weather_description}\n"
            for _ in range(3):
                try:
                    result = subprocess.run(['sed', '-i', f"s/PLACEHOLDER_{emp_id}/{new_line}/", kickstart_file_path], check=True)
                    if result.returncode == 0:
                        logging.info(f"Successfully updated Kickstart file for employee {emp_id} with weather information")
                        break
                except subprocess.CalledProcessError as e:
                    logging.warning(f"Failed to update Kickstart file for employee {emp_id} with weather information: {e}")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Modify Kickstart configuration and encrypt passwords")
    parser.add_argument("kickstart_file_path", help="Path to the Kickstart configuration file")
    parser.add_argument("--department_ids", nargs='+', type=int, help="List of department IDs for filtering employees")

    args = parser.parse_args()

    main(args.kickstart_file_path, args.department_ids)
