class DatabaseManager {
private:
    sqlite3* db;
    std::mutex mutex;

public:
    DatabaseManager(const char* filename) {
        int rc = sqlite3_open(filename, &db);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Cannot open database");
        }
    }

    ~DatabaseManager() {
        sqlite3_close(db);
    }

    void addUserPreference(const std::string& location, const std::string& time, int brightnessThreshold, int contrastThreshold) {
        std::lock_guard<std::mutex> lock(mutex);
        char* errMsg = nullptr;
        sqlite3_exec(db, "INSERT INTO preferences (location, time, brightness_threshold, contrast_threshold) VALUES (?, ?, ?, ?)",
                     [](void*, int argc, char** argv, char**) -> int { return 0; },
                     const_cast<void*>(static_cast<const void*>(&location)), &errMsg);
        if (errMsg != nullptr) {
            sqlite3_free(errMsg);
            throw std::runtime_error("SQL error: " + std::string(errMsg));
        }
    }

    // Add other methods for managing user preferences
};
