    public String analyzeWeaknesses(String pokemonName) {
        try (Connection connection = getConnection(); // Use try-with-resources for database connection
             Statement statement = connection.createStatement()) {

            // Get Pokemon type from API
            String type = pokemonTypeService.getType(pokemonName);

