            for (Weakness weakness : weaknesses) {
                result.append(weakness.getName()).append(": Strength ").append(weakness.getStrength());
                if (!weakness.getMoves().isEmpty()) {
                    result.append(", Exploited by: ").append(String.join(", ", weakness.getMoves()));
                }
                result.append("\n");
            }

            return result.toString();

        } catch (SQLException e) {
            // Handle database error
            return "Error: Database connection failed.";
        } catch (Exception e) {
            // Handle other errors
            return "Error: An unexpected error occurred.";
        }
    }

    private Connection getConnection() throws SQLException {
        // Simulate getting a database connection
        return DriverManager.getConnection("jdbc:mysql://localhost", "user", "password"); // Replace with actual connection logic
    }
