extern crate reqwest;
extern crate tokio;

use std::collections::HashMap;
use std::env;
use std::sync::{Arc, Mutex};
use tokio::task;
use chrono::{Local, Duration};

#[derive(Debug)]
struct WeatherData {
    current: CurrentWeather,
    forecast: Vec<Forecast>,
}

#[derive(Debug)]
struct CurrentWeather {
    temperature: f32,
    condition: String,
}

#[derive(Debug)]
struct Forecast {
    time: String,
    temperature: f32,
    condition: String,
}

async fn fetch_weather(api_url: &str, api_key: &str, city: &str) -> Result<WeatherData, reqwest::Error> {
    let url = format!("{}?q={}&appid={}", api_url, city, api_key);
    let response = reqwest::get(&url).await?;
    response.json().await
}

async fn get_weather(api_cache: Arc<Mutex<HashMap<String, WeatherData>>>, api_url: &str, api_key: &str, city: &str) -> WeatherData {
    if let Some(weather_data) = api_cache.lock().unwrap().get(city) {
        return weather_data.clone();
    }

    let weather_data = fetch_weather(api_url, api_key, city).await;
    match weather_data {
        Ok(data) => {
            api_cache.lock().unwrap().insert(city.to_string(), data.clone());
            data
        }
        Err(_) => panic!("Failed to fetch weather data"),
    }
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <city>", args[0]);
        return;
    }

    let city = &args[1];
    let api_cache = Arc::new(Mutex::new(HashMap::new()));
    let api_url = "https://api.openweathermap.org/data/2.5/weather";
    let api_key = env!("OPENWEATHERMAP_API_KEY");

    let weather_data = get_weather(api_cache.clone(), api_url, api_key, city).await;

    println!("Current Weather in {}: {}, {:.1}°C", city, weather_data.current.condition, weather_data.current.temperature);
    for forecast in &weather_data.forecast {
        println!("{}: {:.1}°C, {}", forecast.time, forecast.temperature, forecast.condition);
    }
}
