#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILES 100
#define BUFFER_SIZE 1024

void print_usage() {
    fprintf(stderr, "Usage: program [-c | -d] [-o output_file] [file1 [file2 ...]]\n");
}

int process_file(const char *filename, int compress, int decompress, FILE *output) {
    // Implement file processing logic here
    return 0;
}

int main(int argc, char *argv[]) {
    int compress = 0, decompress = 0;
    const char *output_file = NULL;
    FILE *output = stdout;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-c") == 0) {
            compress = 1;
        } else if (strcmp(argv[i], "-d") == 0) {
            decompress = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            output_file = argv[++i];
            if (!output_file) {
                fprintf(stderr, "Error: -o requires a filename.\n");
                print_usage();
                return 1;
            }
            output = fopen(output_file, "w");
            if (!output) {
                perror("Error opening output file");
                return 1;
            }
        } else {
            break; // First non-option argument is the first file
        }
    }

    if (i >= argc) {
        print_usage();
        return 1;
    }

    int total_lines = 0;
    for (; i < argc; ++i) {
        const char *filename = argv[i];
        if (strcmp(filename, "-") == 0) {
            filename = "stdin";
        }
        int lines = process_file(filename, compress, decompress, output);
        if (lines < 0) {
            fprintf(stderr, "Error processing file: %s\n", filename);
            continue;
        }
        total_lines += lines;
    }

    if (output != stdout && fclose(output)) {
        perror("Error closing output file");
        return 1;
    }

    fprintf(stdout, "Total lines processed: %d\n", total_lines);

    return 0;
}
