// Define record structure
typedef struct {
    long value;
    long timestamp;
} Record;

// Function to generate random values
long generateRandomValue() {
    return rand();
}

// Function to get current time in seconds since the epoch
long getCurrentTime() {
    return (long)time(NULL);
}

// Function to simulate database operations
int dbInsert(Record *records, int numRecords) {
    // Simulate successful database operation
    printf("Inserted %d records into the database.\n", numRecords);
    return 0;
}

// Function to simulate cache operations
void cacheFlush() {
    printf("Flushing cache to database.\n");
}

// Thread-safe function to initialize arrays and persist records
int initAndPersistRecords(int numRecords, int keyRange, long delayMin, long delayMax) {
    srand(time(NULL));

    // Allocate memory for arrays
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return -1;
    }

    int *keys = (int *)malloc(numRecords * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(offsets);
        return -2;
    }

    Record *records = (Record *)malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return -3;
    }

    // Initialize arrays with random values
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = generateRandomValue();
        keys[i] = rand() % keyRange;

        records[i].value = generateRandomValue();
        long delay = delayMin + rand() % (delayMax - delayMin);
        records[i].timestamp = getCurrentTime() + delay;
    }

    // Simulate database insertion
    int result = dbInsert(records, numRecords);
    if (result != 0) {
        fprintf(stderr, "Failed to insert records into the database.\n");
        free(offsets);
        free(keys);
        free(records);
        return -4;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}

// Example usage
int main() {
    int numRecords = 100;
    int keyRange = 1000;
    long delayMin = 10;
    long delayMax = 50;

    int result = initAndPersistRecords(numRecords, keyRange, delayMin, delayMax);
    if (result == 0) {
        printf("Records initialized and persisted successfully.\n");
    } else {
        printf("Failed to initialize and persist records. Error code: %d\n", result);
    }

    return 0;
}
