#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>

// Function to encrypt data using AES
int aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, const unsigned char *iv,
                unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        return -1;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        return -1;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        return -1;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to decrypt data using AES
int aes_decrypt(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *key, const unsigned char *iv,
                unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        return -1;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        return -1;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        return -1;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

// Function to hash data using MD5
void md5_hash(const unsigned char *data, int length, unsigned char *digest) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, data, length);
    MD5_Final(digest, &md5);
}

// Function to hash data using SHA-256
void sha256_hash(const unsigned char *data, int length, unsigned char *digest) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, data, length);
    SHA256_Final(digest, &sha256);
}

// Function to sign data using RSA and SHA1
int rsa_sign(const unsigned char *data, int datalen, const RSA *rsa, unsigned char *signature, unsigned int *siglen) {
    return RSA_sign(NID_sha1, data, datalen, signature, siglen, rsa);
}

// Function to verify RSA signature
int rsa_verify(const unsigned char *data, int datalen, const unsigned char *signature, int siglen, const RSA *rsa) {
    return RSA_verify(NID_sha1, data, datalen, signature, siglen, rsa);
}
