  const regex = /\b(Genesis|Exodus|Leviticus|Numbers|Moses|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiahus|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk(Zephaniah)|Zacharias|Malachi)\b/gi;
  const matches = text.match(regex);
  return matches ? matches.map(match => match.toLowerCase()) : [];
}

// Function to count occurrences of each book name
function countBookOccurrences(bookNames) {
  const counts = {};
  bookNames.forEach(name => {
    counts[name] = (counts[name] || 0) + 1;
  });
  return counts;
}

// Middleware for rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// API endpoint for processing text data
app.post('/process', async (req, res) => {
  const { text, format } = req.body;

  if (!text || !format) {
    return res.status(400).json({ error: 'Invalid request' });
  }

  try {
    const startTime = performance.now();

    // Retrieve list of Old Testament books from Redis cache
    let bookNames;
    await redisClient.get('books', async (err, cachedBooks) => {
      if (err) throw err;

      if (cachedBooks) {
        bookNames = JSON.parse(cachedBooks);
      } else {
        const books = await Book.find();
        bookNames = books.map(book => book.name.toLowerCase());
        redisClient.setex('books', 3600, JSON.stringify(bookNames)); // Cache for 1 hour
      }
    });

    // Extract book names from text
    const extractedBooks = extractBookNames(text);

    // Count occurrences of each book name
    const bookCounts = countBookOccurrences(extractedBooks);

    // Perform sentiment analysis on the text
    const sentimentScore = await analyzeSentiment(text);

    const endTime = performance.now();
    const processingTime = endTime - startTime;

    res.json({
      format,
      bookCounts,
      sentimentScore,
      processingTime,
    });
  } catch (error) {
    console.error('Error processing request:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
