```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

public class FileHasher {
    private final ExecutorService threadPool;
    private final ConcurrentHashMap<String, String> cache;
    private final AtomicInteger cacheSize;
    private final long timeoutMillis;
    private final boolean resumeOnInterrupt;
    private final boolean secureDeleteAfterCompute;
    private final int maxThreads;
    private final int maxCacheSize;

    public FileHasher(int maxThreads, int maxCacheSize, long timeoutMillis, boolean resumeOnInterrupt, boolean secureDeleteAfterCompute) {
        this.maxThreads = maxThreads;
        this.maxCacheSize = maxCacheSize;
        this.timeoutMillis = timeoutMillis;
        this.resumeOnInterrupt = resumeOnInterrupt;
        this.secureDeleteAfterCompute = secureDeleteAfterCompute;

        this.threadPool = Executors.newFixedThreadPool(maxThreads, new ThreadFactory() {
            private final AtomicInteger threadNumber = new AtomicInteger(1);
            @Override
            public Thread newThread(Runnable r) {
                return new Thread(r, "FileHasher-" + threadNumber.getAndIncrement());
            }
        });

        this.cacheSize = new AtomicInteger(0);
        this.cache = new ConcurrentHashMap<>(maxCacheSize);
    }

    public String getMD5Hash(String filePath) throws IOException, InterruptedException, ExecutionException {
        if (filePath == null || filePath.length() > 1000) {
            throw new IllegalArgumentException("Invalid file path");
        }

        // Check cache first
        String cachedHash = cache.get(filePath);
        if (cachedHash != null) {
            return cachedHash;
        }

        Future<String> future = threadPool.submit(() -> computeMD5Hash(filePath));
        try {
            String hash = future.get(timeoutMillis, TimeUnit.MILLISECONDS);
            putToCache(filePath, hash);
            if (secureDeleteAfterCompute) {
                File file = new File(filePath);
                file.delete();
            }
            return hash;
        } catch (TimeoutException e) {
            future.cancel(true); // Cancel the task
            throw new ExecutionException("Hash computation timed out", e);
        } finally {
            cacheSize.decrementAndGet(); // Ensure consistency in case of interruption or error
        }
    }

    private String computeMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private String computeSHA256Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void putToCache(String filePath, String hash) {
        cache.putIfAbsent(filePath, hash);
        if (cache.size() > maxCacheSize) {
            cache.remove(cache.keySet().iterator().next());
        }
    }

    public static void main(String[] args) {
        FileHasher hasher = new FileHasher(4, 100, 60_000L, true, false);
        try {
            String hash = hasher.getMD5Hash("path/to/large/file.txt");
            System.out.println("MD5: " + hash);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
