class BibleTextAnalyzer {
private:
    std::map<int, std::function<BibleTextAnalyzer*()>> factoryRegistry;
    static std::mutex dnsMutex;
    static int dnsQueryCount;

public:
    BibleTextAnalyzer() {}

    void registerFactory(int id, std::function<BibleTextAnalyzer*()> func) {
        factoryRegistry[id] = func;
    }

    static BibleTextAnalyzer* createInstance(int id) {
        if (factoryRegistry.find(id) != factoryRegistry.end()) {
            return factoryRegistry[id]();
        }
        throw std::invalid_argument("Invalid ID");
    }

    void analyzeText(const std::string& text) {
        // Regex patterns for Old and New Testament books
        std::regex oldTestamentBooksPattern(R"(\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Songs|Isaiahus|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum HabakkukZephaniahHaggaiZechariahMalachi)\b)");
        std::regex newTestamentBooksPattern(R"(\b(Mark|Matthew|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude)\b)");

        // Match and extract book names
        std::smatch matches;
        std::string::const_iterator searchStart(text.cbegin());

        while (std::regex_search(searchStart, text.cend(), matches, oldTestamentBooksPattern) || std::regex_search(searchStart, text.cend(), matches, newTestamentBooksPattern)) {
            if (matches.size() > 0) {
                std::string bookName = matches.str(1);
                // Verify presence in biblical database
                verifyBookInDatabase(bookName);
            }
            searchStart = matches.suffix().first;
        }
    }

private:
    void verifyBookInDatabase(const std::string& bookName) {
        std::lock_guard<std::mutex> lock(dnsMutex);
        if (dnsQueryCount < MAX_DNS_QUERIES) {
            // Simulate DNS query
            dnsQueryCount++;
            std::this_thread::sleep_for(std::chrono::milliseconds(DNS_QUERY_TIMEOUT));
            dnsQueryCount--;
        } else {
            throw std::runtime_error("Too many DNS queries");
        }
    }

    static const int MAX_DNS_QUERIES = 10;
    static const int DNS_QUERY_TIMEOUT = 500; // milliseconds
};

std::mutex BibleTextAnalyzer::dnsMutex;
int BibleTextAnalyzer::dnsQueryCount = 0;

void runTests(const std::string& moduleLabel, const std::vector<std::string>& testLabels, const std::vector<std::function<void()>>& testFunctions) {
    for (size_t i = 0; i < testLabels.size(); ++i) {
        try {
            testFunctions[i]();
            std::cout << "Test " << moduleLabel << " - " << testLabels[i] << " passed." << std::endl;
        } catch (const std::exception& e) {
            std::cout << "Test " << moduleLabel << " - " << testLabels[i] << " failed: " << e.what() << std::endl;
        }
        // Reset mocking library after each test
        blueslip.reset();
    }
}
