#define MAX_KEY_LENGTH 8
#define DEFAULT_IV_LENGTH 8

void des_ecb_encrypt(unsigned char *data, unsigned char *key) {
    DES_key_schedule ks;
    DES_set_key((C_Block *)key, &ks);
    for (int i = 0; i < strlen(data); i += 8) {
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks, DES_ENCRYPT);
    }
}

void des_ecb_decrypt(unsigned char *data, unsigned char *key) {
    DES_key_schedule ks;
    DES_set_key((C_Block *)key, &ks);
    for (int i = 0; i < strlen(data); i += 8) {
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks, DES_DECRYPT);
    }
}

void des_ede_encrypt(unsigned char *data, unsigned char *key1, unsigned char *key2) {
    DES_key_schedule ks1, ks2;
    DES_set_key((C_Block *)key1, &ks1);
    DES_set_key((C_Block *)key2, &ks2);
    for (int i = 0; i < strlen(data); i += 8) {
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks1, DES_ENCRYPT);
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks2, DES_DECRYPT);
    }
}

void des_ede_decrypt(unsigned char *data, unsigned char *key1, unsigned char *key2) {
    DES_key_schedule ks1, ks2;
    DES_set_key((C_Block *)key1, &ks1);
    DES_set_key((C_Block *)key2, &ks2);
    for (int i = 0; i < strlen(data); i += 8) {
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks2, DES_ENCRYPT);
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks1, DES_DECRYPT);
    }
}

void des_ede3_encrypt(unsigned char *data, unsigned char *key1, unsigned char *key2, unsigned char *key3) {
    DES_key_schedule ks1, ks2, ks3;
    DES_set_key((C_Block *)key1, &ks1);
    DES_set_key((C_Block *)key2, &ks2);
    DES_set_key((C_Block *)key3, &ks3);
    for (int i = 0; i < strlen(data); i += 8) {
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks1, DES_ENCRYPT);
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks2, DES_DECRYPT);
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks3, DES_ENCRYPT);
    }
}

void des_ede3_decrypt(unsigned char *data, unsigned char *key1, unsigned char *key2, unsigned char *key3) {
    DES_key_schedule ks1, ks2, ks3;
    DES_set_key((C_Block *)key1, &ks1);
    DES_set_key((C_Block *)key2, &ks2);
    DES_set_key((C_Block *)key3, &ks3);
    for (int i = 0; i < strlen(data); i += 8) {
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks3, DES_ENCRYPT);
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks2, DES_DECRYPT);
        DES_ecb_encrypt((DES_cblock *)(data + i), (DES_cblock *)(data + i), &ks1, DES_ENCRYPT);
    }
}

void des_cfb_encrypt(unsigned char *data, unsigned char *key, unsigned char *iv, int iv_length) {
    DES_key_schedule ks;
    DES_set_key((C_Block *)key, &ks);
    for (int i = 0; i < strlen(data); i++) {
        DES_ecb_encrypt(iv, iv, &ks, DES_ENCRYPT);
        data[i] ^= iv[0];
        memcpy(iv, iv + 1, iv_length - 1);
        iv[iv_length - 1] = data[i];
    }
}

void des_cfb_decrypt(unsigned char *data, unsigned char *key, unsigned char *iv, int iv_length) {
    DES_key_schedule ks;
    DES_set_key((C_Block *)key, &ks);
    for (int i = 0; i < strlen(data); i++) {
        DES_ecb_encrypt(iv, iv, &ks, DES_ENCRYPT);
        data[i] ^= iv[0];
        memcpy(iv, iv + 1, iv_length - 1);
        iv[iv_length - 1] = data[i];
    }
}

