const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const LRU = require('lru-cache');

const app = express();
app.use(bodyParser.json());

// Connect to MongoDB database
mongoose.connect('mongodb://localhost/bookReferences', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Define a schema for books
const bookSchema = new mongoose.Schema({
  name: String,
  testament: String
});

const Book = mongoose.model('Book', bookSchema);

// Create an LRU cache to store book names and their counts
const cache = new LRU({ max: 1000, maxAge: 3600000 });

// Define a regular expression to match book names
const bookRegex = /(\b(?:Old|New) Testament\b\s*\w+\s*)/g;

// Route to process incoming text data streams and identify book references
app.post('/process', async (req, res) => {
  const text = req.body.text || '';

  // Check if the result is already in the cache
  if (cache.has(text)) {
    return res.json(cache.get(text));
  }

  // Find all matches of book names in the text
  let match;
  let bookCounts = {};
  while ((match = bookRegex.exec(text)) !== null) {
    const bookName = match[1].trim().toLowerCase();
    if (bookCounts[bookName]) {
      bookCounts[bookName]++;
    } else {
      bookCounts[bookName] = 1;
    }
  }

  // Store the result in the cache
  cache.set(text, bookCounts);

  res.json(bookCounts);
});

// Route to get a list of books from both testaments
app.get('/books', async (req, res) => {
  const books = await Book.find({});
  res.json(books);
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
