import os
import threading
from collections import OrderedDict
from http.client import HTTPConnection, HTTPResponse
from urllib.parse import urlparse
from socket import timeout as SocketTimeout
from logging import getLogger

class URLFetcher:
    _cache_lock = threading.Lock()
    _cache = OrderedDict()
    _max_cache_size = 100
    _connection_pool = {}

    def __init__(self, max_connections=10, max_cache_size=100):
        self.max_connections = max_connections
        self.max_cache_size = max_cache_size

    @classmethod
    def configure(cls, max_connections=None, max_cache_size=None):
        if max_connections is not None:
            cls._max_cache_size = max_cache_size
        if max_cache_size is not None:
            cls._max_cache_size = max_cache_size

    def fetch(self, url, retries=3, timeout=10):
        self.validate_url(url)
        if url in self._cache:
            return self._cache[url]

        with self._cache_lock:
            while len(self._cache) >= self.max_cache_size:
                self._cache.popitem(last=False)

            try:
                response = self._fetch_from_server(url, retries, timeout)
                headers = response.getheaders()
                content_length = response.length
                self._cache[url] = (headers, content_length)
                return headers, content_length
            except Exception as e:
                self.log_error(f"Error fetching {url}: {e}")
                raise

    def _fetch_from_server(self, url, retries=3, timeout=10):
        parsed_url = urlparse(url)
        host = parsed_url.hostname
        port = parsed_url.port or 80 if parsed_url.scheme == 'http' else 443

        if host not in self._connection_pool:
            self._connection_pool[host] = HTTPConnection(host, timeout=timeout)

        for _ in range(retries + 1):
            try:
                self._connection_pool[host].request('GET', url)
                return self._connection_pool[host].getresponse()
            except (SocketTimeout, ConnectionRefusedError) as e:
                self.log_error(f"Connection to {url} timed out or refused: {e}")
                if _ == retries:
                    raise
            finally:
                self._connection_pool[host].close()

    def validate_url(self, url):
        if len(url) > 1000:
            raise ValueError("URL is too long")
        try:
            urlparse(url)
        except ValueError:
            raise ValueError("Invalid URL format")

    @classmethod
    def log_error(cls, message):
        logger = getLogger(__name__)
        logger.error(message)

# Example usage
fetcher = URLFetcher(max_connections=20, max_cache_size=50)
headers, content_length = fetcher.fetch('https://example.com')
print(headers, content_length)
