using System;
using System.Data;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.SignalR;

[Route("api/[controller]")]
public class PageController : ControllerBase
{
    private readonly IElementService _elementService;
    private readonly IHubContext<NotificationHub> _notificationHub;

    public PageController(IElementService elementService, IHubContext<NotificationHub> notificationHub)
    {
        _elementService = elementService;
        _notificationHub = notificationHub;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement(int pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
        {
            return BadRequest("Element ID and HTML content cannot be null or empty.");
        }

        try
        {
            if (!await _elementService.CheckPermissionAsync(User.Identity.Name, pageSectionId, elementId))
            {
                return Forbid();
            }

            await _elementService.UpdateHtmlAsync(pageSectionId, elementId, htmlContent);

            await _notificationHub.Clients.All.SendAsync("RefreshPage");

            return Ok(new { success = true, message = "Element updated successfully." });
        }
        catch (ConcurrencyException ex)
        {
            return Conflict(ex.Message);
        }
        catch (DataException ex)
        {
            return StatusCode(500, new { success = false, message = "Database error: " + ex.Message });
        }
        catch (Exception ex)
        {
            return StatusCode(500, new { success = false, message = "An unexpected error occurred: " + ex.Message });
        }
    }
}
