NFAPI_CRC_INDICATION_PDU_T** dynamicTestLoader(int N, pthread_mutex_t* lock) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        int crcflag;
        do {
            crcflag = rand();
        } while (isCrcFlagUsed(list, N, crcflag));

        list[i]->CRCFLAG = crcflag;

        // Simulate database interaction
        pthread_mutex_lock(lock);
        storeInDatabase(list[i]);
        pthread_mutex_unlock(lock);

        logEntry("Generated CRC Flag", crcflag);
    }

    return list;
}

int isCrcFlagUsed(NFAPI_CRC_INDICATION_PDU_T** list, int N, int crcflag) {
    for (int i = 0; i < N; i++) {
        if (list[i]->CRCFLAG == crcflag) {
            return 1;
        }
    }
    return 0;
}

void storeInDatabase(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate database storage
    printf("Storing CRC Flag: %d\n", pdu->CRCFLAG);
}

void logEntry(const char* description, int crcflag) {
    time_t now = time(NULL);
    printf("%s - %s: %d\n", ctime(&now), description, crcflag);
