#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules) {
    if (num_structures > MAX_STRUCTURES) {
        printf("Error: Too many structures requested.\n");
        return -1;
    }

    *nfalist = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_structures; i++) {
        pthread_mutex_lock(&mutex);
        (*nfalist)[i].RX_UE_INFORMATION_TAG = i + 1; // Unique RX_UE_INFORMATION_TAG
        (*nfalist)[i].RNTI = i * 10 + 1;              // Unique RNTI
        pthread_mutex_unlock(&mutex);

        int rule_index = i % num_structures;
        if (crc_flag_rules[rule_index] == 1) {
            (*nfalist)[i].CRCFLAG = 1; // Set CRC flag based on rule
        } else {
            (*nfalist)[i].CRCFLAG = 0;
        }

        log_structure_creation(&(*nfalist)[i]); // External logging function

        if (validate_structure(&(*nfalist)[i], crc_flag_rules) != 0) {
            printf("Validation error in structure %d.\n", i);
        }
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}

int read_and_find_max(int *array, int *max) {
    int num_elements;
    printf("Enter the number of elements: ");
    scanf("%d", &num_elements);

    if (num_elements <= 0) {
        printf("Error: Invalid number of elements.\n");
        return -1;
    }

    for (int i = 0; i < num_elements; i++) {
        printf("Enter element %d: ", i + 1);
        scanf("%d", &array[i]);
        if (i == 0 || array[i] > *max) {
            *max = array[i];
        }
    }

    printf("The largest number is: %d\n", *max);

    return 0;
}

int validate_structure(NFAPI_CRC_INDICATION_PDU_T *structure, int *crc_flag_rules) {
    int rule_index = structure->RX_UE_INFORMATION_TAG % sizeof(crc_flag_rules);
    if (crc_flag_rules[rule_index] != structure->CRCFLAG) {
        return -1; // Validation failed
    }
    return 0;
}

void log_structure_creation(NFAPI_CRC_INDICATION_PDU_T *structure) {
    printf("Structure created: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", 
           structure->RX_UE_INFORMATION_TAG, structure->RNTI, structure->CRCFLAG);
}
