import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import javax.cache.Cache;
import javax.cache.Caching;
import javax.cache.configuration.FactoryBuilder;
import javax.cache.configuration.MutableConfiguration;
import javax.cache.expiry.CreatedExpiryPolicyFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class HashService {
    private static final Logger logger = LoggerFactory.getLogger(HashService.class);
    private ExecutorService executorService;
    private Cache<String, String> cache;
    private int maxThreads;
    private long cacheSize;
    private int sha256Limit;

    public HashService(int maxThreads, long cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        initializeCache();
        initializeThreadPool();
    }

    private void initializeCache() {
        MutableConfiguration<String, String> config = new MutableConfiguration<>();
        config.setTypes(String.class, String.class)
              .setStoreByValue(true)
              .setExpiryPolicyFactory(new CreatedExpiryPolicyFactory<>(TimeUnit.MINUTES.toSeconds(10)));
        CacheManager cacheManager = Caching.getCacheManager();
        cache = cacheManager.createCache("hashCache", config);
    }

    private void initializeThreadPool() {
        executorService = Executors.newFixedThreadPool(maxThreads);
    }

    public String getHash(String input, String encoding) throws InterruptedException {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Input string is null or exceeds maximum length");
        }
        String key = input + encoding;
        if (cache.containsKey(key)) {
            return cache.get(key);
        }
        executorService.submit(() -> computeHash(input, encoding));
        return null; // Return immediately without waiting for hash computation
    }

    private void computeHash(String input, String encoding) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            String md5Hash = bytesToHex(hashBytes);
            cache.put(input + encoding, md5Hash);
        } catch (NoSuchAlgorithmException e) {
            logger.error("Failed to compute MD5 hash", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        cache.close();
    }
}
