```java
import java.io.*;
import java.util.HashMap;
import java.util.Map;

public class Deserializer {

    private static final Map<Class<?>, Object> classCache = new HashMap<>();
    private static SchemaValidator schemaValidator;

    public static <T> T deserialize(byte[] byteArray, Class<T> clazz) throws RuntimeException {
        if (!classCache.containsKey(clazz)) {
            try {
                Class<?> cachedClass = Class.forName(clazz.getName());
                classCache.put(clazz, cachedClass.newInstance());
            } catch (ClassNotFoundException | InstantiationException | IllegalAccessException e) {
                throw new RuntimeException("Failed to cache class: " + clazz.getName(), e);
            }
        }

        Object deserializedObject = null;
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray))) {
            deserializedObject = ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object", e);
        }

        if (!clazz.isInstance(deserializedObject)) {
            throw new RuntimeException("Deserialized object is not an instance of the expected class: " + clazz.getName());
        }

        try {
            schemaValidator.validate(deserializedObject);
        } catch (ValidationException e) {
            throw new RuntimeException("Schema validation failed", e);
        }

        return clazz.cast(deserializedObject);
    }

    public static void setSchemaValidator(SchemaValidator validator) {
        schemaValidator = validator;
    }
}

interface SchemaValidator {
    void validate(Object object) throws ValidationException;
}

class ValidationException extends Exception {
    public ValidationException(String message) {
        super(message);
    }
}
