#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_FILETYPE_LENGTH 10

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to determine the number of digits based on file type
int get_digit_count(const char *filetype) {
    if (strcmp(filetype, ".jpg") == 0 || strcmp(filetype, ".png") == 0)
        return 3;
    else if (strcmp(filetype, ".txt") == 0 || strcmp(filetype, ".pdf") == 0)
        return 5;
    log_error("Unsupported file type");
    return -1; // Error code for unsupported file type
}

// Function to set the new file type based on input options
void set_file_type(char *new_filename, const char *filetype) {
    if (strlen(new_filename) + strlen(filetype) > MAX_FILENAME_LENGTH) {
        log_error("New filename exceeds maximum length");
        return;
    }
    strcat(new_filename, filetype);
}

// Function to modify the file extension
int modify_file_extension(const char *filename, const char *filetype_options[], int num_options) {
    if (filename == NULL || filetype_options == NULL || num_options <= 0) {
        log_error("Invalid input parameters");
        return -1; // Error code for invalid input
    }

    char new_filename[MAX_FILENAME_LENGTH];
    strncpy(new_filename, filename, MAX_FILENAME_LENGTH);
    new_filename[MAX_FILENAME_LENGTH-1] = '\0';

    // Find the last dot in the filename to separate the name and extension
    char *dot_position = strrchr(new_filename, '.');
    if (dot_position == NULL) {
        log_error("Filename has no extension");
        return -2; // Error code for no extension
    }

    // Create new file extension with digits based on file type
    int digit_count = get_digit_count(filetype_options[0]);
    if (digit_count < 0)
        return -3; // Error code from get_digit_count

    char new_extension[MAX_FILETYPE_LENGTH];
    sprintf(new_extension, ".%d", digit_count);

    // Replace the old extension with the new one
    *dot_position = '\0';
    strcat(new_filename, new_extension);
    set_file_type(new_filename, filetype_options[0]);

    printf("New filename: %s\n", new_filename);
    return 0; // Success
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <filename> <filetype>\n", argv[0]);
        return -1;
    }

    const char *filename = argv[1];
    const char *filetype_options[] = {argv[2]};
    int num_options = 1;

    modify_file_extension(filename, filetype_options, num_options);
    return 0;
}
