<?php

class ClinicManager {
    private $db;
    private $weatherAPI;
    private $patientSchedulingSystem;
    private $notificationService;
    private $supplyChainManagementSystem;

    public function __construct($db, $weatherAPI, $patientSchedulingSystem, $notificationService, $supplyChainManagementSystem) {
        $this->db = $db;
        $this->weatherAPI = $weatherAPI;
        $this->patientSchedulingSystem = $patientSchedulingSystem;
        $this->notificationService = $notificationService;
        $this->supplyChainManagementSystem = $supplyChainManagementSystem;
    }

    public function handleClinicOperations($operation, $data) {
        switch ($operation) {
            case 'create':
                return $this->createClinicRecord($data);
            case 'update':
                return $this->updateClinicStatus($data);
            case 'delete':
                return $this->deleteClinicRecord($data);
            default:
                return false;
        }
    }

    private function createClinicRecord($data) {
        // Validate clinic name and other details
        if (!isset($data['name']) || strlen($data['name']) > 50) {
            throw new Exception('Invalid clinic name');
        }

        // Check for prohibited terms in clinic name
        $prohibitedTerms = ['prohibited', 'terms'];
        foreach ($prohibitedTerms as $term) {
            if (stripos($data['name'], $term) !== false) {
                throw new Exception('Clinic name contains a prohibited term');
            }
        }

        // Validate supply chain management system
        if (!$this->supplyChainManagementSystem->hasNecessarySupplies($data)) {
            throw new Exception('Insufficient supplies for the clinic');
        }

        // Create clinic record in database
        $query = "INSERT INTO clinics (name, location, capacity) VALUES (:name, :location, :capacity)";
        $stmt = $this->db->prepare($query);
        if ($stmt->execute(['name' => $data['name'], 'location' => $data['location'], 'capacity' => $data['capacity']])) {
            return true;
        } else {
            throw new Exception('Failed to create clinic record');
        }
    }

    private function updateClinicStatus($data) {
        // Update clinic status in database
        $query = "UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id";
        $stmt = $this->db->prepare($query);
        if ($stmt->execute(['status' => $data['status'], 'ip' => $_SERVER['REMOTE_ADDR'], 'id' => $data['id']])) {
            // Trigger notifications based on new status
            if ($data['status'] == 'closed' || $data['status'] == 'emergency') {
                $this->weatherAPI->assessClosureRisk($data['id']);
                $this->patientSchedulingSystem->clearAndRescheduleAppointments($data['id']);
                $this->notificationService->sendPersonalizedEmails($data['id'], $data['status']);
            }
            // Notify medical supply chain management system
            $this->supplyChainManagementSystem->adjustSupplyLevels($data['id'], $data['status']);
            return true;
        } else {
            throw new Exception('Failed to update clinic status');
        }
    }

    private function deleteClinicRecord($data) {
        // Check if clinic is in use
        if ($this->patientSchedulingSystem->hasUpcomingAppointments($data['id'])) {
            throw new Exception('Cannot delete a clinic with active appointments');
        }

        // Delete clinic record from database
        $query = "DELETE FROM clinics WHERE id = :id";
        $stmt = $this->db->prepare($query);
        if ($stmt->execute(['id' => $data['id']])) {
            // Notify patients and suggest alternatives
            $this->notificationService->notifyPatientsOfAlternativeClinics($data['id']);
            return true;
        } else {
            throw new Exception('Failed to delete clinic record');
        }
    }
}
