# microservices_inventory_management_system.py

from flask import Flask, request, jsonify
import requests
from datetime import datetime
import threading

app = Flask(__name__)

# Mock data for product and inventory management
products = {}
inventory = {}

def fetch_third_party_data(api_url):
    response = requests.get(api_url)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to fetch data from {api_url}")

@app.route('/add_product', methods=['POST'])
def add_product():
    product_id = request.form['product_id']
    description = request.form['description']
    if product_id in products:
        return jsonify({"error": "Product ID already exists"}), 400
    products[product_id] = {"description": description}
    return jsonify({"message": "Product added successfully"})

@app.route('/update_inventory', methods=['POST'])
def update_inventory():
    product_id = request.form['product_id']
    quantity = int(request.form['quantity'])
    if product_id not in inventory:
        inventory[product_id] = 0
    inventory[product_id] += quantity
    return jsonify({"message": "Inventory updated successfully"})

@app.route('/get_product_inventory', methods=['GET'])
def get_product_inventory():
    product_id = request.args.get('product_id')
    if product_id not in inventory:
        return jsonify({"error": "Product ID not found"}), 404
    return jsonify({"product_id": product_id, "inventory_level": inventory[product_id]})

@app.errorhandler(Exception)
def handle_error(e):
    app.logger.error(f"Error: {str(e)}")
    response = jsonify({"message": str(e)})
    response.status_code = 500
    return response

if __name__ == '__main__':
    app.run(debug=True)
