```php
class AdvancedPasswordManager {
    private $hashedPassword = null;
    private $cachedStrings = [];
    private $passwordAttempts = [];
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';

    public function generateSecureRandomString($length) {
        if (isset($this->cachedStrings[$length]) && time() - $this->cachedStrings[$length]['timestamp'] < 3600) {
            return $this->cachedStrings[$length]['value'];
        }

        $randomString = substr(str_shuffle(str_repeat($this->characterSet, 5)), 0, $length);
        $this->cachedStrings[$length] = [
            'value' => $randomString,
            'timestamp' => time()
        ];

        return $randomString;
    }

    public function hashPassword($password) {
        $this->validateCharacterSet($this->characterSet);

        if (count($this->passwordAttempts) >= 100) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        if (password_verify($password, $this->hashedPassword)) {
            return true;
        } else {
            $this->logPasswordAttempts($_SERVER['REMOTE_ADDR'], false);
            return false;
        }
    }

    public function validateCharacterSet($characterSet) {
        $uppercase = preg_match('/[A-Z]/', $characterSet);
        $lowercase = preg_match('/[a-z]/', $characterSet);
        $digits = preg_match('/\d/', $characterSet);
        $specialChars = preg_match('/[!@#$%^&*()_+-=[]{}|;:,.<>?]/', $characterSet);

        if (!$uppercase || !$lowercase || !$digits || !$specialChars) {
            throw new Exception("Invalid character set. Please include at least one uppercase letter, one lowercase letter, one digit, and one special character.");
        }
    }

    public function setSaltRoundCount($rounds) {
        $minRounds = 12;
        $maxRounds = 31;

        if ($rounds < $minRounds || $rounds > $maxRounds) {
            throw new Exception("Invalid salt round count. Must be between $minRounds and $maxRounds.");
        }

        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $this->hashedPassword = null;
        unset($this->cachedStrings[count($this->characterSet)]);
        $this->passwordAttempts = [];
    }

    public function logPasswordAttempts($ipAddress, $result) {
        if (!isset($this->passwordAttempts[$ipAddress])) {
            $this->passwordAttempts[$ipAddress] = [];
        }

        array_push($this->passwordAttempts[$ipAddress], [
            'timestamp' => time(),
            'result' => $result
        ]);

        // Trim the log to keep only the last 100 attempts
        if (count($this->passwordAttempts[$ipAddress]) > 100) {
            array_shift($this->passwordAttempts[$ipAddress]);
        }
    }
}
