void logParsedStructures(NFAPI_CRC_INDICATION_PDU_T *parsed_list, int count) {
    for (int i = 0; i < count; ++i) {
        printf("Entry %d: CRC_FLAG = %d\n", i, parsed_list[i].crc_flag);
    }
}

void* parseLogStream(void* arg) {
    const char* log_stream_path = ((const char**)arg)[0];
    int max_entries = atoi(((const char**)arg)[1]);
    NFAPI_CRC_INDICATION_PDU_T **parsed_list = (NFAPI_CRC_INDICATION_PDU_T**)((const char**)arg)[2];
    const char* rules_config_file = ((const char**)arg)[3];

    // Implement parsing logic here
    *parsed_list = malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*parsed_list == NULL) {
        perror("Failed to allocate memory for parsed list");
        return (void*)-1;
    }

    int count = 0;
    FILE* log_file = fopen(log_stream_path, "r");
    if (log_file == NULL) {
        perror("Failed to open log file");
        free(*parsed_list);
        return (void*)-1;
    }

    NFAPI_CRC_INDICATION_PDU_T entry;
    while (fscanf(log_file, "%d", &entry.crc_flag) != EOF && count < max_entries) {
        (*parsed_list)[count++] = entry;
    }
    fclose(log_file);

    logParsedStructures(*parsed_list, count);
    return NULL;
}

int processNFALogStream(const char *log_stream_path, int max_entries, NFAPI_CRC_INDICATION_PDU_T **parsed_list, const char *rules_config_file) {
    pthread_t thread_id;
    void* result;

    // Create a new thread to handle the log stream parsing
    const char* args[] = {log_stream_path, (const char*)max_entries, (const char**)(parsed_list), rules_config_file};
    if (pthread_create(&thread_id, NULL, parseLogStream, (void*)args) != 0) {
        perror("Failed to create thread");
        return -1;
    }

    // Wait for the thread to finish
    if (pthread_join(thread_id, &result) != 0) {
        perror("Failed to join thread");
        return -1;
    }

    if ((long)result == -1) {
        free(*parsed_list);
        *parsed_list = NULL;
    }

    return 0;
}
