            string decryptedMessage = System.Text.Encoding.UTF8.GetString(decryptedBytes);

            // Parse the OAuth request to extract the private key and certificate paths
            string privateKeyPath = ExtractPrivateKeyPathFromDecryptedMessage(decryptedMessage);
            string certificatePath = ExtractCertificatePathFromDecryptedMessage(decryptedMessage);

            // Combine the private key and certificate into a single PEM file
