            CombineFiles(privateKeyPath, certificatePath, pemFilePath);

            return decryptedMessage;
        }
        catch (Exception ex)
        {
            return $"Error: {ex.Message}";
        }
    }

    private static byte[] Decrypt(string base64EncryptedString)
    {
        using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
        {
            // Set the key and IV for decryption
            des.Key = Encoding.UTF8.GetBytes("YourKeyHere");
            des.IV = Encoding.UTF8.GetBytes("YourIVHere");

            // Create a decryptor to perform the stream transform
            ICryptoTransform decryptor = des.CreateDecryptor(des.Key, des.IV);

            using (MemoryStream msEncrypt = new MemoryStream(Convert.FromBase64String(base64EncryptedString)))
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, decryptor, CryptoStreamMode.Read))
                {
                    // Read the decrypted bytes from the crypto stream
                    byte[] decryptedBytes = new byte[msEncrypt.Length];
                    csEncrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
