#include <forward_list>
#include <string>
#include <memory>
#include <iostream>

template <typename Allocator = std::allocator<std::string>, typename Compare = std::equal_to<std::string>>
void insertAfterOrAtEnd(std::forward_list<std::string, Allocator>& list, const std::string& target, const std::string& toInsert, Compare compare = Compare()) {
    auto it = list.begin();
    for (; it != list.end(); ++it) {
        if (compare(*it, target)) {
            it = list.insert_after(it, toInsert);
            return;
        }
    }
    list.push_back(toInsert);
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertAfterOrAtEnd(myList, "banana", "grape");
    for (const auto& item : myList) {
        std::cout << item << " ";
    }
    return 0;
}
