#include <iostream>
#include <thread>
#include <filesystem>
#include <fstream>
#include <queue>
#include <vector>
#include <mutex>
#include <condition_variable>

namespace fs = std::filesystem;

std::mutex mtx;
std::condition_variable cv;
bool stop_thread = false;
std::queue<fs::path> image_queue;
std::vector<std::thread> workers(4);

void scan_directory(const fs::path& directory) {
    while (!stop_thread) {
        fs::directory_iterator it(directory);
        for (const auto& entry : it) {
            if (entry.is_regular_file()) {
                std::string extension = entry.path().extension().string();
                if (extension == ".jpg" || extension == ".jpeg" || extension == ".png" || extension == ".svg") {
                    std::lock_guard<std::mutex> lock(mtx);
                    image_queue.push(entry.path());
                    cv.notify_one();
                }
            }
        }
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
}

void convert_image(const fs::path& path) {
    std::string filename = path.filename().string();
    std::string name_without_extension = filename.substr(0, filename.find_last_of("."));

    // Convert to PDF
    std::string pdf_command = "convert " + path.string() + " " + name_without_extension + ".pdf";
    system(pdf_command.c_str());

    // Convert to PNG (if not already)
    if (path.extension().string() != ".png") {
        std::string png_command = "convert " + path.string() + " " + name_without_extension + ".png";
        system(png_command.c_str());
    }

    // Convert to SVG
    std::string svg_command = "potrace -s " + path.string() + " > " + name_without_extension + ".svg";
    system(svg_command.c_str());
}

void process_images() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [] { return !image_queue.empty() || stop_thread; });

        if (stop_thread && image_queue.empty()) {
            break;
        }

        fs::path path = image_queue.front();
        image_queue.pop();
        lock.unlock();

        convert_image(path);
    }
}

void report_progress(size_t processed, size_t total) {
    std::cout << "Processed " << processed << "/" << total << " files." << std::endl;
}

int main() {
    fs::path directory = "/path/to/image/directory";

    // Start scan thread
    std::thread scanner(scan_directory, directory);

    // Start image processing threads
    for (auto& worker : workers) {
        worker = std::thread(process_images);
    }

    // Simulate reporting progress
    size_t processed_files = 0;
    while (!stop_thread) {
        std::this_thread::sleep_for(std::chrono::seconds(5));
        report_progress(processed_files, 100); // Assuming total is 100 for demonstration
        processed_files++;
    }

    stop_thread = true;
    scanner.join();
    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
