# Import necessary libraries
from flask import Flask, request, jsonify
import websocket
import json
import threading
import time
import requests

app = Flask(__name__)
graph_db = {}  # Simulated graph database
property_cache = {}
lock = threading.Lock()
property_locks = {}

def add_vertex(vertex_id):
    with lock:
        if vertex_id not in graph_db:
            graph_db[vertex_id] = {'properties': {}, 'edges': {}}
        return True

def set_property(vertex_id, property_key, value):
    with lock:
        if vertex_id in graph_db:
            graph_db[vertex_id]['properties'][property_key] = value
            return True
        return False

def get_vertex_properties(vertex_id):
    with lock:
        if vertex_id in graph_db:
            return graph_db[vertex_id]['properties']
        return {}

def add_edge(source, target, edge_type):
    with lock:
        if source in graph_db and target in graph_db:
            if edge_type not in graph_db[source]['edges']:
                graph_db[source]['edges'][edge_type] = []
            graph_db[source]['edges'][edge_type].append(target)
            return True
        return False

def get_vertex_edges(vertex_id):
    with lock:
        if vertex_id in graph_db:
            return graph_db[vertex_id]['edges']
        return {}

@app.route('/config', methods=['POST'])
def apply_config():
    config = request.get_json()
    for operation, params in config.items():
        if operation == 'add_vertex':
            add_vertex(params['vertex_id'])
        elif operation == 'add_edge':
            add_edge(params['source'], params['target'], params['edge_type'])
        elif operation == 'set_property':
            set_property(params['vertex_id'], params['property_key'], params['value'])
    return jsonify({'status': 'success'})

@app.route('/properties/<vertex_id>', methods=['GET'])
def get_properties(vertex_id):
    properties = get_vertex_properties(vertex_id)
    if not properties:
        return jsonify({'error': 'Vertex not found'}), 404
    return jsonify(properties)

@websocket.on_message
def on_message(ws, message):
    config = json.loads(message)
    for operation, params in config.items():
        if operation == 'set_property':
            set_property(params['vertex_id'], params['property_key'], params['value'])
            ws.send(json.dumps({'status': 'success'}))

@websocket.on_error
def on_error(ws, error):
    print(error)

@websocket.on_close
def on_close(ws, close_status_code, close_msg):
    print("### closed ###")

@websocket.on_open
def on_open(ws):
    def run(*args):
        while True:
            time.sleep(1)
            ws.send(json.dumps({'operation': 'update'}))
    thread = threading.Thread(target=run, args=(ws,))
    thread.start()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

