#include <iostream>
#include <string>
#include <curl/curl.h>
#include <unordered_map>
#include <chrono>
#include <ctime>

// Define the NetworkClient class with an abstract FetchDataFromApi function
class NetworkClient {
public:
    virtual std::string FetchDataFromApi(const std::string& url) = 0;
};

// Implement a concrete NetworkClient using cURL for real API calls
class RealNetworkClient : public NetworkClient {
public:
    std::string FetchDataFromApi(const std::string& url) override {
        CURL *curl;
        CURLcode res;
        std::string readBuffer;

        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                std::cerr << "cURL error: " << curl_easy_strerror(res) << std::endl;

            curl_easy_cleanup(curl);
        }

        return readBuffer;
    }

private:
    static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
        ((std::string*)userp)->append((char*)contents, size * nmemb);
        return size * nmemb;
    }
};

// Implement a test double for the NetworkClient class
class MockNetworkClient : public NetworkClient {
public:
    std::string FetchDataFromApi(const std::string& url) override {
        if (url == "https://api.openweathermap.org/data/2.5/weather?lat=37.7749&lon=-122.4194") {
            return "{\"weather\":[{\"main\":\"Clear\"}],\"temperature\":28}";
        } else {
            return "";
        }
    }

    void SetFail() {
        fail = true;
    }

private:
    bool fail = false;
};

// Define the WeatherService class to manage weather data
class WeatherService {
public:
    WeatherService(NetworkClient* network_client, double cache_duration)
        : network_client(network_client), cache_duration(cache_duration) {}

    std::string GetWeather(double lat, double lon) {
        std::string url = "https://api.openweathermap.org/data/2.5/weather?lat=" + std::to_string(lat) + "&lon=" + std::to_string(lon);
        auto now = std::chrono::system_clock::now();

        if (cache.find(url) != cache.end() && (now - cache[url].second) < std::chrono::seconds(cache_duration)) {
            log("Cache hit for " + url);
            return cache[url].first;
        }

        if (fail) {
            log("API call failed");
            return "";
        }

        std::string data = network_client->FetchDataFromApi(url);
        if (!data.empty()) {
            log("API call successful for " + url);
            cache[url] = {data, now};
        } else {
            log("API call failed");
        }

        return data;
    }

private:
    NetworkClient* network_client;
    double cache_duration;
    std::unordered_map<std::string, std::pair<std::string, std::chrono::system_clock::time_point>> cache;

    void log(const std::string& message) {
        auto now = std::chrono::system_clock::now();
        auto time = std::chrono::system_clock::to_time_t(now);
        std::cout << std::ctime(&time) << ": " << message << std::endl;
    }
};

int main() {
    MockNetworkClient mock_client;
    WeatherService weather_service(&mock_client, 3600);

    std::cout << "Weather data: " << weather_service.GetWeather(37.7749, -122.4194) << std::endl;
