void convert_jpeg_to_pdf(const char *input_file, const char *output_file) {
    // Call the third-party tool to convert JPEG to PDF
    char command[256];
    snprintf(command, sizeof(command), "third_party_tool %s %s", input_file, output_file);
    system(command);
}

void manage_log_files(const char *input_file, const char *output_file) {
    // Convert the input file to PDF format
    convert_jpeg_to_pdf(input_file, output_file);

    // Create a new log file atomically
    int fd;
    do {
        char log_path[256];
        snprintf(log_path, sizeof(log_path), "/tmp/log_%d.log", getpid());
        fd = open(log_path, O_WRONLY | O_CREAT | O_EXCL, 0644);
    } while (fd == -1 && errno == EEXIST);

    if (fd != -1) {
        // Write log file creation information
        char log_entry[512];
        snprintf(log_entry, sizeof(log_entry), "Log file created: %s at %ld\n", log_path, time(NULL));
        write(fd, log_entry, strlen(log_entry));

        // Update the environment variable pointing to the current log file
        setenv("LOG_FILE", log_path, 1);

        // Close the log file descriptor
        close(fd);
    } else {
        perror("Failed to create log file");
    }
}

void background_cleanup() {
    while (1) {
        char *log_files = getenv("LOG_FILE");
        if (log_files != NULL) {
            DIR *dir = opendir("/tmp");
            if (dir != NULL) {
                struct dirent *entry;
                while ((entry = readdir(dir)) != NULL) {
                    if (strncmp(entry->d_name, "log_", 4) == 0 && entry->d_type == DT_REG) {
                        char log_path[256];
                        snprintf(log_path, sizeof(log_path), "/tmp/%s", entry->d_name);
                        if (strcmp(log_path, log_files) != 0) {
                            // Write log file deletion information
                            printf("Log file deleted: %s at %ld\n", log_path, time(NULL));
                            unlink(log_path);
                        }
                    }
                }
                closedir(dir);
            } else {
                perror("Failed to open directory");
            }
        }
        sleep(60); // Run the cleanup process every 60 seconds
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    manage_log_files(argv[1], argv[2]);

    // Start the background cleanup process
    pid_t pid = fork();
    if (pid == 0) {
        background_cleanup();
        exit(0);
    } else if (pid > 0) {
        // Main program can continue with other tasks
    } else {
        perror("Failed to create background cleanup process");
        return 1;
    }

    return 0;
}
