from flask import Flask, request, jsonify
import json
import threading

app = Flask(__name__)

# In-memory graph storage
graph_database = {}

def add_vertex(vertex_id):
    if vertex_id not in graph_database:
        graph_database[vertex_id] = {'edges': {}}
        return True
    return False

def remove_vertex(vertex_id):
    if vertex_id in graph_database:
        del graph_database[vertex_id]
        return True
    return False

def add_edge(from_vertex, to_vertex, weight=1):
    if from_vertex in graph_database and to_vertex in graph_database:
        graph_database[from_vertex]['edges'][to_vertex] = weight
        return True
    return False

def remove_edge(from_vertex, to_vertex):
    if from_vertex in graph_database and to_vertex in graph_database:
        if to_vertex in graph_database[from_vertex]['edges']:
            del graph_database[from_vertex]['edges'][to_vertex]
            return True
    return False

@app.route('/graph', methods=['POST'])
def update_graph():
    data = request.get_json()
    operation = data.get('operation')
    if operation == 'add_vertex':
        vertex_id = data.get('vertex_id')
        result = add_vertex(vertex_id)
    elif operation == 'remove_vertex':
        vertex_id = data.get('vertex_id')
        result = remove_vertex(vertex_id)
    elif operation == 'add_edge':
        from_vertex = data.get('from_vertex')
        to_vertex = data.get('to_vertex')
        weight = data.get('weight', 1)
        result = add_edge(from_vertex, to_vertex, weight)
    elif operation == 'remove_edge':
        from_vertex = data.get('from_vertex')
        to_vertex = data.get('to_vertex')
        result = remove_edge(from_vertex, to_vertex)
    else:
        return jsonify({'error': 'Invalid operation'}), 400
    if result:
        return jsonify({'success': True})
    else:
        return jsonify({'error': 'Operation failed'}), 500

if __name__ == '__main__':
    app.run(debug=True)
