```java
import java.util.*;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

class UnionFind {
    int[] parent;
    int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]); // Path compression
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);

        if (rootP != rootQ) {
            if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }

    public boolean isDisjoint(int p, int q) {
        return find(p) != find(q);
    }
}

class DisjointPairsLogger {
    private static final String API_URL = "https://your-api-endpoint.com/log";

    public void logDisjointPairsCount(int count, long timeTaken) throws IOException {
        URL url = new URL(API_URL);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setDoOutput(true);

        String jsonInputString = "{\"disjointPairsCount\": " + count + ", \"timeTaken\": " + timeTaken + "}";
        try(OutputStream os = conn.getOutputStream()) {
            byte[] input = jsonInputString.getBytes("utf-8");
            os.write(input, 0, input.length);           
        }

        int responseCode = conn.getResponseCode();
        System.out.println("POST Response Code :: " + responseCode);

        if (responseCode == HttpURLConnection.HTTP_OK) { //success
            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            String inputLine;
            StringBuffer response = new StringBuffer();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();
            System.out.println(response.toString());
        } else {
            System.out.println("POST request not worked");
        }
    }
}

class DisjointPairsChecker {
    private UnionFind unionFind;
    private DisjointPairsLogger logger;

    public DisjointPairsChecker(int size) {
        unionFind = new UnionFind(size);
        logger = new DisjointPairsLogger();
    }

    public int countDisjointPairs(int[] array) throws IOException {
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < array.length - 1; i++) {
            if (array[i] < 0 || array[i] >= array.length) {
                throw new IllegalArgumentException("Invalid element: " + array[i]);
            }
            for (int j = i + 1; j < array.length; j++) {
                if (unionFind.isDisjoint(array[i], array[j])) {
                    unionFind.union(array[i], array[j]);
                }
            }
        }

        int count = 0;
        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (unionFind.isDisjoint(i, j)) {
                    count++;
                }
            }
        }

        long endTime = System.currentTimeMillis();
        logger.logDisjointPairsCount(count, endTime - startTime);

        return count;
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            int[] array = {0, 1, 2, 3, 4};
            DisjointPairsChecker checker = new DisjointPairsChecker(array.length);
            int disjointPairsCount = checker.countDisjointPairs(array);
            System.out.println("Number of disjoint pairs: " + disjointPairsCount);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

```java
import java.util.Random;
import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final Random random = new Random();
    private static int consecutiveFailures = 0;
    private static boolean isRunning = false;

    public static void main(String[] args) {
        // Command-line interface for user interaction
        if (args.length > 0 && args[0].equalsIgnoreCase("start")) {
            startService();
        } else if (args.length > 0 && args[0].equalsIgnoreCase("stop")) {
            stopService();
        } else if (args.length > 0 && args[0].equalsIgnoreCase("configure")) {
            configureService(Integer.parseInt(args[1]));
        }
    }

    public static void startService() {
        if (!isRunning) {
            isRunning = true;
            scheduler.scheduleAtFixedRate(ServiceManager::performTask, 0, getDelay(), TimeUnit.SECONDS);
        }
    }

    public static void stopService() {
        if (isRunning) {
            isRunning = false;
            scheduler.shutdown();
            // Send message to messaging system
            System.out.println("Service stopped. Sending message...");
        }
    }

    public static void configureService(int delay) {
        // Logic to adjust delay interval based on current load and performance metrics
        System.out.println("Delay configured to " + delay + " seconds.");
    }

    private static long getDelay() {
        return random.nextInt(10); // Random delay between 0-9 seconds
    }

    private static void performTask() {
        try {
            // Logic for the specific task
            System.out.println("Performing task at " + Instant.now());
            consecutiveFailures = 0; // Reset consecutive failures on success
        } catch (Exception e) {
            System.err.println("Error performing task: " + e.getMessage());
            consecutiveFailures++;
            if (consecutiveFailures >= 3) {
                stopService();
                System.out.println("Too many consecutive failures. Stopping service.");
            }
        }
    }

    static {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            scheduler.shutdownNow();
            System.out.println("Shutting down...");
        }));
    }
}
```

This code provides a basic implementation of a Service Manager in Java that can start, stop, and configure a service with random delays. It includes error handling for the specific task performed by the service, tracks consecutive failures, and stops the entire process if there are too many consecutive failures. The program also shuts down gracefully when interrupted.

To use this code, you can run it from the command line with different arguments to start, stop, or configure the service. For example:
```
java ServiceManager start
java ServiceManager stop
java ServiceManager configure 15
```

