const blueslip = require('blueslip');
const axios = require('axios');
const { Queue } = require('p-queue');

async function executeTests(moduleLabel, testSuite, rateLimit = 5) {
    const queue = new Queue({ concurrency: rateLimit });
    let passed = 0;
    let failed = 0;

    console.log(`Starting tests for module ${moduleLabel}...`);

    for (const testCase of testSuite) {
        await queue.add(async () => {
            try {
                await testCase();
                passed++;
                console.log(`${passed + failed}/${testSuite.length}: [PASSED] ${testCase.name}`);
            } catch (error) {
                failed++;
                console.error(`${passed + failed}/${testSuite.length}: [FAILED] ${testCase.name}`, error);
            } finally {
                blueslip.reset(); // Reset mocking library after each test
            }
        });
    }

    await queue.onIdle();

    console.log(`Tests completed. Passed: ${passed}, Failed: ${failed}`);
}

// Sample test suite
const sampleTestSuite = [
    async () => {
        const response = await axios.get('https://api.example.com/data');
        if (response.status === 200) {
            // Test logic here
        } else {
            throw new Error(`API request failed with status ${response.status}`);
        }
    },
    async () => {
        // Another test case
    }
];

// Execute tests for a sample module
