<?php

session_start();

function updateClinicStatus($clientId, $clientSecret, $redirectUri, $code, $clinicId, $newStatus, $ipAddress) {
    // 1. Authenticate user using OAuth 2.0 client
    $authUrl = "https://oauth.example.com/authorize";
    $tokenUrl = "https://oauth.example.com/token";

    $stateToken = bin2hex(random_bytes(32));
    $_SESSION['oauth_state'] = $stateToken;

    $authParams = [
        'client_id' => $clientId,
        'redirect_uri' => urlencode($redirectUri),
        'response_type' => 'code',
        'scope' => 'user_clinic_update',
        'state' => $stateToken
    ];

    header('Location: ' . $authUrl . '?' . http_build_query($authParams));
    exit;

    // Handle OAuth callback and retrieve access token
    if (isset($_GET['code']) && $_SESSION['oauth_state'] === $_GET['state']) {
        $tokenParams = [
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
            'grant_type' => 'authorization_code',
            'redirect_uri' => urlencode($redirectUri),
            'code' => $_GET['code']
        ];

        $ch = curl_init($tokenUrl);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($tokenParams));
        $response = curl_exec($ch);
        curl_close($ch);

        if ($response) {
            $responseData = json_decode($response, true);
            $_SESSION['access_token'] = $responseData['access_token'];
        } else {
            return "Error retrieving access token";
        }
    }

    // 2. Update database with new status
    try {
        $dbHost = 'localhost';
        $dbName = 'your_database_name';
        $dbUser = 'your_db_user';
        $dbPassword = 'your_db_password';

        $pdo = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUser, $dbPassword);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $transaction = $pdo->beginTransaction();

        $stmt = $pdo->prepare('SELECT id FROM clinics WHERE id = :clinicId AND status IN (SELECT active_id FROM clinic_status)');
        $stmt->execute([':clinicId' => $clinicId]);
        $clinic = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$clinic) {
            return "Unauthorized clinic ID";
        }

        // 3. Validate IP address
        if (!isValidIP($ipAddress, $clinic['network_config'])) {
            return "Invalid IP address for this clinic";
        }

        $updateStmt = $pdo->prepare('UPDATE clinics SET status = :newStatus, last_modified_ip = :ipAddress, last_modified_date = NOW() WHERE id = :clinicId');
        $updateStmt->execute([
            ':newStatus' => $newStatus,
            ':ipAddress' => $ipAddress,
            ':clinicId' => $clinicId
        ]);

        $logStmt = $pdo->prepare('INSERT INTO update_logs (clinic_id, user_id, new_status, ip_address) VALUES (:clinicId, :userId, :newStatus, :ipAddress)');
        $logStmt->execute([
            ':clinicId' => $clinicId,
            ':userId' => 1, // Assuming user ID is available
            ':newStatus' => $newStatus,
            ':ipAddress' => $ipAddress
        ]);

        $transaction->commit();
    } catch (PDOException $e) {
        $pdo->rollBack();
        return "Database error: " . $e->getMessage();
    }

    // 4. Return success message in PEM format
    $successMessage = "Clinic status updated successfully";
    return openssl_pkey_export(openssl_pkey_new(), $successMessage);
}

