```python
import os
import threading
from concurrent.futures import ThreadPoolExecutor
import logging
from typing import List
import time
import gzip

def merge_files(file_paths: List[str], dest_path: str, buffer_size: int = 1024*1024,
                 compression_level: int = 6) -> None:
    def read_file(file_path):
        try:
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(buffer_size)
                    if not data:
                        break
                    yield data
        except IOError as e:
            logging.error(f"Failed to read file {file_path}: {e}")
            return None

    def write_chunk(dest_file, chunk):
        try:
            dest_file.write(chunk)
        except IOError as e:
            logging.error(f"Failed to write to destination file: {e}")

    def retry_operation(operation, max_retries=3, delay_factor=2):
        for attempt in range(max_retries + 1):
            try:
                return operation()
            except Exception as e:
                if attempt == max_retries:
                    logging.error(f"Failed after {max_retries} attempts: {e}")
                    raise
                time.sleep(delay_factor ** attempt)

    def merge_chunk(file_paths):
        with ThreadPoolExecutor(max_workers=len(file_paths)) as executor:
            chunk_futures = [executor.submit(retry_operation, read_file, file_path) for file_path in file_paths]
            for future in concurrent.futures.as_completed(chunk_futures):
                if future.result() is not None:
                    yield from future.result()

    try:
        logging.info(f"Starting merging process. Destination: {dest_path}")
        start_time = time.time()

        with open(dest_path, 'wb') as dest_file:
            if compression_level > 0:
                dest_file = gzip.open(dest_path, 'wb', compresslevel=compression_level)
            for chunk in merge_chunk(file_paths):
                retry_operation(lambda: write_chunk(dest_file, chunk), delay_factor=1)

        end_time = time.time()
        file_size = os.path.getsize(dest_path)
        logging.info(f"Finished merging process. Total time: {end_time - start_time:.2f}s, File size: {file_size} bytes")
    except Exception as e:
        logging.error(f"Merging failed with exception: {e}")
        raise

# Example usage
merge_files(['file1.txt', 'file2.txt'], 'merged_file.txt', buffer_size=10*1024*1024, compression_level=9)
```

