// Import necessary modules (assuming fetch and localForage are available)
import fetch from 'node-fetch';
import localForage from 'localforage';

const SCRIPT_CACHE_KEY = 'scriptCache';
const VALIDATION_API_URL = 'https://example.com/validate-script-key';
const METADATA_SERVICE_URL = 'https://example.com/get-script-metadata';
const MAX_RETRIES = 3;
const TIMEOUT_MS = 5000;

function fetchScriptContent(url, retries = 0) {
    return fetch(url, { timeout: TIMEOUT_MS })
        .then(response => response.text())
        .catch(err => {
            if (retries < MAX_RETRIES) {
                console.warn(`Failed to fetch script from ${url}. Retrying... (${retries + 1}/${MAX_RETRIES})`);
                return fetchScriptContent(url, retries + 1);
            }
            console.error(`Failed to fetch script from ${url} after ${MAX_RETRIES} attempts.`);
            throw err;
        });
}

async function validateScriptKey(key) {
    try {
        const response = await fetch(VALIDATION_API_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ key })
        });
        const result = await response.json();
        return result.isValid;
    } catch (err) {
        console.error('Failed to validate script key:', err);
        return false;
    }
}

async function getScriptMetadata(key) {
    try {
        const response = await fetch(METADATA_SERVICE_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ key })
        });
        const result = await response.json();
        return result.metadata || {};
    } catch (err) {
        console.error('Failed to get script metadata:', err);
        return {};
    }
}

function sanitizeScript(scriptContent) {
    // Basic XSS prevention by escaping HTML entities
    return scriptContent.replace(/&/g, '&amp;').replace(/</g, '&lt;');
}

async function renderFooterScripts(scripts) {
    let html = '';
    const cache = await localForage.getItem(SCRIPT_CACHE_KEY) || {};

    for (const script of scripts) {
        if (!script.src || !script.type || !script.key) {
            console.error('Invalid script object:', script);
            continue;
        }

        if (cache[script.src]) {
            html += `<script type="${script.type}">${sanitizeScript(cache[script.src])}</script>`;
            continue;
        }

        const isValid = await validateScriptKey(script.key);
        if (!isValid) {
            console.warn('Invalid script key:', script.key);
            continue;
        }

        let scriptContent = cache[script.src] || (await fetchScriptContent(script.src));
        cache[script.src] = scriptContent;
        await localForage.setItem(SCRIPT_CACHE_KEY, cache);

        const metadata = await getScriptMetadata(script.key);
        if (metadata.fallbackUrl) {
            html += `<script type="${script.type}" src="${metadata.fallbackUrl}"></script>`;
        } else {
            html += `<script type="${script.type}">${sanitizeScript(scriptContent)}</script>`;
        }
    }

    return html;
}
```

