use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::collections::HashMap;

use quick_xml::Reader;
use quick_xml::events::BytesStart;
use xpath_rs::{Document, XPath};

type Cache = HashMap<String, Document>;

fn parse_and_extract(xml_data: &[u8], xpaths: &[&str]) -> Result<Vec<String>, String> {
    let mut reader = Reader::from_reader(xml_data);
    reader.trim_text(true);

    let doc = Document::parse(&reader).map_err(|e| e.to_string())?;
    let mut results = Vec::new();

    for xpath in xpaths {
        match doc.query(xpath) {
            Ok(nodes) => {
                if nodes.is_empty() {
                    return Err(format!("No data found for XPath: {}", xpath));
                } else if nodes.len() > 1 {
                    return Err(format!("Multiple matching nodes found for XPath: {}", xpath));
                }
                results.push(nodes[0].inner_text());
            },
            Err(e) => return Err(format!("Error parsing XPath {} : {}", xpath, e)),
        }
    }

    Ok(results)
}

fn create_and_set_directory(dir_name: &str) -> Result<PathBuf, String> {
    if let Some(path) = env::var_os("MY_DIR") {
        Ok(PathBuf::from(path))
    } else {
        let path = Path::new(&dir_name);
        fs::create_dir_all(path).map_err(|e| e.to_string())?;
        env::set_var("MY_DIR", path.as_os_str());
        Ok(path.to_path_buf())
    }
}

fn cache_results(cache: &mut Cache, key: String, doc: Document) {
    if !cache.contains_key(&key) {
        cache.insert(key.clone(), doc);
    }
}

fn validate_with_api(data: &str) -> Result<(), String> {
    // Implement API validation logic here
    Ok(())
}

fn main() -> Result<(), String> {
    let xml_data = br#"
        <root>
            <child1 attribute="value1">text1</child1>
            <child2 attribute="value2">text2</child2>
        </root>
    "#;
    let xpaths = &["/root/child1/text()", "/root/child2/text()"];

    let mut cache: Cache = HashMap::new();
    let dir_path = create_and_set_directory("my_dir")?;
    let key = format!("{:?}", xpaths);

    if !cache.contains_key(&key) {
        let doc = Document::parse(xml_data).map_err(|e| e.to_string())?;
        cache_results(&mut cache, key.clone(), doc);
    }

    let parsed_data = parse_and_extract(cache.get(key.as_str()).unwrap().as_bytes(), xpaths)?;
    for item in parsed_data {
        println!("{}", item);
        validate_with_api(&item)?;
    }

    Ok(())
}
