        if config.status_callback:
            config.status_callback(status)

    if not validate_deployment_package(deployment_package):
        return "Invalid deployment package"

    with ThreadPoolExecutor(max_workers=len(config.instances)) as executor:
        futures = {executor.submit(deploy_to_instance, instance['id'], script): instance for instance in config.instances for script in config.installation_scripts}
        for future in as_completed(futures):
            instance_id = futures[future]['id']
            update_status_callback(f"Deploying to instance {instance_id}: {as_completed.__len__()} of {executor._max_workers} completed")

    return "Deployment completed"
