import requests

class Product:
    def __init__(self, name, category, price, quantity):
        self.name = name
        self.category = category
        self.price = price
        self.quantity = quantity

def fetch_risk_info(category):
    api_url = f"https://risk-assessment-api.com/products/{category}/risks"
    try:
        response = requests.get(api_url)
        if response.status_code == 200:
            return response.json()
        else:
            print("Failed to retrieve risk information from the API.")
            return {}
    except requests.RequestException as e:
        print(f"Error occurred while accessing the API: {e}")
        return {}

def assess_product_risks(product):
    risks = {
        "Electronics": "High",
        "Clothing": "Medium",
        "Groceries": "Low"
    }

    base_risk = risks.get(product.category, "Unknown")

    api_risk_info = fetch_risk_info(product.category)

    detailed_risks = api_risk_info.get("detailedRisks", [])
    additional_risks = [
        f"{risk['type']}: {risk['description']}" for risk in detailed_risks
    ]

    final_risks = f"Base Risk: {base_risk}\nAdditional Risks:\n" + "\n".join(additional_risks)

    return final_risks

# Example usage:
product = Product("Smartphone", "Electronics", 500, 10)
print(assess_product_risks(product))
```

This code defines a `Product` class and a function `assess_product_risks` that assesses the risks associated with a product based on its category. It uses a dictionary to map categories to base risks and fetches additional risk information from an external API. If the API request fails, it handles the error gracefully and provides fallback options.

