import json
import os
from abc import ABC, abstractmethod

class ConfigValidator(ABC):
    @abstractmethod
    def validate(self, config):
        pass

class PhysicsConfigValidator(ConfigValidator):
    def validate(self, config):
        if config['max_fps'] < 30 or config['min_fps'] > 120:
            raise ValueError("FPS values are out of the recommended range.")

class RenderingConfigValidator(ConfigValidator):
    def validate(self, config):
        if config['texture_quality'] not in ['low', 'medium', 'high']:
            raise ValueError("Invalid texture quality setting.")

class InputHandlingConfigValidator(ConfigValidator):
    def validate(self, config):
        if config['input_timeout'] < 0.1:
            raise ValueError("Input timeout must be greater than 0.1 seconds.")

class ConfigLoader(ABC):
    @abstractmethod
    def load(self, file_path):
        pass

class JSONConfigLoader(ConfigLoader):
    def load(self, file_path):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"Configuration file not found at {file_path}")

        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except json.JSONDecodeError:
            raise ValueError("Malformed JSON configuration.")

class ConfigManager:
    def __init__(self, validators):
        self.validators = validators
        self.configs = {}

    def load_configs(self, loaders):
        for loader in loaders:
            config_name = type(loader).__name__.replace('ConfigLoader', '').lower()
            config = loader.load(f"config_{config_name}.json")

            for validator in self.validators:
                validator.validate(config)

            self.configs[config_name] = config

    def get_config(self, config_name):
        return self.configs.get(config_name)

# Example usage
validators = [
    PhysicsConfigValidator(),
    RenderingConfigValidator(),
    InputHandlingConfigValidator()
]

loaders = [
    JSONConfigLoader()
]

config_manager = ConfigManager(validators)
config_manager.load_configs(loaders)

physics_config = config_manager.get_config('physics')
rendering_config = config_manager.get_config('rendering')
input_handling_config = config_manager.get_config('inputhandling')

print("Physics Config:", physics_config)
print("Rendering Config:", rendering_config)
print("Input Handling Config:", input_handling_config)
```

