import requests
from functools import lru_cache
from time import sleep

class NotificationService:
    def __init__(self, apns_url, fcm_url, apns_token, fcm_key):
        self.apns_url = apns_url
        self.fcm_url = fcm_url
        self.apns_token = apns_token
        self.fcm_key = fcm_key

    @lru_cache(maxsize=100)
    def send_notification(self, device_id, message, protocol):
        if protocol == 'apns':
            return self.send_apns(device_id, message)
        elif protocol == 'fcm':
            return self.send_fcm(device_id, message)
        else:
            raise ValueError("Unsupported protocol")

    def send_apns(self, device_id, message):
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {self.apns_token}'
        }
        payload = {
            "to": device_id,
            "notification": {
                "title": "Notification",
                "body": message
            }
        }
        response = requests.post(self.apns_url, headers=headers, json=payload)
        return self.handle_response(response)

    def send_fcm(self, device_id, message):
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'key={self.fcm_key}'
        }
        payload = {
            "to": device_id,
            "notification": {
                "title": "Notification",
                "body": message
            }
        }
        response = requests.post(self.fcm_url, headers=headers, json=payload)
        return self.handle_response(response)

    def handle_response(self, response):
        if response.status_code == 200:
            return response.json()
        elif response.status_code in [500, 503]:
            sleep(1)  # Retry after a short delay
            return self.send_notification(device_id, message, protocol)
        else:
            raise Exception(f"Failed to send notification: {response.text}")

# Example usage
apns_url = 'https://api.push.apple.com/3/device/<device_token>'
fcm_url = 'https://fcm.googleapis.com/fcm/send'
apns_token = '<your_apns_token>'
fcm_key = '<your_fcm_key>'

notification_service = NotificationService(apns_url, fcm_url, apns_token, fcm_key)
response = notification_service.send_notification('device_id', 'Hello World', 'apns')
print(response)
```

