```rust
// Rust HTTP Client Module
use reqwest::{Client, Error};
use tokio::time::{Duration, sleep};

async fn fetch_book_reference(url: &str) -> Result<String, Error> {
    let client = Client::builder()
        .timeout(Duration::from_secs(5))
        .build()?;

    for _ in 0..3 {
        match client.get(url).send().await {
            Ok(response) => return response.text().await,
            Err(e) if e.is_timeout() || e.status().is_client_error() => {
                sleep(Duration::from_secs(1)).await;
            },
            Err(_) => break,
        }
    }

    Err(Error::new(reqwest::ErrorKind::Other, "Failed after retries"))
}
