<?php

class AdvancedWebPageManager {
    private $cachedStrings = [];
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $logFile = 'password_attempts.log';
    private $twoFactorEnabled = false;

    public function generateSecureRandomString($length) {
        if (isset($this->cachedStrings[$length])) {
            return $this->cachedStrings[$length];
        }

        $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
        $randomString = substr(str_shuffle(str_repeat($characters, ceil($length / strlen($characters)))), 1, $length);
        $this->cachedStrings[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\w\s]).*$/', $characterSet)) {
            return true;
        } else {
            // Suggest a corrected character set
            return 'Suggested Character Set: abcABC123!';
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            throw new InvalidArgumentException('Salt round count must be between 12 and 31.');
        }
    }

    public function resetPassword() {
        $newPassword = $this->generateSecureRandomString(10);
        $this->hashPassword($newPassword);
        $this->invalidateCache();
    }

    private function invalidateCache() {
        $this->cachedStrings = [];
    }

    public function logPasswordAttempts($ipAddress, $result) {
        file_put_contents($this->logFile, date('Y-m-d H:i:s') . ' - IP: ' . $ipAddress . ', Result: ' . ($result ? 'Success' : 'Failure') . PHP_EOL, FILE_APPEND);
    }

    public function enforceTwoFactorAuthentication() {
        if ($this->twoFactorEnabled) {
            // Implement 2FA logic here
        }
    }

    public function limitLoginAttemptsPerIp($maxAttempts, $timeFrame = 300) {
        static $attempts = [];

        $ipAddress = $_SERVER['REMOTE_ADDR'];
        $currentTime = time();
        $key = $ipAddress . '_' . $currentTime;

        if (!isset($attempts[$key])) {
            $attempts[$key] = ['count' => 1, 'time' => $currentTime];
        } else {
            $attempts[$key]['count']++;
        }

        foreach ($attempts as &$attempt) {
            if (time() - $attempt['time'] > $timeFrame) {
                unset($attempt);
            }
        }

        if (count($attempts) > $maxAttempts) {
            // Block further attempts from this IP
        }
    }

    public function sanitizeInput($input) {
        return filter_var($input, FILTER_SANITIZE_STRING);
    }
}
