```rust
use tokio;
use std::env;
use std::fs;
use std::process::{Command, Stdio};
use log::{info, error};
use serde_json;

#[tokio::main]
async fn main() {
    // Parse command line arguments
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        error!("Missing function argument");
        return;
    }

    let function_name = &args[1];

    match function_name.as_str() {
        "run" => run_function(),
        "configure" => configure_application(),
        _ => error!("Invalid function name"),
    };
}

async fn run_function() {
    // Set environment variables
    env::set_var("APP_ENV", "production");

    // Load vendor autoloader
    let autoload_script = "path/to/autoloader.sh";
    Command::new(autoload_script)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to execute vendor autoloader")
        .wait_with_output()
        .expect("Vendor autoloader execution failed");

    // Load configuration
    let config = load_configuration().await;
    if let Err(e) = config {
        error!("Failed to load configuration: {}", e);
        return;
    }

    // Configure application
    configure_app(&config.unwrap()).await;
}

async fn configure_application() {
    // Get current environment from ENV variable
    let env = env::var("ENV").expect("ENV variable not set");

    // Load environment-specific configuration
    let config = load_environment_config(env).await;
    if let Err(e) = config {
        error!("Failed to load environment configuration: {}", e);
        return;
    }

    // Configure application with environment-specific settings
    configure_app(&config.unwrap()).await;
}

async fn load_configuration() -> Result<serde_json::Value, String> {
    // Load global configuration from file
    let config_file = "path/to/config.json";
    fs::read_to_string(config_file)
        .map_err(|e| format!("Failed to read configuration file: {}", e))
        .and_then(|content| serde_json::from_str(&content).map_err(|e| format!("Failed to parse JSON: {}", e)))
}

async fn load_environment_config(env: String) -> Result<serde_json::Value, String> {
    // Load environment-specific configuration from database
    let db_url = "db://user:password@localhost/dbname";
    let client = reqwest::Client::new();

    let response = client.get(&format!("{}/config?env={}", db_url, env))
        .send()
        .await?
        .json::<serde_json::Value>()
        .await?;

    Ok(response)
}

async fn configure_app(config: &serde_json::Value) {
    // Configure application using loaded configuration
    info!("Configuring application with settings: {:?}", config);
}
