import requests
from collections import defaultdict
from jinja2 import Template

# Define a class to represent a script object
class Script:
    def __init__(self, id, src, fallback):
        self.id = id
        self.src = src
        self.fallback = fallback

# Create a global dictionary to cache loaded scripts
script_cache = {}

# Define the template for the footer section
footer_template = Template("""
<footer>
  {% for script in scripts %}
    <script id="{{ script.id }}">
      {{ script.content }}
    </script>
  {% endfor %}
</footer>
""")

def load_script(script):
    try:
        response = requests.get(script.src)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        logging.error(f"Failed to load script {script.id}: {e}")
        return script.fallback

def render_footer(scripts):
    # Load each script and cache the content
    for script in scripts:
        if script.src not in script_cache:
            script.content = load_script(script)
            script_cache[script.src] = script.content
        else:
            script.content = script_cache[script.src]

    # Render the footer template with the loaded scripts
    return footer_template.render(scripts=scripts)

# Example usage
scripts = [
    Script("jquery", "https://code.jquery.com/jquery-3.6.0.min.js", "<!-- jQuery fallback content -->"),
    Script("my-script", "/static/my-script.js", "<!-- My script fallback content -->")
]

footer_html = render_footer(scripts)
print(footer_html)
