// Define an interface for transaction logging
class TransactionLogger {
public:
    virtual ~TransactionLogger() = default;
    virtual void log(const std::string& transaction) = 0;
};

// Implement a logger that writes to a database
class DatabaseLogger : public TransactionLogger {
private:
    // Simulated database connection object
    struct DBConnection {
        bool connect();
        void disconnect();
        bool execute(const std::string& query);
    };

    DBConnection dbConn;

public:
    void log(const std::string& transaction) override {
        if (!dbConn.connect()) {
            fallbackLogger->log(transaction);
            return;
        }
        std::string query = "INSERT INTO transactions VALUES ('" + transaction + "');";
        if (!dbConn.execute(query)) {
            fallbackLogger->log(transaction);
        } else {
            dbConn.disconnect();
        }
    }

private:
    std::unique_ptr<TransactionLogger> fallbackLogger;
};

// Implement a logger that writes to a log file
class FileLogger : public TransactionLogger {
public:
    void log(const std::string& transaction) override {
        std::ofstream file("transactions.log", std::ios::app);
        if (file.is_open()) {
            file << transaction << std::endl;
            file.close();
        } else {
            fallbackLogger->log(transaction);
        }
    }

private:
    std::unique_ptr<TransactionLogger> fallbackLogger;
};

// Implement a logger that sends data to an external payment processing system
class PaymentProcessingLogger : public TransactionLogger {
public:
    void log(const std::string& transaction) override {
        // Simulated API call to payment processing system
        if (sendToPaymentSystem(transaction)) {
            return;
        } else {
            fallbackLogger->log(transaction);
        }
    }

private:
    bool sendToPaymentSystem(const std::string& transaction) {
        // Dummy implementation
        return true; // Assume it always succeeds for simplicity
    }

    std::unique_ptr<TransactionLogger> fallbackLogger;
};

// Implement a logger that combines multiple logging strategies
class CompositeLogger : public TransactionLogger {
public:
    void addLogger(std::unique_ptr<TransactionLogger> logger) {
        loggers.push_back(std::move(logger));
    }

    void log(const std::string& transaction) override {
        for (auto& logger : loggers) {
            try {
                logger->log(transaction);
                return;
            } catch (...) {
                // Handle exception and continue to next logger
            }
        }
    }

private:
    std::vector<std::unique_ptr<TransactionLogger>> loggers;
};

// Factory function to create a logger based on configuration
std::unique_ptr<TransactionLogger> createLogger(const std::string& config) {
    if (config == "database") {
        return std::make_unique<DatabaseLogger>();
    } else if (config == "file") {
        return std::make_unique<FileLogger>();
    } else if (config == "payment_processing") {
        return std::make_unique<PaymentProcessingLogger>();
    } else {
        throw std::invalid_argument("Invalid logger configuration");
    }
}

// Example usage
int main() {
    auto logger = createLogger("database");
    logger->log("Transaction 123");

    CompositeLogger compositeLogger;
    compositeLogger.addLogger(createLogger("file"));
    compositeLogger.log("Transaction 456");

    return 0;
}
