```java
public class JwtService {

    private final ConfigurationLoader configLoader;
    private final JwtValidator validator;
    private final CacheStorage cache;
    private final ExternalApiClient apiClient;

    public JwtService(ConfigurationLoader configLoader, JwtValidator validator, CacheStorage cache, ExternalApiClient apiClient) {
        this.configLoader = configLoader;
        this.validator = validator;
        this.cache = cache;
        this.apiClient = apiClient;
    }

    public UserInformation processJwt(String jwt, String issuer, String audience) {
        try {
            // Check cache first
            if (cache.contains(jwt)) {
                return cache.get(jwt);
            }

            // Load configuration and validate JWT
            Config config = configLoader.loadConfig();
            if (!validator.validateToken(jwt, issuer, audience, config.getSecretKey(), config.getAllowedIssuers(), config.getAllowedAudiences())) {
                throw new InvalidJwtException("JWT is invalid");
            }

            // Extract user information
            UserInformation userInfo = validator.extractUserInfo(jwt);

            // Check for token revocation if it's a refresh token
            if (userInfo.isRefreshToken()) {
                if (apiClient.isTokenRevoked(userInfo.getTokenId())) {
                    throw new RevokedJwtException("JWT has been revoked");
                }
            }

            // Store in cache
            cache.put(jwt, userInfo);

            return userInfo;
        } catch (InvalidJwtException | RevokedJwtException e) {
            handleExceptions(e);
            return null;
        }
    }

    private void handleExceptions(Exception e) {
        // Log the exception and possibly notify an administrator
        System.err.println("Error processing JWT: " + e.getMessage());
    }
}
