    pass

class FileAggregator:
    def __init__(self, storage_services: list[CloudStorageService]):
        self.storage_services = storage_services
        self.executor = ThreadPoolExecutor(max_workers=len(storage_services))

    def add_file(self, file_path: str) -> None:
        # Dynamically select a service based on user preference
        for service in self.storage_services:
            self.executor.submit(service.upload_file, file_path)

class FileValidator:
    @staticmethod
    def calculate_checksum(data: bytes, algorithm: str = 'sha256') -> str:
        hash_object = hashlib.new(algorithm)
        hash_object.update(data)
        return hash_object.hexdigest()

