```php
class FilePasswordManager {
    private $hashedPassword = null;
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
    private $saltRoundCount = 12;
    private $cache = [];

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }
        $string = '';
        for ($i = 0; $i < $length; $i++) {
            $string .= substr($this->characterSet, mt_rand(0, strlen($this->characterSet) - 1), 1);
        }
        return $this->cache[$length] = $string;
    }

    public function hashPassword($password) {
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        if ($this->hashedPassword === null) {
            throw new Exception('No hashed password set.');
        }
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\da-zA-Z]).+$/', $characterSet)) {
            throw new Exception('Invalid character set. Please include at least one uppercase, one lowercase letter, one digit, and one special character.');
        }
        return true;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new Exception('Salt round count must be between 12 and 31.');
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $newPassword = $this->generateSecureRandomString(16);
        $this->hashPassword($newPassword);
        if (isset($this->cache[strlen($newPassword)])) {
            unset($this->cache[strlen($newPassword)]);
        }
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement file-based logging system
        $logEntry = date('Y-m-d H:i:s') . ' - IP: ' . $ipAddress . ' - Result: ' . ($result ? 'Success' : 'Failure') . PHP_EOL;
        file_put_contents('password_attempts.log', $logEntry, FILE_APPEND);
    }

    public function calculateFileMD5($filePath) {
        return hash_file('md5', $filePath, true);
    }
}
