            while (true) {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !asyncOperations.empty() || !running; });
                if (!running && asyncOperations.empty()) {
                    break;
                }

                auto future = asyncOperations.back();
