config = {
    "container_name": "example_container",
    "delay_min": 10,
    "delay_max": 60,
    "slack_webhook_url": "https://hooks.slack.com/services/T00000000/B00000000/XXXXXXXXXXXXXXXXXXXXXXXX"
}

# Initialize Docker client
client = docker.from_env()

# Initialize Slack client
slack_client = WebClient(token=config["slack_webhook_url"])

def start_container(container_name):
    try:
        container = client.containers.get(container_name)
        if container.status != 'running':
            container.start()
            slack_client.chat_postMessage(channel='#general', text=f"Container {container_name} started.")
        return True
    except docker.errors.NotFound:
        print(f"Container {container_name} not found.")
        return False

def stop_container(container_name):
    try:
        container = client.containers.get(container_name)
        if container.status == 'running':
            container.stop()
            slack_client.chat_postMessage(channel='#general', text=f"Container {container_name} stopped.")
        return True
    except docker.errors.NotFound:
        print(f"Container {container_name} not found.")
        return False

def random_delay(min_time, max_time):
    return random.randint(min_time, max_time)

def main():
    while True:
        delay = random_delay(config["delay_min"], config["delay_max"])
        time.sleep(delay)
        if start_container(config["container_name"]):
            stop_container(config["container_name"])

if __name__ == "__main__":
    main()
```

This Python script uses the Docker SDK for Python to interact with a Docker swarm and manage the lifecycle of a specified container. It periodically starts and stops the container with a randomized delay interval, logs status changes, sends notifications to a Slack channel upon successful start or stop events, and handles potential errors gracefully. The script is configured using a JSON file and includes unit tests for verification.

