// CalculateFileHash function to handle file hash calculation and resumable uploads

function calculateFileHash($privateKeyPath, $certificatePath, $outputFilePath, $chunkSize = 1024 * 1024) {
    if (!file_exists($privateKeyPath) || !file_exists($certificatePath)) {
        return ["error" => "Private key or certificate file not found."];
    }

    $tempPemFile = tempnam(sys_get_temp_dir(), 'pem');
    file_put_contents($tempPemFile, file_get_contents($privateKeyPath) . PHP_EOL . file_get_contents($certificatePath));

    $hashContext = hash_init('sha256', HASH_FILE, $tempPemFile);

    $fileHandle = fopen($outputFilePath, 'rb');

    if ($fileHandle === false) {
        return ["error" => "Failed to open output file for reading."];
    }

    while (!feof($fileHandle)) {
        $data = fread($fileHandle, $chunkSize);

        if (hash_update($hashContext, $data) === false) {
            fclose($fileHandle);
            unlink($tempPemFile);
            return ["error" => "Failed to update hash context."];
        }
    }

    fclose($fileHandle);
    unlink($tempPemFile);

    $finalHash = hash_final($hashContext, true);
    return bin2hex($finalHash);
}
