#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>

#define MAX_PROCESSES 100

typedef struct semaphore {
    char name[256];
    sem_t *sem;
} Semaphore;

Semaphore semaphores[MAX_PROCESSES];

int create_semaphore(const char *name, unsigned int initial_value) {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (semaphores[i].sem == NULL) {
            snprintf(semaphores[i].name, sizeof(semaphores[i].name), "%s", name);
            semaphores[i].sem = sem_open(name, O_CREAT | O_EXCL, 0644, initial_value);
            return 0;
        }
    }
    return -1;
}

int delete_semaphore(const char *name) {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (semaphores[i].sem != NULL && strcmp(semaphores[i].name, name) == 0) {
            sem_close(semaphores[i].sem);
            sem_unlink(name);
            semaphores[i].sem = NULL;
            return 0;
        }
    }
    return -1;
}

int increment_semaphore(const char *name) {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (semaphores[i].sem != NULL && strcmp(semaphores[i].name, name) == 0) {
            sem_post(semaphores[i].sem);
            return 0;
        }
    }
    return -1;
}

int decrement_semaphore(const char *name) {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (semaphores[i].sem != NULL && strcmp(semaphores[i].name, name) == 0) {
            sem_wait(semaphores[i].sem);
            return 0;
        }
    }
    return -1;
}

