function asyncArrayReduce(arr, initialValue, callback, concurrency = 1) {
    return new Promise((resolve, reject) => {
        let index = 0;
        let completed = 0;
        let result = initialValue;

        function processNext() {
            if (index >= arr.length) {
                resolve(result);
                return;
            }

            const value = arr[index++];
            callback(value, result).then(newResult => {
                result = newResult;
                completed++;
                logProgress(completed, index - 1, result);
                if (completed % concurrency === 0) {
                    setTimeout(processNext, 0);
                } else {
                    processNext();
                }
            }).catch(error => reject(error));
        }

        for (let i = 0; i < concurrency; i++) {
            processNext();
        }
    });
}

function logProgress(completed, total, result) {
