class MessagingLibrary {
public:
    void loadModule(std::unique_ptr<MessagingModule> module) {
        std::lock_guard<std::mutex> lock(mutex_);
        modules_.push_back(std::move(module));
    }

    bool sendTextMessage(const std::string& recipient, const std::string& message) {
        for (auto& module : modules_) {
            if (module->sendTextMessage(recipient, message)) {
                return true;
            }
        }
        return false;
    }

    bool sendVoiceCall(const std::string& recipient, const std::string& number) {
        for (auto& module : modules_) {
            if (module->sendVoiceCall(recipient, number)) {
                return true;
            }
        }
        return false;
    }

    bool sendMultimediaMessage(const std::string& recipient, const std::string& file_path) {
        for (auto& module : modules_) {
            if (module->sendMultimediaMessage(recipient, file_path)) {
                return true;
            }
        }
        return false;
    }

private:
    std::vector<std::unique_ptr<MessagingModule>> modules_;
    std::mutex mutex_;
};

