```javascript
const asyncStreamReducer = async (stream, {
  reducer,
  pauseHandler,
  resumeHandler,
  batchSize = 100,
  throttleMs = 1000,
  cacheSize = 500,
  apiCall,
  reportProgress,
  auth,
  parallelism = 1,
  timeoutMs = 30000
}) => {
  const collectedData = [];
  let isPaused = false;
  let isProcessing = false;
  let cache = new Map();
  let progress = 0;

  const fetchAndProcessBatch = async () => {
    try {
      if (isPaused) return;
      isProcessing = true;
      const batch = await stream.read(batchSize);
      for (const item of batch) {
        collectedData.push(await reducer(item, auth));
        cache.set(item.id, item);
      }
      progress += batch.length;
      reportProgress(progress);
      if (!batch.length) isProcessing = false;
    } catch (error) {
      console.error('Error processing batch:', error);
      isProcessing = false;
    }
  };

  const callApiWithTimeout = async (url, options) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeoutMs);
    try {
      return await apiCall(url, { ...options, signal: controller.signal });
    } finally {
      clearTimeout(id);
    }
  };

  const processApiBatch = async () => {
    try {
      if (isPaused) return;
      isProcessing = true;
      const batch = Array.from(cache.values());
      for (const item of batch) {
        await callApiWithTimeout('https://api.example.com/data', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${auth.token}` },
          body: JSON.stringify(item)
        });
        cache.delete(item.id);
      }
      progress += batch.length;
      reportProgress(progress);
      if (!cache.size) isProcessing = false;
    } catch (error) {
      console.error('Error processing API batch:', error);
      isProcessing = false;
    }
  };

  const throttledProcessApiBatch = throttle(() => processApiBatch(), throttleMs, { leading: true, trailing: true });

  const pause = () => {
    isPaused = true;
    pauseHandler();
  };

  const resume = async () => {
    isPaused = false;
    resumeHandler();
    while (!isProcessing) await new Promise(resolve => setTimeout(resolve, 100));
  };

  stream.on('data', throttledProcessApiBatch);
  stream.on('pause', pause);
  stream.on('resume', resume);

  setInterval(fetchAndProcessBatch, throttleMs / parallelism);

  return collectedData;
};
