using StackExchange.Redis;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicConfigUpdater
{
    private readonly IDatabase _database;
    private readonly ConnectionMultiplexer _redisConnection;
    private static readonly object LockObject = new object();

    public DynamicConfigUpdater(string connectionString)
    {
        _redisConnection = ConnectionMultiplexer.Connect(connectionString);
        _database = _redisConnection.GetDatabase();
    }

    public async Task UpdateConfigurationAsync(int userId, string configName, string newValue)
    {
        try
        {
            lock (LockObject)
            {
                var key = $"{userId}:{configName}";
                if (!_database.KeyExists(key))
                    throw new Exception("Configuration not found.");

                _database.StringSet(key, newValue);
                await Task.Delay(10); // Simulate database write delay
            }

            var imagePath = "cache/theme.png";
            using (var imageBytes = System.IO.File.ReadAllBytes(imagePath))
            {
                var themeKey = $"theme:{userId}";
                _database.Set(themeKey, imageBytes);
                await Task.Delay(10); // Simulate database write delay
            }
        }
        catch (OutOfMemoryException)
        {
            throw new Exception("Failed to allocate memory.");
        }
        catch (RedisConnectionMultiplexerException)
        {
            throw new Exception("Network error during database interaction.");
        }
        catch (DataMisalignedException)
        {
            throw new Exception("Conflict in configuration update.");
        }
    }
}
