def encrypt_password(password, encryption_key):
    f = Fernet(encryption_key)
    encrypted_password = f.encrypt(password.encode())
    return encrypted_password.decode()

def update_kickstart_config(kickstart_path, config_dict, encryption_key):
    with open(kickstart_path, 'r') as file:
        kickstart_content = file.read()

    for key, value in config_dict.items():
        kickstart_content = kickstart_content.replace(f"{key}=", f"{key}={value}")

    encrypted_password = encrypt_password(config_dict['password'], encryption_key)

    with open(kickstart_path, 'a') as file:
        file.write(f"\nencrypted_password={encrypted_password}\n")

def run_command(command):
    try:
        result = subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return result.stdout.decode()
    except subprocess.CalledProcessError as e:
        raise Exception(f"Command failed with error: {e.stderr.decode()}")

encryption_key = Fernet.generate_key()

update_kickstart_config("path/to/kickstart.cfg", {
