#include <condition_variable>
#include <chrono>
#include <variant>
#include <system_error>

enum class TransactionType { DEBIT, CREDIT };
enum RecorderType { DATABASE, FILE, PAYMENT_PROCESSOR };

struct Transaction {
    int id;
    TransactionType type;
    double amount;
    std::time_t timestamp;
};

class TransactionFilter {
public:
    static bool isRecent(const Transaction& t) {
        auto now = std::chrono::system_clock::now();
        return std::chrono::duration_cast<std::chrono::seconds>(now - std::chrono::system_clock::from_time_t(t.timestamp)).count() <= 3;
    }

    static double calculateWeightedSum(const std::vector<Transaction>& transactions) {
        double sum = 0.0;
        for (const auto& t : transactions) {
            sum += t.amount * (t.type == TransactionType::CREDIT ? 1.0 : -1.0);
        }
        return sum;
    }
};

