# app_logging.py

import logging
from flask import Flask
from logging.handlers import RotatingFileHandler, SMTPHandler

def configure_logging(app: Flask, log_levels: dict, log_formats: dict):
    # Set up basic configuration for logging
    logging.basicConfig(level=logging.DEBUG)

    for level_name, level in log_levels.items():
        logger = app.logger
        handler = None

        if level_name == 'console':
            handler = logging.StreamHandler()
        elif level_name == 'file':
            handler = RotatingFileHandler('app.log', maxBytes=1024 * 1024 * 5, backupCount=3)
        elif level_name == 'email':
            # Placeholder for email handler configuration
            continue

        if handler:
            formatter = logging.Formatter(log_formats.get(level_name, '%(asctime)s - %(levelname)s - %(message)s'))
            handler.setFormatter(formatter)
            logger.setLevel(level)
            logger.addHandler(handler)

# Example usage in your Flask app

if __name__ == "__main__":
    app = Flask(__name__)

    # Define log levels and formats
    log_levels = {
        'console': logging.DEBUG,
        'file': logging.ERROR,
    }

    log_formats = {
        'console': '%(asctime)s - %(levelname)s - %(message)s',
        'file': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    }

    # Configure logging
    configure_logging(app, log_levels, log_formats)

    @app.route('/')
    def index():
        app.logger.debug("This is a debug message")
        app.logger.info("This is an info message")
        app.logger.warning("This is a warning message")
        app.logger.error("This is an error message")
        app.logger.critical("This is a critical message")
        return "Check your logs!"

    if __name__ == "__main__":
        app.run(debug=True)
