# test_app_logging.py

import unittest
from app_logging import configure_logging, logging
from flask import Flask

class TestAppLogging(unittest.TestCase):
    def setUp(self):
        self.app = Flask(__name__)

    def test_configure_logging_console_handler(self):
        log_levels = {'console': logging.DEBUG}
        log_formats = {'console': '%(asctime)s - %(levelname)s - %(message)s'}

        configure_logging(self.app, log_levels, log_formats)

        console_handler = next((handler for handler in self.app.logger.handlers if isinstance(handler, logging.StreamHandler)), None)
        self.assertIsNotNone(console_handler)
        self.assertEqual(console_handler.level, logging.DEBUG)

    def test_configure_logging_file_handler(self):
        log_levels = {'file': logging.ERROR}
        log_formats = {'file': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'}

        configure_logging(self.app, log_levels, log_formats)

        file_handler = next((handler for handler in self.app.logger.handlers if isinstance(handler, logging.FileHandler)), None)
        self.assertIsNotNone(file_handler)
        self.assertEqual(file_handler.level, logging.ERROR)

    def test_configure_logging_email_handler(self):
        log_levels = {'email': logging.CRITICAL}

        configure_logging(self.app, log_levels, {})

        email_handler = next((handler for handler in self.app.logger.handlers if isinstance(handler, SMTPHandler)), None)
        self.assertIsNone(email_handler)  # SMTPHandler is not configured

if __name__ == "__main__":
    unittest.main()
