import java.io.File;
import java.io.IOException;
import java.util.List;

public class PokemonWeaknessService {

    public static PokemonWeaknessResult getWeaknesses(Pokemon pokemon, String directoryPath) {
        boolean webConfigExists = false;
        List<String> weaknesses = null;
        String errorMessage = null;

        try {
            File configFile = new File(directoryPath + "/web.config");
            webConfigExists = configFile.exists();

            if (!webConfigExists) {
                return new PokemonWeaknessResult(false, null, "Web.config file does not exist.");
            }

            ProcessBuilder processBuilder = new ProcessBuilder("cmd.exe", "/c", "start", directoryPath);
            try {
                Process process = processBuilder.start();
                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    weaknesses = getPokemonWeaknesses(pokemon.getType());
                } else {
                    errorMessage = "Failed to start directory with exit code: " + exitCode;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                errorMessage = "Process interrupted.";
            }

        } catch (IOException e) {
            errorMessage = "IO Exception occurred: " + e.getMessage();
        }

        return new PokemonWeaknessResult(webConfigExists, weaknesses, errorMessage);
    }

    private static List<String> getPokemonWeaknesses(String type) {
        // Dummy implementation to simulate fetching weaknesses based on type
        switch (type.toLowerCase()) {
            case "fire":
                return List.of("water", "ground");
            case "water":
                return List.of("grass", "electric");
            case "grass":
                return List.of("fire", "ice");
            default:
                return List.of();
        }
    }
}
