import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class DirectoryCompressor {

    public static void main(String[] args) {
        if (args.length < 3) {
            System.out.println("Usage: java DirectoryCompressor <inputDir> <outputZip> <level>");
            return;
        }

        Path inputDir = Paths.get(args[0]);
        Path outputZip = Paths.get(args[1]);
        int level = Integer.parseInt(args[2]);

        try {
            compressDirectory(inputDir, outputZip, level);
        } catch (IOException | InterruptedException e) {
            System.err.println("Error during compression: " + e.getMessage());
        }
    }

    private static void compressDirectory(Path inputDir, Path outputZip, int level) throws IOException, InterruptedException {
        if (!Files.exists(inputDir)) {
            throw new IOException("Input directory does not exist");
        }

        if (Files.exists(outputZip)) {
            Files.delete(outputZip);
        }

        ProcessBuilder pb = new ProcessBuilder();
        pb.directory(new File(System.getProperty("user.dir")));
        pb.command("zip", "-r", outputZip.toString(), inputDir.toString());
        pb.inheritIO();

        Process process = pb.start();

        if (process.waitFor() == 0) {
            System.out.println("Directory compressed successfully");
        } else {
            throw new IOException("Failed to compress directory");
        }
    }
}
