            }

            JsonNode rootNode = objectMapper.readTree(jsonData);
            JsonNode result = extractData(rootNode, jsonPath);

            if (result != null) {
                cache.put(jsonPath, result);
            } else {
                throw new IllegalArgumentException("No data found for path: " + jsonPath);
            }

            return result;
        } catch (IOException e) {
