    }

    public void logCacheStats() {
        // Log cache hits and misses along with query times
    }

    private static class CacheEntry {
        long lastAccessTime;
        JsonNode data;

        CacheEntry(JsonNode data) {
            this.data = data;
            this.lastAccessTime = System.currentTimeMillis();
        }
    }

    private static class LRUCache<K, V> {
        private final int capacity;
        private final ConcurrentHashMap<K, V> cache;
        private final java.util.LinkedHashMap<K, V> order;

        public LRUCache(int capacity) {
            this.capacity = capacity;
            this.cache = new ConcurrentHashMap<>(capacity);
            this.order = new java.util.LinkedHashMap<>(capacity);
        }

        public V get(K key) {
            if (cache.containsKey(key)) {
                order.remove(key);
                order.put(key, cache.get(key));
            }
            return cache.get(key);
        }

        public void put(K key, V value) {
            cache.put(key, value);
            order.put(key, value);

            if (order.size() > capacity) {
                K eldestKey = order.keySet().iterator().next();
                order.remove(eldestKey);
                cache.remove(eldestKey);
            }
        }

        public void remove(K key) {
            cache.remove(key);
            order.remove(key);
        }
    }
}
