// Fetch configuration from the external API with caching and fallback strategy
function fetchConfig($env, $apiEndpoint, $cacheDir) {
    $cacheFile = $cacheDir . $env . '.json';

    if (file_exists($cacheFile)) {
        $lastModified = filemtime($cacheFile);
        $currentTimestamp = time();
        $maxCacheAge = 3600; // Cache for 1 hour

        if ($currentTimestamp - $lastModified < $maxCacheAge) {
            return json_decode(file_get_contents($cacheFile), true);
        }
    }

    try {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $apiEndpoint . '?env=' . urlencode($env));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_TIMEOUT, 10); // Set timeout to 10 seconds

        $response = curl_exec($ch);

        if (curl_errno($ch)) {
            throw new Exception('API request failed: ' . curl_error($ch));
        }

        curl_close($ch);

        $config = json_decode($response, true);
        file_put_contents($cacheFile, json_encode($config));

        return $config;
    } catch (Exception $e) {
        if (file_exists($cacheFile)) {
            return json_decode(file_get_contents($cacheFile), true);
        } else {
            throw new Exception('Failed to fetch configuration: ' . $e->getMessage());
        }
    }
