// Function to derive a key using Argon2
int derive_key(const char *password, const char *salt, unsigned int salt_len, unsigned int key_len, unsigned char *key) {
    argon2id_ctx ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.out = (uint8_t *)key;
    ctx.outlen = key_len;
    ctx.pwd = (uint8_t *)password;
    ctx.pwdsz = strlen(password);
    ctx.salt = (uint8_t *)salt;
    ctx.salthash = NULL; // Use the default Argon2 algorithm
    ctx.secret = NULL;
    ctx.secretlen = 0;
    ctx.ad = NULL;
    ctx.adlen = 0;
    ctx.t_cost = 3; // Number of passes
    ctx.m_cost = 16 * 1024; // Memory cost in KiB
    ctx.lanes = 4; // Number of lanes
    ctx.threads = 4; // Number of threads

    if (argon2id_hash(&ctx) != ARGON2_OK) {
        fprintf(stderr, "Argon2 hash failed\n");
        return -1;
    }

    return 0;
}

