    public S3ApiClient(String accessKey, String secretKey) {
        AWSCredentialsProvider credentialsProvider = new AWSStaticCredentialsProvider(new BasicAWSCredentials(accessKey, secretKey));
        this.s3Client = AmazonS3ClientBuilder.standard().withRegion("us-east-1").withCredentials(credentialsProvider).build();
        this.executorService = Executors.newFixedThreadPool(10);
    }

    // CRUD Operations
    public void putObject(String bucketName, String key, File file) {
        PutObjectRequest request = new PutObjectRequest(bucketName, key, file);
        s3Client.putObject(request);
    }

    public S3Object getObject(String bucketName, String key) {
        return s3Client.getObject(new GetObjectRequest(bucketName, key));
    }

    public void deleteObject(String bucketName, String key) {
        s3Client.deleteObject(new DeleteObjectRequest(bucketName, key));
    }

    // Advanced Features
    public void enableVersioning(String bucketName) {
        VersioningConfiguration versioningConfig = new VersioningConfiguration();
        versioningConfig.setStatus(CannedVersioningStatus.Enabled);
        PutBucketVersioningConfigurationRequest versioningReq =
                new PutBucketVersioningConfigurationRequest(bucketName, versioningConfig);
        s3Client.setBucketVersioningConfiguration(versioningReq);
    }

    // Rate Limiting and Retry Policies
    public void uploadLargeFile(String bucketName, String key, File file) {
        executorService.submit(() -> {
            try {
                TransferManager transferManager = new TransferManager(s3Client);
                Upload upload = transferManager.upload(bucketName, key, file);
                upload.waitForCompletion();
            } catch (Exception e) {
                logger.error("Error uploading file: " + e.getMessage());
            }
        });
    }

    // Authentication and Connection Settings
    public void setRegion(String region) {
        this.s3Client.setRegion(Regions.fromName(region));
    }

    // Logging and Metrics Collection
    private static class S3ApiMetrics {
        public void logOperationTime(long timeTaken) {
            logger.info("Operation took " + timeTaken + " ms");
        }
    }

