class ConfigManager:
    _registry = {}
    _cache = {}
    _lock = threading.Lock()

    @staticmethod
    def register_parser(config_type, parser):
        with ConfigManager._lock:
            if config_type not in ConfigManager._registry:
                ConfigManager._registry[config_type] = parser

    @staticmethod
    def parse_config_file(file_path, config_type):
        with ConfigManager._lock:
            parser = ConfigManager._registry.get(config_type)
            if parser is None:
                raise ValueError(f"No parser registered for configuration type: {config_type}")

            config_data = parser(file_path)
            ConfigManager._cache[config_type] = config_data
            return config_data

    @staticmethod
    def notify_services(config_type):
        with ConfigManager._lock:
            # Logic to notify connected services about the configuration change
            print(f"Notify services about {config_type} config change")

class JsonSerializer:
    @staticmethod
    def serialize(data):
        return json.dumps(data)

    @staticmethod
    def deserialize(json_str):
        return json.loads(json_str)

def example_config_parser(file_path):
    with open(file_path, 'r') as file:
        config_data = json.load(file)
    return config_data

# Usage
ConfigManager.register_parser('example', example_config_parser)
