using System;
using System.Collections.Concurrent;
using System.Xml.XPath;

public class XmlParser
{
    private readonly ConcurrentDictionary<string, XPathDocument> _cache = new();
    private readonly IConfigLoader _configLoader;

    public XmlParser(IConfigLoader configLoader)
    {
        _configLoader = configLoader ?? throw new ArgumentNullException(nameof(configLoader));
    }

    public XPathNodeIterator GetFirstElement(string documentName, string elementName)
    {
        var xmlPath = _configLoader.GetXmlPath(documentName);
        if (xmlPath == null)
            throw new ArgumentException("Document name not found in configuration.");

        return GetCachedDocument(xmlPath).CreateNavigator().SelectSingleNode($"//*[local-name()='{elementName}']")?.CreateNavigator();
    }

    private XPathDocument GetCachedDocument(string xmlPath)
    {
        if (!_cache.TryGetValue(xmlPath, out var document))
        {
            lock (_cache)
            {
                if (!_cache.ContainsKey(xmlPath)) // Double-check locking
                {
                    document = new XPathDocument(xmlPath);
                    _cache.TryAdd(xmlPath, document);

                    // Set up cache eviction policy here (e.g., based on size or time-to-live)
                }
            }
        }

        return document;
    }
}

public interface IConfigLoader
{
    string GetXmlPath(string documentName);
}

// Example implementation of IConfigLoader
public class ConfigLoader : IConfigLoader
{
    private readonly ConcurrentDictionary<string, string> _config = new();

    public ConfigLoader()
    {
        // Load configuration from file or external system here
        _config.TryAdd("DocumentA", "path/to/documentA.xml");
        _config.TryAdd("DocumentB", "path/to/documentB.xml");
    }

    public string GetXmlPath(string documentName)
    {
        return _config.TryGetValue(documentName, out var path) ? path : null;
    }
}
