import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class StateLoader {

    public MoSTState loadStateFromFile(String filePath) throws DFSClientNotAvailableException, NetworkConnectivityException {
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                throw new FileNotFoundException("File not found: " + filePath);
            }

            FileInputStream fis = new FileInputStream(file);
            ObjectInputStream ois = new ObjectInputStream(fis);

            Object obj = ois.readObject();
            ois.close();
            fis.close();

            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            } else {
                return null;
            }

        } catch (FileNotFoundException e) {
            logError("File not found: " + filePath, e);
            throw new NetworkConnectivityException("Failed to find file at specified path.", e);

        } catch (EOFException e) {
            logError("Reached end of file unexpectedly", e);
            throw new NetworkConnectivityException("Failed to read complete data from file.", e);

        } catch (IOException | ClassNotFoundException e) {
            logError("Error reading state object from file", e);
            throw new DFSClientNotAvailableException("DFS client error or network issue.", e);
        }
    }

    private void logError(String message, Exception e) {
        // Implement logging mechanism here
        System.err.println(message + " - " + e.getMessage());
        e.printStackTrace();
    }

    // Custom exceptions
    public static class DFSClientNotAvailableException extends Exception {
        public DFSClientNotAvailableException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    public static class NetworkConnectivityException extends Exception {
        public NetworkConnectivityException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
