const AWS = require('aws-sdk');
const { Storage } = require('@google-cloud/storage');
const axios = require('axios');
const bluebird = require('bluebird');
const logger = require('winston');

// Initialize cloud storage clients
const s3Client = new AWS.S3();
const gcsClient = new Storage();

// Configurable criteria for provider selection
const providerConfigurations = {
  'aws': { cost: 0.01, performance: 4, regionAvailability: ['us-east-1', 'eu-central-1'] },
  'google': { cost: 0.02, performance: 3, regionAvailability: ['us-central1', 'europe-west1'] }
};

// Function to select the best cloud storage provider
async function selectProvider(fileMetadata) {
  // Implement logic based on configurable criteria
  const availableProviders = Object.keys(providerConfigurations).filter(provider => 
    providerConfigurations[provider].regionAvailability.includes(fileMetadata.region)
  );

  if (availableProviders.length === 0) {
    throw new Error('No suitable cloud storage provider found');
  }

  // Sort providers based on cost and performance
  availableProviders.sort((a, b) => {
    const aCost = providerConfigurations[a].cost;
    const bCost = providerConfigurations[b].cost;
    if (aCost === bCost) return providerConfigurations[b].performance - providerConfigurations[a].performance;
    return aCost - bCost;
  });

  return availableProviders[0];
}

// Function to upload file to selected cloud storage provider
async function uploadFile(file, provider) {
  const chunkSize = 5 * 1024 * 1024; // 5MB chunks
  let position = 0;

  try {
    while (position < file.size) {
      const chunkEnd = Math.min(position + chunkSize, file.size);
      const chunkBuffer = await bluebird.promisify(file.slice.bind(file))(position, chunkEnd);

      if (provider === 'aws') {
        const params = {
          Bucket: process.env.AWS_BUCKET,
          Key: file.name,
          Body: chunkBuffer,
          PartNumber: Math.floor(position / chunkSize) + 1
        };
        await bluebird.promisify(s3Client.uploadPart.bind(s3Client))(params);
      } else if (provider === 'google') {
        const bucket = gcsClient.bucket(process.env.GCS_BUCKET);
        const fileUploadStream = bucket.file(file.name).createWriteStream();
        fileUploadStream.end(chunkBuffer, async () => {
          await bluebird.promisify(bucket.upload.bind(bucket))({ path: file.path }, { partNumber: Math.floor(position / chunkSize) + 1 });
        });
      }

      position += chunkSize;
    }
  } catch (error) {
    logger.error(`Error uploading file to ${provider}:`, error);
    throw new Error('File upload failed');
  }
}

// Main function to handle file upload
async function upload(fileMetadata, fileStream) {
  try {
    const selectedProvider = await selectProvider(fileMetadata);

    if (selectedProvider === 'aws') {
      const params = {
        Bucket: process.env.AWS_BUCKET,
        Key: fileMetadata.name,
        Body: fileStream
      };
      const result = await bluebird.promisify(s3Client.upload.bind(s3Client))(params);
      return result.Location;
    } else if (selectedProvider === 'google') {
      const bucket = gcsClient.bucket(process.env.GCS_BUCKET);
      const [response] = await bucket.upload(fileStream, { destination: fileMetadata.name });
      return response.publicUrl();
    }

    throw new Error('Selected provider not supported');
  } catch (error) {
    logger.error('Error uploading file:', error);
    throw error;
  }
}

module.exports = upload;
