public class SocketChannelPool {
  private static final int POOL_SIZE = 10;
  private List<SocketChannel> pool;

  public SocketChannelPool(String address, int port) throws IOException {
    pool = new ArrayList<>(POOL_SIZE);
    for (int i = 0; i < POOL_SIZE; i++) {
      SocketChannel channel = SocketChannel.open(StandardOpenOption.WRITE);
      channel.configureBlocking(false);
      channel.connect(new InetSocketAddress(address, port));
      pool.add(channel);
    }
  }

  public void handleConnections() throws IOException {
    Selector selector = Selector.open();
    for (SocketChannel channel : pool) {
      channel.register(selector, SelectionKey.OP_READ);
    }

    while (true) {
      selector.select();

      Iterator<SelectionKey> iter = selector.selectedKeys().iterator();
      while (iter.hasNext()) {
        SelectionKey key = iter.next();
        if (key.isReadable()) {
          SocketChannel channel = (SocketChannel) key.channel();
          // handle incoming data asynchronously
        }
        iter.remove();
      }
    }
  }
}
