void insertAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& value, int timeout) {
  auto it = std::find(list.begin(), list.end(), target);
  if (it != list.end()) {
    list.insert_after(it, value);
  } else {
    list.push_back(value);
  }
}
