            return false; // Network timeout
        }
        lastRequest = std::chrono::system_clock::now();
        response = "Weather data for coordinates: " + std::to_string(latitude) + ", " + std::to_string(longitude);
        requests++;
        cache.isCached(response);
        if (cache.isCached(response)) {
            cacheHits++;
            return true;
        } else {
            cache.addToCache(response, response);
            return true;
        }
    }

