        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as executor:
            future_hash_functions = [executor.submit(hash_manager.get_hash_function, fn.split('=')[1]) for fn in hash_functions]
            future_ciphers = [executor.submit(cipher_manager.get_cipher, cp.split('=')[1]) for cp in ciphers]

            for future in concurrent.futures.as_completed(future_hash_functions):
                try:
                    future.result()
                except Exception as e:
                    print(f"Error getting hash function: {e}")

            for future in concurrent.futures.as_completed(future_ciphers):
                try:
                    future.result()
                except Exception as e:
                    print(f"Error getting cipher: {e}")
    except FileNotFoundError:
        print("Config file not found")

if __name__ == "__main__":
    main()
