```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.concurrent.CompletableFuture;

public class WeatherAPIManager {
    private static final HttpClient client = HttpClient.newHttpClient();

    public static CompletableFuture<String> getWeatherData(String location) {
        String apiKey = "YOUR_API_KEY";
        URI uri = URI.create("https://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=" + apiKey);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(uri)
                .GET()
                .build();

        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body)
                .exceptionally(ex -> {
                    System.err.println("Error fetching weather data: " + ex.getMessage());
                    // Retry mechanism
                    try {
                        Thread.sleep(2000); // Wait for 2 seconds before retrying
                        return getWeatherData(location).join();
                    } catch (Exception e) {
                        System.err.println("Failed to fetch weather data after retry");
                        return null;
                    }
                });
    }

    public static void main(String[] args) {
        CompletableFuture<String> future = getWeatherData("New York");
        try {
            String weatherData = future.get();
            if (weatherData != null) {
                System.out.println(weatherData);
            } else {
                System.err.println("Failed to fetch weather data");
            }
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
