using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Threading;

public class XmlParser
{
    private XmlDocument _xmlDocument;
    private readonly object _lockObject = new object();
    private Dictionary<string, XPathNodeIterator> _cache = new Dictionary<string, XPathNodeIterator>();
    private ILog _logger;

    public XmlParser(string xmlContent)
    {
        _xmlDocument = new XmlDocument();
        _xmlDocument.LoadXml(xmlContent);
        _logger = new Logger(); // Assuming a simple logger implementation
    }

    public string GetSingleElementValue(string xpathExpression)
    {
        lock (_lockObject)
        {
            XPathNodeIterator iterator;
            if (!_cache.TryGetValue(xpathExpression, out iterator))
            {
                iterator = _xmlDocument.CreateNavigator().Select(xpathExpression);
                _cache[xpathExpression] = iterator.Clone();
            }

            if (!iterator.MoveNext())
                throw new FileNotFoundException($"No element found for XPath: {xpathExpression}");

            var next = iterator.Current.SelectSingleNode(".");
            if (next.MoveToNext())
                throw new MultipleElementException($"Multiple elements found for XPath: {xpathExpression}");

            return next.Value;
        }
    }

    public List<string> GetElementsValues(string xpathExpression)
    {
        lock (_lockObject)
        {
            XPathNodeIterator iterator;
            if (!_cache.TryGetValue(xpathExpression, out iterator))
            {
                iterator = _xmlDocument.CreateNavigator().Select(xpathExpression);
                _cache[xpathExpression] = iterator.Clone();
            }

            List<string> values = new List<string>();
            while (iterator.MoveNext())
            {
                values.Add(iterator.Current.Value);
            }

            return values;
        }
    }

    public Dictionary<string, string> ExtractAttributes(string xpathExpression)
    {
        lock (_lockObject)
        {
            XPathNodeIterator iterator;
            if (!_cache.TryGetValue(xpathExpression, out iterator))
            {
                iterator = _xmlDocument.CreateNavigator().Select(xpathExpression);
                _cache[xpathExpression] = iterator.Clone();
            }

            Dictionary<string, string> attributes = new Dictionary<string, string>();
            while (iterator.MoveNext())
            {
                foreach (XmlAttribute attribute in iterator.Current.Attributes)
                {
                    attributes[attribute.Name] = attribute.Value;
                }
            }

            return attributes;
        }
    }

    public void ManipulateTextNodes(string xpathExpression, Func<string, string> transformation)
    {
        lock (_lockObject)
        {
            XPathNodeIterator iterator;
            if (!_cache.TryGetValue(xpathExpression, out iterator))
            {
                iterator = _xmlDocument.CreateNavigator().Select(xpathExpression);
                _cache[xpathExpression] = iterator.Clone();
            }

            while (iterator.MoveNext())
            {
                var currentNode = iterator.Current.SelectSingleNode(".");
                if (!currentNode.IsEmptyElement && currentNode.Value != null)
                {
                    currentNode.SetValue(transformation(currentNode.Value));
                }
            }
        }
    }

    public void TransformDocument(XsltArgumentList arguments, string xslContent)
    {
        try
        {
            using (XmlReader reader = _xmlDocument.CreateNavigator().ReadSubtree())
            using (StringReader srXsl = new StringReader(xslContent))
            {
                XslCompiledTransform transform = new XslCompiledTransform();
                transform.Load(srXsl);

                using (TextWriter writer = new StringWriter())
                {
                    transform.Transform(reader, arguments, writer);
                    _xmlDocument.LoadXml(writer.ToString());
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex.Message);
            throw;
        }
    }
}

public class FileNotFoundException : Exception
{
    public FileNotFoundException(string message) : base(message) { }
}

public class MultipleElementException : Exception
{
    public MultipleElementException(string message) : base(message) { }
}

public interface ILog
{
    void LogError(string message);
}

public class Logger : ILog
{
    public void LogError(string message)
    {
        Console.Error.WriteLine($"[ERROR] {message}");
    }
}
