<?php

use OAuth2\Client;
use Redis;
use Predis\Client as PredisClient;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

// Configuration
$clientID = 'your_client_id';
$clientSecret = 'your_client_secret';
$accessTokenEndpoint = 'https://oauth.example.com/token';
$userInfoEndpoint = 'https://api.example.com/userinfo';
$cachePrefix = 'user_data:';
$lockPrefix = 'auth_lock:';
$mfaEnabledUsers = ['user1', 'user2'];
$logFile = '/var/log/auth.log';

// Redis and Predis clients
$redisClient = new Redis();
$predisClient = new PredisClient();

// Logger
$logger = new Logger('auth');
$logger->pushHandler(new StreamHandler($logFile, Logger::DEBUG));

function authenticateUser($username, $password, $mfaCode = null) {
    global $clientID, $clientSecret, $accessTokenEndpoint, $userInfoEndpoint,
           $cachePrefix, $lockPrefix, $mfaEnabledUsers, $logger, $redisClient, $predisClient;

    // Rate limiting
    if (isUserRateLimited($username)) {
        return ['error' => 'Too many requests', 'status' => 429];
    }

    // Acquire lock
    $lockKey = $lockPrefix . $username;
    if (!$redisClient->setnx($lockKey, 1)) {
        return ['error' => 'User already being authenticated', 'status' => 409];
    }
    $redisClient->expire($lockKey, 30);

    try {
        // OAuth 2.0 authentication
        $client = new Client();
        $tokenResponse = $client->getAccessToken('password', [
            'username' => $username,
            'password' => $password,
            'client_id' => $clientID,
            'client_secret' => $clientSecret,
        ]);

        if ($tokenResponse === false) {
            $logger->error("Authentication failed for user: {$username}");
            return ['error' => 'Invalid credentials', 'status' => 401];
        }

        // Refresh token if needed
        if (isset($tokenResponse['expires_in']) && time() > $tokenResponse['expires_in'] - 60) {
            $refreshTokenResponse = $client->getAccessToken('refresh_token', [
                'refresh_token' => $tokenResponse['refresh_token'],
                'client_id' => $clientID,
                'client_secret' => $clientSecret,
            ]);

            if ($refreshTokenResponse === false) {
                $logger->error("Failed to refresh token for user: {$username}");
                return ['error' => 'Invalid credentials', 'status' => 401];
            }

            // Store new access token
            $redisClient->set($cachePrefix . $username, json_encode($refreshTokenResponse));
        } else {
            // Use existing access token from cache
            $tokenResponse = json_decode($redisClient->get($cachePrefix . $username), true);
        }

        // MFA verification
        if (in_array($username, $mfaEnabledUsers) && $mfaCode === null) {
            $logger->info("MFA required for user: {$username}");
            return ['mfa_required' => true];
        } elseif (!empty($mfaCode)) {
            // Verify MFA code
            if (!verifyMfaCode($username, $mfaCode)) {
                $logger->error("Invalid MFA code for user: {$username}");
                return ['error' => 'Invalid MFA code', 'status' => 401];
            }
        }

        // Retrieve and cache user information
        $userCacheKey = $cachePrefix . $username;
        if (!$redisClient->exists($userCacheKey)) {
            $userInfoResponse = file_get_contents($userInfoEndpoint, false, stream_context_create([
                'http' => [
                    'header'  => "Authorization: Bearer {$tokenResponse['access_token']}\r\n",
                ],
            ]));

            if ($userInfoResponse === false) {
                $logger->error("Failed to retrieve user info for user: {$username}");
                return ['error' => 'Unable to fetch user information', 'status' => 500];
            }

            $userInfo = json_decode($userInfoResponse, true);
            $redisClient->setex($userCacheKey, 3600, json_encode($userInfo));
        } else {
            $userInfo = json_decode($redisClient->get($userCacheKey), true);
        }

        // Store access token in session
        $_SESSION['access_token'] = $tokenResponse['access_token'];

        // Log successful login
        $logger->info("User {$username} logged in successfully");

        return ['user_info' => $userInfo];
    } catch (Exception $e) {
        $logger->error("Authentication failed: " . $e->getMessage());
        return ['error' => 'Internal server error', 'status' => 500];
    } finally {
        // Release lock
        $redisClient->del($lockKey);
    }
}

function isUserRateLimited($username) {
    global $predisClient;

    $key = "rate_limit_{$username}";
    $count = $predisClient->incr($key);
    if ($count == 1) {
        $predisClient->expire($key, 60); // Reset counter after 1 minute
    }

    return $count > 5; // Allow up to 5 requests per minute
}

