import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class FileHashService {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final BlockingQueue<String> cache = new LinkedBlockingQueue<>(1000);
    private final ConcurrentHashMap<String, Future<String>> futureCache = new ConcurrentHashMap<>();
    private final RateLimiter rateLimiter = RateLimiter.create(1.0);

    public String[] getFileHashes(String filePath) {
        if (!rateLimiter.tryAcquire()) {
            throw new RuntimeException("Too many requests");
        }
        try {
            validateFilePath(filePath);
            return computeHashes(filePath);
        } catch (Exception e) {
            logError(e);
            throw new RuntimeException("Failed to compute file hashes", e);
        }
    }

    private String[] computeHashes(String filePath) throws InterruptedException, ExecutionException {
        Future<String> md5Future = futureCache.computeIfAbsent(filePath + "_md5", k -> executor.submit(() -> {
            try {
                return Files.readAllBytes(new File(filePath).toPath());
            } catch (IOException e) {
                logError(e);
                throw new RuntimeException("Failed to read file", e);
            }
        }));
        Future<String> sha256Future = futureCache.computeIfAbsent(filePath + "_sha256", k -> executor.submit(() -> {
            try {
                return Files.readAllBytes(new File(filePath).toPath());
            } catch (IOException e) {
                logError(e);
                throw new RuntimeException("Failed to read file", e);
            }
        }));

        byte[] md5Data = md5Future.get();
        byte[] sha256Data = sha256Future.get();

        String md5Hash = computeHash(md5Data, "MD5");
        String sha256Hash = computeHash(sha256Data, "SHA-256");

        return new String[]{md5Hash, sha256Hash};
    }

    private String computeHash(byte[] data, String algorithm) {
        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            byte[] hashBytes = digest.digest(data);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            logError(e);
            throw new RuntimeException("Failed to compute hash", e);
        }
    }

    private void validateFilePath(String filePath) {
        if (filePath.length() > 1000 || !new File(filePath).exists()) {
            throw new IllegalArgumentException("Invalid file path");
        }
    }

    private void logError(Exception e) {
        // Log the error using an external logging system
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
