using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureDataProcessor : IDisposable
{
    private readonly ILogger _logger;
    private readonly IRateLimiter _rateLimiter;

    public SecureDataProcessor(ILogger logger, IRateLimiter rateLimiter)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _rateLimiter = rateLimiter ?? throw new ArgumentNullException(nameof(rateLimiter));
    }

    public async Task<string> GenerateMd5Async(string input) => await HashAsync(input, MD5.Create);
    public async Task<string> GenerateMd5Async(byte[] input) => await HashAsync(input, MD5.Create);

    public async Task<string> GenerateSha1Async(string input) => await HashAsync(input, SHA1.Create);
    public async Task<string> GenerateSha1Async(byte[] input) => await HashAsync(input, SHA1.Create);

    public async Task<string> GenerateSha256Async(string input) => await HashAsync(input, SHA256.Create);
    public async Task<string> GenerateSha256Async(byte[] input) => await HashAsync(input, SHA256.Create);

    private async Task<string> HashAsync<T>(string input, Func<T> hashFactory) where T : HashAlgorithm
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        using (var algorithm = hashFactory())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            await _rateLimiter.EnsureRateLimitAsync(nameof(HashAsync), input.Length);
            var hashBytes = await ProcessDataAsync(bytes, algorithm.TransformFinalBlock);
            return BitConverter.ToString(hashBytes).Replace("-", string.Empty).ToLower();
        }
    }

    private async Task<string> HashAsync<T>(byte[] input, Func<T> hashFactory) where T : HashAlgorithm
    {
        if (input == null || input.Length == 0)
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        using (var algorithm = hashFactory())
        {
            await _rateLimiter.EnsureRateLimitAsync(nameof(HashAsync), input.Length);
            var hashBytes = await ProcessDataAsync(input, algorithm.TransformFinalBlock);
            return BitConverter.ToString(hashBytes).Replace("-", string.Empty).ToLower();
        }
    }

    public async Task<string> CompressDataAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        var bytes = Encoding.UTF8.GetBytes(input);
        return await CompressAsync(bytes);
    }

    public async Task<string> CompressDataAsync(byte[] input)
    {
        if (input == null || input.Length == 0)
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        return await CompressAsync(input);
    }

    private async Task<string> CompressAsync(byte[] data)
    {
        using (var memoryStream = new MemoryStream())
        using (var gzipStream = new System.IO.Compression.GZipStream(memoryStream, System.IO.Compression.CompressionMode.Compress))
        {
            await _rateLimiter.EnsureRateLimitAsync(nameof(CompressAsync), data.Length);
            await gzipStream.WriteAsync(data, 0, data.Length);
            await gzipStream.FlushAsync();
            return Convert.ToBase64String(await memoryStream.ToArrayAsync());
        }
    }

    public async Task<string> EncryptDataAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        var bytes = Encoding.UTF8.GetBytes(input);
        return await EncryptAsync(bytes);
    }

    public async Task<string> EncryptDataAsync(byte[] input)
    {
        if (input == null || input.Length == 0)
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        return await EncryptAsync(input);
    }

    private async Task<string> EncryptAsync(byte[] data)
    {
        using (var rijndael = Aes.Create())
        {
            rijndael.KeySize = 256;
            rijndael.GenerateKey();
            var iv = new byte[rijndael.BlockSize / 8];
            RandomNumberGenerator.Fill(iv);
            rijndael.IV = iv;

            using (var memoryStream = new MemoryStream())
            using (var cryptoStream = new CryptoStream(memoryStream, rijndael.CreateEncryptor(), CryptoStreamMode.Write))
            {
                await _rateLimiter.EnsureRateLimitAsync(nameof(EncryptAsync), data.Length);
                await cryptoStream.WriteAsync(data, 0, data.Length);
                await cryptoStream.FlushFinalBlockAsync();
                return Convert.ToBase64String(memoryStream.ToArray()) + ":" + Convert.ToBase64String(iv);
            }
        }
    }

    public void Dispose()
    {
        _rateLimiter.Dispose();
    }
}

public interface ILogger
{
    void Log(string message, LogLevel level);
}

public enum LogLevel
{
    Debug,
    Info,
    Warning,
    Error
}

public class RateLimiter : IRateLimiter
{
    private readonly object _lock = new object();
    private DateTime _lastRequest;
    private int _requestCount;

    public async Task EnsureRateLimitAsync(string operation, int dataSize)
    {
        lock (_lock)
        {
            if (DateTime.Now - _lastRequest < TimeSpan.FromSeconds(1))
            {
                _requestCount++;
                if (_requestCount > 1000) // Example rate limit: 1000 requests per second
                    throw new RateLimitException("Rate limit exceeded");
            }
            else
            {
                _requestCount = 1;
                _lastRequest = DateTime.Now;
            }
        }

        // Simulate processing time based on data size
        await Task.Delay(dataSize / 1000); // Example: 1ms per KB of data
    }

    public void Dispose() { }
}

public class RateLimitException : Exception
{
    public RateLimitException(string message) : base(message) { }
}
