// Define error codes
enum class RecorderError {
    Success,
    DatabaseFailure,
    LogFileFailure,
    PaymentProcessorFailure
};

// Mock classes for different recorders
class DatabaseRecorder {
public:
    bool record(const std::string& message) {
        // Simulate database recording with potential failure
        if (rand() % 2 == 0) {
            return false; // Simulate failure
        }
        std::cout << "Database recorded: " << message << std::endl;
        return true;
    }
};

class LogFileRecorder {
public:
    bool record(const std::string& message, std::ofstream& logFile) {
        if (!logFile.is_open()) {
            return false; // Simulate failure
        }
        logFile << "Log recorded: " << message << std::endl;
        return true;
    }

    void openLogFile(std::ofstream& logFile, const std::string& filename) {
        logFile.open(filename, std::ios::app);
    }

    void closeLogFile(std::ofstream& logFile) {
        if (logFile.is_open()) {
            logFile.close();
        }
    }
};

class PaymentProcessorRecorder {
public:
    bool record(const std::string& message) {
        // Simulate payment processor recording with potential failure
        if (rand() % 2 == 0) {
            return false; // Simulate failure
        }
        std::cout << "Payment Processor recorded: " << message << std::endl;
        return true;
    }
};

// Transaction recorder class using the strategy pattern
class TransactionRecorder {
public:
    TransactionRecorder(DatabaseRecorder& db, LogFileRecorder& log, PaymentProcessorRecorder& payment)
        : dbRecorder(db), logRecorder(log), paymentRecorder(payment) {}

    RecorderError recordTransaction(const std::string& message) {
        if (dbRecorder.record(message)) {
            return RecorderError::Success;
        } else {
            return recordOnFallback(message);
        }
    }

private:
    DatabaseRecorder& dbRecorder;
    LogFileRecorder& logRecorder;
    PaymentProcessorRecorder& paymentRecorder;

    RecorderError recordOnFallback(const std::string& message) {
        if (logRecorder.record(message, logFile)) {
            return RecorderError::LogFileFailure;
        } else {
            if (paymentRecorder.record(message)) {
                return RecorderError::PaymentProcessorFailure;
            } else {
                return RecorderError::Success; // Fallback success
            }
        }
    }

    std::ofstream logFile;
};

int main() {
    DatabaseRecorder db;
    LogFileRecorder log;
    PaymentProcessorRecorder payment;

    TransactionRecorder recorder(db, log, payment);

    for (int i = 0; i < 5; ++i) {
        std::string message = "Transaction " + std::to_string(i);
        RecorderError result = recorder.recordTransaction(message);
        switch (result) {
            case RecorderError::Success:
                std::cout << "Transaction recorded successfully." << std::endl;
                break;
            case RecorderError::DatabaseFailure:
                std::cout << "Failed to record transaction, falling back to log file." << std::endl;
                break;
            case RecorderError::LogFileFailure:
                std::cout << "Failed to record transaction, falling back to payment processor." << std::endl;
                break;
            case RecorderError::PaymentProcessorFailure:
                std::cout << "Transaction recording failed on all fallback mechanisms." << std::endl;
                break;
        }
    }

    return 0;
}
