        return -1; // Memory allocation failed
    }
    *numNewStates = 5; // Simulated number of new states
    // Initialize new states...
    return 0; // Success
}

// Function to expand the state list in an FSA
FSA* expandStateList(State **currentList, int currentSize, FSA *fsa, void *externalData) {
    pthread_mutex_lock(&fsa->mutex);

    State *newStates = NULL;
    int numNewStates = 0;

    if (fetchDataFromExternalSource(&newStates, &numNewStates) != 0) {
        perror("Failed to fetch data from external source");
        pthread_mutex_unlock(&fsa->mutex);
        return fsa; // Return the original FSA on error
    }

    State *originalLastState = (*currentList + currentSize - 1);
    originalLastState->next = newStates;
    fsa->currentState->next = newStates; // Update the next pointer of the last state

    pthread_mutex_unlock(&fsa->mutex);

    return fsa; // Return the updated FSA
}

// Example usage
int main() {
    State *currentList = (State *)malloc(5 * sizeof(State));
    // Initialize current list...
    FSA *fsa = (FSA *)malloc(sizeof(FSA));
    pthread_mutex_init(&fsa->mutex, NULL);

    // Expand the state list
    expandStateList(&currentList, 5, fsa, NULL);

    // Clean up
    free(currentList);
    free(fsa);
    return 0;
}
