#include <forward_list>
#include <mutex>
#include <string>
#include <iostream>

class ForwardListUpdater {
private:
    std::forward_list<std::string> list;
    mutable std::mutex mutex;

public:
    void update(const std::string& search, const std::string& update) {
        std::lock_guard<std::mutex> lock(mutex);

        auto it = list.begin();
        for (; it != list.end(); ++it) {
            if (*it == search) {
                list.insert_after(it, update);
                return;
            }
        }

        list.push_back(update);
    }

    void printList() const {
        std::lock_guard<std::mutex> lock(mutex);
        for (const auto& item : list) {
            std::cout << item << " ";
        }
        std::cout << std::endl;
    }
};

int main() {
    ForwardListUpdater updater;
    updater.update("apple", "orange");
    updater.update("banana", "grape");
    updater.update("cherry", "plum");

    updater.printList();

    return 0;
}
```

This code provides a basic implementation of a thread-safe `ForwardListUpdater` class in C++. It uses a forward list to store strings and a mutex to ensure that the list can be accessed by multiple threads without causing data races. The `update` method inserts an update string after the first occurrence of a search string, or appends it to the end if the search string is not found. The `printList` method is used to print the current contents of the forward list.

