import org.springframework.stereotype.Service;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import reactor.core.publisher.Mono;

@Service
public class FileMd5Service {

    public Mono<String> computeMd5(String filePath) {
        return Mono.fromCallable(() -> Path.of(filePath))
                .flatMap(path -> {
                    if (!Files.exists(path)) {
                        throw new IllegalArgumentException("File does not exist: " + path);
                    }
                    if (!Files.isReadable(path)) {
                        throw new SecurityException("File is not readable: " + path);
                    }
                    return Mono.fromCallable(() -> Files.readAllBytes(path));
                })
                .flatMap(bytes -> {
                    try {
                        MessageDigest digest = MessageDigest.getInstance("MD5");
                        byte[] hash = digest.digest(bytes);
                        StringBuilder hexString = new StringBuilder();
                        for (byte b : hash) {
                            String hex = Integer.toHexString(0xff & b);
                            if (hex.length() == 1) hexString.append('0');
                            hexString.append(hex);
                        }
                        return Mono.just(hexString.toString());
                    } catch (NoSuchAlgorithmException e) {
                        throw new RuntimeException("MD5 algorithm not available", e);
                    }
                })
                .onErrorResume(e -> Mono.error(new ServiceUnavailableException("Failed to compute MD5 hash for file: " + filePath, e)));
    }
}
