import hashlib
import requests

def aggregate_files(file_paths):
    with open('aggregated_file', 'wb') as outfile:
        for file_path in file_paths:
            with open(file_path, 'rb') as infile:
                outfile.write(infile.read())
    return calculate_checksum('aggregated_file')

def validate_oauth2_token(json_str):
    try:
        data = json.loads(json_str)
        if not all(key in data for key in ['access_token', 'expires_in', 'token_type']):
            return False
        if data['token_type'] != 'Bearer':
            return False
        if not isinstance(data['expires_in'], int) or data['expires_in'] <= 0:
            return False
        return True
    except json.JSONDecodeError:
        return False

def calculate_checksum(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

# Example usage
file_paths = ['path/to/small/file1', 'path/to/small/file2']
checksum = aggregate_files(file_paths)
print(f'Checksum of aggregated file: {checksum}')

token_json = '{"access_token": "example_token", "expires_in": 3600, "token_type": "Bearer"}'
is_valid_token = validate_oauth2_token(token_json)
print(f'Is OAuth2 token valid? {is_valid_token}')
```

