        this.databaseClient = databaseClient;
        this.executorService = Executors.newFixedThreadPool(10);
    }

    public String getPokemonWeaknesses(Pokemon pokemon) {
        return executorService.submit(() -> {
            try {
                String weaknesses = apiClient.getWeaknesses(pokemon.getType()).get();
                String[] weaknessList = weaknesses.split(",");
                StringBuilder result = new StringBuilder("Weaknesses: ");
                for (String weakness : weaknessList) {
                    WeaknessData detail = databaseClient.fetchWeaknessDetails(weakness).get();
                    result.append(detail.getWeaknessName()).append(" (Strength: ").append(detail.getStrengthLevel())
                            .append(", Moves: ").append(String.join(", ", detail.getAssociatedMoves())).append(")");
                }
                return result.toString();
            } catch (Exception e) {
                // Fallback mechanism
                return "Fallback Weaknesses: Water, Grass";
            }
        }).join();
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
