const asyncReduce = async (array, initialValue, callback) => {
  let result = initialValue;

  for (let i = 0; i < array.length; i++) {
    try {
      const additionalData = await fetchAdditionalData(array[i]);
      const reducedValue = await callback(result, array[i], additionalData);
      result = reducedValue;
    } catch (error) {
      console.error(`Error processing element ${array[i]}:`, error);
    }
  }

  return result;
};

const fetchAdditionalData = async (number) => {
  // Simulate fetching data from an external API with rate limiting
  const response = await fetch(`https://api.example.com/data/${number}`, { method: 'GET' });
  if (!response.ok) {
    throw new Error(`API error for number ${number}: ${response.statusText}`);
  }
  return response.json();
};

