#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_FILENAME_LEN 256

typedef struct {
    CURL* curl_handle;
    char response[MAX_FILENAME_LEN];
} NamingConventionService;

NamingConventionService* createNamingConventionService() {
    NamingConventionService* service = (NamingConventionService*)malloc(sizeof(NamingConventionService));
    if (service) {
        service->curl_handle = curl_easy_init();
        if (!service->curl_handle) {
            free(service);
            return NULL;
        }
    }
    return service;
}

void destroyNamingConventionService(NamingConventionService* service) {
    if (service->curl_handle) {
        curl_easy_cleanup(service->curl_handle);
    }
    free(service);
}

int getFilenameFromService(const char* base_filename, NamingConventionService* service, char** filename) {
    CURLcode res;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    char request[256];
    snprintf(request, sizeof(request), "{\"filename\":\"%s\"}", base_filename);

    curl_easy_setopt(service->curl_handle, CURLOPT_URL, "https://naming-convention-service.com/getFilename");
    curl_easy_setopt(service->curl_handle, CURLOPT_POSTFIELDS, request);
    curl_easy_setopt(service->curl_handle, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(service->curl_handle, CURLOPT_WRITEFUNCTION, (curl_write_callback)strcpy);
    curl_easy_setopt(service->curl_handle, CURLOPT_WRITEDATA, service->response);

    res = curl_easy_perform(service->curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        return -1;
    }

    *filename = strdup(service->response);
    if (!*filename) {
        return -1;
    }

    curl_slist_free_all(headers);
    return 0;
}

void loadAndExecuteJSFiles(const char* base_filename, const char* js_files[], int num_files) {
    NamingConventionService* service = createNamingConventionService();
    if (!service) {
        fprintf(stderr, "Error: Failed to initialize naming convention service.\n");
        return;
    }

    for (int i = 0; i < num_files; i++) {
        char* new_filename = NULL;
        if (getFilenameFromService(js_files[i], service, &new_filename) != 0) {
            fprintf(stderr, "Error: Failed to get new filename for %s.\n", js_files[i]);
            continue;
        }

        // Load and execute the JavaScript file
        printf("Loading and executing %s\n", new_filename);

        // Free allocated memory
        free(new_filename);
    }

    destroyNamingConventionService(service);
}

int main() {
    const char* js_files[] = {"script1.js", "script2.js", "script3.js"};
    int num_files = sizeof(js_files) / sizeof(js_files[0]);

    loadAndExecuteJSFiles("base", js_files, num_files);

    return 0;
}
