<?php

class ClinicManager {
    private $database;
    private $weatherApi;
    private $patientSchedulingSystem;
    private $notificationService;
    private $supplyChainManagement;

    public function __construct($database, $weatherApi, $patientSchedulingSystem, $notificationService, $supplyChainManagement) {
        $this->database = $database;
        $this->weatherApi = $weatherApi;
        $this->patientSchedulingSystem = $patientSchedulingSystem;
        $this->notificationService = $notificationService;
        $this->supplyChainManagement = $supplyChainManagement;
    }

    public function handleClinicOperations($action, $data) {
        switch ($action) {
            case 'create':
                return $this->createClinicRecord($data);
            case 'update':
                return $this->updateClinicStatus($data['id'], $data['status'], $data['metadata']);
            case 'delete':
                return $this->deleteClinicRecord($data['id']);
            default:
                throw new Exception("Invalid operation");
        }
    }

    private function createClinicRecord($data) {
        // Validate name length
        if (strlen($data['name']) > 50) {
            throw new Exception(" Clinic name must be 50 characters or less.");
        }

        // Check for prohibited terms in clinic names
        $prohibitedTerms = ['forbidden', 'restricted'];
        if (array_intersect(array_map('strtolower', explode(' ', $data['name'])), array_map('strtolower', $prohibitedTerms))) {
            throw new Exception("Clinic name contains a prohibited term.");
        }

        // Check supply chain management system
        if (!$this->supplyChainManagement->hasNecessarySupplies($data)) {
            throw new Exception("Clinic does not have necessary supplies.");
        }

        // Create clinic record in the database
        $result = $this->database->insert('clinics', [
            'name' => $data['name'],
            'location' => $data['location'],
            'capacity' => $data['capacity'],
            'created_at' => date('Y-m-d H:i:s'),
            'updated_at' => date('Y-m-d H:i:s')
        ]);

        return ['status' => 'success', 'message' => 'Clinic record created successfully.'];
    }

    private function updateClinicStatus($id, $status, $metadata) {
        // Update clinic status in the database
        $result = $this->database->update('clinics', [
            'status' => $status,
            'last_modified_ip' => $_SERVER['REMOTE_ADDR'],
            'updated_at' => date('Y-m-d H:i:s')
        ], ['id' => $id]);

        if ($status === 'closed' || $status === 'emergency') {
            // Trigger weather API assessment
            $this->weatherApi->assessClosureRisk($id);

            // Update patient scheduling system
            $this->patientSchedulingSystem->clearAndRescheduleAppointments($id);

            // Send personalized emails to affected patients
            $patients = $this->database->select('appointments', ['patient_id'], ['clinic_id' => $id]);
            foreach ($patients as $patient) {
                $this->notificationService->sendPersonalizedEmail($patient['patient_id'], $status, $metadata);
            }
        }

        // Notify supply chain management system
        $this->supplyChainManagement->adjustSupplyLevels($id, $status);

        return ['status' => 'success', 'message' => 'Clinic status updated successfully.'];
    }

    private function deleteClinicRecord($id) {
        // Check if the clinic is currently in use
        $inUse = $this->database->select('appointments', '*', ['clinic_id' => $id]);
        if (!empty($inUse)) {
            throw new Exception("Cannot delete a clinic that is currently in use.");
        }

        // Delete clinic record from the database
        $result = $this->database->delete('clinics', ['id' => $id]);

        return ['status' => 'success', 'message' => 'Clinic record deleted successfully.'];
    }
}
