<?php

class AdvancedWebSecurityManager {
    private $password;
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
    private $cache = [];

    public function generateSecureRandomString($length, $characterSet) {
        if (!isset($this->cache[$characterSet])) {
            $this->validateCharacterSet($characterSet);
            $this->cache[$characterSet] = [];
        }

        if (isset($this->cache[$characterSet][$length])) {
            return $this->cache[$characterSet][$length];
        }

        $randomString = '';
        $maxIndex = strlen($characterSet) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characterSet[random_int(0, $maxIndex)];
        }

        $this->cache[$characterSet][$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        $salt = $this->generateSecureRandomString(22, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
        $this->password = password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($hashedPassword, $password) {
        return password_verify($password, $hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()]).+$/', $characterSet)) {
            return true;
        }

        throw new Exception("Invalid character set. Please include at least one uppercase letter, one lowercase letter, one digit, and one special character.");
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new Exception("Salt round count must be between 12 and 31.");
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $newCharacterSet = $this->generateSecureRandomString(4, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
        $this->hashPassword($newCharacterSet);
        $this->resetCache($this->characterSet);
        $this->characterSet = $newCharacterSet;
    }

    private function resetCache($oldCharacterSet) {
        if (isset($this->cache[$oldCharacterSet])) {
            unset($this->cache[$oldCharacterSet]);
        }
    }
}
