use reqwest::Error;

#[derive(Debug)]
enum HttpClientError {
    Reqwest(Error),
    Custom(String),
}

struct HttpClient {
    client: reqwest::Client,
}

impl HttpClient {
    fn new() -> Self {
        HttpClient {
            client: reqwest::Client::new(),
        }
    }

    async fn get(&self, url: &str) -> Result<String, HttpClientError> {
        match self.client.get(url).send().await {
            Ok(response) => response.text().await.map_err(HttpClientError::Reqwest),
            Err(e) => Err(HttpClientError::Custom(format!("Request failed: {}", e))),
        }
    }

    async fn post(&self, url: &str, body: String) -> Result<String, HttpClientError> {
        match self.client.post(url).body(body).send().await {
            Ok(response) => response.text().await.map_err(HttpClientError::Reqwest),
            Err(e) => Err(HttpClientError::Custom(format!("Request failed: {}", e))),
        }
    }

    // Add other methods for different HTTP methods as needed
}
