use reqwest::Error as ReqwestError;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::{
    sync::{Mutex, RwLock},
    task,
};
use redis::{Commands, ConnectionManager};

#[derive(Serialize, Deserialize)]
struct Config {
    weather_api_url: String,
    api_key: String,
    update_interval_secs: u64,
    cache_expiration_secs: u64,
}

async fn fetch_weather_data(url: &str, api_key: &str) -> Result<String, ReqwestError> {
    reqwest::get(format!("{}?apikey={}", url, api_key))
        .await?
        .text()
        .await
}

async fn update_weather_cache(
    config: Arc<Config>,
    cache_manager: ConnectionManager,
    weather_data: String,
) -> Result<(), redis::Error> {
    let mut conn = cache_manager.get_async().await?;
    conn.set_ex("weather_data", &weather_data, config.cache_expiration_secs).await?;
    Ok(())
}

async fn update_weather_task(
    config: Arc<Config>,
    cache_manager: ConnectionManager,
) {
    loop {
        if let Err(e) = task::spawn(async move {
            match fetch_weather_data(&config.weather_api_url, &config.api_key).await {
                Ok(data) => update_weather_cache(config.clone(), cache_manager.clone(), data).await,
                Err(_) => log::error!("Failed to fetch weather data"),
            }
        })
        .await {
            log::error!("Failed to spawn task: {:?}", e);
        }

        tokio::time::sleep(tokio::time::Duration::from_secs(config.update_interval_secs)).await;
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Load configuration from JSON file
    let config: Config = serde_json::from_str(include_str!("config.json"))?;

    // Initialize Redis connection manager
    let cache_manager = redis::Client::open("redis://127.0.0.1/")?.get_async_manager();

    // Start background task for updating weather cache
    tokio::spawn(update_weather_task(Arc::new(config.clone()), cache_manager.clone()));

    // Simulate handling incoming requests
    let mut last_fetch = tokio::time::Instant::now();
    loop {
        if last_fetch.elapsed().as_secs() >= config.update_interval_secs {
            last_fetch = tokio::time::Instant::now();

            // Fetch and display weather data
            match cache_manager.get_async::<_, String>("weather_data").await? {
                Some(data) => println!("Fetched Weather Data: {}", data),
                None => log::warn!("No weather data in cache"),
            }
        }

        tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
    }
}
