public class ImageLoader {
    private ExecutorService executor = Executors.newFixedThreadPool(10);
    private HashMap<String, String> cache = new HashMap<>();

    public void loadImage(String imageUrl) {
        if (cache.containsKey(imageUrl)) {
            // Serve image from cache
            System.out.println("Serving image from cache: " + imageUrl);
        } else {
            executor.submit(() -> downloadAndCacheImage(imageUrl));
        }
    }

    private void downloadAndCacheImage(String imageUrl) {
        try {
            // Simulate network request and image download
            String image = simulateNetworkRequest(imageUrl);
            cache.put(imageUrl, image);
            System.out.println("Cached new image: " + imageUrl);
        } catch (Exception e) {
            handleDownloadFailure(imageUrl);
        }
    }

    private String simulateNetworkRequest(String url) throws Exception {
        // Simulate network delay
        Thread.sleep(1000);
        return "Image data";
    }

    private void handleDownloadFailure(String imageUrl) {
        System.out.println("Failed to load image: " + imageUrl);
        // Implement fallback logic here (e.g., display placeholder)
