class BibleTextAnalyzer {
  constructor() {
    this.oldTestamentBooks = ['Genesis', 'Exodus', /*...*/];
    this.newTestamentBooks = ['Matthew', 'Mark', /*...*/];
    this.bookRegex = /^(Old|New) Testament$/i;
    this.bookNameRegex = /\b(?:Old|New)\s+Testament\s+(?:and)?\s*(\w+)\b/gi;
    this.cache = {};
  }

  analyzeText(text) {
    if (typeof text !== 'string' || !text.trim()) {
      throw new Error('Invalid input: Please provide a non-empty string.');
    }

    const bookOccurrences = {};
    let match;

    while ((match = this.bookNameRegex.exec(text)) !== null) {
      const bookName = match[1];
      if (this.oldTestamentBooks.includes(bookName) || this.newTestamentBooks.includes(bookName)) {
        bookOccurrences[bookName] = (bookOccurrences[bookName] || 0) + 1;
      }
    }

    return { text, bookOccurrences };
  }

  categorizeBooks(occurrences) {
    const categorizedBooks = {
      oldTestament: {},
      newTestament: {}
    };

    for (const [book, count] of Object.entries(occurrences)) {
      if (this.oldTestamentBooks.includes(book)) {
        categorizedBooks.oldTestament[book] = count;
      } else if (this.newTestamentBooks.includes(book)) {
        categorizedBooks.newTestament[book] = count;
      }
    }

    return categorizedBooks;
  }
}

// Example usage:
const analyzer = new BibleTextAnalyzer();
const result = analyzer.analyzeText('In the New Testament, Jesus said "Love thy neighbor."');
console.log(analyzer.categorizeBooks(result.bookOccurrences));
