import random
from neo4j import GraphDatabase

class GraphMethod:
    def __init__(self, uri, user, password):
        self.driver = GraphDatabase.driver(uri, auth=(user, password))

    def close(self):
        self.driver.close()

    def add_random_elements(self, num_vertices, num_edges):
        with self.driver.session() as session:
            try:
                session.write_transaction(self._add_random_nodes, num_vertices)
                session.write_transaction(self._add_random_relationships, num_edges)
                print(f"Added {num_vertices} vertices and {num_edges} edges successfully.")
            except Exception as e:
                print(f"Failed to add random elements: {e}")

    def remove_random_elements(self, num_vertices, num_edges):
        with self.driver.session() as session:
            try:
                session.write_transaction(self._remove_random_nodes, num_vertices)
                session.write_transaction(self._remove_random_relationships, num_edges)
                print(f"Removed {num_vertices} vertices and {num_edges} edges successfully.")
            except Exception as e:
                print(f"Failed to remove random elements: {e}")

    @staticmethod
    def _add_random_nodes(tx, num_vertices):
        for _ in range(num_vertices):
            node_id = random.randint(1000, 9999)
            properties = {
                'name': f'Node{node_id}',
                'value': random.uniform(0.0, 1.0),
                'timestamp': datetime.datetime.now()
            }
            tx.run("CREATE (n:RandomNode {id: $id, name: $name, value: $value, timestamp: $timestamp})", id=node_id, **properties)

    @staticmethod
    def _add_random_relationships(tx, num_edges):
        for _ in range(num_edges):
            node1_id = random.randint(1000, 9998)
            node2_id = random.randint(node1_id+1, 9999)
            properties = {
                'weight': random.uniform(0.5, 2.0),
                'timestamp': datetime.datetime.now()
            }
            tx.run("MATCH (n1:RandomNode {id: $node1}), (n2:RandomNode {id: $node2}) CREATE (n1)-[:CONNECTED_TO {weight: $weight, timestamp: $timestamp}]->(n2)", node1=node1_id, node2=node2_id, **properties)

    @staticmethod
    def _remove_random_nodes(tx, num_vertices):
        for _ in range(num_vertices):
            node_id = random.randint(1000, 9999)
            tx.run("MATCH (n:RandomNode {id: $node_id}) DELETE n", node_id=node_id)

    @staticmethod
    def _remove_random_relationships(tx, num_edges):
        for _ in range(num_edges):
            relationship = tx.run("MATCH ()-[r:CONNECTED_TO]->() RETURN r ORDER BY rand() LIMIT 1").single()
            if relationship:
                tx.run("MATCH ()-[r:CONNECTED_TO]->() DELETE r")
