// Import necessary libraries
import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import android.graphics.Bitmap;
import android.os.AsyncTask;
import android.util.Log;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.URL;
import javax.imageio.ImageIO;

public class ThemeCacheManager {
    private static final String TAG = "ThemeCacheManager";
    private Context context;
    private SQLiteDatabase database;
    private String defaultThemeDir;
    private Bitmap currentThemeBitmap;

    public ThemeCacheManager(Context context, SQLiteDatabase database) {
        this.context = context;
        this.database = database;
        this.defaultThemeDir = "/sdcard/DefaultTheme/";
    }

    public void setDefaultThemeDirectory(String directory) {
        if (directory != null && !directory.isEmpty()) {
            this.defaultThemeDir = directory;
        }
    }

    public void cacheThemeBasedOnUserPreference(int themeId) {
        String themeName = getThemeNameFromDatabase(themeId);
        if (themeName != null) {
            cacheTheme(themeName);
        } else {
            Log.e(TAG, "Theme not found for ID: " + themeId);
        }
    }

    private String getThemeNameFromDatabase(int themeId) {
        // Query the database to fetch the theme name based on themeId
        // This is a placeholder for actual database query logic
        return "theme_" + themeId;
    }

    private void cacheTheme(String themeName) {
        File themeFile = new File(defaultThemeDir, themeName + ".png");
        if (!themeFile.exists()) {
            downloadAndCacheImage(themeName);
        } else {
            currentThemeBitmap = loadBitmapFromDisk(themeFile.getAbsolutePath());
        }
    }

    private void downloadAndCacheImage(String themeName) {
        try {
            new ImageDownloader().execute(themeName);
        } catch (Exception e) {
            Log.e(TAG, "Error downloading image", e);
        }
    }

    private Bitmap loadBitmapFromDisk(String filePath) {
        try {
            return BitmapFactory.decodeFile(filePath);
        } catch (OutOfMemoryError e) {
            Log.e(TAG, "Out of memory while loading bitmap", e);
            return null;
        }
    }

    private void saveBitmapToDisk(Bitmap bitmap, String filePath) throws IOException {
        FileOutputStream fos = new FileOutputStream(filePath);
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, fos);
        fos.close();
    }

    public class ImageDownloader extends AsyncTask<String, Void, Bitmap> {
        @Override
        protected Bitmap doInBackground(String... themeNames) {
            String themeName = themeNames[0];
            try {
                URL url = new URL("http://example.com/themes/" + themeName + ".png");
                Bitmap bitmap = ImageIO.read(url);
                saveBitmapToDisk(bitmap, defaultThemeDir + themeName + ".png");
                return bitmap;
            } catch (IOException e) {
                Log.e(TAG, "Error downloading image", e);
                return null;
            }
        }

        @Override
        protected void onPostExecute(Bitmap result) {
            if (result != null) {
                currentThemeBitmap = result;
            }
        }
    }

    public void clearCache() {
        File cacheDir = new File(defaultThemeDir);
        deleteRecursive(cacheDir);
        currentThemeBitmap = null;
    }

    private boolean deleteRecursive(File fileOrDirectory) {
        if (fileOrDirectory.isDirectory()) {
            for (File child : fileOrDirectory.listFiles()) {
                deleteRecursive(child);
            }
        }
        return fileOrDirectory.delete();
    }
}
