        self.storage_services = storage_services
        self.validation_service = validation_service

    def add_file(self, file_path, bucket_name, storage_type='S3'):
        service = self.get_storage_service(storage_type)
        if not service:
            raise ValueError("Unsupported storage type")

        try:
            service.upload_file(file_path, bucket_name)
            checksum = self.calculate_checksum(file_path)
            self.validation_service.validate_data(file_path, checksum)
        except Exception as e:
            print(f"Failed to add file: {e}")

    def calculate_checksum(self, file_path, algorithm='sha256'):
        hash_obj = hashlib.new(algorithm)
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hash_obj.update(chunk)
        return hash_obj.hexdigest()

    def get_storage_service(self, storage_type):
        service_map = {
            'S3': AWSS3(),
            'GCS': GoogleCloudStorage(),
            'Azure': AzureBlobStorage()
        }
