import os
import threading
import time
from concurrent.futures import ThreadPoolExecutor, as_completed

def merge_files(file_paths, dest_path, buffer_size=1024*1024, max_retries=5, backoff_factor=2):
    def read_file_chunk(file_path, start, end, retries=0):
        while retries < max_retries:
            try:
                with open(file_path, 'rb') as f:
                    f.seek(start)
                    return f.read(end - start)
            except IOError as e:
                if retries >= max_retries:
                    raise
                time.sleep(backoff_factor ** retries)
                retries += 1

    def write_file_chunk(dest_path, data, retries=0):
        while retries < max_retries:
            try:
                with open(dest_path, 'ab') as f:
                    f.write(data)
                break
            except IOError as e:
                if retries >= max_retries:
                    raise
                time.sleep(backoff_factor ** retries)
                retries += 1

    def merge_file_segment(segment):
        start, end = segment
        data = read_file_chunk(file_paths[0], start, end)
        write_file_chunk(dest_path, data)

    file_sizes = [os.path.getsize(path) for path in file_paths]
    total_size = sum(file_sizes)
    segments = [(0, 0)] * len(file_paths)

    with ThreadPoolExecutor(max_workers=len(file_paths)) as executor:
        futures = {executor.submit(merge_file_segment, segment): segment for segment in segments}
        for future in as_completed(futures):
            segment = futures[future]
            try:
                start, end = segment
                next_start = end + os.path.getsize(file_paths[file_paths.index(segment[0])+1])
                segments[file_paths.index(segment[0]) + 1] = (next_start, next_start)
                print(f"Merged segment: {segment} - Progress: {(sum([x[1] for x in segments]) / total_size) * 100:.2f}%")
            except Exception as e:
                print(f"Failed to merge segment: {segment} - Error: {e}")

    print("Merging complete.")
```
This code block provides a solution to the described problem. It includes functions for reading and writing file chunks, merging segments of files in parallel using multiple threads, handling I/O errors with retries, and logging progress. The implementation ensures minimal memory usage, proper resource management, and support for large files by breaking them into smaller segments before merging.

