import jwt
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives import hashes
import requests

# Constants and configuration files
SECRET_KEY = "your_secret_key"
PUBLIC_KEY_PATH = "path_to_public_key.pem"
AUTH_API_URL = "https://auth-service.com/validate"

def load_public_key():
    with open(PUBLIC_KEY_PATH, "rb") as key_file:
        public_key = serialization.load_pem_public_key(key_file.read())
    return public_key

def verify_jwt_signature(token):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
        return payload
    except jwt.ExpiredSignatureError:
        raise ValueError("JWT signature has expired")
    except jwt.InvalidTokenError:
        raise ValueError("Invalid JWT token")

def decrypt_rsa_payload(payload):
    public_key = load_public_key()
    try:
        decrypted_data = public_key.decrypt(
            base64.b64decode(payload),
            padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None
            )
        )
        return decrypted_data.decode('utf-8')
    except Exception as e:
        raise ValueError("Failed to decrypt RSA payload") from e

def validate_payload(decrypted_payload):
    data = json.loads(decrypted_payload)
    # Add your validation rules here (e.g., expiration date, claim values)
    if "exp" in data and datetime.datetime.utcnow() > datetime.datetime.fromtimestamp(data["exp"]):
        raise ValueError("Token has expired")
    if data.get("claim") != "expected_value":
        raise ValueError("Invalid claim value")

def process_jwt_batch(jwt_tokens):
    results = []
    for token in jwt_tokens:
        try:
            verified_payload = verify_jwt_signature(token)
            decrypted_data = decrypt_rsa_payload(verified_payload["payload"])
            validate_payload(decrypted_data)
            # Validate claims and additional metadata from external service
            response = requests.post(AUTH_API_URL, json={"data": decrypted_data})
            if response.status_code == 200:
                results.append({"token": token, "status": "valid"})
            else:
                raise ValueError("External validation failed")
        except Exception as e:
            results.append({"token": token, "error": str(e)})
    return results
