import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.lang3.exception.ExceptionUtils;

import java.io.InputStream;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class JsonParser {
    private static final Logger logger = Logger.getLogger(JsonParser.class.getName());
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private ConcurrentHashMap<String, JsonNode> cache = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public JsonParser() {
        // Start background cleanup thread
        scheduler.scheduleAtFixedRate(this::cleanupCache, 60, 60, TimeUnit.MINUTES);
    }

    public void parseJson(InputStream inputStream) {
        try {
            JsonNode rootNode = objectMapper.readTree(inputStream);
            cache.putIfAbsent("root", rootNode);
        } catch (Exception e) {
            logger.severe("Failed to parse JSON: " + ExceptionUtils.getStackTrace(e));
        }
    }

    public JsonNode extractData(String path) {
        if (!cache.containsKey(path)) {
            throw new RuntimeException("Path not found in cache: " + path);
        }
        return cache.get(path);
    }

    private void cleanupCache() {
        long currentTime = System.currentTimeMillis();
        for (String key : cache.keySet()) {
            JsonNode node = cache.get(key);
            if ((currentTime - node.path("lastAccessTime").asLong()) > TimeUnit.HOURS.toMillis(1)) {
                cache.remove(key, node);
            }
        }
    }

    public void validateJson(JsonNode node, String schema) {
        // Implement JSON schema validation logic
    }

    public static void main(String[] args) {
        JsonParser parser = new JsonParser();
        // Simulate parsing a large JSON stream
        InputStream inputStream = ...; // Get input stream from message queue or API
        parser.parseJson(inputStream);

        try {
            JsonNode data = parser.extractData("path.to.data");
            parser.validateJson(data, "schema.json");
        } catch (Exception e) {
            logger.severe(e.getMessage());
        }
    }
}
```

