```java
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import redis.clients.jedis.Jedis;

public class DirectoryProcessor {

    private static final Logger logger = LoggerFactory.getLogger(DirectoryProcessor.class);
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private Jedis jedis = new Jedis("localhost");
    private RateLimiter rateLimiter;

    public DirectoryProcessor(RateLimiter rateLimiter) {
        this.rateLimiter = rateLimiter;
    }

    public String processDirectoryContents(String directoryPath, String fileExtension, String encoding)
            throws IOException, InterruptedException {
        if (directoryPath == null || directoryPath.length() > 1000) {
            throw new IllegalArgumentException("Invalid directory path");
        }

        if (!rateLimiter.tryAcquire()) {
            throw new RuntimeException("Rate limit exceeded");
        }

        String cachedResult = cache.get(directoryPath);
        if (cachedResult != null) {
            logger.info("Using cached result for directory: {}", directoryPath);
            return cachedResult;
        }

        Future<String> future = executorService.submit(() -> readFilesFromDirectory(directoryPath, fileExtension, encoding));
        String result = future.get();
        cache.put(directoryPath, result);

        jedis.set(directoryPath, result);
        logger.info("Processed directory: {} with content length: {}", directoryPath, result.length());

        return result;
    }

    private String readFilesFromDirectory(String directoryPath, String fileExtension, String encoding) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(Paths.get(directoryPath), "*." + fileExtension)) {
            for (Path file : stream) {
                sb.append(readFileContent(file.toAbsolutePath().toString(), encoding));
            }
        }
        return sb.toString();
    }

    private String readFileContent(String filePath, String encoding) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(filePath), java.nio.charset.Charset.forName(encoding))) {
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                contentBuilder.append(line).append("\n");
            }
            return contentBuilder.toString();
        } catch (UnsupportedCharsetException e) {
            logger.warn("Unsupported encoding: {}", encoding);
            throw new IOException("Encoding not supported", e);
        }
    }

    public String getSHA256(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes());
            return bytesToHex(hashBytes);
        } catch (Exception e) {
            logger.error("Error generating SHA-256 hash", e);
            return null;
        }
    }

    public String getMD5(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            return bytesToHex(hashBytes);
        } catch (Exception e) {
            logger.error("Error generating MD5 hash", e);
            return null;
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public void shutdown() {
        executorService.shutdown();
        jedis.close();
    }

    public static class RateLimiter {
        private final Semaphore semaphore;

        public RateLimiter(int permitsPerSecond) {
            this.semaphore = new Semaphore(permitsPerSecond, true);
        }

        public boolean tryAcquire() {
            return semaphore.tryAcquire();
        }
    }
}
