using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;
using Newtonsoft.Json; // Ensure Newtonsoft.Json package is installed via NuGet

public class DataHandler
{
    private readonly ILoggingService _loggingService;
    private readonly IConfigurationManager _configurationManager;

    public DataHandler(ILoggingService loggingService, IConfigurationManager configurationManager)
    {
        _loggingService = loggingService;
        _configurationManager = configurationManager;
    }

    public async Task<T> LoadDataAsync<T>(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
        {
            throw new ArgumentException("File path cannot be null or empty", nameof(filePath));
        }

        var format = _configurationManager.GetSerializationFormat();
        try
        {
            switch (format.ToLower())
            {
                case "binary":
                    return await LoadDataBinaryAsync<T>(filePath);
                case "json":
                    return await LoadDataJsonAsync<T>(filePath);
                default:
                    throw new InvalidOperationException("Unsupported serialization format");
            }
        }
        catch (Exception ex)
        {
            _loggingService.LogError($"Error loading data from {filePath}: {ex.Message}");
            throw;
        }
    }

    private async Task<T> LoadDataBinaryAsync<T>(string filePath)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 4096, useAsync: true))
        {
            var formatter = new BinaryFormatter();
            return (T)formatter.Deserialize(await Task.Run(() => fileStream));
        }
    }

    private async Task<T> LoadDataJsonAsync<T>(string filePath)
    {
        using (var reader = File.OpenText(filePath))
        {
            var jsonSerializerSettings = new JsonSerializerSettings
            {
                TypeNameHandling = TypeNameHandling.Auto,
                Formatting = Formatting.None
            };

            return await Task.Run(() => JsonConvert.DeserializeObject<T>(await reader.ReadToEndAsync(), jsonSerializerSettings));
        }
    }
}

public interface ILoggingService
{
    void LogError(string message);
}

public interface IConfigurationManager
{
    string GetSerializationFormat();
}
