// Function to convert images to PDF using a third-party tool
const { spawn } = require('child_process');

async function convertImagesToPDF(imageDir, outputPath) {
    return new Promise((resolve, reject) => {
        const semaphore = semver.Semaphore.create(1);
        semaphore.take(() => {
            try {
                const process = spawn('third_party_tool', [imageDir, outputPath]);
                process.on('close', (code) => {
                    if (code === 0) {
                        resolve();
                    } else {
                        reject(new Error(`Conversion failed with code ${code}`));
                    }
                    semaphore.leave();
                });
                process.stderr.on('data', (data) => {
                    console.error(`stderr: ${data}`);
                    reject(new Error(data.toString().trim()));
                });
            } catch (err) {
                semaphore.leave();
                reject(err);
            }
        });
    });
}

// Endpoint to trigger image conversion
app.post('/convert-to-pdf', async (req, res) => {
    const { imagesDir, outputPath } = req.body;
    try {
        await convertImagesToPDF(imagesDir, outputPath);
        res.status(200).send('Conversion successful');
    } catch (err) {
        console.error('Error converting images to PDF:', err);
        res.status(500).send('Internal Server Error');
    }
});

// Route to handle HTTP requests
app.get('/', (req, res) => {
    res.send('Hello World!');
});

// Start server
async function startServer() {
    await initDatabase();
    app.listen(3000, () => {
        console.log('Microservice is running on port 3000');
    });
}

startServer();

// Error handling middleware
app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).send('Something broke!');
});
