// Mock structure definitions and mock database system setup
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createNFAPIList(int n) {
    if (n <= 0) {
        printf("Invalid number of elements: %d\n", n);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    int crcFlag = 0;
    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random tag
        list[i].RNTI = rand() % 256; // Random RNTI
        do {
            crcFlag = rand() % 3; // Random CRC flag (assuming 0, 1, or 2)
        } while (findCRCFlag(list, i - 1, crcFlag) != -1); // Ensure uniqueness
        list[i].CRC_INDICATION_REL8_TAG = crcFlag;
    }

    printf("NFAPI list created successfully with %d elements\n", n);
    return list;
}

int findCRCFlag(NFAPI_CRC_INDICATION_PDU_T* list, int index, int crcFlag) {
    for (int i = 0; i < index; i++) {
        if (list[i].CRC_INDICATION_REL8_TAG == crcFlag) {
            return i;
        }
    }
    return -1;
}

// Main function to demonstrate the usage of createNFAPIList
int main() {
    int n = 100000;
    NFAPI_CRC_INDICATION_PDU_T* list = createNFAPIList(n);
    if (list) {
        free(list); // Clean up allocated memory
    }
    return 0;
}
