import java.io.*;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;

public class StateFetcher {

    private static final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();

    public MoSTState fetchAndProcessState(String filePath) throws DFSClientNotAvailableException, NetworkConnectivityException, ClassLoadingException {
        try {
            // Check if the state object is already cached
            MoSTState cachedState = cache.get(filePath);
            if (cachedState != null) {
                return cachedState;
            }

            // Fetch and deserialize the state object from the file path
            ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath));
            Object obj = ois.readObject();
            ois.close();

            // Check if the deserialized object is an instance of MoSTState
            if (obj instanceof MoSTState) {
                MoSTState state = (MoSTState) obj;
                // Cache the state object for future use
                cache.put(filePath, state);
                return state;
            } else {
                return null;
            }
        } catch (IOException e) {
            throw new NetworkConnectivityException("Failed to read file due to network issues", e);
        } catch (ClassNotFoundException | InvalidClassException | SecurityException e) {
            throw new ClassLoadingException("Failed to load class for deserialization", e);
        }
    }

    // Custom exceptions for better error handling
    public static class DFSClientNotAvailableException extends Exception {
        public DFSClientNotAvailableException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    public static class NetworkConnectivityException extends Exception {
        public NetworkConnectivityException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    public static class ClassLoadingException extends Exception {
        public ClassLoadingException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
