import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class CacheManager {

    private static final Logger logger = LoggerFactory.getLogger(CacheManager.class);
    private ConcurrentHashMap<String, Object> cache;
    private AtomicInteger hitCount = new AtomicInteger(0);
    private AtomicInteger missCount = new AtomicInteger(0);
    private AtomicInteger evictionCount = new AtomicInteger(0);

    public CacheManager(int initialCapacity) {
        this.cache = new ConcurrentHashMap<>(initialCapacity);
    }

    public Object get(String key) {
        if (cache.containsKey(key)) {
            hitCount.incrementAndGet();
            return cache.get(key);
        } else {
            missCount.incrementAndGet();
            return null;
        }
    }

    public void put(String key, Object value) {
        cache.put(key, value);
    }

    public void remove(String key) {
        if (cache.remove(key) != null) {
            evictionCount.incrementAndGet();
        }
    }

    public void clear() {
        cache.clear();
    }

    public int getHitCount() {
        return hitCount.get();
    }

    public int getMissCount() {
        return missCount.get();
    }

    public int getEvictionCount() {
        return evictionCount.get();
    }

    // Additional methods for custom caching algorithm, evictions, and logging
}
```

