import os
import json
import time
from abc import ABC, abstractmethod
import threading

# Configuration class to manage runtime settings
class Config:
    def __init__(self):
        self.db_config = json.loads(os.getenv('DB_CONFIG', '{}'))
        self.log_file_path = os.getenv('LOG_FILE_PATH', 'transactions.log')
        self.payment_processor = os.getenv('PAYMENT_PROCESSOR', 'default')

# Abstract base class for different recording strategies
class RecordingStrategy(ABC):
    @abstractmethod
    def record(self, transaction_data):
        pass

# Database recording strategy
class DBRecordingStrategy(RecordingStrategy):
    def record(self, transaction_data):
        # Simulate database insertion
        print(f"Recording to database: {transaction_data}")

# Log file recording strategy
class LogFileRecordingStrategy(RecordingStrategy):
    def __init__(self, log_file_path):
        self.log_file_path = log_file_path

    def record(self, transaction_data):
        # Simulate log file writing
        with open(self.log_file_path, 'a') as file:
            file.write(f"Recording to log: {transaction_data}\n")

# Payment processor interface
class PaymentProcessor(ABC):
    @abstractmethod
    def process_payment(self, transaction_data):
        pass

# Default payment processor
class DefaultPaymentProcessor(PaymentProcessor):
    def process_payment(self, transaction_data):
        # Simulate successful payment processing
        print(f"Processing payment: {transaction_data}")

# External payment processor (placeholder)
class ExternalPaymentProcessor(PaymentProcessor):
    def process_payment(self, transaction_data):
        # Simulate external payment processing
        print(f"Processing payment with external system: {transaction_data}")

# Transaction recorder class
class TransactionRecorder:
    def __init__(self, config: Config):
        self.config = config
        self.recording_strategy: RecordingStrategy = None
        self.payment_processor: PaymentProcessor = None

        self._initialize_recording_strategy()
        self._initialize_payment_processor()

    def _initialize_recording_strategy(self):
        if self.config.db_config:
            self.recording_strategy = DBRecordingStrategy()
        else:
            self.recording_strategy = LogFileRecordingStrategy(self.config.log_file_path)

    def _initialize_payment_processor(self):
        if self.config.payment_processor == 'default':
            self.payment_processor = DefaultPaymentProcessor()
        elif self.config.payment_processor == 'external':
            self.payment_processor = ExternalPaymentProcessor()

    def record_transaction(self, transaction_data):
        try:
            # Simulate payment processing
            self.payment_processor.process_payment(transaction_data)

            # Record the transaction
            self.recording_strategy.record(transaction_data)
        except Exception as e:
            print(f"Error recording transaction: {e}")

# Example usage
if __name__ == "__main__":
    config = Config()
    recorder = TransactionRecorder(config)

    transaction_data = {"amount": 100, "currency": "USD", "card_number": "1234-5678-9012-3456"}
    recorder.record_transaction(transaction_data)
```

