            // Perform decryption asynchronously using the selected algorithm and key/IV
            byte[] decryptedBytes = await DecryptAsync(encryptedMessage, cryptoProvider, key, iv);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            AuditLog(sourceId, clearanceLevel, cryptoProvider.Algorithm, false, ex.Message);
            throw;
        }
        finally
        {
            _stopwatch.Stop();
            AuditLog(sourceId, clearanceLevel, cryptoProvider.Algorithm, true, null);
            MonitorEnter(_lockObject);
            try
            {
                _concurrentOperations--;
                if (_concurrentOperations < 0)
                    _concurrentOperations = 0;
            }
            finally
            {
                MonitorExit(_lockObject);
            }
        }
    }

    private ICryptoServiceProvider CreateCryptoServiceProvider(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "tripledes":
                return new TripleDESCryptoServiceProvider();
            case "aes":
                return new AesCryptoServiceProvider();
            case "rsa":
                return new RSACryptoServiceProvider();
