public class SecureDataProcessorConfigurationSection : ConfigurationSection
{
    [ConfigurationProperty("CryptoProviders", IsDefaultCollection = false)]
    public CryptoProviderElementCollection CryptoProviders
    {
        get { return (CryptoProviderElementCollection)this["CryptoProviders"]; }
    }
}

[ConfigurationCollection(typeof(CryptoProviderElement))]
public class CryptoProviderElementCollection : ConfigurationElementCollection
{
    protected override ConfigurationElement CreateNewElement()
    {
        return new CryptoProviderElement();
    }

    protected override object GetElementKey(ConfigurationElement element)
    {
        return ((CryptoProviderElement)element).Name;
    }
}

public class CryptoProviderElement : ConfigurationElement
{
    [ConfigurationProperty("Name", IsRequired = true)]
    public string Name
    {
        get { return (string)this["Name"]; }
        set { this["Name"] = value; }
    }

    [ConfigurationProperty("Algorithm", IsRequired = true)]
    public string Algorithm
    {
        get { return (string)this["Algorithm"]; }
        set { this["Algorithm"] = value; }
    }
}
