<?php

// Configuration loader class
class ConfigLoader {
    private $cmsUrl;
    private $fallbackPath;
    private $cacheKey = 'app_config';
    private $cacheTtl = 3600; // 1 hour in seconds
    private $cmsInstances;

    public function __construct($cmsUrl, $fallbackPath, array $cmsInstances) {
        $this->cmsUrl = $cmsUrl;
        $this->fallbackPath = $fallbackPath;
        $this->cmsInstances = $cmsInstances;
    }

    public function loadConfig() {
        if ($config = $this->getCachedConfig()) {
            return $config;
        }

        foreach ($this->cmsInstances as $instance) {
            try {
                $response = file_get_contents($instance);
                if ($response !== false) {
                    $this->cacheConfig($response);
                    return json_decode($response, true);
                }
            } catch (Exception $e) {
                // Log CMS instance failure
                error_log("CMS instance {$instance} failed: " . $e->getMessage());
            }
        }

        // Fallback to local file if all CMS instances fail
        if (file_exists($this->fallbackPath)) {
            return json_decode(file_get_contents($this->fallbackPath), true);
        } else {
            throw new Exception("Failed to load configuration from any source.");
        }
    }

    private function getCachedConfig() {
        $cache = file_get_contents('config_cache.json');
        if ($cache && (time() - json_decode($cache)->timestamp) < $this->cacheTtl) {
            return json_decode($cache)->data;
        }
        return null;
    }

    private function cacheConfig($data) {
        file_put_contents('config_cache.json', json_encode([
            'data' => $data,
            'timestamp' => time()
        ]));
    }
}

// Usage
$configLoader = new ConfigLoader(
    'https://cms.example.com/config',
    '/path/to/local/fallback_config.json',
    ['https://cms1.example.com/config', 'https://cms2.example.com/config']
);
$appConfig = $configLoader->loadConfig();
