```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureMessageProcessor {
    private Aes _aesAlg;
    private ICspProvider _cspProvider;
    private string _masterKey;
    private int _keyRotationInterval = 86400; // 24 hours in seconds
    private TimeSpan _retryDelay = TimeSpan.FromSeconds(5);
    private string _errorLogPath;
    private string _auditLogPath;

    public SecureMessageProcessor(ICspProvider cspProvider, string masterKey, string errorLogPath, string auditLogPath) {
        _cspProvider = cspProvider;
        _masterKey = masterKey;
        _errorLogPath = errorLogPath;
        _auditLogPath = auditLogPath;
        InitializeAes();
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId) {
        try {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            string decryptionKey = DeriveKey(contextId);
            byte[] decryptedBytes = await _cspProvider.Decrypt(encryptedBytes, decryptionKey);
            return Encoding.UTF8.GetString(decryptedBytes);
        } catch (Exception ex) {
            LogError(ex.Message);
            throw;
        }
    }

    private void InitializeAes() {
        _aesAlg = Aes.Create();
        _aesAlg.KeySize = 256;
    }

    private string DeriveKey(string contextId) {
        byte[] salt = Encoding.UTF8.GetBytes(contextId);
        byte[] derivedBytes = new Rfc2898DeriveBytes(_masterKey, salt).GetBytes(32);
        return Convert.ToBase64String(derivedBytes);
    }

    private async Task RetryDecryptionAsync(string base64EncodedMessage, string contextId) {
        for (int attempt = 0; attempt < 5; attempt++) {
            try {
                await DecryptMessageAsync(base64EncodedMessage, contextId);
                return;
            } catch (Exception ex) {
                LogError($"Failed decryption attempt {attempt + 1}: " + ex.Message);
                await Task.Delay(_retryDelay);
            }
        }
        throw new Exception("All retry attempts failed.");
    }

    private void LogError(string message) {
        File.AppendAllText(_errorLogPath, DateTime.Now.ToString() + " - " + message + Environment.NewLine);
    }

    // Additional methods for key rotation and auditing logs
}
