#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define constants for maximum number of concurrent readers/writers, buffer size etc.
#define MAX_CONCURRENT_ACCESS 100
#define BUFFER_SIZE 256

// Structure to hold data source and shared resources
typedef struct {
    int* buffer;
    int bufferSize;
    int writeIndex;
    int readIndex;
    pthread_mutex_t mutex;
    pthread_cond_t condVar;
} DataSource;

// Function prototypes
void* dataSourceReader(void*);
int findLargestInteger(DataSource* dataSource);

int main() {
    DataSource dataSource = {NULL, BUFFER_SIZE, 0, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

    // Initialize data source buffer
    dataSource.buffer = (int*)malloc(dataSource.bufferSize * sizeof(int));
    if (!dataSource.buffer) {
        fprintf(stderr, "Failed to allocate memory for buffer.\n");
        return EXIT_FAILURE;
    }

    // Create threads for reading from data source
    pthread_t readerThreads[MAX_CONCURRENT_ACCESS];
    for (int i = 0; i < MAX_CONCURRENT_ACCESS; ++i) {
        if (pthread_create(&readerThreads[i], NULL, dataSourceReader, &dataSource)) {
            fprintf(stderr, "Failed to create thread %d.\n", i);
            return EXIT_FAILURE;
        }
    }

    // Main function can now use findLargestInteger to get the largest integer processed
    int largestInteger = findLargestInteger(&dataSource);

    // Clean up resources
    free(dataSource.buffer);

    for (int i = 0; i < MAX_CONCURRENT_ACCESS; ++i) {
        pthread_join(readerThreads[i], NULL);
    }

    printf("Largest Integer Processed: %d\n", largestInteger);

    return EXIT_SUCCESS;
}

// Example dataSourceReader function
void* dataSourceReader(void* arg) {
    DataSource* dataSource = (DataSource*)arg;

    while (1) {
        // Simulate reading an integer from data source
        int newInt = readFromDataSource();  // Function to simulate reading

        if (newInt == -1) {  // Assume -1 is the signal to stop
            break;
        }

        pthread_mutex_lock(&dataSource->mutex);

        // Add new integer to buffer and notify all waiting threads
        dataSource->buffer[dataSource->writeIndex] = newInt;
        dataSource->writeIndex = (dataSource->writeIndex + 1) % dataSource->bufferSize;
        pthread_cond_signal(&dataSource->condVar);

        pthread_mutex_unlock(&dataSource->mutex);
    }

    return NULL;
}

// Example findLargestInteger function
int findLargestInteger(DataSource* dataSource) {
    int maxInt = INT_MIN;

    while (1) {
        pthread_mutex_lock(&dataSource->mutex);

        // Wait for new data if buffer is empty
        while (dataSource->writeIndex == dataSource->readIndex) {
            pthread_cond_wait(&dataSource->condVar, &dataSource->mutex);
        }

        // Read integer from buffer and update maxInt if it's larger
        int currentInt = dataSource->buffer[dataSource->readIndex];
        dataSource->readIndex = (dataSource->readIndex + 1) % dataSource->bufferSize;

        if (currentInt > maxInt) {
            maxInt = currentInt;
        }

        pthread_mutex_unlock(&dataSource->mutex);

        // Simulate processing time
        usleep(1000);
    }

    return maxInt;
}

// Mock function to simulate reading from data source
int readFromDataSource() {
    static int count = 0;
    if (count > 100) {
        return -1;  // Signal to stop after 100 reads
    }
    return rand() % 100;  // Simulate a random integer between 0 and 99
}
