// app.js

const express = require('express');
const bodyParser = require('body-parser');
const crypto = require('crypto');
const axios = require('axios');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(bodyParser.json());
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

let orderDatabase = {};

// Payment Gateway API endpoint
const PAYMENT_GATEWAY_API = 'https://api.paymentgateway.com/transactions';

async function processPaymentAndUpdateOrderStatus(orderId, paymentMethod, details) {
    try {
        let transactionResponse;
        switch (paymentMethod) {
            case 'creditCard':
                transactionResponse = await axios.post(PAYMENT_GATEWAY_API + '/credit-card', details);
                break;
            case 'paypal':
                transactionResponse = await axios.post(PAYMENT_GATEWAY_API + '/paypal', details);
                break;
            default:
                throw new Error('Unsupported payment method');
        }

        if (transactionResponse.data.status === 'success') {
            orderDatabase[orderId].status = 'paid';
            return transactionResponse.data.transactionId;
        } else {
            throw new Error(transactionResponse.data.message);
        }
    } catch (error) {
        console.error('Payment processing failed:', error);
        throw error;
    }
}

function calculateTransactionHash(transactionRecord) {
    const hash = crypto.createHmac('sha256', 'your_secret_key');
    hash.update(JSON.stringify(transactionRecord));
    return hash.digest('hex');
}

app.post('/process-payment', async (req, res) => {
    try {
        const { orderId, paymentMethod, details } = req.body;
        if (!orderId || !paymentMethod || !details) {
            throw new Error('Missing required parameters');
        }

        orderDatabase[orderId] = { status: 'pending' };
        const transactionId = await processPaymentAndUpdateOrderStatus(orderId, paymentMethod, details);
        res.json({ transactionId });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

app.get('/transaction-hash/:orderId', async (req, res) => {
    try {
        const { orderId } = req.params;
        if (!orderDatabase[orderId]) {
            throw new Error('Order not found');
        }

        const transactionRecord = orderDatabase[orderId];
        const hash = calculateTransactionHash(transactionRecord);
        res.json({ hash });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```

