import requests
from threading import Lock

# Global variables for script caching and loading status
script_cache = {}
script_status = {}
lock = Lock()

def generate_footer_section(scripts):
    global script_cache, script_status, lock

    # Check if scripts are already cached
    with lock:
        for script in scripts:
            if script.name not in script_cache:
                # Fetch script from CDN and store in cache
                response = requests.get(script.url)
                if response.status_code == 200:
                    script_cache[script.name] = response.text
                    script_status[script.name] = 'cached'
                else:
                    script_status[script.name] = 'cache_miss'

    # Generate footer section using cached scripts
    footer_section = '<footer>'
    for script in scripts:
        if script.name not in script_cache:
            # Use fallback content if script is not cached
            footer_section += f'<p>{script.fallback_content}</p>'
        else:
            # Render script from cache
            footer_section += f'<script type="text/javascript">{script_cache[script.name]}</script>'

    return footer_section

def health_check():
    global script_cache, script_status, lock

    # Check availability and correctness of cached scripts
    with lock:
        for script_name in script_cache:
            response = requests.get(script.url)
            if response.status_code != 200:
                print(f'Script {script_name} is not available')
            elif response.text != script_cache[script_name]:
                print(f'Script {script_name} has been updated')

    return len(script_cache) > 0
