type HttpResult<T> = Result<T, Box<dyn std::error::Error>>;

fn create_http_client(disable_ssl_verification: bool) -> HttpResult<Client<hyper_tls::HttpsConnector>> {
    let https_connector = if disable_ssl_verification {
        let mut builder = hyper_tls::HttpsConnectorBuilder::new();
        builder.danger_accept_invalid_certs(true);
        builder.build()
    } else {
        HttpsConnector::new()
    };
    Ok(Client::builder().build(https_connector))
}

fn build_request(
    client: &Client<hyper_tls::HttpsConnector>,
    url: String,
    method: Method,
    body: Option<String>,
    headers: Option<Vec<(String, String)>>,
    timeout: Option<std::time::Duration>,
) -> HttpResult<Request<Body>> {
    let uri = url.parse::<Uri>()?;
    let mut builder = Request::builder().method(method).uri(uri);

    if let Some(headers) = headers {
        for (key, value) in headers {
            builder = builder.header(key, HeaderValue::from_str(&value)?);
        }
    }

    if let Some(body) = body {
        builder = builder.body(Body::from(body))?;
    }

    Ok(builder.build()?)
}

fn execute_request(
    client: &Client<hyper_tls::HttpsConnector>,
    request: Request<Body>,
) -> HttpResult<String> {
    let response = client.request(request).map_err(|e| e.into())?;

    if !response.status().is_success() {
        error!("Request failed with status: {}", response.status());
        return Err(format!("HTTP error: {}", response.status()).into());
    }

    hyper::body::to_bytes(response.into_body())
        .await
        .map_err(|e| e.into())
        .and_then(|bytes| String::from_utf8(bytes.to_vec()).map_err(|e| e.into()))
}

pub async fn make_http_request(
    url: String,
    method: Method,
    body: Option<String>,
    headers: Option<Vec<(String, String)>>,
    disable_ssl_verification: bool,
    timeout: Option<std::time::Duration>,
) -> HttpResult<String> {
    info!("Making HTTP request to {}", url);

    let client = create_http_client(disable_ssl_verification)?;
    let request = build_request(&client, url, method, body, headers, timeout)?;

    execute_request(&client, request)
}
