        Options options = new Options.Builder()
                .server(natsServer)
                .build();
        this.natsConnection = Nats.connect(options);
        this.databaseUrl = databaseUrl;
        this.apiKey = apiKey;
    }

    public void processWeatherEvents(String userId, double latitude, double longitude, JsonNode weatherEvents) {
        for (JsonNode event : weatherEvents) {
            String eventType = event.get("type").asText();
            switch (eventType) {
                case "TEMPERATURE":
                    updateTemperature(userId, latitude, longitude, event.get("value").asDouble());
                    break;
                case "WIND_SPEED":
                    updateWindSpeed(userId, latitude, longitude, event.get("value").asDouble());
                    break;
                // Add more cases as needed
            }
        }
    }

    private void updateTemperature(String userId, double latitude, double longitude, double temperature) {
        try (Connection connection = DriverManager.getConnection(databaseUrl)) {
            String sql = "UPDATE weather_data SET temperature = ? WHERE user_id = ? AND latitude = ? AND longitude = ?";
            PreparedStatement preparedStatement = connection.prepareStatement(sql);
            preparedStatement.setDouble(1, temperature);
            preparedStatement.setString(2, userId);
            preparedStatement.setDouble(3, latitude);
            preparedStatement.setDouble(4, longitude);
            preparedStatement.executeUpdate();
        } catch (SQLException e) {
            logError(e);
            retryUpdateTemperature(userId, latitude, longitude, temperature);
        }
    }

    private void retryUpdateTemperature(String userId, double latitude, double longitude, double temperature) {
        CompletableFuture.runAsync(() -> updateTemperature(userId, latitude, longitude, temperature))
                .orTimeout(30, TimeUnit.SECONDS)
                .exceptionally(ex -> {
                    logError(ex);
                    return null;
                });
    }

    private void logError(Exception e) {
