class AttackProfile {
public:
    int damage;
    int cost;
    int cooldown;
    std::string specialEffect;

    AttackProfile(int d, int c, int cd, std::string se) : damage(d), cost(c), cooldown(cd), specialEffect(se) {}
};

class Character {
public:
    int health;
    int energy;
    double distanceToEnemy;
    std::vector<AttackProfile> attackProfiles;

    Character(int h, int e, double d) : health(h), energy(e), distanceToEnemy(d), attackProfiles() {}

    void addAttackProfile(AttackProfile profile) {
        attackProfiles.push_back(profile);
    }

    void updateState(int newHealth, int newEnergy, double newDistance) {
        std::lock_guard<std::mutex> lock(mutex_);
        health = newHealth;
        energy = newEnergy;
        distanceToEnemy = newDistance;
        condition_.notify_one();
    }

    void performAttack() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (condition_.wait_for(lock, std::chrono::seconds(1), [this] { return shouldPerformAttack(); })) {
            // Select and execute the attack based on current state
            int maxDamage = 0;
            AttackProfile* selectedAttack = nullptr;

            for (auto& profile : attackProfiles) {
                if (profile.damage > maxDamage && canExecute(profile)) {
                    maxDamage = profile.damage;
                    selectedAttack = &profile;
                }
            }

            if (selectedAttack) {
                // Execute the attack
                std::cout << "Executing attack with damage: " << selectedAttack->damage
                          << ", cost: " << selectedAttack->cost
                          << ", special effect: " << selectedAttack->specialEffect << std::endl;
                executeCooldown(selectedAttack->cooldown);
            } else {
                // Perform default action if no valid attack
                std::cout << "Performing default non-attack action" << std::endl;
            }
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;

    bool shouldPerformAttack() const {
        return health > 0 && energy >= 10; // Simplified logic for demonstration
    }

    bool canExecute(const AttackProfile& profile) const {
        return energy >= profile.cost && distanceToEnemy <= 5; // Simplified logic for demonstration
    }

    void executeCooldown(int cooldownSeconds) {
        std::this_thread::sleep_for(std::chrono::seconds(cooldownSeconds));
        // Update the character's state based on cooldowns or resource management
    }
};

