# json_base.py
import json
import yaml
from abc import ABC, abstractmethod
from threading import Lock
import time

class JSONBase(ABC):
    _registry = {}
    _lock = Lock()
    _last_cleanup_time = 0
    CLEANUP_INTERVAL = 60  # Cleanup interval in seconds

    @classmethod
    def register_subclass(cls, subclass_id, subclass):
        with cls._lock:
            if subclass_id not in cls._registry:
                cls._registry[subclass_id] = subclass

    @classmethod
    def discover_subclasses(cls, directory: str):
        import pkgutil
        import importlib
        for _, name, _ in pkgutil.iter_modules([directory]):
            module = importlib.import_module(f"{directory}.{name}")
            for attr_name in dir(module):
                attr = getattr(module, attr_name)
                if isinstance(attr, type) and issubclass(attr, cls) and attr != cls:
                    cls.register_subclass(attr.__name__, attr)

    @classmethod
    def load_yaml_registry(cls, file_path: str):
        with open(file_path, 'r') as f:
            registry_data = yaml.safe_load(f)
            for subclass_id, subclass_info in registry_data.items():
                subclass = importlib.import_module(subclass_info['module']).__getattribute__(subclass_info['name'])
                cls.register_subclass(subclass_id, subclass)

    @classmethod
    def save_registry(cls, file_path: str):
        registry_data = {subclass_id: {
            'module': subclass.__module__,
            'name': subclass.__name__
        } for subclass_id, subclass in cls._registry.items()}
        with open(file_path, 'w') as f:
            yaml.dump(registry_data, f)

    @abstractmethod
    def to_json(self):
        pass

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        subclass_id = data['type']
        if subclass_id in cls._registry:
            return cls._registry[subclass_id].from_dict(data)
        else:
            raise ValueError(f"Unknown subclass: {subclass_id}")

    @classmethod
    def from_dict(cls, data):
        raise NotImplementedError("Subclasses must implement this method")

    @classmethod
    def cleanup_registry(cls):
        with cls._lock:
            current_time = time.time()
            if current_time - cls._last_cleanup_time > cls.CLEANUP_INTERVAL:
                for subclass_id in list(cls._registry.keys()):
                    # Implement logic to determine if the subclass is unused and can be removed
                    pass  # Placeholder for actual cleanup logic
                cls._last_cleanup_time = current_time

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.register_subclass(cls.__name__, cls)

# registry.py
import json_base

def create_instance(subclass_id, data):
    subclass = getattr(json_base, subclass_id)
    return subclass.from_dict(data)

# subclasses.py
from json_base import JSONBase

class MySubClass(JSONBase):
    def to_json(self):
        return json.dumps({'type': self.__class__.__name__, 'data': self.data})

    @classmethod
    def from_dict(cls, data):
        instance = cls()
        instance.data = data['data']
        return instance
