#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/rsa.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>

typedef void (*crypto_module_func)();

void* load_crypto_module(const char* module_name) {
    return dlopen(module_name, RTLD_LAZY);
}

void unload_crypto_module(void* handle) {
    dlclose(handle);
}

void execute_crypto_operation(void* handle, crypto_module_func func) {
    if (handle && func) {
        func();
    }
}

int main() {
    void* aes_handle = load_crypto_module("libaes.so");
    void* camellia_handle = load_crypto_module("libcamellia.so");
    void* md5_handle = load_crypto_module("libmd5.so");
    void* sha_handle = load_crypto_module("libsha.so");
    void* rsa_sha1_handle = load_crypto_module("librsa_sha1.so");

    crypto_module_func aes_func = dlsym(aes_handle, "aes_operation");
    crypto_module_func camellia_func = dlsym(camellia_handle, "camellia_operation");
    crypto_module_func md5_func = dlsym(md5_handle, "md5_operation");
    crypto_module_func sha_func = dlsym(sha_handle, "sha_operation");
    crypto_module_func rsa_sha1_func = dlsym(rsa_sha1_handle, "rsa_sha1_operation");

    execute_crypto_operation(aes_handle, aes_func);
    execute_crypto_operation(camellia_handle, camellia_func);
    execute_crypto_operation(md5_handle, md5_func);
    execute_crypto_operation(sha_handle, sha_func);
    execute_crypto_operation(rsa_sha1_handle, rsa_sha1_func);

    unload_crypto_module(aes_handle);
    unload_crypto_module(camellia_handle);
    unload_crypto_module(md5_handle);
    unload_crypto_module(sha_handle);
    unload_crypto_module(rsa_sha1_handle);

    return 0;
}
