import com.fasterxml.jackson.databind.JsonNode;
import redis.clients.jedis.JedisPool;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.clients.consumer.KafkaConsumer;

public class MetricProcessor {
    private KafkaConsumer<String, String> consumer;
    private JedisPool jedisPool;
    private Map<String, Function<JsonNode, Object>> metricExtractors;
    private Map<String, Double> thresholds;
    private RateLimiter rateLimiter;

    public MetricProcessor(String kafkaBootstrapServers, int cacheSize) {
        this.consumer = new KafkaConsumer<>(Collections.singletonMap("bootstrap.servers", kafkaBootstrapServers));
        this.jedisPool = new JedisPool(new JedisPoolConfig(), "localhost");
        this.metricExtractors = new HashMap<>();
        this.thresholds = new HashMap<>();
        this.rateLimiter = RateLimiter.create(10); // 10 requests per second
    }

    public void addMetricExtractor(String metricName, Function<JsonNode, Object> extractor) {
        metricExtractors.put(metricName, extractor);
    }

    public void setThreshold(String metricName, double threshold) {
        thresholds.put(metricName, threshold);
    }

    public void processLogs() {
        while (true) {
            if (!rateLimiter.tryAcquire()) continue;

            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                try {
                    JsonNode jsonLog = objectMapper.readTree(record.value());
                    extractAndCacheMetrics(jsonLog);
                    checkThresholdsAndUpdateAlerts(jsonLog);
                } catch (Exception e) {
                    handleException(e);
                }
            }
        }
    }

    private void extractAndCacheMetrics(JsonNode jsonLog) {
        try (Jedis jedis = jedisPool.getResource()) {
            for (Map.Entry<String, Function<JsonNode, Object>> entry : metricExtractors.entrySet()) {
                String key = entry.getKey();
                Function<JsonNode, Object> extractor = entry.getValue();
                Object metricValue = extractor.apply(jsonLog);
                if (metricValue != null) {
                    jedis.setex(key, 3600, metricValue.toString()); // Cache for 1 hour
                }
            }
        }
    }

    private void checkThresholdsAndUpdateAlerts(JsonNode jsonLog) {
        for (Map.Entry<String, Double> entry : thresholds.entrySet()) {
            String key = entry.getKey();
            double threshold = entry.getValue();
            try (Jedis jedis = jedisPool.getResource()) {
                Object cachedValue = jedis.get(key);
                if (cachedValue != null) {
                    double value = Double.parseDouble(cachedValue.toString());
                    if (value > threshold) {
                        updateAlerts(jsonLog, key, value);
                    }
                }
            }
        }
    }

    private void handleException(Exception e) {
        // Log the error and retry logic here
    }

    private void updateAlerts(JsonNode jsonLog, String metricName, double value) {
        // Implement alerting logic based on threshold breaches
    }
}
