        // Load logging service client library dynamically
        loadClientLibrary();

        // Authenticate and retrieve access token
        accessToken_ = authenticate(clientId_, clientSecret_);

        // Start processing logs from various sources
        for (int i = 0; i < numThreads_; ++i) {
            threads_.emplace_back(&RealTimeLogProcessor::processLogs, this);
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();

        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void setFilterCriteria(const FilterCriteria& criteria) {
        filterCriteria_ = criteria;
