// Define the fetchAndProcessFiles function
async function fetchAndProcessFiles(options) {
    const { url, extensions, concurrency, retryOptions, log, onFileChange } = options;
    const fileCache = new Map();
    let activeTasks = 0;

    // Helper function to handle retries
    async function retryableFetch(url, attempt = 1) {
        try {
            return await fetch(url);
        } catch (error) {
            if (attempt >= retryOptions.maxRetries) throw error;
            const backoffTime = retryOptions.backoff * Math.pow(2, attempt - 1);
            log(`Retry ${url} due to error: ${error}. Retrying in ${backoffTime}ms`);
            await new Promise(resolve => setTimeout(resolve, backoffTime));
            return await retryableFetch(url, attempt + 1);
        }
    }

    // Helper function to process a single file
    async function processFile(fileUrl) {
        try {
            log(`Processing file: ${fileUrl}`);
            const response = await retryableFetch(fileUrl);
            const content = await response.text();
            // Process the content here (e.g., extract data, transform)
            console.log(`Processed file: ${fileUrl}`);
        } catch (error) {
            log(`Error processing file: ${fileUrl}. Error: ${error}`);
        }
    }

    // Recursive function to fetch and process files
    async function fetchFiles(directory) {
        try {
            const response = await retryableFetch(directory);
            const files = await response.json(); // Assuming JSON response for simplicity

            for (const file of files) {
                if (extensions.includes(file.extension)) {
                    const fileUrl = `${directory}/${file.name}`;
                    if (!fileCache.has(fileUrl)) {
                        fileCache.set(fileUrl, true);
                        activeTasks++;
                        processFile(fileUrl).then(() => {
                            activeTasks--;
                            checkCompletion();
                        }).catch(error => {
                            log(`Error processing ${fileUrl}. Error: ${error}`);
                            activeTasks--;
                            checkCompletion();
                        });
                    }
                }

                if (file.isDirectory) {
                    await fetchFiles(fileUrl);
                }
            }
        } catch (error) {
            log(`Error fetching files from directory: ${directory}. Error: ${error}`);
        }
    }

    // Function to check for completion
    function checkCompletion() {
        if (activeTasks === 0 && onFileChange) {
            onFileChange();
        }
    }

    // Start fetching and processing files
    await fetchFiles(url);
}

// Example usage:
fetchAndProcessFiles({
    url: 'http://example.com/api/files',
    extensions: ['txt', 'json'],
    concurrency: 10,
    retryOptions: { maxRetries: 5, backoff: 1000 },
    log: console.log,
    onFileChange: () => {
        console.log('All files processed.');
    }
});
