class BibleTextAnalyzer {
  static oldTestamentBooks = [
    "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
    "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel", "1 Kings",
    "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra", "Nehemiah",
    "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "Song of Solomon",
    "Isaiahu", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea",
    "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk",
    "Zephaniah", "Haggai", "Zechariah", "Malachi"
  ];

  static newTestamentBooks = [
    "Matthew", "Mark", "Luke", "John", "Acts", "Romans", "1 Corinthians",
    "2 Corinthians", "Galatians", "Ephesians", "Philippians", "Colossians",
    "1 Thessalonians", "2 Thessalonians", "1 Timothy", "2 Timothy", "Titus",
    "Philemon", "Hebrews", "James", "1 Peter", "2 Peter", "1 John", "2 John",
    "3 John", "Jude", "Revelation"
  ];

  static bibleBooks = [...BibleTextAnalyzer.oldTestamentBooks, ...BibleTextAnalyzer.newTestamentBooks];

  constructor() {
    this.bookRegex = new RegExp(`\\b(${BibleTextAnalyzer.bibleBooks.join("|")})\\b`, 'gi');
  }

  analyze(text) {
    if (typeof text !== 'string' || !text.trim()) {
      throw new Error('Invalid input. Please provide a non-empty string.');
    }

    const bookNames = text.match(this.bookRegex);
    if (!bookNames) return {};

    const bookCount = {};
    for (const book of bookNames) {
      const cleanBookName = book.toLowerCase();
      if (BibleTextAnalyzer.bibleBooks.includes(cleanBookName)) {
        bookCount[cleanBookName] = (bookCount[cleanBookName] || 0) + 1;
      }
    }

    return bookCount;
  }
}

module.exports = BibleTextAnalyzer;
