import java.security.SecureRandom;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import org.json.JSONObject;

public class SecurePasswordManager {
    private static final int SALT_LENGTH = 16;
    private static final int ITERATIONS = 1024;
    private static final String ALGORITHM = "PBKDF2WithHmacSHA256";

    public static String generateRandomString(int length) {
        SecureRandom random = new SecureRandom();
        byte[] bytes = new byte[length];
        random.nextBytes(bytes);
        return javax.xml.bind.DatatypeConverter.printBase64Binary(bytes);
    }

    public static String hashPassword(String password, byte[] salt) throws Exception {
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), salt, ITERATIONS, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance(ALGORITHM);
        return javax.xml.bind.DatatypeConverter.printBase64Binary(factory.generateSecret(spec).getEncoded());
    }

    public static boolean verifyPassword(String password, byte[] storedSalt, String storedHash) throws Exception {
        String hashToVerify = hashPassword(password, storedSalt);
        return hashToVerify.equals(storedHash);
    }

    // Additional methods for SecurePasswordManager class implementation
}

