public class FactoryRegistry {
    private Map<String, Map<Integer, Function<Object[], Object>>> factoryFunctions = new ConcurrentHashMap<>();

    public void registerFactoryFunction(String id, int version, Function<Object[], Object> function) {
        factoryFunctions.computeIfAbsent(id, k -> new HashMap<>()).put(version, function);
    }

    public <T> T createInstance(String id, int version, Object... args) throws Exception {
        Map<Integer, Function<Object[], Object>> versionMap = factoryFunctions.get(id);
        if (versionMap != null && versionMap.containsKey(version)) {
            return (T) versionMap.get(version).apply(args);
        } else {
            throw new IllegalArgumentException("Factory function not found for ID: " + id + ", Version: " + version);
        }
    }

    // External database integration and metadata management
}

