@Component
public class RateLimiter {
    private final Map<String, AtomicInteger> rateLimits = new ConcurrentHashMap<>();

    public boolean allowRequest(String userId) {
        rateLimits.putIfAbsent(userId, new AtomicInteger(0));
        int currentCount = rateLimits.get(userId).incrementAndGet();
        if (currentCount > 10) { // Limit to 10 requests per minute
            rateLimits.get(userId).decrementAndGet();
            return false;
        }
        return true;
    }

    public void resetRateLimit(String userId) {
        rateLimits.remove(userId);
    }
}

