#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256

// Function to log errors
void log_error(const char *message) {
    // Implement logging logic here
    printf("ERROR: %s\n", message);
}

// Function to parse the filename and extract extension
char* get_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) {
        return strdup(dot + 1);
    }
    return NULL;
}

// Function to determine the number of digits based on file type
int get_digit_count(const char *extension) {
    // Implement digit count logic here
    // Example: Always use 3 digits for all extensions
    return 3;
}

// Function to validate the new extension format
int validate_extension(const char *new_extension) {
    // Implement validation logic here
    if (strlen(new_extension) < 5) return 0; // Minimum length for digit + file type

    char digits[4];
    strncpy(digits, new_extension, 3);
    digits[3] = '\0';

    if (atoi(digits) == 0 || strlen(new_extension) != strlen(digits) + 1) {
        log_error("Invalid digit count in extension");
        return 0;
    }

    if (!isalpha(new_extension[3])) {
        log_error("Invalid file type in extension");
        return 0;
    }

    return 1;
}

// Function to set the new file extension
char* set_new_extension(const char *filename, const char *file_type) {
    // Implement logic to create new filename with new extension
    char *new_filename = (char *)malloc(MAX_FILENAME_LENGTH);
    if (!new_filename) {
        log_error("Memory allocation failed");
        return NULL;
    }

    strcpy(new_filename, filename);
    size_t pos = strlen(new_filename);
    while (pos > 0 && new_filename[pos - 1] != '.') pos--;

    if (pos == 0) {
        log_error("Invalid filename format");
        free(new_filename);
        return NULL;
    }

    new_filename[pos] = '\0';
    strcat(new_filename, file_type);

    if (!validate_extension(file_type)) {
        free(new_filename);
        return NULL;
    }

    return new_filename;
}

// Main function to modify the file extension
char* modify_file_extension(const char *filename, const char *file_type) {
    char *extension = get_extension(filename);
    if (!extension) {
        log_error("No extension found in filename");
        return NULL;
    }

    int digit_count = get_digit_count(extension);
    char digits[4];
    snprintf(digits, 4, "%03d", digit_count);

    char new_extension[5];
    sprintf(new_extension, "%s.%s", digits, file_type);

    char *new_filename = set_new_extension(filename, new_extension);
    free(extension);

    return new_filename;
}

// Example usage
int main(int argc, char **argv) {
    if (argc != 3) {
        printf("Usage: %s <filename> <file_type>\n", argv[0]);
        return 1;
    }

    const char *filename = argv[1];
    const char *file_type = argv[2];

    char *new_filename = modify_file_extension(filename, file_type);
    if (new_filename) {
        printf("New filename: %s\n", new_filename);
        free(new_filename);
    }

    return 0;
}
