CREATE PROCEDURE GetEmployeeDetailsAndWeather(@SupervisorID INT, @Page INT = 1, @PageSize INT = 20)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TotalCount INT;
    DECLARE @Offset INT = (@Page - 1) * @PageSize;

    BEGIN TRY
        -- Query to fetch employee details and count
        SELECT 
            e.EmployeeName,
            e.City,
            e.Address,
            (SELECT COUNT(*) FROM Employees WHERE SupervisorID = e.EmployeeID) AS DirectReportsCount
        INTO #EmployeeDetails
        FROM Employees e
        WHERE e.SupervisorID = @SupervisorID
        ORDER BY EmployeeName
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

        -- Fetch the total count for pagination
        SELECT @TotalCount = COUNT(*) FROM Employees e WHERE e.SupervisorID = @SupervisorID;

        -- Fetch weather data from external API and merge with employee details
        DECLARE @WeatherData NVARCHAR(MAX);
        SET @WeatherData = (
            SELECT 
                CONCAT('[', STRING_AGG(
                    CONCAT('{"EmployeeName": "', ed.EmployeeName, '", "City": "', ed.City, '", "Address": "', ed.Address, '", "DirectReportsCount": ', ed.DirectReportsCount, 
                           ', "Weather": {"Temperature": "', w.Temperature, '", "Condition": "', w.Condition, '"}}'), ','), '')
                , ']') AS WeatherDetails
            FROM #EmployeeDetails ed
            CROSS APPLY (
                SELECT TOP 1 Temperature, Condition
                FROM ExternalWeatherAPI (NOLOCK)
                WHERE City = ed.City
                FOR JSON AUTO
            ) w
        );

        -- Final JSON response including employee details and weather data
        DECLARE @JSONResponse NVARCHAR(MAX);
        SET @JSONResponse = CONCAT(
            '{"TotalCount": ', @TotalCount, 
            ', "Page": ', @Page, 
            ', "PageSize": ', @PageSize, 
            ', "EmployeeDetails": ', @WeatherData,
            '}'
        );

        -- Return the JSON response
        PRINT @JSONResponse;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000);
        DECLARE @ErrorSeverity INT;
        DECLARE @ErrorState INT;

        SELECT 
            @ErrorMessage = ERROR_MESSAGE(),
            @ErrorSeverity = ERROR_SEVERITY(),
            @ErrorState = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END

-- To call the stored procedure:
EXEC GetEmployeeDetailsAndWeather @SupervisorID = 1, @Page = 1, @PageSize = 20;
