// Array of available cryptographic primitives
CryptoPrimitive crypto_primitives[] = {
    {EVP_aes_256_cbc, EVP_md5, NULL, "aes"},
    {NULL, EVP_sha1, RSA_new, "sha"}
    // Add more primitives here
};

int initialize_crypto_library() {
