    return 0; // Return 0 for success
}

void cleanup_crypto_library() {
    // Cleanup resources used by the library (not shown)
}

EVP_CIPHER *get_cipher_by_name(const char *name) {
    pthread_mutex_lock(&crypto_lib_mutex);
    for (int i = 0; crypto_primitives[i].cipher_func != NULL; i++) {
        if (strcmp(crypto_primitives[i].alias, name) == 0) {
            pthread_mutex_unlock(&crypto_lib_mutex);
            return crypto_primitives[i].cipher_func();
        }
    }
    pthread_mutex_unlock(&crypto_lib_mutex);
    return NULL;
}

EVP_MD *get_md_by_name(const char *name) {
    pthread_mutex_lock(&crypto_lib_mutex);
    for (int i = 0; crypto_primitives[i].md_func != NULL; i++) {
        if (strcmp(crypto_primitives[i].alias, name) == 0) {
            pthread_mutex_unlock(&crypto_lib_mutex);
            return crypto_primitives[i].md_func();
        }
    }
    pthread_mutex_unlock(&crypto_lib_mutex);
    return NULL;
}

RSA *get_rsa_by_name(const char *name) {
    pthread_mutex_lock(&crypto_lib_mutex);
    for (int i = 0; crypto_primitives[i].rsa_func != NULL; i++) {
        if (strcmp(crypto_primitives[i].alias, name) == 0) {
            pthread_mutex_unlock(&crypto_lib_mutex);
            return crypto_primitives[i].rsa_func();
        }
    }
    pthread_mutex_unlock(&crypto_lib_mutex);
    return NULL;
}

int main() {
    initialize_crypto_library();

    EVP_CIPHER *cipher = get_cipher_by_name("aes");
    if (cipher == NULL) {
        printf("Cipher not found\n");
    }

    EVP_MD *md = get_md_by_name("sha");
    if (md == NULL) {
        printf("Digest not found\n");
    }

    RSA *rsa = get_rsa_by_name("rsa");
    if (rsa == NULL) {
        printf("RSA key not found\n");
    }

    cleanup_crypto_library();
    return 0;
}
