s3_client = boto3.client('s3')
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)
cache_max_age = 86400  # Cache images for a day

def download_image_from_s3(bucket_name, key):
    response = s3_client.get_object(Bucket=bucket_name, Key=key)
    return Image.open(response['Body'])

def cache_image(image, key):
    image_byte_arr = io.BytesIO()
    image.save(image_byte_arr, format='JPEG')
    redis_client.setex(key, cache_max_age, image_byte_arr.getvalue())

def get_cached_image(key):
    if redis_client.exists(key):
        image_data = redis_client.get(key)
        return Image.open(io.BytesIO(image_data))
    else:
        # Download from S3 and cache
        bucket_name = 'your-bucket-name'
        image = download_image_from_s3(bucket_name, key)
        cache_image(image, key)
        return image

def invalidate_cache_key(key):
    redis_client.delete(key)

def refresh_cached_images():
    bucket_name = 'your-bucket-name'
    response = s3_client.list_objects_v2(Bucket=bucket_name)
    for obj in response['Contents']:
        key = obj['Key']
        # Check if the image is expired
        if redis_client.ttl(key) <= 0:
            invalidate_cache_key(key)
            image = download_image_from_s3(bucket_name, key)
            cache_image(image, key)

def resize_and_crop_image(image, size, crop_box):
    return image.resize(size).crop(crop_box)

def handle_user_login(user_id):
    # Invalidate old user-specific images
    for image_type in ['avatar', 'banner']:
        invalidate_cache_key(f'{user_id}_{image_type}')

def trigger_cache_invalidation(admin_api_url, user_id=None, image_type=None):
    headers = {'Authorization': 'Bearer admin_token'}
    if user_id:
        response = requests.post(f'{admin_api_url}/invalidate_user_cache', json={'user_id': user_id}, headers=headers)
    elif image_type:
        response = requests.post(f'{admin_api_url}/invalidate_image_type_cache', json={'image_type': image_type}, headers=headers)
    else:
        raise ValueError('Invalid parameters. Please specify either user_id or image_type.')

def background_job_manager():
    with ThreadPoolExecutor(max_workers=5) as executor:
        while True:
            executor.submit(refresh_cached_images)
            # Add other background jobs here

if __name__ == '__main__':
    background_job_manager()
