#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <mutex>

enum RecorderType { DATABASE, FILE };

class TransactionRecorder {
public:
    virtual ~TransactionRecorder() {}
    virtual bool record(const std::string& details) = 0;
};

class DatabaseRecorder : public TransactionRecorder {
public:
    bool record(const std::string& details) override {
        // Simulate database connection and recording
        if (std::rand() % 2 == 0) {
            return false; // Simulate database failure
        }
        std::cout << "Recording to database: " << details << std::endl;
        return true;
    }
};

class FileRecorder : public TransactionRecorder {
public:
    bool record(const std::string& details) override {
        // Simulate file write operation
        if (std::rand() % 2 == 0) {
            return false; // Simulate file write failure
        }
        std::cout << "Writing to log file: " << details << std::endl;
        return true;
    }
};

class ImageCrawler {
private:
    std::unique_ptr<TransactionRecorder> recorder;
    std::mutex mutex;

public:
    void setRecorder(TransactionRecorder* rec) {
        recorder.reset(rec);
    }

    int recordTransaction(bool shouldRecord, RecorderType type, const std::string& details) {
        if (!shouldRecord) return 0;

        std::unique_lock<std::mutex> lock(mutex);
        if (type == DATABASE && recorder) {
            DatabaseRecorder* dbRec = dynamic_cast<DatabaseRecorder*>(recorder.get());
            if (dbRec) {
                if (!dbRec->record(details)) {
                    // Fallback mechanism for database failure
                    FileRecorder fileRec;
                    return fileRec.record(details);
                }
                return 0; // Success
            }
        } else if (type == FILE && recorder) {
            FileRecorder* fileRec = dynamic_cast<FileRecorder*>(recorder.get());
            if (fileRec) {
                if (!fileRec->record(details)) {
                    // Fallback mechanism for file write failure
                    DatabaseRecorder dbRec;
                    return dbRec.record(details);
                }
                return 0; // Success
            }
        }

        std::cerr << "Invalid recorder type or no recorder set." << std::endl;
        return -1; // Error
    }
};

int main() {
    ImageCrawler crawler;

    DatabaseRecorder dbRecorder;
    FileRecorder fileRecorder;

    crawler.setRecorder(&dbRecorder);
    crawler.recordTransaction(true, DATABASE, "Transaction 1");

    crawler.setRecorder(&fileRecorder);
    crawler.recordTransaction(true, FILE, "Transaction 2");

    return 0;
}
