    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
    private $saltRoundCount = 12;
    private static $saltCache = [];

    public function generateRandomString($length) {
        $characters = $this->characterSet;
        $charactersLength = strlen($characters);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, $charactersLength - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        $salt = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->getSaltRoundCount()]);
        $this->hashedPassword = $salt;
    }

    public function checkPassword($password) {
        if (isset($this->hashedPassword)) {
            return password_verify($password, $this->hashedPassword);
        }
        return false;
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/[a-z]/', $characterSet) ||
            !preg_match('/[A-Z]/', $characterSet) ||
            !preg_match('/\d/', $characterSet) ||
            !preg_match('/[^a-zA-Z0-9]/', $characterSet)) {
            return false;
        }
        // Add more checks for common patterns
        return true;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds > 1 && $rounds < PHP_INT_MAX) {
            $this->saltRoundCount = $rounds;
        }
    }

    private function getSaltRoundCount() {
        if (!isset(self::$saltCache[$this->saltRoundCount])) {
            self::$saltCache[$this->saltRoundCount] = password_hash($this->generateRandomString(16), PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
