// C# method to parameterize a SQL command with values
using System;
using System.Data;

public class SqlHelper {
    public static IDataReader ExecuteParameterizedQuery(List<object> values, string connectionString, string sqlCommand) {
        using (SqlConnection connection = new SqlConnection(connectionString)) {
            SqlCommand command = new SqlCommand(sqlCommand, connection);
            for (int i = 0; i < values.Count; i++) {
                command.Parameters.AddWithValue($"@Param{i}", values[i]);
            }
            connection.Open();
            return command.ExecuteReader(CommandBehavior.CloseConnection);
        }
    }
}
