public class ValueGenerator : IDisposable
{
    private int minValue;
    private int maxValue;
    private int seed;
    private bool loggingEnabled;
    private string logFilePath;
    private Random random;

    public ValueGenerator(int min, int max, int seed = 0, bool enableLogging = false, string logFile = "random_values.log")
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        minValue = min;
        maxValue = max;
        this.seed = seed;
        loggingEnabled = enableLogging;
        logFilePath = logFile;
        random = new Random(seed);

        if (loggingEnabled)
        {
            // Initialize logging setup here
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(
            UnityEngine.Random.Range(minValue, maxValue),
            UnityEngine.Random.Range(minValue, maxValue),
            UnityEngine.Random.Range(minValue, maxValue)
        );
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }

    public void Dispose()
    {
        // Clean up logging resources here if necessary
    }

    // Additional methods for customizing logging, error handling, and other features can be added here
}
