import java.io.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class StateManager {
    private static final Logger logger = LoggerFactory.getLogger(StateManager.class);
    private Map<String, MoSTState> cache = new ConcurrentHashMap<>();
    private ObjectInputStream ois;
    private ObjectOutputStream oos;
    private ExternalStateService stateService;
    private ScheduledExecutorService syncScheduler;

    public StateManager(String filePath, int cacheSize) throws IOException {
        loadCacheFromFiles(filePath);
        stateService = new ExternalStateService();
        syncScheduler = Executors.newScheduledThreadPool(1);
        syncScheduler.scheduleAtFixedRate(this::syncCacheWithExternalService, 0, 5, TimeUnit.MINUTES);
    }

    public MoSTState getState(String key) {
        MoSTState cachedState = cache.get(key);
        if (cachedState != null && !isOutdated(cachedState)) {
            logger.info("Returning cached state for: {}", key);
            return cachedState;
        } else {
            try {
                MoSTState updatedState = stateService.getStateFromExternalService(key);
                if (updatedState != null) {
                    cache.put(key, updatedState);
                    saveStateToFile(updatedState);
                    logger.info("Updated state for: {} from external service", key);
                }
                return updatedState;
            } catch (Exception e) {
                logger.error("Failed to get state for: {}", key, e);
                return null;
            }
        }
    }

    private void loadCacheFromFiles(String filePath) throws IOException {
        File file = new File(filePath);
        if (file.exists()) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                int size = ois.readInt();
                for (int i = 0; i < size; i++) {
                    MoSTState state = (MoSTState) ois.readObject();
                    cache.put(state.getKey(), state);
                }
            } catch (IOException | ClassNotFoundException e) {
                logger.error("Failed to load cache from file", e);
            }
        }
    }

    private void saveStateToFile(MoSTState state) throws IOException {
        File file = new File("state_cache.dat");
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(file))) {
            oos.writeInt(cache.size());
            for (MoSTState cachedState : cache.values()) {
                oos.writeObject(cachedState);
            }
        }
    }

    private void syncCacheWithExternalService() {
        // Logic to sync cache with external service
    }

    private boolean isOutdated(MoSTState state) {
        // Logic to check if the state is outdated
        return false;
    }

    public void invalidateState(String key) {
        cache.remove(key);
        logger.info("Invalidated state for: {}", key);
    }

    public void shutdown() {
        try {
            syncScheduler.shutdown();
            syncScheduler.awaitTermination(1, TimeUnit.MINUTES);
            ois.close();
            oos.close();
        } catch (InterruptedException e) {
            logger.error("Failed to close resources", e);
        }
    }
}
