fn calculate_average_response_time(ip_address_to_times: HashMap<String, Vec<f64>>) -> HashMap<String, f64> {
    let mut average_response_times = HashMap::new();

    for (ip_address, times) in ip_address_to_times.iter() {
        if !times.is_empty() {
            let total_time: f64 = times.iter().sum();
            let average_time = total_time / times.len() as f64;
            average_response_times.insert(ip_address.clone(), average_time);
        }
    }

    average_response_times
}

