    pthread_t producers[numProducers];
    pthread_t consumers[numConsumers];

    // Create producer threads
    for (int i = 0; i < numProducers; ++i) {
        pthread_create(&producers[i], NULL, producer, queue);
    }

    // Create consumer threads
    for (int i = 0; i < numConsumers; ++i) {
        pthread_create(&consumers[i], NULL, consumer, queue);
    }

    // Wait for the stop signal
    while (1) {
        if (/* stopSignal condition */) {
            break;
        }
    }

    stopUploads(queue, numConsumers);

    // Join producer threads
    for (int i = 0; i < numProducers; ++i) {
        pthread_join(producers[i], NULL);
    }

    // Join consumer threads
    for (int i = 0; i < numConsumers; ++i) {
        pthread_join(consumers[i], NULL);
    }

    cleanup(queue, numProducers, numConsumers);

    return EXIT_SUCCESS;
}
