import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import javax.imageio.ImageIO;

public class ImageToPdfConverter {

    public static int convertImagesToPdf(String inputDir, String pattern, String outputPdf, boolean progressCallback) {
        // Validate inputs
        if (inputDir == null || inputDir.isEmpty() || pattern == null || pattern.isEmpty() || outputPdf == null || outputPdf.isEmpty()) {
            System.err.println("Invalid input parameters.");
            return 1;
        }

        // Initialize variables
        int failedConversions = 0;
        ExecutorService executor = Executors.newFixedThreadPool(4); // Adjust thread pool size as needed

        try (PDDocument document = new PDDocument()) {
            // List all matching image files
            Path dirPath = Paths.get(inputDir);
            Pattern regex = Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
            Files.list(dirPath)
                 .filter(path -> regex.matcher(path.getFileName().toString()).matches())
                 .sorted() // Ensure images are processed in a specific order
                 .forEach(path -> executor.submit(() -> {
                     try {
                         PDPage page = new PDPage(PDRectangle.A4); // Adjust size as needed
                         document.addPage(page);

                         try (PDPageContentStream contentStream = new PDPageContentStream(document, page)) {
                             BufferedImage image = ImageIO.read(path.toFile());
                             float scale = Math.min((float) page.getMediaBox().getWidth() / image.getWidth(), 
                                                  (float) page.getMediaBox().getHeight() / image.getHeight());
                             contentStream.drawImage(PDImageXObject.createFromFileByContent(image, document), 
                                                   0, 0, image.getWidth() * scale, image.getHeight() * scale);
                         }
                     } catch (IOException e) {
                         System.err.println("Error processing file: " + path.getFileName());
                         failedConversions++;
                     }
                 }));

            // Await all tasks completion
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

            // Save the PDF document
            document.save(outputPdf);
        } catch (IOException | InterruptedException e) {
            System.err.println("Error creating PDF: " + e.getMessage());
            return 1;
        }

        if (progressCallback) {
            System.out.println("Conversion complete. Failed conversions: " + failedConversions);
        }

        return failedConversions;
    }
}
```

This code snippet provides a basic implementation of the `convertImagesToPdf` method according to the given requirements. It uses Java NIO for file listing, Apache PDFBox for PDF creation, and Java's concurrent utilities for multi-threading. The actual implementation may require adjustments based on specific use cases and environment constraints.

