```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public interface ICryptoServiceProvider
{
    byte[] Decrypt(byte[] encryptedData);
}

public class CryptoServiceProviderAdapter : ICryptoServiceProvider
{
    private readonly Func<byte[], byte[]> _decryptFunction;

    public CryptoServiceProviderAdapter(Func<byte[], byte[]> decryptFunction)
    {
        _decryptFunction = decryptFunction;
    }

    public byte[] Decrypt(byte[] encryptedData)
    {
        return _decryptFunction(encryptedData);
    }
}

public class SecureMessageHandler
{
    private readonly Dictionary<string, ICryptoServiceProvider> _cryptoServiceProviders;

    public SecureMessageHandler(Dictionary<string, ICryptoServiceProvider> cryptoServiceProviders)
    {
        _cryptoServiceProviders = cryptoServiceProviders;
    }

    public byte[] DecryptMessage(string base64EncodedMessage, string contextId)
    {
        if (!_cryptoServiceProviders.ContainsKey(contextId))
            throw new ArgumentException("Invalid context ID");

        var encryptedData = Convert.FromBase64String(base64EncodedMessage);
        return _cryptoServiceProviders[contextId].Decrypt(encryptedData);
    }

    public async Task<List<byte[]>> DecryptMessagesAsync(List<string> base64EncodedMessages, string contextId)
    {
        if (!_cryptoServiceProviders.ContainsKey(contextId))
            throw new ArgumentException("Invalid context ID");

        var tasks = base64EncodedMessages.Select(async base64EncodedMessage =>
        {
            var encryptedData = Convert.FromBase64String(base64EncodedMessage);
            return _cryptoServiceProviders[contextId].Decrypt(encryptedData);
        }).ToList();

        return await Task.WhenAll(tasks);
    }
}

public class SecureMessageHandlerBuilder
{
    private readonly Dictionary<string, ICryptoServiceProvider> _cryptoServiceProviders = new Dictionary<string, ICryptoServiceProvider>();

    public SecureMessageHandlerBuilder AddCryptoServiceProvider(string contextId, Func<byte[], byte[]> decryptFunction)
    {
        if (_cryptoServiceProviders.ContainsKey(contextId))
            throw new ArgumentException("Context ID already exists");

        _cryptoServiceProviders.Add(contextId, new CryptoServiceProviderAdapter(decryptFunction));
        return this;
    }

    public SecureMessageHandler Build()
    {
        return new SecureMessageHandler(_cryptoServiceProviders);
    }
}
