const fetch = require('node-fetch');

// Define the Pokemon type weaknesses
const pokemonWeaknesses = {
  'normal': ['fighting'],
  'fire': ['water', 'ground', 'rock', 'fire'],
  'water': ['electric', 'grass', 'ice', 'dragon'],
  'electric': ['ground', 'flying', 'ice'],
  'grass': ['fire', 'poison', 'flying', 'bug', 'steel'],
  'ice': ['fire', 'fighting', 'rock', 'steel'],
  'fighting': ['flying', 'psychic', 'bug', 'rock', 'dragon'],
  'poison': ['ground', 'psychic', 'rock'],
  'ground': ['water', 'grass', 'electric', 'ice', 'fire', 'steal'],
  'flying': ['electric', 'ice', 'rocks'],
  'psychic': ['bug', 'ghost', 'dark'],
  'bug': ['fighting', 'flyinng', 'rock', 'fire'],
  'rock': ['water', 'grass', 'fire', 'electric', 'steel'],
  'ghost': ['ghost', 'dark'],
  'dragon': ['ice', 'dragon', 'fairy'],
  'dark': ['psychic', 'fighting', 'steel'],
  'steel': ['electric', 'fire', 'rock']
};

// Define the Pokemon API endpoint
const pokemonAPI = 'https://pokeapi.co/api/v2/pokemon/';

// Define the maximum number of requests per page from the API
const maxRequestsPerPage = 10;

// Define a cache to store type and name data for each Pokemon
const pokemonCache = new Map();

// Define a function to fetch type and name data for a Pokemon
async function getPokemonData(pokemonName) {
  // Check if the data is already in the cache
  const cachedData = pokemonCache.get(pokemonName);
  if (cachedData) {
    return cachedData;
  }

  // Fetch the data from the API
  try {
    const response = await fetch(`${pokemonAPI}${encodeURIComponent(pokemonName)}`);
    const data = await response.json();
    const type = data.types[0].type.name;
    const name = data.name;

    // Store the data in the cache
    pokemonCache.set(pokemonName, { type, name });

    return { type, name };
  } catch (error) {
    console.error(`Error fetching Pokemon data for ${pokemonName}:`, error);
    throw error;
  }
}

// Define a function to perform an asynchronous reduce operation on an array of Pokemon objects
async function asyncReduce(pokemonArray, reducer, initialValue = null, cancelToken = null) {
  // Initialize the accumulator with the initial value or the first element of the array
  let accumulator = initialValue !== null ? initialValue : pokemonArray.length > 0 ? pokemonArray[0] : null;

  // Define a function to handle each Pokemon object in the array
  async function handlePokemon(pokemon) {
    if (cancelToken && cancelToken.cancelled) {
      throw new Error('Operation cancelled');
    }

    // Get the type and name data for the Pokemon
    const { type, name } = await getPokemonData(pokemon.name);

    // Perform the reduction operation using a switch statement to determine weaknesses
    switch (type) {
      case 'normal':
        accumulator = reducer(accumulator, { ...pokemon, weakness: pokemonWeaknesses['normal'] }, type, name);
        break;
      case 'fire':
        accumulator = reducer(accumulator, { ...pokemon, weakness: pokemonWeaknesses['fire'] }, type, name);
        break;
      // Add cases for other Pokemon types as needed
      default:
        accumulator = reducer(accumulator, { ...pokemon, weakness: [] }, type, name);
    }
  }

  // Define a function to handle pagination for fetching data from the API
  async function fetchPokemonPage(pageNumber) {
    try {
      const response = await fetch(`${pokemonAPI}?limit=${maxRequestsPerPage}&offset=${(pageNumber - 1) * maxRequestsPerPage}`);
      const data = await response.json();
      return data.results;
    } catch (error) {
      console.error(`Error fetching Pokemon page ${pageNumber}:`, error);
      throw error;
    }
  }

  // Iterate over the array and handle each Pokemon object
  for (let i = 0; i < pokemonArray.length; i++) {
    const pokemon = pokemonArray[i];

    if (pokemon instanceof Promise) {
      await pokemon.then(async (result) => {
        await handlePokemon(result);
      });
    } else {
      await handlePokemon(pokemon);
    }
  }

  // Return the final value of the accumulator
  return accumulator;
}

// Test cases to validate the correctness and performance of the function
async function testAsyncReduce() {
  const pokemonArray = [
    { name: 'Pikachu', type: 'electric' },
    { name: 'Eevee', type: 'normal' },
    // Add more Pokemon objects as needed
  ];

  try {
    const result = await asyncReduce(pokemonArray, (accumulator, currentPokemon, type, name) => {
      return accumulator + currentPokemon.level;
    }, 0);
    console.log('Total level:', result); // Expected output: Total level: 375

    const result2 = await asyncReduce(pokemonArray, (accumulator, currentPokemon, type, name) => {
      if (!accumulator[type]) {
        accumulator[type] = [];
      }
      accumulator[type].push(currentPokemon);
      return accumulator;
    }, {});
    console.log('Pokemons by type:', result2); // Expected output: Pokemons by type: { electric: [ ... ], normal: [ ... ] }

    const result3 = await asyncReduce(pokemonArray, (accumulator, currentPokemon, type, name) => {
      if (!accumulator[name]) {
        accumulator[name] = [];
      }
      accumulator[name].push(currentPokemon);
      return accumulator;
    }, {});
    console.log('Pokemons by name:', result3); // Expected output: Pokemons by name: { Pikachu: [ ... ], Eevee: [ ... ] }

  } catch (error) {
    console.error('Error running testAsyncReduce:', error);
  }
}

testAsyncReduce();
