```python
import json
from datetime import datetime
from decimal import Decimal
import uuid

class JSONSerializable:
    _factory_functions = {}

    @classmethod
    def add_factory_function(cls, id, func):
        cls._factory_functions[id] = func

    @classmethod
    def create_instance_from_id(cls, id, data):
        if id not in cls._factory_functions:
            raise ValueError(f"No factory function registered for ID: {id}")
        return cls._factory_functions[id](data)

    @classmethod
    def to_json(cls, obj):
        return json.dumps(obj, default=cls._serialize_value)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        return cls.create_instance_from_id(data['type'], data['value'])

    @staticmethod
    def _serialize_value(value):
        if isinstance(value, (datetime, UUID)):
            return value.isoformat() if isinstance(value, datetime) else str(value)
        elif isinstance(value, Decimal):
            return str(value)
        elif isinstance(value, JSONSerializable):
            return {'type': type(value).__name__, 'value': value.to_json()}
        raise TypeError(f"Type {type(value)} not serializable")

# Example usage:
class MyCustomData(JSONSerializable):
    def __init__(self, data):
        self.data = data

    @classmethod
    def _serialize_value(cls, value):
        if isinstance(value, MyCustomData):
            return {'type': 'MyCustomData', 'value': str(value.data)}
        return JSONSerializable._serialize_value(value)

# Register factory function for MyCustomData
JSONSerializable.add_factory_function('MyCustomData', lambda data: MyCustomData(data['value']))

# Create a custom data object and serialize it
custom_data = MyCustomData({'key': 'value'})
json_str = JSONSerializable.to_json(custom_data)
print(json_str)

# Deserialize the JSON string back to an instance of MyCustomData
deserialized_obj = JSONSerializable.from_json(json_str)
print(deserialized_obj.data)
```

