import jwt
from datetime import datetime, timedelta
import requests
from functools import lru_cache

class AuthHandler:
    def __init__(self, oauth_providers, secret_key):
        self.oauth_providers = oauth_providers
        self.secret_key = secret_key

    @lru_cache(maxsize=128)
    def fetch_user_profile(self, access_token, provider):
        # Fetch user profile from external API using validated OAuth token
        response = requests.get(f"https://{provider}/api/user", headers={"Authorization": f"Bearer {access_token}"})
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to fetch user profile")

    def validate_oauth_token(self, access_token, provider):
        # Validate provided OAuth access token against a configured OAuth provider
        response = requests.get(f"https://{provider}/api/token/validate", headers={"Authorization": f"Bearer {access_token}"})
        if response.status_code == 200:
            return True
        else:
            raise Exception("Invalid OAuth token")

    def generate_jwt(self, user_profile):
        # Generate JWT with user's profile information and custom claims
        payload = {
            "sub": user_profile["id"],
            "name": user_profile["name"],
            "email": user_profile["email"],
            "roles": user_profile.get("roles", []),
            "exp": datetime.utcnow() + timedelta(hours=1)
        }
        return jwt.encode(payload, self.secret_key, algorithm="HS256")

    def handle_auth_request(self, access_token, provider):
        try:
            if not self.validate_oauth_token(access_token, provider):
                return {"error": "Invalid OAuth token"}, 403

            user_profile = self.fetch_user_profile(access_token, provider)
            jwt_token = self.generate_jwt(user_profile)

            # Log relevant information for auditing purposes
            print(f"User {user_profile['id']} authenticated successfully")

            return {"token": jwt_token}, 200
        except Exception as e:
            print(f"Error during authentication: {e}")
            return {"error": str(e)}, 500

# Example usage
oauth_providers = {
    "provider1": {
        "url": "example.com/oauth"
    },
    "provider2": {
        "url": "another-example.com/oauth"
    }
}
secret_key = "your_secret_key_here"

auth_handler = AuthHandler(oauth_providers, secret_key)
access_token = "user_access_token"
provider = "provider1"

result, status_code = auth_handler.handle_auth_request(access_token, provider)
print(result, status_code)
