function asyncReduceArray(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let result = initialValue;
    const performReduction = (index) => {
      if (index >= arr.length) {
        resolve(result);
      } else {
        try {
          const nextResult = callback(result, arr[index]);
          result = nextResult;
          setTimeout(() => performReduction(index + 1), 0); // Asynchronous processing
        } catch (error) {
          reject(error);
        }
      }
    };
    performReduction(0);
  });
}

// Test the function with a sample array
