struct JsonHandler {
    data: Value,
}

impl JsonHandler {
    // Constructor to create a new instance of JsonHandler from a JSON string
    fn from_json(json_str: &str) -> Result<Self, serde_json::Error> {
        Ok(JsonHandler {
            data: serde_json::from_str(json_str)?,
        })
    }

    // Method to convert data to a JSON string
    fn to_json_string(&self) -> String {
        self.data.to_string()
    }
}

// Registry of factory functions
static mut FACTORY_REGISTRY: HashMap<String, Box<dyn Fn() -> Box<dyn JsonHandler>>> = HashMap::new();

// Function to add a new factory function to the registry
fn register_factory(id: &str, factory: impl Fn() -> Box<dyn JsonHandler> + 'static) {
    unsafe {
        FACTORY_REGISTRY.insert(id.to_string(), Box::new(factory));
    }
}

// Function to create a new instance of a subclass using the factory function associated with a given ID
fn create_instance(id: &str) -> Option<Box<dyn JsonHandler>> {
    unsafe {
        FACTORY_REGISTRY.get(id).cloned().map(|factory| factory())
    }
}

