# Import necessary libraries
import requests
from abc import ABC, abstractmethod
import time
import logging
from functools import lru_cache

# Set up basic configuration for logging
logging.basicConfig(level=logging.INFO)

# Abstract base class for notification providers
class NotificationProvider(ABC):
    @abstractmethod
    def send_notification(self, device_token: str, message: str) -> bool:
        pass

# Class for Apple Push Notification Service (APNs)
class APN(NotificationProvider):
    def __init__(self, api_key: str):
        self.api_key = api_key

    def send_notification(self, device_token: str, message: str) -> bool:
        headers = {
            'Authorization': f'Bearer {self.api_key}',
            'Content-Type': 'application/json'
        }
        payload = {
            "aps": {
                "alert": message
            },
            "token": device_token
        }
        response = requests.post('https://api.push.apple.com/3/device/{device_token}', headers=headers, json=payload)
        return response.status_code == 200

# Class for Firebase Cloud Messaging (FCM)
class FCM(NotificationProvider):
    def __init__(self, api_key: str):
        self.api_key = api_key

    def send_notification(self, device_token: str, message: str) -> bool:
        headers = {
            'Authorization': f'key={self.api_key}',
            'Content-Type': 'application/json'
        }
        payload = {
            "to": device_token,
            "notification": {
                "title": "Notification",
                "body": message
            }
        }
        response = requests.post('https://fcm.googleapis.com/fcm/send', headers=headers, json=payload)
        return response.status_code == 200

# Class for OneSignal Notification Service
class OneSignal(NotificationProvider):
    def __init__(self, app_id: str, rest_api_key: str):
        self.app_id = app_id
        self.rest_api_key = rest_api_key

    def send_notification(self, device_token: str, message: str) -> bool:
        headers = {
            'Content-Type': 'application/json; charset=utf-8',
            'Authorization': f'Basic {self.rest_api_key}'
        }
        payload = {
            "app_id": self.app_id,
            "include_player_ids": [device_token],
            "contents": {"en": message}
        }
        response = requests.post('https://onesignal.com/api/v1/notifications', headers=headers, json=payload)
        return response.status_code == 200

# Notification manager class to handle protocol selection and fallback
class NotificationManager:
    def __init__(self, providers: list):
        self.providers = providers

    def send_notification(self, device_token: str, message: str) -> bool:
        for provider in self.providers:
            if provider.send_notification(device_token, message):
                return True
        return False

# Example usage
api_key_apn = 'your_apn_api_key'
api_key_fcm = 'your_fcm_api_key'
app_id_onesignal = 'your_onesignal_app_id'
rest_api_key_onesignal = 'your_onesignal_rest_api_key'

providers = [APN(api_key_apn), FCM(api_key_fcm), OneSignal(app_id_onesignal, rest_api_key_onesignal)]
manager = NotificationManager(providers)

device_token = 'example_device_token'
message = 'Hello, notification!'
manager.send_notification(device_token, message)
