    API
};

class IBackendSystem {
public:
    virtual ~IBackendSystem() = default;
    virtual void processTransaction(const TransactionEvent& event) = 0;
};

class DatabaseBackend : public IBackendSystem {
public:
    void processTransaction(const TransactionEvent& event) override;
};

class LogFileBackend : public IBackendSystem {
public:
    void processTransaction(const TransactionEvent& event) override;
};

class APIBackend : public IBackendSystem {
public:
    void processTransaction(const TransactionEvent& event) override;
};

class DynamicPaymentProcessor {
private:
    std::vector<std::shared_ptr<IBackendSystem>> backends_;
    std::mutex backendMutex_;
    std::condition_variable loadCondition_;
    int maxLoad_;

    bool isBackendHealthy(IBackendSystem* backend);

public:
    DynamicPaymentProcessor(const std::vector<BackendType>& backendTypes, int maxLoad);
    void addTransactionEvent(const TransactionEvent& event);
    void configure(int retryInterval, int timeout);
    // Other methods for monitoring and configuration
};

// DynamicPaymentProcessor.cpp

#include "DynamicPaymentProcessor.h"
#include <algorithm>
#include <thread>
#include <chrono>

void DatabaseBackend::processTransaction(const TransactionEvent& event) {
    // Implement database processing logic
}

void LogFileBackend::processTransaction(const TransactionEvent& event) {
    // Implement log file processing logic
}

void APIBackend::processTransaction(const TransactionEvent& event) {
    // Implement API processing logic
}

DynamicPaymentProcessor::DynamicPaymentProcessor(const std::vector<BackendType>& backendTypes, int maxLoad)
    : backends_(), backendMutex_(), loadCondition_(), maxLoad_(maxLoad) {
    for (auto type : backendTypes) {
        switch (type) {
            case BackendType::DATABASE:
                backends_.push_back(std::make_shared<DatabaseBackend>());
                break;
            case BackendType::LOG_FILE:
                backends_.push_back(std::make_shared<LogFileBackend>());
                break;
            case BackendType::API:
                backends_.push_back(std::make_shared<APIBackend>());
                break;
        }
    }
}

void DynamicPaymentProcessor::addTransactionEvent(const TransactionEvent& event) {
    std::unique_lock<std::mutex> lock(backendMutex_);
    while (isLoadHigh()) {
        loadCondition_.wait(lock, [this] { return !isLoadHigh(); });
    }

    // Select backend based on load and health
    auto selectedBackend = selectBackend();
    if (selectedBackend) {
        std::thread([selectedBackend, event]() {
            selectedBackend->processTransaction(event);
        }).detach();
    }
}

void DynamicPaymentProcessor::configure(int retryInterval, int timeout) {
    // Implement configuration logic
}

bool DynamicPaymentProcessor::isLoadHigh() {
    // Check current load against threshold
    return /* load is high */;
}

IBackendSystem* DynamicPaymentProcessor::selectBackend() {
    std::unique_lock<std::mutex> lock(backendMutex_);
    auto healthyBackends = std::remove_if(backends_.begin(), backends_.end(),
                                          [this](const std::shared_ptr<IBackendSystem>& backend) {
                                              return !isBackendHealthy(backend.get());
                                          });
    if (healthyBackends == backends_.end()) {
        loadCondition_.wait(lock, [this] { return isLoadHigh(); });
    }

    auto selected = healthyBackends;
    // Implement logic to select the most appropriate backend
    std::shuffle(selected, backends_.end(), std::default_random_engine{std::random_device{}()});
    return *selected;
}

bool DynamicPaymentProcessor::isBackendHealthy(IBackendSystem* backend) {
    // Check backend health
    return /* backend is healthy */;
}
