#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_IP_LENGTH 16
#define MAX_TIME_LENGTH 20
#define MAX_STATUS_CODE_LENGTH 4

typedef struct {
    char ip[MAX_IP_LENGTH];
    char time[MAX_TIME_LENGTH];
    int status_code;
} HttpRequest;

HttpRequest* parse_line(char* line) {
    HttpRequest* request = (HttpRequest*)malloc(sizeof(HttpRequest));
    if (sscanf(line, "%[^ ] %[^ ] %d", request->ip, request->time, &request->status_code) != 3) {
        free(request);
        return NULL;
    }
    return request;
}

void process_chunk(FILE* file, size_t chunk_size) {
    char buffer[MAX_LINE_LENGTH];
    HttpRequest** requests = (HttpRequest**)malloc(chunk_size * sizeof(HttpRequest*));
    if (!requests) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t count = 0;
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        HttpRequest* request = parse_line(buffer);
        if (request) {
            requests[count++] = request;
        }
    }

    for (size_t i = 0; i < count; i++) {
        printf("%s,%s,%d\n", requests[i]->ip, requests[i]->time, requests[i]->status_code);
        free(requests[i]);
    }

    free(requests);
}

int main() {
    FILE* file = fopen("server.log", "r");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    size_t chunk_size = 1000; // Adjust chunk size as needed
    while (1) {
        process_chunk(file, chunk_size);
        if (feof(file)) {
            break;
        }
        fseek(file, -1L, SEEK_CUR); // Move back one character to read the new line separator
    }

    fclose(file);
    return 0;
}
```
