        std::unique_lock<std::mutex> lock(mutex);
        this->health = health;
        this->energy = energy;
        this->distanceToEnemy = distanceToEnemy;
        this->weaponDurability = weaponDurability;
    }

    void Attack() const {
        std::lock_guard<std::mutex> lock(mutex);
        if (allAttacksOnCooldown()) {
            PerformDefaultAction();
            return;
        }
        auto attack = SelectAttack();
        std::cout << "Character attacks with " << attack.second << " damage." << std::endl;
        SetAttackCooldown(attack.first);
    }

