        std::lock_guard<std::mutex> lock(mutex);
        cooldowns[attackIndex - 1] = true;
        std::this_thread::sleep_for(std::chrono::seconds(attacks.at(attackIndex).second));
        cooldowns[attackIndex - 1] = false;
