```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionService
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public DecryptionService(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 24)
            throw new ArgumentException("Key must be exactly 24 bytes long.");
        if (iv == null || iv.Length != 8)
            throw new ArgumentException("IV must be exactly 8 bytes long.");

        _key = key;
        _iv = iv;
    }

    public string DecryptAndValidate(string base64EncryptedMessage, byte[] hmacKey)
    {
        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = _key;
            tdes.IV = _iv;

            // Split the encrypted message into data and HMAC
            int hmacLength = 32; // HMAC-SHA256 length
            byte[] encryptedData = Convert.FromBase64String(base64EncryptedMessage);
            byte[] receivedHmac = new byte[hmacLength];
            Array.Copy(encryptedData, encryptedData.Length - hmacLength, receivedHmac, 0, hmacLength);
            byte[] actualData = new byte[encryptedData.Length - hmacLength];
            Array.Copy(encryptedData, 0, actualData, 0, encryptedData.Length - hmacLength);

            using (HMACSHA256 hmac = new HMACSHA256(hmacKey))
            {
                byte[] calculatedHmac = hmac.ComputeHash(actualData);

                if (!ConstantTimeComparison.Equals(receivedHmac, calculatedHmac))
                    throw new AuthenticationException("Message authentication failed.");
            }

            // Decrypt the data
            ICryptoTransform decryptor = tdes.CreateDecryptor(_key, _iv);
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write))
                {
                    cs.Write(actualData, 0, actualData.Length);
                }
                return Encoding.UTF8.GetString(ms.ToArray());
            }
        }
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        byte[] key = Convert.FromBase64String("your-24-byte-key-here");
        byte[] iv = Convert.FromBase64String("your-8-byte-iv-here");
        byte[] hmacKey = Convert.FromBase64String("your-hmac-key-here");

        DecryptionService decryptionService = new DecryptionService(key, iv);

        string base64EncryptedMessage = "your-base64-encoded-message-here";
        try
        {
            string decryptedMessage = await Task.Run(() => decryptionService.DecryptAndValidate(base64EncryptedMessage, hmacKey));
            Console.WriteLine("Decrypted Message: " + decryptedMessage);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }
}
```

This code defines a `DecryptionService` class that handles the decryption and validation of Base64-encoded messages using Triple DES encryption and HMAC-SHA256 for authentication. The `DecryptAndValidate` method takes a Base64-encoded message, decrypts it, and validates its authenticity before returning the decrypted string. If the validation fails, it throws an `AuthenticationException`.

The `Main` method demonstrates how to use this service by creating an instance of `DecryptionService`, calling the `DecryptAndValidate` method with a sample encrypted message, and handling any exceptions that might occur during decryption or validation.

To implement caching mechanisms for frequently decrypted messages, consider using a distributed cache like Redis or Memcached. For logging and metrics collection, integrate with your application's monitoring system (e.g., Prometheus, Grafana). To handle multiple tenants, pass the tenant-specific keys and IVs as parameters to the `DecryptionService` constructor.

Remember to follow best practices for secure key management, such as using environment variables or a secure vault for storing cryptographic keys. Implement key rotation strategies and ensure that keys are securely transmitted and stored.

