s3_client = boto3.client('s3')

def upload_file_to_s3(file_name, file_size, metadata, bucket_name):
    try:
        s3_client.upload_file(file_name, bucket_name, file_name, ExtraArgs={'Metadata': metadata})
        return {'success': True, 'message': 'File uploaded successfully'}
    except FileNotFoundError:
        return {'success': False, 'message': 'The file was not found'}
    except NoCredentialsError or PartialCredentialsError:
        return {'success': False, 'message': 'Credentials not available'}
    except Exception as e:
        return {'success': False, 'message': f'An error occurred: {str(e)}'}

def notify_clients(file_name):
    # Notify all connected clients via WebSocket
    pass

def handle_file_upload(file_name, file_size, metadata, bucket_name):
    result = upload_file_to_s3(file_name, file_size, metadata, bucket_name)
    if result['success']:
        notify_clients(file_name)
    return result
