```javascript
// Import necessary libraries
const fetch = require('node-fetch'); // Mock or real API call library

// Semaphore implementation
class Semaphore {
    constructor(max) {
        this.max = max;
        this.current = 0;
        this.queue = [];
    }

    acquire() {
        return new Promise((resolve, reject) => {
            if (this.current < this.max) {
                this.current++;
                resolve();
            } else {
                this.queue.push({ resolve });
            }
        });
    }

    release() {
        if (this.queue.length > 0) {
            const next = this.queue.shift();
            next.resolve();
        } else {
            this.current--;
        }
    }
}

// Mock external API call function
async function mockApiCall(number, callback) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            try {
                const result = callback(number);
                resolve(result);
            } catch (error) {
                reject(error);
            }
        }, 100); // Simulate a delay of 100ms
    });
}

// asyncArrayReduce function
async function asyncArrayReduce(arr, initialValue, reducerCallback, maxConcurrentRequests = 5) {
    const semaphore = new Semaphore(maxConcurrentRequests);
    let result = initialValue;

    try {
        for (const number of arr) {
            await semaphore.acquire();
            try {
                result = await mockApiCall(number, (num) => reducerCallback(result, num));
            } catch (error) {
                console.error(`Error processing ${number}:`, error);
                throw new Error(`Failed to reduce array: ${error.message}`);
            } finally {
                semaphore.release();
            }
        }
    } catch (error) {
        return Promise.reject(error);
    }

    return result;
}

// Example usage
const numbers = Array.from({ length: 1000000 }, (_, i) => i + 1);
const initialValue = 0;
const reducerCallback = (acc, num) => acc + num;

asyncArrayReduce(numbers, initialValue, reducerCallback)
    .then(result => console.log('Reduced value:', result))
    .catch(error => console.error('Error:', error));
```

