// Rust HTTP client module

extern crate reqwest;

use reqwest::{Client, Error};

#[derive(Debug)]
struct Config {
    base_url: String,
    certificate_path: Option<String>,
}

impl Config {
    fn new(base_url: &str, certificate_path: Option<&str>) -> Self {
        Config {
            base_url: base_url.to_string(),
            certificate_path,
        }
    }

    async fn make_request(&self, endpoint: &str) -> Result<reqwest::Response, Error> {
        let client = Client::new();
        if let Some(path) = self.certificate_path {
            client
                .post(format!("{}/{}", self.base_url, endpoint))
                .timeout(std::time::Duration::from_secs(10))
                .send()
                .await?
        } else {
            client
                .post(format!("{}/{}", self.base_url, endpoint))
                .timeout(std::time::Duration::from_secs(10))
                .send()
                .await?
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let config = Config::new("https://api.example.com", Some("/path/to/certificate.crt"));
    let response = config.make_request("/data").await?;
    println!("{:?}", response);
    Ok(())
}
