use std::fs::{self, File};
use std::path::Path;
use std::time::{Duration, SystemTime};
use log::{info, error};

const CACHE_CLEANUP_INTERVAL: Duration = Duration::from_secs(86400); // 24 hours

fn create_or_get_cache_dir(cache_name: &str) -> Result<String, String> {
    let cache_path = Path::new(&cache_name);
    if !cache_path.exists() {
        fs::create_dir_all(cache_path).map_err(|e| format!("Failed to create cache directory: {}", e))?;
    }
    Ok(cache_path.to_str().unwrap().to_string())
}

fn set_cache_env_var(cache_path: &str) {
    std::env::set_var("CACHE_DIR", cache_path);
}

fn clean_old_files(cache_path: &str, keep_duration: Duration) -> Result<(), String> {
    let now = SystemTime::now();
    for entry in fs::read_dir(cache_path).map_err(|e| format!("Failed to read cache directory: {}", e))? {
        let entry = entry.map_err(|e| format!("Failed to read directory entry: {}", e))?;
        if let Ok(file_type) = entry.file_type() {
            if file_type.is_file() {
                if let Ok(metadata) = fs::metadata(entry.path()) {
                    if let Ok(last_modified) = metadata.modified() {
                        if now.duration_since(last_modified).map_err(|e| format!("Failed to get file modification time: {}", e))? > keep_duration {
                            fs::remove_file(&entry.path()).map_err(|e| format!("Failed to remove old file: {}", e))?;
                            info!("Removed old file: {:?}", entry.path());
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

fn manage_cache_directory(cache_name: &str) -> Result<(), String> {
    let cache_path = create_or_get_cache_dir(cache_name)?;
    set_cache_env_var(&cache_path);
    clean_old_files(&cache_path, CACHE_CLEANUP_INTERVAL)?;
    info!("Cache directory managed successfully.");
    Ok(())
}

fn main() {
    if let Err(e) = manage_cache_directory("my_cache") {
        error!("{}", e);
    }
}
