from typing import Dict, Tuple
import time
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

class DatabaseManager:
    def __init__(self, db_config: Dict):
        # Initialize database connection using provided configuration
        pass

    def record_transaction(self, transaction_id: str, details: str) -> Tuple[bool, int]:
        # Record transaction details to the database
        pass

class LogFileManager:
    def __init__(self, log_config: Dict):
        # Initialize log file handle using provided configuration
        pass

    def record_transaction(self, transaction_id: str, details: str) -> Tuple[bool, int]:
        # Record transaction details to the log file
        pass

def processAndRecordTransaction(should_record: bool, record_type: str, transaction_details: Dict, config: Dict, *args) -> Tuple:
    try:
        payment_gateway_url = config['payment_gateway_url']
        db_config = config.get('db_config', {})
        log_config = config.get('log_config', {})

        with ThreadPoolExecutor(max_workers=2) as executor:
            future_payment = executor.submit(processPaymentTransaction, payment_gateway_url, transaction_details)
            future_record = None

            if should_record:
                record_class = DatabaseManager if record_type == 'database' else LogFileManager
                record_manager = record_class(record_config)
                future_record = executor.submit(record_transaction, record_manager, transaction_details)

            payment_result, payment_code = future_payment.result()

            if should_record and payment_code == 0:
                _, record_code = future_record.result() if future_record else (False, -1)
                return payment_result, payment_code, record_code

            return payment_result, payment_code

    except Exception as e:
        # Handle general exceptions
        print(f"An error occurred: {e}")
        return False, -2

def processPaymentTransaction(payment_gateway_url: str, transaction_details: Dict) -> Tuple[bool, int]:
    headers = {'Content-Type': 'application/json'}
    response = requests.post(payment_gateway_url, json=transaction_details, headers=headers)

    if response.status_code == 200:
        return True, 0
    elif response.status_code == 429:
        # Handle rate limit exceeded
        return False, -1
    else:
        return False, response.status_code

def record_transaction(record_manager: DatabaseManager or LogFileManager, transaction_details: Dict) -> Tuple[bool, int]:
    try:
        if isinstance(record_manager, DatabaseManager):
            return record_manager.record_transaction(transaction_details['transaction_id'], str(transaction_details))
        elif isinstance(record_manager, LogFileManager):
            return record_manager.record_transaction(transaction_details['transaction_id'], str(transaction_details))
        else:
            raise ValueError("Unsupported record manager type")
    except Exception as e:
        # Handle exceptions during recording
        print(f"Failed to record transaction: {e}")
        return False, -2
