from flask import Flask, request, jsonify
from functools import wraps
import logging
import time

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

# Mock database
resources = {
    '1': {'id': '1', 'name': 'Resource 1'},
    '2': {'id': '2', 'name': 'Resource 2'}
}

# Authentication decorator (mock)
def authenticate(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Simulate authentication
        if request.headers.get('Authorization') == 'Bearer valid_token':
            return f(*args, **kwargs)
        else:
            return jsonify({'error': 'Unauthorized'}), 401
    return decorated_function

# Caching decorator (mock)
def cache(max_age=60):
    def wrapper(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            # Simulate caching
            response = f(*args, **kwargs)
            response.headers['Cache-Control'] = f'max-age={max_age}'
            return response
        return decorated_function
    return wrapper

# Soft delete decorator (mock)
def soft_delete(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Simulate soft delete
        result = f(*args, **kwargs)
        if 'deleted' in result:
            resources[result['id']]['deleted'] = True
            return jsonify({'message': 'Resource deleted'}), 204
        else:
            return result
    return decorated_function

# Error handling decorator (mock)
def error_handler(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        try:
            return f(*args, **kwargs)
        except KeyError as e:
            return jsonify({'error': f'Invalid ID: {e}'}), 404
        except Exception as e:
            app.logger.error(f'Error: {e}')
            return jsonify({'error': 'Internal server error'}), 500
    return decorated_function

# Request validation decorator (mock)
def validate_request(required_fields):
    def wrapper(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            data = request.json
            if not all(field in data for field in required_fields):
                return jsonify({'error': f'Missing required fields: {required_fields}'}), 400
            return f(*args, **kwargs)
        return decorated_function
    return wrapper

@app.route('/resource/<id>', methods=['PUT'])
@authenticate
@cache(max_age=30)
@soft_delete
@error_handler
def update_resource(id):
    data = request.json
    if 'name' in data:
        resources[id]['name'] = data['name']
    else:
        return jsonify({'error': 'No updates provided'}), 400
    return jsonify(resources[id]), 200

@app.route('/resource/<id>', methods=['DELETE'])
@authenticate
@cache(max_age=30)
@soft_delete
@error_handler
def delete_resource(id):
    if id not in resources:
        return jsonify({'error': 'Resource not found'}), 404
    else:
        resources[id]['deleted'] = True
        return jsonify({'message': 'Resource deleted'}), 204

if __name__ == '__main__':
    app.run(debug=True)
```

This code snippet provides a basic implementation of the required functionality. It includes decorators for authentication, caching, soft deletion, error handling, request validation, and logging. The `update_resource` function handles PUT requests to update an existing resource, while the `delete_resource` function handles DELETE requests to delete a resource.

