<?php

// Microservice for e-commerce platform user account management

class UserAccountManager {
    private $db;
    private $authSystem;
    private $paymentGateway;
    private $emailVerificationService;

    public function __construct($db, $authSystem, $paymentGateway, $emailVerificationService) {
        $this->db = $db;
        $this->authSystem = $authSystem;
        $this->paymentGateway = $paymentGateway;
        $this->emailVerificationService = $emailVerificationService;
    }

    public function createUser($name, $email, $password, $role, $mfaToken) {
        if ($this->db->isEmailUnique($email)) {
            $userId = $this->db->createUser($name, $email, $password, $role);
            if ($this->authSystem->verifyMFA($email, $mfaToken)) {
                $this->emailVerificationService->sendVerificationEmail($email);
                return [
                    "status" => "success",
