// Define a class for Religious Text Analyzer
class ReligiousTextAnalyzer {
    constructor() {
        // Regular expressions for different religious texts
        this.bibleRegex = /(?:\b\bible\b)|(?:(?:the|a)\s+bible\s*)/i;
        this.quranRegex = /(?:\bquran\b)|(?:the\s+quran\s*)/i;
        this.torahRegex = /(?:\btora\b)|(?:the\s+tora\s*)/i;
        this.vedasRegex = /(?:\bvedas\b)|(?:(?:the|a)\s+vedas\s*)/i;

        // Caching mechanism for previously analyzed texts
        this.cache = new Map();

        // Registry of factory functions for subclasses
        this.factoryFunctions = new Map();
    }

    // Method to extract book names from text
    extractBooks(text) {
        if (typeof text !== 'string' || text.trim() === '') {
            throw new Error('Invalid input: Text must be a non-empty string');
        }

        let books = [];
        if (this.bibleRegex.test(text)) books.push('Bible');
        if (this.quranRegex.test(text)) books.push('Quran');
        if (this.torahRegex.test(text)) books.push('Torah');
        if (this.vedasRegex.test(text)) books.push('Vedas');

        return books;
    }

    // Method to categorize extracted books
    categorizeBooks(books) {
        let categorized = {};
        for (let book of books) {
            switch (book.toLowerCase()) {
                case 'bible':
                    categorized.Bible = (categorized.Bible || 0) + 1;
                    break;
                case 'quran':
                    categorized.Quran = (categorized.Quran || 0) + 1;
                    break;
                case 'torah':
                    categorized.Torah = (categorized.Torah || 0) + 1;
                    break;
                case 'vedas':
                    categorized.Vedas = (categorized.Vedas || 0) + 1;
                    break;
            }
        }

        return categorized;
    }

    // Method to run tests for the analyzer
    static async runTests(moduleLabel, testLabels, testFunctions) {
        try {
            const module = require(moduleLabel);

            for (let i = 0; i < testLabels.length; i++) {
                await testFunctions[i]();
                blueslip.reset(); // Reset mocking library after each test
            }

            console.log('All tests completed successfully');
        } catch (error) {
            console.error(`Test failed: ${testLabels[i]} - Error: ${error.message}`);
        }
    }

    // Method to generate reports based on analysis
    generateReports(categorizedBooks, format) {
        let report = '';

        if (format === 'csv') {
            report += 'Book,Count\n';
            for (let [book, count] of Object.entries(categorizedBooks)) {
                report += `${book},${count}\n`;
            }
        } else if (format === 'json') {
            report = JSON.stringify(categorizedBooks, null, 2);
        }

        return report;
    }
}

// Example usage
const analyzer = new ReligiousTextAnalyzer();
let text = "The Bible says love thy neighbor.";
try {
    let books = analyzer.extractBooks(text);
    console.log(books); // Output: ['Bible']

    let categorizedBooks = analyzer.categorizeBooks(books);
    console.log(categorizedBooks); // Output: { 'Bible': 1 }

    let report = analyzer.generateReports(categorizedBooks, 'json');
    console.log(report);
} catch (error) {
    console.error(error.message);
}
