class WeatherDataFetcher {
  constructor(apiKeys, apiUrls) {
    this.apiKeys = apiKeys;
    this.apiUrls = apiUrls;
    this.currentKeyIndex = 0;
    setInterval(() => this.rotateAPIKey(), 12 * 60 * 60 * 1000);
  }

  async fetchWeather(location) {
    const key = this.apiKeys[this.currentKeyIndex];
    try {
      for (const url of this.apiUrls) {
        const response = await fetch(`${url}?q=${location}&appid=${key}`);
        if (response.ok) {
          const data = await response.json();
          return this.processWeatherData(data);
        } else {
          console.error(`API ${url} returned error: ${response.status}`);
        }
      }
    } catch (error) {
      console.error('Error fetching weather:', error);
    }
    throw new Error('Failed to fetch weather data');
  }

  rotateAPIKey() {
    this.currentKeyIndex = (this.currentKeyIndex + 1) % this.apiKeys.length;
  }

  processWeatherData(data) {
    // Standardize the data format here
    return {
      current: {
        temperature: data.main.temp,
        description: data.weather[0].description
      },
      forecast: data.list.map(item => ({
        date: item.dt_txt,
        temperature: item.main.temp
      }))
    };
  }
}

