using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Xml.XPath;

public class XmlDocumentCache
{
    private readonly ConcurrentDictionary<string, XPathNavigator> cache = new ConcurrentDictionary<string, XPathNavigator>();
    private readonly HttpClient httpClient;
    private readonly string[] sources;
    private readonly int cacheSize;
    private readonly ILoggingService loggingService;

    public XmlDocumentCache(string[] sources, int cacheSize, ILoggingService loggingService)
    {
        this.sources = sources;
        this.cacheSize = cacheSize;
        this.loggingService = loggingService;
        httpClient = new HttpClient();
    }

    public XPathNavigator GetDocument(string uri, string xpathQuery, TimeSpan timeout)
    {
        try
        {
            if (cache.TryGetValue(uri, out var navigator))
            {
                return navigator.Clone();
            }

            var document = LoadDocumentFromSource(uri, timeout);
            var navigator = document.CreateNavigator();

            lock (cache)
            {
                if (cache.Count >= cacheSize)
                {
                    cache.Remove(cache.Keys.First(), out _); // Simple eviction policy
                }
                cache.TryAdd(uri, navigator.Clone());
            }

            return navigator;
        }
        catch (Exception ex)
        {
            loggingService.LogError(ex.Message);
            throw new XPathException("Error processing XML document or executing XPath query.");
        }
    }

    private XmlDocument LoadDocumentFromSource(string uri, TimeSpan timeout)
    {
        if (uri.StartsWith("http"))
        {
            var response = httpClient.GetAsync(uri, HttpCompletionOption.ResponseHeadersRead).GetAwaiter().GetResult();
            return new XmlDocument { XmlResolver = null }.Load(response.Content.ReadAsStream());
        }
        else
        {
            using var reader = File.OpenText(uri);
            return new XmlDocument { XmlResolver = null }.Load(reader);
        }
    }

    public XPathNodeIterator SelectNodes(string xpathQuery, XPathNavigator navigator)
    {
        try
        {
            return navigator.Select(xpathQuery);
        }
        catch (XmlNamespaceNotResolvedException ex)
        {
            loggingService.LogError(ex.Message);
            throw new XPathException("XPath query contains unresolved namespace.");
        }
    }
}

public interface ILoggingService
{
    void LogError(string message);
}
