import jwt
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend
from datetime import datetime, timedelta
import asyncio
import aiohttp

class JWTProcessor:
    def __init__(self, secret_key_path, public_key_path, key_refresh_interval):
        self.secret_key = self.load_private_key(secret_key_path)
        self.public_key = self.load_public_key(public_key_path)
        self.key_refresh_interval = key_refresh_interval
        self.keys_last_refreshed = None

    async def process_jwt_batch(self, jwt_batch, algorithms, encryption_algorithms):
        if not self.keys_last_refreshed or (datetime.now() - self.keys_last_refreshed > timedelta(seconds=self.key_refresh_interval)):
            await self.refresh_keys()

        results = []
        for token in jwt_batch:
            try:
                payload = self.decode_and_verify_token(token, algorithms)
                decrypted_payload = self.decrypt_payload(payload, encryption_algorithms)
                if self.validate_payload(decrypted_payload):
                    external_validation_result = await self.validate_with_external_service(decrypted_payload)
                    results.append((True, external_validation_result))
                else:
                    results.append((False, "Payload validation failed"))
            except Exception as e:
                results.append((False, str(e)))
        return results

    def decode_and_verify_token(self, token, algorithms):
        try:
            payload = jwt.decode(token, self.secret_key, algorithms=algorithms)
            if 'exp' in payload and datetime.utcnow() > datetime.utcfromtimestamp(payload['exp']):
                raise ValueError("Token has expired")
            return payload
        except jwt.ExpiredSignatureError:
            raise Exception("JWT has expired")
        except jwt.InvalidTokenError as e:
            raise Exception(f"Invalid JWT: {e}")

    def decrypt_payload(self, payload, encryption_algorithms):
        try:
            decrypted_data = padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None
            ).decrypt(payload['encrypted_payload'], self.public_key, backend=default_backend())
            return decrypted_data.decode('utf-8')
        except Exception as e:
            raise Exception(f"Failed to decrypt payload: {e}")

    def validate_payload(self, payload):
        # Add your validation logic here
        if 'claim' in payload and payload['claim'] != 'expected_value':
            return False
        return True

    async def validate_with_external_service(self, payload):
        async with aiohttp.ClientSession() as session:
            response = await session.post('https://auth.example.com/validate', json=payload)
            if response.status == 200:
                return await response.json()
            else:
                raise Exception(f"External service validation failed with status code: {response.status}")

    def load_private_key(self, key_path):
        with open(key_path, "rb") as key_file:
            private_key = serialization.load_pem_private_key(
                key_file.read(),
                password=None,
                backend=default_backend()
            )
        return private_key

    def load_public_key(self, key_path):
        with open(key_path, "rb") as key_file:
            public_key = serialization.load_pem_public_key(
                key_file.read(),
                backend=default_backend()
            )
        return public_key

    async def refresh_keys(self):
        # Implement your logic to refresh keys from a secure key server here
        self.keys_last_refreshed = datetime.now()

# Example usage
processor = JWTProcessor("secret_key.pem", "public_key.pem", 3600)
jwt_batch = ["token1", "token2"]
algorithms = ['HS256', 'HS384', 'HS512']
encryption_algorithms = ['RSA']
results = asyncio.run(processor.process_jwt_batch(jwt_batch, algorithms, encryption_algorithms))
print(results)
