        payload = Payload(alert=message, sound="default", badge=1)
        frame = Frame()
        frame.add_item(token_hex=device_token, payload=payload)
        return apns.gateway_server.send_notification_multiple(frame)

    def _send_fcm(self, device_token, message):
        fcm = FCM('your_fcm_server_key')
        response = fcm.notify_single_device(registration_id=device_token, message=message)
        return response

