```
// This is a high-level design overview in Go that demonstrates key components of a scalable chat application.

package main

import (
	"fmt"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/go-redis/redis/v8"
	"github.com/streadway/amqp"
)

var rdb *redis.Client
var conn *amqp.Connection

func init() {
	// Initialize Redis and RabbitMQ connections
	rdb = redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "", // no password set
		DB:       0,  // use default DB
	})
	conn, _ = amqp.Dial("amqp://guest:guest@localhost:5672/")
}

func main() {
	r := gin.Default()

	r.GET("/channels", listChannels)
	r.POST("/channels", createChannel)
	r.DELETE("/channels/:id", deleteChannel)

	r.GET("/users/me/connected_channels", getConnectedChannels)
	r.POST("/users/me/subscriptions", subscribeToChannel)
	r.DELETE("/users/me/subscriptions/:channel_id", unsubscribeFromChannel)

	r.POST("/messages", sendMessage)
	r.GET("/messages/user/:user_id", getUserMessages)

	// Start background workers
	go processBackgroundJobs()

	http.ListenAndServe(":8080", r)
}

func listChannels(c *gin.Context) {
	// List all channels from Redis
	channels, _ := rdb.Keys(context.Background(), "channel:*").Result()
	c.JSON(http.StatusOK, gin.H{"channels": channels})
}

func createChannel(c *gin.Context) {
	var channel struct {
		ID    string `json:"id"`
		Name  string `json:"name"`
		Members []string `json:"members"`
	}
	if err := c.ShouldBindJSON(&channel); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// Create channel in Redis and RabbitMQ
	rdb.Set(context.Background(), fmt.Sprintf("channel:%s", channel.ID), channel.Name, 0)
	ch, _ := conn.Channel()
	ch.QueueDeclare(channel.ID, true, false, false, nil)

	c.JSON(http.StatusOK, gin.H{"message": "Channel created"})
}

func deleteChannel(c *gin.Context) {
	channelID := c.Param("id")

	// Delete channel from Redis and RabbitMQ
	rdb.Del(context.Background(), fmt.Sprintf("channel:%s", channelID))
	ch, _ := conn.Channel()
	ch.QueueDelete(channelID, true, false, false)

	c.JSON(http.StatusOK, gin.H{"message": "Channel deleted"})
}

func getConnectedChannels(c *gin.Context) {
	// Retrieve connected channels for the user from Redis
	userID := c.GetString("user_id")
	channels, _ := rdb.Keys(context.Background(), fmt.Sprintf("channel:%s:*", userID)).Result()
	c.JSON(http.StatusOK, gin.H{"channels": channels})
}

func subscribeToChannel(c *gin.Context) {
	var subscription struct {
		ChannelID string `json:"channel_id"`
	}
	if err := c.ShouldBindJSON(&subscription); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	userID := c.GetString("user_id")
	key := fmt.Sprintf("channel:%s:%s", subscription.ChannelID, userID)

	// Subscribe user to channel in Redis and RabbitMQ
	rdb.Set(context.Background(), key, "subscribed", 0)
	ch, _ := conn.Channel()
	ch.QueueBind(subscription.ChannelID, key, "", false, nil)

	c.JSON(http.StatusOK, gin.H{"message": "User subscribed"})
}

func unsubscribeFromChannel(c *gin.Context) {
	userID := c.GetString("user_id")
	channelID := c.Param("channel_id")
	key := fmt.Sprintf("channel:%s:%s", channelID, userID)

	// Unsubscribe user from channel in Redis and RabbitMQ
	rdb.Del(context.Background(), key)
	ch, _ := conn.Channel()
	ch.QueueUnbind(key, channelID, "", nil)

	c.JSON(http.StatusOK, gin.H{"message": "User unsubscribed"})
}

func sendMessage(c *gin.Context) {
	var message struct {
		ChannelID string `json:"channel_id"`
		SenderID  string `json:"sender_id"`
		Content   string `json:"content"`
	}
	if err := c.ShouldBindJSON(&message); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// Publish message to RabbitMQ and store in Redis for persistence
	ch, _ := conn.Channel()
	ch.Publish("", message.ChannelID, false, false, amqp.Publishing{
		ContentType: "text/plain",
		Body:        []byte(message.Content),
	})

	rdb.LPush(context.Background(), fmt.Sprintf("messages:%s", message.ChannelID), message.Content)

	c.JSON(http.StatusOK, gin.H{"message": "Message sent"})
}

func getUserMessages(c *gin.Context) {
	userID := c.Param("user_id")

	// Retrieve messages for user from Redis
	messages, _ := rdb.LRange(context.Background(), fmt.Sprintf("messages:user:%s", userID), 0, -1).Result()
	c.JSON(http.StatusOK, gin.H{"messages": messages})
}

func processBackgroundJobs() {
	ch, _ := conn.Channel()

	msgChan, _ := ch.Consume(
		"background_jobs",
		"",
		true,
		false,
		false,
		false,
		nil,
	)

	for msg := range msgChan {
		fmt.Printf("Processing job: %s\n", msg.Body)
		// Process the job here
		time.Sleep(1 * time.Second) // Simulate job processing time
	}
}

func main() {
	r := gin.Default()

	r.GET("/channels", listChannels)
	r.POST("/channels", createChannel)
	r.DELETE("/channels/:id", deleteChannel)

	r.GET("/users/me/connected_channels", getConnectedChannels)
	r.POST("/users/me/subscriptions", subscribeToChannel)
	r.DELETE("/users/me/subscriptions/:channel_id", unsubscribeFromChannel)

	r.POST("/messages", sendMessage)
	r.GET("/messages/user/:user_id", getUserMessages)

	// Start background workers
	go processBackgroundJobs()

	http.ListenAndServe(":8080", r)
}
```

