use reqwest::{ClientBuilder, RequestBuilder, Error};
use std::time::Duration;
use tokio;

#[derive(Debug)]
enum HttpClientError {
    InvalidUrl,
    ConnectionFailed,
    SslHandshakeFailed,
    AuthenticationFailed,
}

async fn create_request_builder(
    url: &str,
    disable_ssl: bool,
    headers: Option<Vec<(&str, &str)>>,
    timeout: Duration,
    token: Option<&str>,
) -> Result<RequestBuilder, HttpClientError> {
    let mut client = ClientBuilder::new();

    if disable_ssl {
        client = client.dangerously_insecure_skip_tls_verify();
    }

    if let Some(headers) = headers {
        for (key, value) in headers {
            client = client.header(key, value);
        }
    }

    if let Some(token) = token {
        client = client.bearer_auth(token);
    }

    client
        .timeout(timeout)
        .get(url)
        .build()
        .map_err(|e| match e.kind() {
            reqwest::ErrorKind::Url(_) => HttpClientError::InvalidUrl,
            reqwest::ErrorKind::Connect(_) | reqwest::ErrorKind::RequestTimeout => {
                HttpClientError::ConnectionFailed
            }
            reqwest::ErrorKind::TlsHandshake(_) => HttpClientError::SslHandshakeFailed,
            _ => HttpClientError::AuthenticationFailed,
        })
}

#[tokio::main]
async fn main() -> Result<(), HttpClientError> {
    let url = "https://example.com";
    let timeout = Duration::from_secs(10);
    let headers = vec![("User-Agent", "MyClient/1.0")];
    let token = Some("my_token");

    let request_builder = create_request_builder(url, false, Some(headers), timeout, token).await?;

    // Use the request_builder to send a request
    let response = request_builder.send().await?;
    println!("Response status: {}", response.status());

    Ok(())
}
