// JavaScript code to load and execute multiple specified JavaScript files

class ScriptLoader {
  constructor(fileList = []) {
    this.fileList = fileList;
  }

  addFile(filePath) {
    this.fileList.push(filePath);
  }

  removeFile(filePath) {
    this.fileList = this.fileList.filter(file => file !== filePath);
  }

  async loadAndExecuteScripts() {
    for (const file of this.fileList) {
      try {
        const script = document.createElement('script');
        script.src = file;
        document.head.appendChild(script);

        return new Promise((resolve, reject) => {
          script.onload = resolve;
          script.onerror = () => reject(`Failed to load ${file}`);
        });
      } catch (error) {
        console.error(error);
      }
    }
  }

  // Additional methods for dynamic updates and resource management can be added here
}

// Example usage:
const loader = new ScriptLoader(['script1.js', 'script2.js']);
loader.loadAndExecuteScripts().then(() => {
  console.log('All scripts loaded and executed successfully');
}).catch(error => {
  console.error(error);
});
