```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import org.xml.sax.Attributes;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;

public class XMLUpdater {
    private ConcurrentHashMap<String, String> map;
    private String keyPrefix;
    private SAXParserFactory factory;

    public XMLUpdater(ConcurrentHashMap<String, String> map, String keyPrefix) {
        this.map = map;
        this.keyPrefix = keyPrefix;
        this.factory = SAXParserFactory.newInstance();
    }

    public void updateMapAsync(String xmlFilePath, UpdateConfig config) {
        new Thread(() -> {
            try (FileInputStream fis = new FileInputStream(xmlFilePath)) {
                SAXParser parser = factory.newSAXParser();
                XMLHandler handler = new XMLHandler(config);
                parser.parse(new InputSource(fis), handler);
            } catch (IOException | SAXException e) {
                System.err.println("Error parsing XML file: " + e.getMessage());
            }
        }).start();
    }

    private class XMLHandler extends DefaultHandler {
        private UpdateConfig config;
        private StringBuilder currentText;

        public XMLHandler(UpdateConfig config) {
            this.config = config;
            this.currentText = new StringBuilder();
        }

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
            currentText.setLength(0);
        }

        @Override
        public void characters(char[] ch, int start, int length) throws SAXException {
            currentText.append(ch, start, length);
        }

        @Override
        public void endElement(String uri, String localName, String qName) throws SAXException {
            if (config.isUpdateOnlyNewValues() && map.containsKey(keyPrefix + localName)) {
                return;
            }
            map.put(keyPrefix + localName, currentText.toString());
        }
    }

    public static class UpdateConfig {
        private boolean updateOnlyNewValues;

        public UpdateConfig(boolean updateOnlyNewValues) {
            this.updateOnlyNewValues = updateOnlyNewValues;
        }

        public boolean isUpdateOnlyNewValues() {
            return updateOnlyNewValues;
        }
    }
}
```

This code defines a class `XMLUpdater` with a method `updateMapAsync` that asynchronously updates a concurrent hash map with key-value pairs derived from an XML document. The `XMLHandler` class extends `DefaultHandler` and processes the XML events to populate the map, applying the provided key prefix and handling configuration options for updating only new values.

