use tokio_postgres::{Client, NoTls};
use std::env;
use std::process;

#[tokio::main]
async fn main() {
    let max_connections = env::var("MAX_CONNECTIONS")
        .unwrap_or_else(|_| "10".to_string())
        .parse::<usize>()
        .expect("Failed to parse MAX_CONNECTIONS as a number");

    let mut clients: Vec<Client> = vec![];

    for _ in 0..max_connections {
        match Client::connect("host=localhost user=postgres password=secret dbname=mydb", NoTls).await {
            Ok(client) => clients.push(client),
            Err(e) => eprintln!("Failed to connect to database: {}", e), process::exit(1),
        }
    }

    let identifier = std::env::args().nth(1)
        .expect("No identifier provided");

    for client in clients {
        tokio::spawn(async move {
            match get_user_data(&client, &identifier).await {
                Ok(data) => println!("User data: {:?}", data),
                Err(e) => eprintln!("Failed to retrieve user data: {}", e),
            }
        });
    }

    tokio::signal::ctrl_c().await.unwrap();
}

async fn get_user_data(client: &Client, identifier: &str) -> Result<sqlx::postgres::PgRow, sqlx::Error> {
    let row = sqlx::query_as::<_, sqlx::postgres::PgRow>("SELECT * FROM users WHERE id = $1")
        .bind(identifier)
        .fetch_one(client)
        .await?;

    Ok(row)
}
