import os
import importlib.util
from collections import defaultdict
from concurrent.futures import Lock

class DatabaseConnector:
    _registry = defaultdict(list)
    _lock = Lock()

    @classmethod
    def register_factory(cls, factory_function):
        def decorator(subclass):
            with cls._lock:
                cls._registry[subclass.__name__].append(factory_function)
            return subclass
        return decorator

    @classmethod
    def discover_subclasses(cls, directory):
        for filename in os.listdir(directory):
            if filename.endswith('.py'):
                module_name = filename[:-3]
                spec = importlib.util.spec_from_file_location(module_name, os.path.join(directory, filename))
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                for name, obj in module.__dict__.items():
                    if isinstance(obj, type) and issubclass(obj, DatabaseConnector) and obj != DatabaseConnector:
                        cls.register_factory(create_instance)(obj)

    @classmethod
    def create_instance(cls, config):
        connection_type = config.get('type')
        factories = cls._registry[connection_type]
        for factory in factories:
            instance = factory(config)
            if instance.is_valid_config(config):
                return instance
        raise ValueError("No valid factory found for the specified database type")

    def __init__(self, config):
        self.config = config

    def is_valid_config(self, config):
        # Add validation logic here
        return True

    def connect(self):
        # Connection establishment logic here
        pass

    def close(self):
        # Connection closure logic here
        pass

    def execute_query(self, query):
        # Query execution logic here
        pass

    def execute_transaction(self, transaction):
        # Transaction execution logic here
        pass

def create_instance(subclass):
    def factory(config):
        return subclass(config)
    return factory

# Example usage
if __name__ == "__main__":
    DatabaseConnector.discover_subclasses("path/to/subclasses")
    db_config = {"type": "custom", "host": "localhost", "port": 5432}
    db_connector = DatabaseConnector.create_instance(db_config)
    db_connector.connect()
    db_connector.execute_query("SELECT * FROM users")
    db_connector.close()
