```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
public class LoadBalancer {
    private Selector selector;
    private List<ServerSocketChannel> servers;
    private ByteBuffer buffer = ByteBuffer.allocate(2048);

    public LoadBalancer(int port) throws IOException {
        this.selector = Selector.open();
        this.servers = new ArrayList<>();

        // Create server socket channels and register them with the selector
        for (int i=0; i<3; i++) {
            ServerSocketChannel server = ServerSocketChannel.open();
            server.bind(new InetSocketAddress(port + i));
            server.configureBlocking(false);
            server.register(selector, SelectionKey.OP_ACCEPT);
            servers.add(server);
        }
    }

    public void run() throws IOException {
        while (true) {
            // Wait for events to occur
            selector.select();

            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();

                if (key.isAcceptable()) {
                    acceptConnection(key);
                } else if (key.isReadable()) {
                    handleRequest(key);
                }

                keys.remove();
            }
        }
    }

    private void acceptConnection(SelectionKey key) throws IOException {
        ServerSocketChannel server = (ServerSocketChannel) key.channel();
        SocketChannel client = server.accept();
        client.configureBlocking(false);

        // Find a server to forward the request to
        int index = selectServer();
        SocketChannel serverToForward = servers.get(index);

        // Register the client and server channels with the selector
        client.register(selector, SelectionKey.OP_READ);
        serverToForward.register(selector, SelectionKey.OP_WRITE);

        // Forward the connection information to the server
        buffer.clear();
        buffer.put((byte) index);
        buffer.flip();
        serverToForward.write(buffer);
    }

    private void handleRequest(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        int index = client.socket().getLocalPort() - servers.get(0).socket().getLocalPort();

        if (key.isReadable()) {
            // Read data from the client and forward it to the corresponding server
            buffer.clear();
            client.read(buffer);
            buffer.flip();
            servers.get(index).write(buffer);
        } else if (key.isWritable()) {
            // Forward data from the server back to the client
            buffer.clear();
            servers.get(index).read(buffer);
            buffer.flip();
            client.write(buffer);

            // Close the connection when done
            key.cancel();
            client.close();
        }
    }

    private int selectServer() {
        // Round-robin algorithm for selecting a server
        static int index = 0;
        return servers.get(index++ % servers.size()).socket().getLocalPort() - servers.get(0).socket().getLocalPort();
    }
}
```
This code creates a load balancer that listens on three ports and forwards incoming connections to one of the three registered servers using round-robin algorithm. It uses NIO Channels to handle multiple connections simultaneously.

