import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.MalformedJwtException;
import redis.clients.jedis.Jedis;
import java.util.concurrent.ConcurrentHashMap;

public class JwtProcessor {

    private final ConfigLoader configLoader;
    private final Jedis jedis;
    private final ExternalApiClient externalApiClient;
    private final ConcurrentHashMap<String, CachedToken> cache = new ConcurrentHashMap<>();

    public JwtProcessor(ConfigLoader configLoader, Jedis jedis, ExternalApiClient externalApiClient) {
        this.configLoader = configLoader;
        this.jedis = jedis;
        this.externalApiClient = externalApiClient;
    }

    public User extractUserInfo(String jwt) throws TokenValidationException {
        String cachedTokenKey = "token:" + jwt;
        CachedToken cachedToken = cache.get(cachedTokenKey);

        if (cachedToken != null && !isExpired(cachedToken)) {
            return cachedToken.getUserInfo();
        } else {
            try {
                Claims claims = validateJwt(jwt);
                User userInfo = extractUserInfoFromClaims(claims);
                cacheToken(jwt, userInfo);
                return userInfo;
            } catch (MalformedJwtException e) {
                throw new TokenValidationException("Invalid JWT format", e);
            }
        }
    }

    private Claims validateJwt(String jwt) throws TokenValidationException {
        String secretKey = configLoader.loadSecretKey();
        String issuer = configLoader.loadIssuer();
        String audience = configLoader.loadAudience();

        try {
            return Jwts.parser()
                .setSigningKey(secretKey)
                .requireSubject(issuer)
                .requireAudience(audience)
                .parseClaimsJws(jwt)
                .getBody();
        } catch (Exception e) {
            throw new TokenValidationException("Invalid JWT", e);
        }
    }

    private User extractUserInfoFromClaims(Claims claims) {
        String username = (String) claims.getSubject();
        String roles = (String) claims.get("roles");
        long expirationTime = claims.getExpiration().getTime();

        return new User(username, roles.split(","), expirationTime);
    }

    private void cacheToken(String jwt, User userInfo) {
        String cachedTokenKey = "token:" + jwt;
        jedis.setex(cachedTokenKey, 3600, userInfo.toString());
        cache.put(cachedTokenKey, new CachedToken(userInfo));
    }

    private boolean isExpired(CachedToken cachedToken) {
        return System.currentTimeMillis() > cachedToken.getExpirationTime();
    }

    private static class CachedToken {
        private final User user;
        private final long expirationTime;

        public CachedToken(User user) {
            this.user = user;
            this.expirationTime = System.currentTimeMillis() + 3600 * 1000; // Cache for 1 hour
        }

        public User getUserInfo() {
            return user;
        }

        public long getExpirationTime() {
            return expirationTime;
        }
    }

    private static class User {
        private final String username;
        private final String[] roles;
        private final long expirationTime;

        public User(String username, String[] roles, long expirationTime) {
            this.username = username;
            this.roles = roles;
            this.expirationTime = expirationTime;
        }

        @Override
        public String toString() {
            return "User{" +
                "username='" + username + '\'' +
                ", roles=" + java.util.Arrays.toString(roles) +
                ", expirationTime=" + expirationTime +
                '}';
        }
    }

    private static class TokenValidationException extends Exception {
        public TokenValidationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
