using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicTextProcessor
{
    private readonly string _apiUrl;
    private readonly ILogger _logger;
    private Dictionary<string, Func<byte[], byte[]>> _hashFunctions;

    public DynamicTextProcessor(string apiUrl, ILogger logger)
    {
        _apiUrl = apiUrl;
        _logger = logger;
        InitializeHashFunctions();
    }

    private void InitializeHashFunctions()
    {
        _hashFunctions = new Dictionary<string, Func<byte[], byte[]>>
        {
            { "MD5", data => MD5.Create().ComputeHash(data) },
            { "SHA1", data => SHA1.Create().ComputeHash(data) },
            { "SHA256", data => SHA256.Create().ComputeHash(data) }
        };
    }

    public string GetHash(string input, string hashAlgorithm)
    {
        if (string.IsNullOrEmpty(input)) throw new ArgumentException("Input cannot be null or empty.");
        if (!_hashFunctions.ContainsKey(hashAlgorithm)) throw new InvalidOperationException($"Unsupported hash algorithm: {hashAlgorithm}");

        byte[] data = Encoding.UTF8.GetBytes(input);
        byte[] result = _hashFunctions[hashAlgorithm](data);

        return BitConverter.ToString(result).Replace("-", "").ToLower();
    }

    public async Task<string> GetHashAsync(string input, string hashAlgorithm)
    {
        if (string.IsNullOrEmpty(input)) throw new ArgumentException("Input cannot be null or empty.");
        if (!_hashFunctions.ContainsKey(hashAlgorithm)) throw new InvalidOperationException($"Unsupported hash algorithm: {hashAlgorithm}");

        byte[] data = Encoding.UTF8.GetBytes(input);
        return BitConverter.ToString(await Task.Run(() => _hashFunctions[hashAlgorithm](data))).Replace("-", "").ToLower();
    }

    public string ProcessUserInput(string input, int maxAllowedLength, bool trim, bool capitalize)
    {
        if (input.Length > maxAllowedLength) throw new ArgumentOutOfRangeException("Input length exceeds maximum allowed length.");

        if (trim) input = input.Trim();
        if (capitalize) input = char.ToUpper(input[0]) + input.Substring(1);

        return input;
    }

    public async Task ProcessUserInputAsync(string input, int maxAllowedLength, bool trim, bool capitalize)
    {
        if (input.Length > maxAllowedLength) throw new ArgumentOutOfRangeException("Input length exceeds maximum allowed length.");

        if (trim) input = input.Trim();
        if (capitalize) input = char.ToUpper(input[0]) + input.Substring(1);

        await Task.CompletedTask; // Simulate async operation
    }

    public void ReportStatistics(Dictionary<string, List<double>> stats)
    {
        // Implement reporting logic here
    }

    public void LogPerformance(string methodName, TimeSpan elapsedTime)
    {
        _logger.Log(elapsedTime);
    }
}

public interface ILogger
{
    void Log(TimeSpan elapsedTime);
}
