from typing import Dict, Type, Any, Callable, List

class JSONBase(ABC):
    _registry: Dict[str, Callable[[str], 'JSONBase']] = {}

    @classmethod
    def register_factory(cls, func: Callable[[str], 'JSONBase']) -> Callable[[str], 'JSONBase']:
        cls._registry[func.__name__] = func
        return func

    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONBase':
        data = cls.validate_json(json_str)
        factory_id = data.get('factory_id')
        if factory_id not in cls._registry:
            raise ValueError(f"Unknown factory ID: {factory_id}")
        return cls._registry[factory_id](json_str)

    @staticmethod
    def validate_json(json_str: str) -> dict:
        try:
            import json
            data = json.loads(json_str)
            # Add your validation logic here
            if 'factory_id' not in data:
                raise ValueError("JSON string must contain a 'factory_id' field")
            return data
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON: {e}")

    @staticmethod
    def load_from_yaml(yaml_path: str) -> None:
        with open(yaml_path, 'r') as file:
            config = yaml.safe_load(file)
            for factory_id, func_path in config.items():
                module_name, func_name = func_path.rsplit('.', 1)
                module = __import__(module_name, fromlist=[func_name])
                func = getattr(module, func_name)
                JSONBase.register_factory(func)

    @staticmethod
    def save_to_file(file_path: str) -> None:
        config = {factory_id: f"{func.__module__}.{func.__name__}" for factory_id, func in JSONBase._registry.items()}
        with open(file_path, 'w') as file:
            yaml.dump(config, file)

class Registry:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._registry: Dict[str, Callable[[str], JSONBase]] = {}
        return cls._instance

    @classmethod
    def register_factory(cls, func: Callable[[str], JSONBase]) -> Callable[[str], JSONBase]:
        cls._registry[func.__name__] = func
        return func

def discover_subclasses(directory: str) -> None:
    for filename in os.listdir(directory):
        if filename.endswith('.py'):
            module_name = filename[:-3]
            __import__(module_name)
```

This code snippet defines a base class `JSONBase` and a registry class `Registry`. The base class includes methods for converting data to a JSON string, creating a new instance from a JSON string, and managing a factory registry. The registry supports dynamic registration of subclasses via the decorator pattern. Additional functionalities such as loading factory functions from a YAML file and saving the registry state are also provided.

