// Import necessary libraries
use tokio::net::TcpStream;
use tokio_postgres::{Client, NoTls};
use std::env;
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use std::sync::{Arc, Mutex};
use std::time::Duration;

#[derive(Debug)]
struct User {
    id: i32,
    name: String,
}

// Function to retrieve user data from the database
async fn get_user(client: &Client, user_id: i32) -> Result<User, tokio_postgres::Error> {
    let rows = client.query("SELECT id, name FROM users WHERE id = $1", &[&user_id]).await?;
    if let Some(row) = rows.first() {
        Ok(User {
            id: row.get(0),
            name: row.get(1),
        })
    } else {
        Err(tokio_postgres::Error::new("User not found"))
    }
}

// Command-line argument parsing
fn parse_args(args: &[String]) -> (i32, bool) {
    let user_id = args[1].parse::<i32>().unwrap();
    let sync_mode = env::var_os("SYNC_MODE").is_none();
    (user_id, sync_mode)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Connect to the database
    let client = Client::connect("host=localhost user=postgres password=password dbname=mydb", NoTls).await?;

    // Parse command-line arguments
    let (user_id, sync_mode) = parse_args(&env::args().collect());

    if sync_mode {
        // Synchronous mode
        match get_user(&client, user_id).await {
            Ok(user) => println!("User: {:?}", user),
            Err(e) => eprintln!("Error: {}", e),
        }
    } else {
        // Asynchronous mode using Tokio
        tokio::spawn(async move {
            match get_user(&client, user_id).await {
                Ok(user) => println!("User: {:?}", user),
                Err(e) => eprintln!("Error: {}", e),
            }
        });
    }

    // Start the HTTP server
    HttpServer::new(move || {
        App::new()
            .route("/user", web::post().to(|| async { HttpResponse::Ok().body("Hello, world!") }))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
