// Transaction recorder class
class TransactionRecorder {
private:
    DatabaseRecorder dbRecorder;
    LogRecorder logRecorder;
    PaymentProcessor paymentProcessors[3]; // Example for 3 processors

    std::mutex queueMutex;
    std::condition_variable cv;
    std::queue<std::string> transactionQueue;
    std::atomic<bool> stopProcessing{false};

public:
    void enqueueTransaction(const std::string& transaction) {
        std::lock_guard<std::mutex> lock(queueMutex);
        transactionQueue.push(transaction);
        cv.notify_one();
    }

    void processTransactions() {
        while (!stopProcessing.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this]{ return !transactionQueue.empty() || stopProcessing.load(); });
            if (stopProcessing.load()) break;

            std::string transaction = transactionQueue.front();
            transactionQueue.pop();

            lock.unlock();

            if (!recordTransaction(transaction)) {
                std::cerr << "Failed to record transaction: " << transaction << std::endl;
            }
        }
    }

    bool recordTransaction(const std::string& transaction) {
        for (int i = 0; i < 3; ++i) { // Try with multiple processors
            if (paymentProcessors[i].process(transaction, i)) {
                return true;
            }
        }
        return logRecorder.record(transaction);
    }

    void startProcessing() {
        std::thread t(&TransactionRecorder::processTransactions, this);
        t.detach();
    }

    ~TransactionRecorder() {
        stopProcessing.store(true);
        cv.notify_one();
    }
};

int main() {
    TransactionRecorder recorder;
    recorder.startProcessing();

    recorder.enqueueTransaction("Transaction 1");
    recorder.enqueueTransaction("Transaction 2");

    return 0;
}
