#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <getopt.h>

#define LOG_FILE "app.log"

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

void handle_sigint(int sig) {
    printf("Received termination signal. Exiting gracefully.\n");
    exit(EXIT_SUCCESS);
}

void print_usage(const char *progname) {
    fprintf(stderr, "Usage: %s [options] input_file\n", progname);
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  --help         Show this help message\n");
    fprintf(stderr, "  --verbose      Enable verbose mode\n");
    fprintf(stderr, "  -cs            Count characters instead of lines\n");
    fprintf(stderr, "  -o output_file Specify output file\n");
}

int main(int argc, char *argv[]) {
    int c;
    FILE *input = NULL;
    FILE *output = stdout;
    int count_lines = 1;
    int verbose = 0;
    int char_count = 0;

    signal(SIGINT, handle_sigint);

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"verbose", no_argument, 0, 'v'},
        {"char-count", no_argument, 0, 'c'},
        {"output", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    while ((c = getopt_long(argc, argv, "hvc:o:", long_options, &option_index)) != -1) {
        switch (c) {
            case 'h':
                print_usage(argv[0]);
                return EXIT_SUCCESS;
            case 'v':
                verbose = 1;
                break;
            case 'c':
                count_lines = 0;
                break;
            case 'o':
                output = fopen(optarg, "w");
                if (!output) {
                    perror("Failed to open output file");
                    log_message("Failed to open output file");
                    return EXIT_FAILURE;
                }
                break;
            default:
                print_usage(argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "No input file provided.\n");
        log_message("No input file provided");
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    input = fopen(argv[optind], "r");
    if (!input) {
        perror("Failed to open input file");
        log_message("Failed to open input file");
        return EXIT_FAILURE;
    }

    char buffer[1024];
    long count = 0;

    while (fgets(buffer, sizeof(buffer), input)) {
        if (count_lines)
            count++;
        else
            count += strlen(buffer);
    }

    fclose(input);

    if (output != stdout) {
        fprintf(output, "%ld\n", count);
        fclose(output);
    } else {
        printf("%ld\n", count);
    }

    return EXIT_SUCCESS;
}
