    // Cache implementation details here
    private RateLimiter rateLimiter;

    public HashService(int maxThreads, int cacheSize, RateLimiter rateLimiter) {
        this.executor = Executors.newFixedThreadPool(maxThreads);
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        this.rateLimiter = rateLimiter;
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public String[] computeHashes(String input, String encoding) throws Exception {
        // Input validation and rate limiting
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Invalid input string");
        }
        if (!rateLimiter.tryAcquire(encoding)) {
            throw new RateLimitException("Rate limit exceeded for encoding: " + encoding);
        }

        // Use caching mechanism
        String[] cachedHashes = cache.get(input);
        if (cachedHashes != null) {
            return cachedHashes;
        }

        // Compute hashes asynchronously
        Future<String[]> future = executor.submit(() -> {
            try {
                String md5 = computeMD5(input, encoding);
                String sha256 = computeSHA256(input, encoding);
                cache.put(input, new String[]{md5, sha256});
                return new String[]{md5, sha256};
            } catch (Exception e) {
                logger.error("Error computing hashes for input: {}", input, e);
                throw e;
            }
        });

        try {
            return future.get();
        } catch (InterruptedException | ExecutionException e) {
            if (e.getCause() instanceof Exception) {
                throw (Exception) e.getCause();
            } else {
                throw new Exception("Error computing hashes", e);
            }
        }
    }

    private String computeMD5(String input, String encoding) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        return bytesToHex(digest.digest(input.getBytes(encoding)));
    }

    private String computeSHA256(String input, String encoding) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        return bytesToHex(digest.digest(input.getBytes(encoding)));
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }
}
