#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 2048

typedef struct {
    int count;
    double sum;
} AverageData;

void readAndProcessFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        AverageData data = {0, 0};
        char *token = strtok(line, " ");
        int fieldIndex = 0;

        while (token != NULL) {
            if (fieldIndex >= 3) {
                break;
            }
            data.sum += atof(token);
            data.count++;
            token = strtok(NULL, " ");
            fieldIndex++;
        }

        if (data.count < 3) {
            printf("Skipping line with insufficient fields: %s", line);
        } else {
            double average = data.sum / data.count;
            printf("%.2f\n", average);
        }
    }

    free(line);
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    readAndProcessFile(argv[1]);

    return 0;
}
