using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureMessageHandler : IDisposable
{
    private ConcurrentDictionary<string, ICryptoServiceProvider> _cspCache;
    private HttpClient _kmsClient;
    private string _kmsBaseUri;

    public SecureMessageHandler(string kmsBaseUri)
    {
        _cspCache = new ConcurrentDictionary<string, ICryptoServiceProvider>();
        _kmsClient = new HttpClient();
        _kmsBaseUri = kmsBaseUri;
    }

    public void DecryptMessage(string base64EncodedMessage, string encryptionContext)
    {
        // Retrieve the appropriate CSP based on the encryption context
        var csp = GetCSP(encryptionContext);
        if (csp == null)
        {
            throw new Exception("No compatible CSP found for the given encryption context.");
        }

        try
        {
            byte[] encryptedData = Convert.FromBase64String(base64EncodedMessage);
            ICryptoTransform decryptor = csp.CreateDecryptor();
            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        string decryptedText = srDecrypt.ReadToEnd();
                        Console.WriteLine("Decrypted Message: " + decryptedText);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Error decrypting message.", ex);
        }
    }

    private ICryptoServiceProvider GetCSP(string encryptionContext)
    {
        if (!_cspCache.ContainsKey(encryptionContext))
        {
            // Simulate dynamic CSP retrieval based on encryption context
            var csp = CreateCSPFromContext(encryptionContext);
            _cspCache.TryAdd(encryptionContext, csp);
        }
        return _cspCache[encryptionContext];
    }

    private ICryptoServiceProvider CreateCSPFromContext(string encryptionContext)
    {
        // Implement logic to create and configure CSP based on the context
        if (encryptionContext.Contains("RSA"))
        {
            using (RSACryptoServiceProvider rsa = new RSACryptoServiceProvider())
            {
                // Configure RSA with parameters from KMS
                var keyMaterial = GetKeyMaterialFromKMS(encryptionContext);
                rsa.FromXmlString(keyMaterial);
                return rsa;
            }
        }
        else if (encryptionContext.Contains("AES"))
        {
            using (Aes aes = Aes.Create())
            {
                // Configure AES with parameters from KMS
                var keyAndIV = GetKeyAndIVFromKMS(encryptionContext);
                aes.Key = Convert.FromBase64String(keyAndIV.Key);
                aes.IV = Convert.FromBase64String(keyAndIV.IV);
                return aes;
            }
        }
        else
        {
            throw new Exception("Unsupported encryption context.");
        }
    }

    private string GetKeyMaterialFromKMS(string context)
    {
        // Implement logic to retrieve key material from KMS using HTTP GET request
        var response = _kmsClient.GetAsync($"{_kmsBaseUri}/key/{context}").Result;
        if (response.IsSuccessStatusCode)
        {
            return response.Content.ReadAsStringAsync().Result;
        }
        else
        {
            throw new Exception("Failed to retrieve key material from KMS.");
        }
    }

    private KeyAndIVResponse GetKeyAndIVFromKMS(string context)
    {
        // Implement logic to retrieve key and IV from KMS using HTTP GET request
        var response = _kmsClient.GetAsync($"{_kmsBaseUri}/key/{context}").Result;
        if (response.IsSuccessStatusCode)
        {
            return response.Content.ReadAsAsync<KeyAndIVResponse>().Result;
        }
        else
        {
            throw new Exception("Failed to retrieve key and IV from KMS.");
        }
    }

    public void Dispose()
    {
        _cspCache?.Clear();
        _kmsClient?.Dispose();
    }
}

public class KeyAndIVResponse
{
    public string Key { get; set; }
    public string IV { get; set; }
}
