            if (!$this->isServiceHealthy($service)) {
                $this->restartService($service);
            }
            // Send status update
            $this->sendStatusUpdate($service, 'Starting');
            $service['process'] = $this->startProcess($service['command']);
        }
    }

    public function stopServices() {
        foreach ($this->services as $service) {
            if (isset($service['process'])) {
                $this->stopProcess($service['process']);
                unset($service['process']);
                $this->sendStatusUpdate($service, 'Stopped');
