import os
import threading
from flask import Flask, request, send_file, abort
from werkzeug.utils import secure_filename
from cachetools import cached, TTLCache

app = Flask(__name__)
# Initialize cache with a maximum of 1000 items and each item lasts for 300 seconds (5 minutes)
cache = TTLCache(maxsize=1000, ttl=300)

def save_sticker(file):
    # Securely save the file to a directory
    filename = secure_filename(file.filename)
    filepath = os.path.join('stickers', filename)
    file.save(filepath)
    return filepath

@app.route('/upload', methods=['POST'])
@cache.cached(timeout=50)  # Cache the result of this function for 50 seconds
def upload_sticker():
    if 'file' not in request.files:
        abort(400, description="No file part")
    file = request.files['file']
    if file.filename == '':
        abort(400, description="No selected file")
    if file and allowed_file(file.filename):
        filepath = save_sticker(file)
        return {"message": "File uploaded successfully", "path": filepath}, 201
    else:
        abort(400, description="Invalid file type")

@app.route('/stickers/<filename>', methods=['GET'])
def get_sticker(filename):
    if filename not in cache:
        # Simulate fetching from a database or other storage
        cache[filename] = os.path.join('stickers', filename)
    filepath = cache[filename]
    if not os.path.exists(filepath):
        abort(404, description="File not found")
    return send_file(filepath, as_attachment=True)

def allowed_file(filename):
    # Check the file extension to allow only certain types
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in {'png', 'gif'}

if __name__ == '__main__':
    app.run(debug=True)
```

