struct DataCache {
    cache: HashMap<String, (Box<dyn std::any::Any>, Duration)>,
    lock: Mutex<()>,
}

impl DataCache {
    fn new() -> Self {
        Self {
            cache: HashMap::new(),
            lock: Mutex::new(()),
        }
    }

    async fn fetch_data<F, T>(&mut self, location: &str, interval: Duration, fetch_func: F) -> Result<T, String>
    where
        F: FnOnce() -> T,
    {
        let mut cache_lock = self.lock.lock().unwrap();
        if let Some((data, last_update)) = self.cache.get(location) {
            if let Ok(data) = data.downcast_ref::<T>() {
                if *last_update.elapsed() < interval {
                    return Ok(data.clone());
                }
            }
        }

        let new_data = fetch_func();
        let new_last_update = std::time::Instant::now();

        self.cache.insert(
            location.to_string(),
            (Box::new(new_data), new_last_update),
        );

        Ok(new_data)
    }
}

