```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DynamicLoadBalancer {
    private final int port;
    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final List<InetSocketAddress> servers;
    private Selector selector;

    public DynamicLoadBalancer(int port, List<String> serverAddresses) throws IOException {
        this.port = port;
        this.servers = new ArrayList<>();
        for (String addr : serverAddresses) {
            String[] parts = addr.split(":");
            servers.add(new InetSocketAddress(parts[0], Integer.parseInt(parts[1])));
        }
        selector = Selector.open();
    }

    public void start() throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        System.out.println("Load balancer started on port " + port);

        while (true) {
            selector.select();
            Set<SelectionKey> keys = selector.selectedKeys();
            Iterator<SelectionKey> iterator = keys.iterator();

            while (iterator.hasNext()) {
                SelectionKey key = iterator.next();
                if (!key.isValid()) continue;

                if (key.isAcceptable()) {
                    handleAccept(key);
                } else if (key.isReadable()) {
                    handleRead(key);
                }

                iterator.remove();
            }
        }
    }

    private void handleAccept(SelectionKey key) throws IOException {
        ServerSocketChannel serverSocketChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverSocketChannel.accept();
        clientChannel.configureBlocking(false);

        System.out.println("New client connected");

        // Choose a server to forward the connection to
        InetSocketAddress serverAddress = chooseServer();
        SocketChannel serverChannel = SocketChannel.open(serverAddress);
        serverChannel.configureBlocking(false);
        serverChannel.register(selector, SelectionKey.OP_WRITE, new ForwardingContext(clientChannel, serverChannel));
    }

    private void handleRead(SelectionKey key) throws IOException {
        ForwardingContext context = (ForwardingContext) key.attachment();
        SocketChannel sourceChannel;
        SocketChannel destinationChannel;

        if (key.channel() == context.clientChannel) {
            sourceChannel = context.clientChannel;
            destinationChannel = context.serverChannel;
        } else {
            sourceChannel = context.serverChannel;
            destinationChannel = context.clientChannel;
        }

        ByteBuffer buffer = ByteBuffer.allocate(8192);
        int bytesRead = sourceChannel.read(buffer);

        if (bytesRead == -1) {
            // Connection closed
            closeConnection(context);
        } else if (bytesRead > 0) {
            buffer.flip();
            destinationChannel.write(buffer);
        }
    }

    private InetSocketAddress chooseServer() {
        // Implement a simple round-robin strategy for server selection
        static int index = 0;
        return servers.get(index++ % servers.size());
    }

    private void closeConnection(ForwardingContext context) throws IOException {
        context.clientChannel.close();
        context.serverChannel.close();
        context.clientChannel.keyFor(selector).cancel();
        context.serverChannel.keyFor(selector).cancel();

        System.out.println("Connection closed");
    }

    private static class ForwardingContext {
        final SocketChannel clientChannel;
        final SocketChannel serverChannel;

        ForwardingContext(SocketChannel clientChannel, SocketChannel serverChannel) {
            this.clientChannel = clientChannel;
            this.serverChannel = serverChannel;
        }
    }

    public void stop() throws IOException {
        executorService.shutdownNow();
        selector.close();
    }

    public static void main(String[] args) {
        try (DynamicLoadBalancer loadBalancer = new DynamicLoadBalancer(8080, Arrays.asList("192.168.1.1:8081", "192.168.1.2:8082"))) {
            loadBalancer.start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
