```java
public void optimizeImageCompression(String inputFilePath, int targetFileSize, double maxQualityReduction) {
    try (BufferedImage originalImage = ImageIO.read(new File(inputFilePath))) {
        String formatName = getFormatName(originalImage);
        String outputFilePath = inputFilePath.replaceFirst("[.][^.]+$", ".optimized." + formatName);

        Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName(formatName);
        if (!writers.hasNext()) {
            throw new IllegalArgumentException("Unsupported image format: " + formatName);
        }

        ImageWriter writer = writers.next();
        ImageOutputStream outputStream = ImageIO.createImageOutputStream(new File(outputFilePath));
        writer.setOutput(outputStream);

        ImageWriteParam param = writer.getDefaultWriteParam();
        int quality = 100;
        boolean isCompressionSupported = param.canWriteCompressed() && param.getCompressionMode() != ImageWriteParam.MODE_DISABLED;

        while (isCompressionSupported && getImageFileSize(outputFilePath) > targetFileSize) {
            if (quality * maxQualityReduction / 100 >= quality) {
                throw new IllegalStateException("Cannot achieve the target file size without exceeding the maximum quality reduction.");
            }

            param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
            param.setCompressionQuality(quality / 100.0);

            writer.write(null, new IIOImage(originalImage, null, null), param);
            outputStream.flush();
            writer.dispose();

            if (getImageFileSize(outputFilePath) <= targetFileSize) {
                break;
            }

            quality--;
        }

        writer.setOutput(new File(outputFilePath));
        writer.write(null, new IIOImage(originalImage, null, null), param);
        outputStream.close();
    } catch (IOException e) {
        throw new RuntimeException("Failed to compress image", e);
    }
}

private String getFormatName(BufferedImage image) {
    if (image instanceof BufferedImage.TYPE_INT_RGB) {
        return "jpg";
    } else if (image instanceof BufferedImage.TYPE_INT_ARGB || image instanceof BufferedImage.TYPE_4BYTE_ABGR) {
        return "png";
    } else {
        throw new IllegalArgumentException("Unsupported image type: " + image.getClass().getName());
    }
}

private int getImageFileSize(String filePath) throws IOException {
    File file = new File(filePath);
    if (!file.exists()) {
        throw new FileNotFoundException("File not found: " + filePath);
    }
    return (int) file.length();
}
