```python
# Python script using Redis caching with an external weather API

import requests
import json
import redis
from datetime import timedelta, datetime
import time

# Initialize Redis connection
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

def get_weather(location):
    cache_key = f"weather:{location}"
    cached_data = redis_client.get(cache_key)

    if cached_data:
        return json.loads(cached_data.decode('utf-8'))

    api_url = f"http://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q={location}"
    response = requests.get(api_url)

    if response.status_code == 200:
        data = response.json()
        redis_client.setex(cache_key, timedelta(minutes=10), json.dumps(data))
        return data
    else:
        raise Exception("Failed to fetch weather data")

def invalidate_cache_for_location(location):
    cache_key = f"weather:{location}"
    if redis_client.exists(cache_key):
        redis_client.delete(cache_key)

# Example usage
try:
    location = "New York"
    weather_data = get_weather(location)
    print(weather_data)
except Exception as e:
    print(e)

# Invalidate cache for a specific location
invalidate_cache_for_location("New York")
