trait RemoteConfigService {
    async fn check_directory_exists(&self, directory_name: &str) -> Result<bool, ConfigError>;
    async fn create_directory(&self, directory_name: &str) -> Result<(), ConfigError>;
    async fn sync_directory(&self, local_path: &Path) -> Result<(), ConfigError>;
}

impl ConfigManager {
    async fn new(remote_service: Arc<Mutex<dyn RemoteConfigService>>, base_path: PathBuf, name: &str) -> Result<Self, ConfigError> {
        let local_path = base_path.join(name);
        if let Err(e) = fs::create_dir_all(&local_path) {
            return Err(ConfigError::PermissionError(format!("Failed to create directory: {}", e)));
        }

        let manager = ConfigManager {
            remote_service,
            local_path,
        };

        manager.sync_or_create_directory().await?;
        Ok(manager)
    }

    async fn sync_or_create_directory(&self) -> Result<(), ConfigError> {
        let mut remote_service = self.remote_service.lock().unwrap();
        if !remote_service.check_directory_exists(self.local_path.file_stem().unwrap().to_str().unwrap()).await? {
            remote_service.create_directory(self.local_path.file_stem().unwrap().to_str().unwrap()).await?;
            remote_service.sync_directory(&self.local_path).await?;
        }
        Ok(())
    }

    async fn sync(&self) -> Result<(), ConfigError> {
        let mut remote_service = self.remote_service.lock().unwrap();
        remote_service.sync_directory(&self.local_path).await?;
        Ok(())
    }
}

