#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_structure_operation(NFAPI_CRC_INDICATION_PDU_T *structure) {
    printf("Transmitted structure: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", 
           structure->RX_UE_INFORMATION_TAG, structure->RNTI, structure->CRCFLAG);
}

void* populate_and_transmit(void* arg) {
    int thread_id = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T *structure = ((NFAPI_CRC_INDICATION_PDU_T**)arg)[thread_id];
    // Simulate fetching sequence generator values from data source
    structure->RX_UE_INFORMATION_TAG = thread_id * 100 + rand() % 100;
    structure->RNTI = thread_id * 10 + rand() % 10;

    // Simulate CRC flag validation based on predefined rules
    static int crc_flag_rules[] = {0, 1, 0, 1};
    structure->CRCFLAG = crc_flag_rules[thread_id];

    log_structure_operation(structure);

    // Simulate network communication
    sleep(1); // Delay to simulate time taken for network transmission

    return NULL;
}

int transmitNFAPIData(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int max_threads, char *ip_address, int port, const char *data_source_url, size_t max_memory_allocation) {
    if (num_structures > max_memory_allocation / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Insufficient memory
    }

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        return -2; // Memory allocation failed
    }

    pthread_t threads[max_threads];
    int thread_ids[num_structures];

    for (int i = 0; i < num_structures; ++i) {
        void** arg_list = malloc(2 * sizeof(void*));
        arg_list[0] = *nfalist;
        arg_list[1] = &thread_ids[i];
        if (pthread_create(&threads[i], NULL, populate_and_transmit, arg_list) != 0) {
            free(arg_list);
            free(*nfalist);
            return -3; // Thread creation failed
        }
    }

    for (int i = 0; i < num_structures; ++i) {
        pthread_join(threads[i], NULL);
        free(((void**)threads[i].specific)[1]);
    }

    free(threads);

    // Simulate transmission over network to the specified endpoint
    struct sockaddr_in server_addr;
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        return -4; // Socket creation failed
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -5; // Invalid IP address
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection Failed");
        close(sockfd);
        return -6; // Connection failed
    }

    for (int i = 0; i < num_structures; ++i) {
        send(sockfd, &(*nfalist)[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 0);
    }

    close(sockfd);

    free(*nfalist);

    return 0; // Success
}
