    private static readonly ConcurrentDictionary<string, XmlDocument> cache = new ConcurrentDictionary<string, XmlDocument>();
    private static readonly string xmlFilePath = ConfigurationManager.AppSettings["XmlFilePath"];
    private static readonly string schemaVersion = ConfigurationManager.AppSettings["SchemaVersion"];
    private static readonly int cacheExpirationTime = int.Parse(ConfigurationManager.AppSettings["CacheExpirationTime"]);

    public static XPathNavigator GetElement(string elementName, string namespacePrefix)
    {
        var key = $"{xmlFilePath}_{elementName}_{namespacePrefix}";
        XmlDocument xmlDoc;

        if (!cache.TryGetValue(key, out xmlDoc))
        {
            xmlDoc = LoadXmlDocument(xmlFilePath);
            cache.TryAdd(key, xmlDoc, DateTimeOffset.UtcNow.AddMinutes(cacheExpirationTime));
        }

        try
        {
            var nav = xmlDoc.CreateNavigator();
            nav.MoveToRoot();

            while (nav.HasChildren)
            {
                if (nav.LocalName == elementName && (namespacePrefix == null || nav.GetNamespaceOfPrefix(namespacePrefix) != ""))
                {
                    return nav.Clone();
                }
                nav.MoveToNext();
            }

            throw new Exception("No matching element found.");
        }
        catch (Exception ex)
        {
            LogError($"XPath evaluation failed: {ex.Message}");
            throw;
        }
    }

    private static XmlDocument LoadXmlDocument(string filePath)
    {
        var xmlDoc = new XmlDocument();

        try
        {
            xmlDoc.Load(filePath);
            ValidateSchema(xmlDoc, schemaVersion);

            return xmlDoc;
        }
        catch (Exception ex)
        {
            LogError($"Failed to load XML document: {ex.Message}");
            throw;
        }
    }

