import os
import json
from abc import ABC, abstractmethod
from typing import Dict, Type, Any
import threading

class Registry:
    _registry: Dict[str, Type[ABC]] = {}
    _lock = threading.Lock()

    @classmethod
    def register_factory(cls, factory_name: str):
        def decorator(subclass: Type[ABC]):
            with cls._lock:
                if subclass in cls._registry.values():
                    raise ValueError(f"Factory {factory_name} already registered")
                cls._registry[factory_name] = subclass
            return subclass
        return decorator

    @classmethod
    def get_factory(cls, factory_name: str) -> Type[ABC]:
        with cls._lock:
            if factory_name not in cls._registry:
                raise KeyError(f"Factory {factory_name} not found")
            return cls._registry[factory_name]

class JSONBase(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str) -> 'JSONBase':
        pass

class Subclass1(JSONBase):
    factory_name = "subclass1"

    @Registry.register_factory(factory_name)
    class Subclass1Factory(Subclass1):
        def to_json(self) -> str:
            return json.dumps({'key': self.value})

        @classmethod
        def from_json(cls, json_str: str) -> 'Subclass1':
            data = json.loads(json_str)
            return cls(value=data['key'])

    def __init__(self, value):
        self.value = value

class Subclass2(JSONBase):
    factory_name = "subclass2"

    @Registry.register_factory(factory_name)
    class Subclass2Factory(Subclass2):
        def to_json(self) -> str:
            return json.dumps({'key': self.value})

        @classmethod
        def from_json(cls, json_str: str) -> 'Subclass2':
            data = json.loads(json_str)
            return cls(value=data['key'])

    def __init__(self, value):
        self.value = value

def discover_subclasses(directory: str):
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                module_path = os.path.join(root, file).replace(os.sep, '.').rstrip('.py')
                spec = importlib.util.spec_from_file_location(module_path, os.path.join(root, file))
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)

# Example usage
if __name__ == "__main__":
    discover_subclasses('path_to_subclass_directory')
    subclass1_instance = Subclass1Factory(value=42).from_json(Subclass1().to_json())
    print(subclass1_instance.value)
```

This code provides a basic structure for managing a dynamic registry of JSON serialization and deserialization classes. The `Registry` class handles the registration and retrieval of factory functions, while the `JSONBase` class defines the abstract methods for JSON conversion. Subclasses like `Subclass1` and `Subclass2` demonstrate how to extend the base class and register their factories using the decorator pattern.

