import os
import logging
from logging.handlers import RotatingFileHandler, TimedRotatingFileHandler
import time
import hashlib
import requests
from abc import ABC, abstractmethod

class LogAggregator(ABC):
    @abstractmethod
    def send_log(self, log_message):
        pass

class SplunkLogAggregator(LogAggregator):
    def __init__(self, url, token):
        self.url = url
        self.token = token

    def send_log(self, log_message):
        headers = {
            'Authorization': f'Splunk {self.token}',
            'Content-Type': 'application/json'
        }
        response = requests.post(f'{self.url}/services/collector', headers=headers, json={'event': log_message})
        if response.status_code != 200:
            raise Exception("Failed to send log to Splunk")

class LogConfigurator:
    def __init__(self, config_file):
        self.config_file = config_file
        self.log_dir = None

    def initialize_log_directory(self):
        if 'log_dir' in os.environ:
            base_dir = os.environ['log_dir']
        else:
            base_dir = '/var/log/myapp/'

        timestamp = time.strftime('%Y%m%d%H%M%S')
        self.log_dir = os.path.join(base_dir, f'logs_run_{timestamp}')

        if not os.path.exists(self.log_dir):
            os.makedirs(self.log_dir)

    def setup_logging(self):
        logging.basicConfig(level=logging.DEBUG)
        file_handler = TimedRotatingFileHandler(os.path.join(self.log_dir, 'app.log'), when='midnight', interval=1, backupCount=7)
        console_handler = logging.StreamHandler()

        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        file_handler.setFormatter(formatter)
        console_handler.setFormatter(formatter)

        logger = logging.getLogger(__name__)
        logger.addHandler(file_handler)
        logger.addHandler(console_handler)

    def integrate_with_log_aggregation(self, log_aggregator):
        logger = logging.getLogger(__name__)
        for handler in logger.handlers:
            if isinstance(handler, logging.StreamHandler):
                original_output = handler.emit
                def new_emit(record):
                    log_message = self.format_record(record)
                    try:
                        log_aggregator.send_log(log_message)
                    except Exception as e:
                        logger.error(f"Failed to send log to log aggregation service: {e}")
                    finally:
                        original_output(record)
                handler.emit = new_emit

    def format_record(self, record):
        return self.log_formatter.format(record)

# Example usage
configurator = LogConfigurator('path/to/config.ini')
configurator.initialize_log_directory()
configurator.setup_logging()

splunk_aggregator = SplunkLogAggregator('https://your.splunk.instance', 'your_splunk_token')
configurator.integrate_with_log_aggregation(splunk_aggregator)
```

This code snippet provides a basic structure for the logging configurator. It includes methods to initialize log directories, set up logging with file and console handlers, integrate with a log aggregation service, and format log records. The use of abstract base classes (ABC) and method decorators allows for easy extension and customization by implementing different log aggregators and adding additional features such as rate limiting and compression.

**Note:** This is a simplified example and may require further refinement to meet specific requirements and handle edge cases.

