using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class SecureMessageProcessor
{
    private ICryptoServiceProvider _primaryCsp;
    private ICryptoServiceProvider _backupCsp;
    private ILogger _logger;
    private ILogAudit _auditLogger;
    private object _lock = new object();
    private int _keyRotationIntervalMinutes;
    private DateTime _lastKeyRotationTime;

    public SecureMessageProcessor(ICryptoServiceProvider primaryCsp, ICryptoServiceProvider backupCsp, ILogger logger, ILogAudit auditLogger, int keyRotationIntervalMinutes)
    {
        _primaryCsp = primaryCsp;
        _backupCsp = backupCsp;
        _logger = logger;
        _auditLogger = auditLogger;
        _keyRotationIntervalMinutes = keyRotationIntervalMinutes;
        _lastKeyRotationTime = DateTime.UtcNow;
    }

    public string DecryptMessage(string base64EncodedMessage)
    {
        ICryptoServiceProvider csp = GetActiveCsp();
        try
        {
            byte[] messageBytes = Convert.FromBase64String(base64EncodedMessage);
            byte[] decryptedBytes = csp.Decrypt(messageBytes, true);
            string decryptedMessage = System.Text.Encoding.UTF8.GetString(decryptedBytes);
            _auditLogger.Log("Decryption successful");
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to decrypt message");
            _auditLogger.Log($"Decryption failed: {ex.Message}");
            throw;
        }
    }

    private ICryptoServiceProvider GetActiveCsp()
    {
        lock (_lock)
        {
            if ((DateTime.UtcNow - _lastKeyRotationTime).TotalMinutes >= _keyRotationIntervalMinutes || !_primaryCsp.CanDecrypt())
            {
                RotateKeys();
            }
            return _primaryCsp.IsHealthy() ? _primaryCsp : _backupCsp;
        }
    }

    private void RotateKeys()
    {
        // Implement key rotation logic here
        // For example, derive new keys from a master key and update CSPs
        _lastKeyRotationTime = DateTime.UtcNow;
        _auditLogger.Log("Key rotation completed");
    }
}

public interface ICryptoServiceProvider
{
    bool CanDecrypt();
    bool IsHealthy();
    byte[] Decrypt(byte[] data, bool useAsync);
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}

public interface ILogAudit
{
    void Log(string message);
}
