```javascript
async function asyncReduce(arr, reducer, initial = 0, concurrencyLimit = 1) {
    let results = new Map();
    let concurrentTasks = 0;

    // Helper function to process elements
    const processElement = async (index) => {
        try {
            const value = arr[index];
            if (typeof value === 'string') {
                value = parseInt(value, 10);
            }
            if (isNaN(value)) {
                throw new TypeError('Non-numeric value encountered');
            }
            const reducedValue = await reducer(results.get(index - 1), value, index);
            results.set(index, reducedValue);
        } catch (error) {
            console.error(`Error at index ${index}:`, error.message);
        } finally {
            concurrentTasks--;
        }
    };

    // Limit the number of concurrent tasks
    const limitConcurrent = async () => {
        while (concurrentTasks >= concurrencyLimit) {
            await new Promise(resolve => setTimeout(resolve, 10));
        }
    };

    // Process each element in the array
    for (let i = 0; i < arr.length; i++) {
        await limitConcurrent();
        concurrentTasks++;
        processElement(i);
    }

    // Wait for all tasks to complete
    while (concurrentTasks > 0) {
        await new Promise(resolve => setTimeout(resolve, 10));
    }

    return results.get(arr.length - 1);
}

// Example usage:
const array = ['1', '2', '3', '4', '5'];
const reducer = async (acc, num) => acc + num;
asyncReduce(array, reducer)
    .then(result => console.log('Reduced result:', result))
    .catch(error => console.error('Error:', error));
```

