import json
from datetime import datetime
from decimal import Decimal
import uuid

class JSONSerializable:
    _factory_registry = {}

    @staticmethod
    def register_factory(data_type, factory_func):
        if data_type in JSONSerializable._factory_registry:
            raise ValueError(f"Factory function already registered for {data_type}")
        JSONSerializable._factory_registry[data_type] = factory_func

    @staticmethod
    def unregister_factory(data_type):
        if data_type not in JSONSerializable._factory_registry:
            raise KeyError(f"No factory function registered for {data_type}")
        del JSONSerializable._factory_registry[data_type]

    @classmethod
    def from_json(cls, json_str):
        try:
            data = json.loads(json_str)
            if cls.__name__ == "JSONSerializable":
                data_type = next(iter(data.keys()))
                return JSONSerializable._factory_registry.get(data_type)(data[data_type])
            else:
                return cls(**data)
        except (json.JSONDecodeError, KeyError) as e:
            raise ValueError(f"Invalid JSON input or unsupported data type: {e}")

    def to_json(self):
        raise NotImplementedError("to_json method must be implemented by subclasses")

    @classmethod
    def _serialize_datetime(cls, obj):
        return obj.isoformat()

    @classmethod
    def _deserialize_datetime(cls, data):
        return datetime.fromisoformat(data)

    @classmethod
    def _serialize_uuid(cls, obj):
        return str(obj)

    @classmethod
    def _deserialize_uuid(cls, data):
        return uuid.UUID(data)

    @classmethod
    def _serialize_decimal(cls, obj):
        return float(obj)  # Note: This is a simplified serialization for demonstration

    @classmethod
    def _deserialize_decimal(cls, data):
        return Decimal(data)

# Registering factory functions for custom data types
JSONSerializable.register_factory('datetime', JSONSerializable._deserialize_datetime)
JSONSerializable.register_factory('UUID', JSONSerializable._deserialize_uuid)
JSONSerializable.register_factory('Decimal', JSONSerializable._deserialize_decimal)

# Example subclass of JSONSerializable
class Trade(JSONSerializable):
    def __init__(self, trade_id, symbol, quantity, price, timestamp):
        self.trade_id = trade_id
        self.symbol = symbol
        self.quantity = quantity
        self.price = price
        self.timestamp = timestamp

    @classmethod
    def from_json(cls, json_str):
        return super().from_json(json_str)

    def to_json(self):
        data = {
            "datetime": self._serialize_datetime(self.timestamp),
            "UUID": self._serialize_uuid(self.trade_id),
            "Decimal": self._serialize_decimal(self.price)
        }
        return json.dumps(data)

# Usage example
trade_data = '{"Trade": {"datetime": "2023-04-10T12:34:56", "UUID": "123e4567-e89b-12d3-a456-426614174000", "Decimal": 12.34}}'
trade = Trade.from_json(trade_data)
print(trade.to_json())
```

This code provides a basic implementation of the `JSONSerializable` class with methods for serialization and deserialization, including support for custom data types like `datetime`, `UUID`, and `Decimal`. It also includes a dynamic factory function registry and error handling mechanisms. The example subclass `Trade` demonstrates how to use the `JSONSerializable` class for serializing and deserializing financial data models.

