class UserDataRequest:
    def __init__(self, username, password, date_range, max_requests_per_minute, data_size_limit, user_ids):
        self.username = username
        self.password = password
        self.date_range = date_range
        self.max_requests_per_minute = max_requests_per_minute
        self.data_size_limit = data_size_limit
        self.user_ids = user_ids

def authenticate_user(username, password):
    client = BackendApplicationClient(client_id='your_client_id')
    oauth = OAuth2Session(client=client)
    token_url = 'https://oauth.example.com/token'
    token = oauth.fetch_token(token_url, username=username, password=password, client_id='your_client_id', client_secret='your_client_secret')
    return token['access_token']

@lru_cache(maxsize=None)
def get_access_token(username, password):
    if username not in access_token_cache:
        access_token_cache[username] = authenticate_user(username, password)
    return access_token_cache[username]

def fetch_data(user_id, access_token):
    headers = {'Authorization': f'Bearer {access_token}'}
    params = {
        'user_id': user_id,
        'date_range_start': request.date_range['start'],
        'date_range_end': request.date_range['end'],
        'data_size_limit': request.data_size_limit
    }
