    return response.json()

def process_and_filter_data(user_ids):
    access_token = get_access_token(request.username, request.password)
    with ThreadPoolExecutor(max_workers=min(len(user_ids), request.max_requests_per_minute)) as executor:
        data_futures = [executor.submit(fetch_data, user_id, access_token) for user_id in user_ids]
        data_list = [future.result() for future in data_futures]

    # Process and filter the data
    filtered_data = {}
    for data in data_list:
        if data['size'] > request.data_size_limit or not data['data']:
            continue
        for item in data['data']:
            if item['id'] not in filtered_data:
                filtered_data[item['id']] = item

    # Update metrics and compress data
    update_metrics(filtered_data)
    zip_buffer = io.BytesIO()
    with ZipFile(zip_buffer, 'w', ZIP_DEFLATED) as zipf:
        for user_id, data in filtered_data.items():
            zipf.writestr(f'{user_id}.json', str(data))

    return len(filtered_data), {user_id: data['size'] for user_id, data in filtered_data.items()}, base64.b64encode(zip_buffer.getvalue()).decode('utf-8')

def update_metrics(data):
    # Logic to update metrics in a distributed database
