#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <chrono>
#include <random>

class Attack {
public:
    int id;
    int energyCost;
    int cooldown;
    bool isOnCooldown;

    Attack(int _id, int _energyCost, int _cooldown) : id(_id), energyCost(_energyCost), cooldown(_cooldown), isOnCooldown(false) {}
};

class Character {
public:
    int energyLevel;
    std::vector<Attack> attacks;
    std::mutex characterMutex;

    Character(int initialEnergy) : energyLevel(initialEnergy) {}

    void addAttack(Attack attack) {
        attacks.push_back(attack);
    }

    bool canExecuteAttack(Attack& attack) const {
        return !attack.isOnCooldown && energyLevel >= attack.energyCost;
    }
};

class EnergyManagerAPI {
public:
    static int getCharacterEnergy(const Character& character) {
        // Simulate getting energy level from API
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        return character.energyLevel;
    }

    static void setCharacterEnergy(Character& character, int newEnergy) {
        // Simulate setting energy level in API
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        character.energyLevel = newEnergy;
    }
};

class AttackStrategy {
public:
    virtual ~AttackStrategy() {}
    virtual void executeAttack(Character& character, Attack& attack) const = 0;
};

class RandomAttackStrategy : public AttackStrategy {
public:
    void executeAttack(Character& character, Attack& attack) const override {
        // Execute the attack logic here
        std::cout << "Executing attack ID: " << attack.id << std::endl;
    }
};

void selectAndExecuteAttack(Character& character, std::shared_ptr<AttackStrategy> strategy) {
    std::lock_guard<std::mutex> lock(character.characterMutex);

    if (character.attacks.empty()) {
        std::cout << "No attacks available." << std::endl;
        return;
    }

    // Select a random attack
    std::random_device rd;
    std::mt19937 g(rd());
    int index = std::uniform_int_distribution<>(0, character.attacks.size() - 1)(g);
    Attack& selectedAttack = character.attacks[index];

    if (!character.canExecuteAttack(selectedAttack)) {
        std::cout << "Cannot execute attack ID: " << selectedAttack.id << " due to insufficient energy or cooldown." << std::endl;
        return;
    }

    // Execute the attack using the strategy
    strategy->executeAttack(character, selectedAttack);

    // Update energy and reset cooldown
    EnergyManagerAPI::setCharacterEnergy(character, character.energyLevel - selectedAttack.energyCost);
    selectedAttack.isOnCooldown = true;

    // Simulate cooldown timer
    std::this_thread::sleep_for(std::chrono::seconds(selectedAttack.cooldown));
    selectedAttack.isOnCooldown = false;

    std::cout << "Attack ID: " << selectedAttack.id << " completed." << std::endl;
}

int main() {
    Character player(50);
    RandomAttackStrategy strategy;

    // Add attacks to the character
    player.addAttack(Attack(1, 20, 5));
    player.addAttack(Attack(2, 30, 7));
    player.addAttack(Attack(3, 40, 9));
    player.addAttack(Attack(4, 10, 3));
    player.addAttack(Attack(5, 25, 6));

    // Simulate multiple attack attempts
    for (int i = 0; i < 10; ++i) {
        selectAndExecuteAttack(player, std::make_shared<RandomAttackStrategy>());
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
    }

    return 0;
}
