#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TAG_RANGE 10000
#define RNTI_RANGE 9000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_structure_creation(int tag, int rnti, int crcflag, int log_level);

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int log_level) {
    if (num_structures <= 0 || !nfalist || !crc_flag_rules) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfalist) {
        perror("Memory allocation failed");
        return -2;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_structures; ++i) {
        pthread_mutex_lock(&lock);

        (*nfalist)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*nfalist)[i].RNTI = 1000 + rand() % RNTI_RANGE;
        (*nfalist)[i].CRCFLAG = crc_flag_rules[i];

        log_structure_creation((*nfalist)[i].RX_UE_INFORMATION_TAG, (*nfalist)[i].RNTI, (*nfalist)[i].CRCFLAG, log_level);

        pthread_mutex_unlock(&lock);
    }

    return 0;
}

void log_structure_creation(int tag, int rnti, int crcflag, int log_level) {
    // External logging function implementation
    printf("CREATED: Tag=%d, RNTI=%d, CRCFLAG=%d\n", tag, rnti, crcflag);
}
```

