#define MAX_LOG_SIZE 1024 * 500 // 5GB
#define NUM_SERVERS 10

typedef struct {
    char log[MAX_LOG_SIZE];
    int size;
} LogEntry;

typedef struct {
    sem_t lock;
    LogEntry logs[NUM_SERVERS];
} LogBuffer;

void* process_logs(void* arg) {
    LogBuffer* buffer = (LogBuffer*)arg;
    while (1) {
        sem_wait(&buffer->lock);
        for (int i = 0; i < NUM_SERVERS; i++) {
            if (buffer->logs[i].size > 0) {
                // Parse log entry
                char* ip = strtok(buffer->logs[i].log, " ");
                char* timestamp = strtok(NULL, " ");
                int status_code = atoi(strtok(NULL, " "));

                // Aggregate statistics and report to API

                // Clear the log entry
                buffer->logs[i].size = 0;
            }
        }
        sem_post(&buffer->lock);
    }
}

int main() {
    LogBuffer buffer;
    sem_init(&buffer.lock, 0, 1);

    pthread_t threads[NUM_SERVERS];
    for (int i = 0; i < NUM_SERVERS; i++) {
        pthread_create(&threads[i], NULL, process_logs, &buffer);
    }

    // Simulate log ingestion from servers
    for (int i = 0; i < NUM_SERVERS; i++) {
        sem_wait(&buffer.lock);
        snprintf(buffer.logs[i].log, MAX_LOG_SIZE, "192.168.%d.%d - [%s] \"%s %s HTTP/1.1\" %d", i%254+1, i%255+1, "01/Oct/2023:12:34:56 +0000", "GET", "/", 200);
        buffer.logs[i].size = strlen(buffer.logs[i].log) + 1;
        sem_post(&buffer.lock);

        // Sleep to simulate log stream
        sleep(1);
    }

    for (int i = 0; i < NUM_SERVERS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&buffer.lock);
