import json
import yaml
import importlib
import logging

class ConfigurationManagerFactory:
    @staticmethod
    def create_manager(config_path):
        try:
            mime_type = ConfigurationManagerFactory.get_mime_type(config_path)
            if mime_type not in ['application/json', 'text/yaml']:
                raise ValueError(f"Invalid MIME type: {mime_type}")

            config_data = ConfigurationManagerFactory.parse_config(config_path, mime_type)
            manager_class_name = config_data['manager']

            try:
                manager_module = importlib.import_module('config_managers')
                manager_class = getattr(manager_module, manager_class_name)

                if not issubclass(manager_class, ConfigurationManager):
                    raise ValueError(f"{manager_class_name} does not inherit from ConfigurationManager")

                manager_instance = manager_class(config_data)
                return manager_instance
            except (ModuleNotFoundError, AttributeError) as e:
                logging.error(f"Failed to import or get manager class: {e}")
                raise ValueError(f"Configuration manager '{manager_class_name}' is not available in the current environment")

        except Exception as e:
            logging.error(f"Error creating configuration manager: {e}")
            raise

    @staticmethod
    def get_mime_type(file_path):
        import mimetypes
        return mimetypes.guess_type(file_path)[0]

    @staticmethod
    def parse_config(config_path, mime_type):
        with open(config_path, 'r') as file:
            if mime_type == 'application/json':
                config_data = json.load(file)
            elif mime_type == 'text/yaml':
                config_data = yaml.safe_load(file)
            else:
                raise ValueError(f"Invalid MIME type: {mime_type}")

        return config_data

class ConfigurationManager:
    def __init__(self, data):
        self.data = data
