// Function to expand the state list in a thread-safe manner
void expandStateList(FSA* fsa, State** currentStates, int* currentStateCount,
                     FILE* fileSource, void* networkSource) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Check if we can read from the file source
    if (fileSource != NULL && fread(currentStates + *currentStateCount, sizeof(State), 1, fileSource)) {
        (*currentStateCount)++;
    }
    // If not, check the network source
    else if (networkSource != NULL) {
        // Logic to read data from network source and populate currentStates
        (*currentStateCount)++;
    }

    pthread_mutex_unlock(&mutex);
}

