```javascript
const asyncReduce = (arr, initialValue, callback, db) => {
  return new Promise((resolve, reject) => {
    let index = 0;
    let accumulator = initialValue;
    let activeQueries = 0;

    const queryRateLimiter = () => {
      while (activeQueries < 5 && index < arr.length) {
        processNext();
      }
    };

    const processNext = async () => {
      if (index >= arr.length) {
        resolve(accumulator);
        return;
      }

      try {
        let currentNum = arr[index];
        if (typeof currentNum !== 'number') {
          throw new Error(`Non-numeric value found at index ${index}`);
        }
        accumulator = await callback(accumulator, currentNum);

        index++;
        activeQueries--;

        queryRateLimiter();
      } catch (error) {
        reject(error);
      }
    };

    const fetchInitialValue = async () => {
      try {
        let initialVal = await db.fetch('initial_value');
        accumulator = initialVal;
        queryRateLimiter();
      } catch (error) {
        reject(error);
      }
    };

    const storeResult = async (result) => {
      try {
        await db.store('final_result', result);
        resolve(result);
      } catch (error) {
        reject(error);
      }
    };

    fetchInitialValue();

    queryRateLimiter();
  });
};
