// Function to handle product updates and deletions
async function manageProduct(req, res) {
  const { productId } = req.params;
  const { action } = req.body;

  try {
    if (!inventory[productId]) {
      return res.status(404).json({ error: 'Invalid product ID' });
    }

    const userPermissions = await validateUserPermissions(req.headers.authorization);

    if (userPermissions !== 'admin') {
      return res.status(403).json({ error: 'Unauthorized access' });
    }

    if (action === 'update') {
      const { price, stock } = req.body;
      inventory[productId] = { ...inventory[productId], price, stock };
      await updateInventoryInRedis(productId, inventory[productId]);
      res.status(200).json({ message: 'Product updated successfully' });
    } else if (action === 'delete') {
      delete inventory[productId];
      await removeProductFromRedis(productId);
      res.status(200).json({ message: 'Product deleted successfully' });
    } else {
      return res.status(400).json({ error: 'Invalid action' });
    }
  } catch (error) {
    if (error.response && error.response.status === 503) {
      return res.status(503).json({ error: 'External service unavailable' });
    }
    return res.status(500).json({ error: 'Internal server error' });
  }
}

// Function to validate user permissions
async function validateUserPermissions(token) {
  try {
    const response = await axios.get('https://user-management-service.com/validate', { headers: { Authorization: token } });
    return response.data.permissions;
  } catch (error) {
    if (error.response && error.response.status === 503) {
      throw new Error('External service unavailable');
    }
    return 'guest';
  }
}

// Function to update inventory in Redis
async function updateInventoryInRedis(productId, productData) {
  await redisClient.set(`inventory:${productId}`, JSON.stringify(productData));
}

// Function to remove product from Redis
