typedef struct {
    bool enabled;
    const char *language;
    int max_message_length;
} LogConfig;

LogConfig log_config = {true, "English", 2048};

void set_log_config(LogConfig config) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    log_config = config;
    pthread_mutex_unlock(&mutex);
}

void logConditionalMessage(bool condition, const char *language, const char *format, ...) {
    if (!log_config.enabled || strcmp(language, log_config.language) != 0) {
        return;
    }

    va_list args;
    va_start(args, format);

    char buffer[log_config.max_message_length];
    vsnprintf(buffer, log_config.max_message_length, format, args);

    va_end(args);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    FILE *file = fopen("error.log", "a");
    if (file) {
        fprintf(file, "%s\n", buffer);
        fclose(file);
    } else {
        // Handle error: logging file not writable
        perror("Failed to open log file for writing");
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    set_log_config((LogConfig){true, "English", 2048});
    logConditionalMessage(true, "English", "This is a test message: %d", 123);
    return 0;
}
