#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_SEMAPHORES 100
#define NUM_NODES 5

typedef struct {
    char name[256];
    int value;
    int max_value;
    int priority;
    sem_t semaphore;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t semaphores_lock;

void log_semaphore_operation(const char* operation, const char* semaphore_name, pid_t pid, pthread_t tid) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] %s - Semaphore: %s, PID: %d, TID: %ld\n", ctime(&now), operation, semaphore_name, pid, (long)tid);
}

void create_semaphore(const char* name, int initial_value, int max_value, int priority) {
    pthread_mutex_lock(&semaphores_lock);
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (semaphores[i].value == -1) { // Unused semaphore
            strncpy(semaphores[i].name, name, sizeof(semaphores[i].name));
            semaphores[i].value = initial_value;
            semaphores[i].max_value = max_value;
            semaphores[i].priority = priority;
            if (sem_init(&semaphores[i].semaphore, 0, initial_value) != 0) {
                perror("Semaphore initialization failed");
                pthread_mutex_unlock(&semaphores_lock);
                return;
            }
            log_semaphore_operation("Create", name, getpid(), pthread_self());
            semaphore_count++;
            break;
        }
    }
    pthread_mutex_unlock(&semaphores_lock);
}

void delete_semaphore(const char* name) {
    pthread_mutex_lock(&semaphores_lock);
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (strcmp(semaphores[i].name, name) == 0 && semaphores[i].value != -1) {
            sem_destroy(&semaphores[i].semaphore);
            memset(&semaphores[i], 0, sizeof(Semaphore));
            log_semaphore_operation("Delete", name, getpid(), pthread_self());
            semaphore_count--;
            break;
        }
    }
    pthread_mutex_unlock(&semaphores_lock);
}

int wait_semaphore(const char* name, int timeout) {
    pthread_mutex_lock(&semaphores_lock);
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (strcmp(semaphores[i].name, name) == 0 && semaphores[i].value != -1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += timeout;
            int ret = sem_timedwait(&semaphores[i].semaphore, &ts);
            if (ret == -1) {
                perror("Semaphore wait timed out");
            } else {
                log_semaphore_operation("Wait", name, getpid(), pthread_self());
            }
            pthread_mutex_unlock(&semaphores_lock);
            return ret;
        }
    }
    pthread_mutex_unlock(&semaphores_lock);
    return -1; // Semaphore not found
}

int post_semaphore(const char* name) {
    pthread_mutex_lock(&semaphores_lock);
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (strcmp(semaphores[i].name, name) == 0 && semaphores[i].value != -1) {
            if (sem_post(&semaphores[i].semaphore) == 0) {
                log_semaphore_operation("Post", name, getpid(), pthread_self());
            } else {
                perror("Semaphore post failed");
            }
            pthread_mutex_unlock(&semaphores_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&semaphores_lock);
    return -1; // Semaphore not found
}

int main() {
    create_semaphore("my_semaphore", 5, 10, 1);
    wait_semaphore("my_semaphore", 2);
    post_semaphore("my_semaphore");
    delete_semaphore("my_semaphore");
    return 0;
}
```

This code provides a basic implementation of a semaphore management system with logging and error handling. It includes functions to create, delete, wait on, and post semaphores. The `wait_semaphore` function supports a timeout parameter. The `log_semaphore_operation` function records all operations in real-time.

For full functionality as described, additional features such as priority support, distributed environment support, configuration management, resource monitoring, dynamic scaling, failover mechanisms, and throttling would need to be implemented.

