class FileStorageManager {
    private $allowedExtensions = ['jpg', 'png', 'pdf'];
    private $fileSizeLimit = 5 * 1024 * 1024; // 5MB

    public function validateFileExtension($file, $allowedExtensions) {
        $extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
        return in_array($extension, array_merge($this->allowedExtensions, $allowedExtensions));
    }

    public function resizeImage($file, $maxWidth, $maxHeight) {
        list($width, $height) = getimagesize($file['tmp_name']);
        $ratio = min($maxWidth / $width, $maxHeight / $height);
        $newWidth = $width * $ratio;
        $newHeight = $height * $ratio;

        $image = imagecreatefromstring(file_get_contents($file['tmp_name']));
        $resizedImage = imagecreatetruecolor($newWidth, $newHeight);
        imagecopyresampled($resizedImage, $image, 0, 0, 0, 0, $newWidth, $newHeight, $width, $height);

        ob_start();
        imagejpeg($resizedImage);
        $resizedFile = ob_get_clean();

        return [
            'tmp_name' => tempnam(sys_get_temp_dir(), 'uploaded_image'),
            'name' => $file['name'],
            'type' => 'image/jpeg',
            'error' => 0,
            'size' => strlen($resizedFile),
            'data' => $resizedFile
        ];
    }

    public function uploadFile($file, $destinationPath) {
        if ($this->validateFileExtension($file, [])) {
            $filePath = $destinationPath . '/' . basename($file['name']);
            if (!file_exists($filePath)) {
                if (move_uploaded_file($file['tmp_name'], $filePath)) {
                    return true;
                }
            } else {
                // Handle file already exists
            }
        }
        return false;
    }

