import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.HashMap;
import java.util.Map;

public class JsonParser {
    private static final Map<String, JsonNode> cache = new HashMap<>();
    private final ObjectMapper objectMapper;

    public JsonParser() {
        this.objectMapper = new ObjectMapper();
    }

    public JsonNode parseJson(String json, String path) {
        try {
            if (cache.containsKey(path)) {
                return cache.get(path);
            }
            JsonNode rootNode = objectMapper.readTree(json);
            JsonNode resultNode = rootNode.at(path);
            if (!resultNode.isMissingNode()) {
                cache.put(path, resultNode);
                return resultNode;
            } else {
                throw new IllegalArgumentException("No data found at path: " + path);
            }
        } catch (Exception e) {
            throw new RuntimeException("Error parsing JSON", e);
        }
    }

