class ImageProcessor {
public:
    struct ConversionJob {
        std::string inputPath;
        std::string outputPath;
        std::string format;
        int quality;
    };

    enum class LogLevel { Error, Warning, Info };
    using LogFunction = std::function<void(LogLevel level, const std::string& message)>;

    ImageProcessor(LogFunction logFunc) : log(logFunc), numThreads(1) {}

    void setNumThreads(int n) {
        numThreads = n;
        threads.resize(n);
    }

    void batchConvertAndSave(const std::vector<ConversionJob>& jobs) {
        if (jobs.empty()) return;

        std::mutex queueMutex;
        std::condition_variable jobQueueCV;
        bool stopProcessing = false;
        std::vector<std::thread> workers(numThreads);

        for (int i = 0; i < numThreads; ++i) {
            workers[i] = std::thread([this, &queueMutex, &jobQueueCV, &stopProcessing]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    jobQueueCV.wait(lock, [this, &stopProcessing]() {
                        return !jobs.empty() || stopProcessing;
                    });

                    if (stopProcessing && jobs.empty()) break;

                    ConversionJob job = jobs.back();
                    jobs.pop_back();
                    lock.unlock();

                    try {
                        convertImage(job.inputPath, job.outputPath, job.format, job.quality);
                        log(LogLevel::Info, "Conversion successful: " + job.inputPath + " -> " + job.outputPath);
                    } catch (const std::exception& e) {
                        log(LogLevel::Error, "Conversion failed for " + job.inputPath + ": " + e.what());
                    }
                }
            });
        }

        // Start processing jobs
        for (auto& job : jobs) {
            std::unique_lock<std::mutex> lock(queueMutex);
            jobs.push_back(job);
            lock.unlock();
            jobQueueCV.notify_one();
        }

        // Wait for all jobs to complete
        stopProcessing = true;
        for (int i = 0; i < numThreads; ++i) {
            jobQueueCV.notify_all();
            workers[i].join();
        }
    }

private:
    void convertImage(const std::string& inputPath, const std::string& outputPath, const std::string& format, int quality) {
        // Placeholder for actual image conversion logic using a third-party library
        // For demonstration purposes, we'll just simulate the conversion process
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate processing time
    }

    LogFunction log;
    int numThreads;
    std::vector<std::thread> threads;
};

int main(int argc, char* argv[]) {
    namespace po = boost::program_options;

    ImageProcessor::LogFunction logger = [](ImageProcessor::LogLevel level, const std::string& message) {
        switch (level) {
            case ImageProcessor::LogLevel::Error:
                std::cerr << "ERROR: " << message << std::endl;
                break;
            case ImageProcessor::LogLevel::Warning:
                std::cerr << "WARNING: " << message << std::endl;
                break;
            case ImageProcessor::LogLevel::Info:
                std::cout << "INFO: " << message << std::endl;
                break;
        }
    };

    ImageProcessor processor(logger);
    int numThreads = 1;
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "produce help message")
        ("threads,n", po::value<int>(&numThreads)->default_value(numThreads), "number of threads for conversion")
        ("input,i", po::value<std::string>(), "input file path")
        ("output,o", po::value<std::string>(), "output file path")
        ("format,f", po::value<std::string>(), "output format")
        ("quality,q", po::value<int>()->default_value(85), "output quality (0-100)");

    po::variables_map vm;
    try {
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);
    } catch (const std::exception& e) {
        std::cerr << "Error parsing command line options: " << e.what() << std::endl;
        return 1;
    }

    if (vm.count("help")) {
        std::cout << desc << std::endl;
        return 0;
    }

    if (!vm.count("input") || !vm.count("output") || !vm.count("format")) {
        std::cerr << "Error: Missing required arguments." << std::endl;
        return 1;
    }

    ImageProcessor::ConversionJob job = {
        vm["input"].as<std::string>(),
        vm["output"].as<std::string>(),
        vm["format"].as<std::string>(),
        vm.count("quality") ? vm["quality"].as<int>() : 85
    };

    processor.setNumThreads(numThreads);
    std::vector<ImageProcessor::ConversionJob> jobs = { job };
    processor.batchConvertAndSave(jobs);

    return 0;
}
```

