        }
    }

    public static void InsertAfter(ConcurrentQueue<string> queue, string target, string insert)
    {
        bool foundTarget = false;
        while (queue.TryDequeue(out var item))
        {
            if (item == target)
                foundTarget = true;

            queue.Enqueue(item);
        }

        if (foundTarget)
        {
            queue.Enqueue(insert);
        }
        else
        {
            queue.Enqueue(target); // Insert at the end if target not found
            queue.Enqueue(insert);
        }
    }
}
