using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml.Linq;

public class ConfigLoader
{
    public static Dictionary<string, string> LoadConfig(string[] filePaths)
    {
        var config = new Dictionary<string, string>();

        foreach (var file in filePaths)
        {
            if (File.Exists(file))
            {
                var xmlDoc = XDocument.Load(file);
                var settings = xmlDoc.Descendants("setting")
                    .ToDictionary(e => e.Attribute("key").Value, e => e.Attribute("value").Value);

                foreach (var kvp in settings)
                {
                    if (!config.ContainsKey(kvp.Key) || DateTime.Now > config[kvp.Key])
                    {
                        config[kvp.Key] = kvp.Value;
                    }
                }
            }
        }

        return config;
    }
}
