use std::{
    env,
    fs::{self, File},
    io::{self, Write},
    path::PathBuf,
    sync::Mutex,
    time::{SystemTime, UNIX_EPOCH},
};

struct DirectoryManager {
    base_dir: PathBuf,
    log_file: File,
}

impl DirectoryManager {
    fn new(base_dir: &str, log_file_path: &str) -> Result<Self, io::Error> {
        let log_file = File::create(log_file_path)?;
        Ok(DirectoryManager {
            base_dir: PathBuf::from(base_dir),
            log_file,
        })
    }

    fn create_directory(&self, dir_name: &str) -> Result<PathBuf, String> {
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        let mut dir_path = self.base_dir.clone();
        dir_path.push(dir_name);
        dir_path.set_extension(timestamp.to_string());

        if !dir_path.exists() {
            fs::create_dir_all(&dir_path)?;
            writeln!(self.log_file, "Directory created: {:?}", dir_path)?;
            Ok(dir_path)
        } else {
            Err("Directory already exists".to_string())
        }
    }

    fn set_env_variable(&self, env_name: &str, path: &PathBuf) -> Result<(), String> {
        if env::var_os(env_name).is_none() {
            env::set_var(env_name, path);
            writeln!(self.log_file, "Environment variable {} set to {:?}", env_name, path)?;
            Ok(())
        } else {
            Err(format!("Environment variable {} already set", env_name))
        }
    }

    fn cleanup(&self) {
        if let Some(path) = env::var_os("DIR_PATH") {
            if fs::remove_dir_all(&path).is_err() {
                eprintln!("Failed to clean up directory {:?}", path);
            } else {
                writeln!(self.log_file, "Directory cleaned up: {:?}", path).unwrap();
            }
        }
    }
}

fn main() -> Result<(), io::Error> {
    let manager = DirectoryManager::new("/path/to/base/dir", "/path/to/logfile.log")?;
    let dir_path = manager.create_directory("my_dir")?;
    manager.set_env_variable("DIR_PATH", &dir_path)?;
    // Perform operations using DIR_PATH
    manager.cleanup();
    Ok(())
}
