use std::process::{Command, Stdio};
use std::time::{Instant};
use libc::{sysconf, _SC_PHYS_PAGES, _SC_CLK_TCK};

fn get_peak_rss() -> usize {
    unsafe {
        let pages = sysconf(_SC_PHYS_PAGES).expect("Failed to get number of physical pages");
        let page_size = sysconf(_SC_CLK_TCK).expect("Failed to get system clock ticks per second");
        let mut rusage: libc::rusage = std::mem::zeroed();
        if libc::getrusage(libc::RUSAGE_SELF, &mut rusage) == 0 {
            (rusage.ru_maxrss as usize * page_size / 1024)
        } else {
            0
        }
    }
}

fn compile_with_hooks() -> i32 {
    static mut LOGGING_SYSTEM: Option<ExternalLoggingSystem> = None;

    fn initialize_logging_system() -> &'static ExternalLoggingSystem {
        unsafe {
            if LOGGING_SYSTEM.is_none() {
                LOGGING_SYSTEM = Some(ExternalLoggingSystem::new());
            }
            LOGGING_SYSTEM.as_ref().unwrap()
        }
    }

    let start_time = Instant::now();
    let peak_rss = get_peak_rss();

    let logging_system = initialize_logging_system();
    logging_system.log_start(start_time, peak_rss);

    let output = Command::new("rustc")
        .args(&["--version"])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to execute command");

    let stdout = output.stdout.unwrap();
    let stderr = output.stderr.unwrap();

    let mut status = None;
    loop {
        if let Some(s) = output.try_wait() {
            status = s.ok();
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }

    if let Some(status) = status {
        let exit_code = status.code().unwrap_or(-1);
        logging_system.log_end(exit_code, get_peak_rss());
        return exit_code;
    } else {
        rustc_driver::catch_with_exit_code(|| {
            early_error(
                ErrorGuarantee::Bug,
                "Failed to compile Rust code",
            );
        });
        return -1;
    }
}
