// Define a trait for JSON processing classes
trait JsonProcessor {
    fn process(&self, json_data: &str) -> Result<String, String>;
}

// Implement the trait for a specific processor
struct SimpleJsonProcessor;

impl JsonProcessor for SimpleJsonProcessor {
    fn process(&self, json_data: &str) -> Result<String, String> {
        // Example processing logic
        Ok(format!("Processed: {}", json_data))
    }
}

// Define the JsonParser module
pub struct JsonParser {
    processors: Arc<Mutex<HashMap<String, Box<dyn JsonProcessor>>>>,
}

impl JsonParser {
    pub fn new() -> Self {
        JsonParser {
            processors: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    // Register a custom JSON processor
    pub async fn register_processor(&self, name: &str, processor: Box<dyn JsonProcessor>) {
        let mut processors = self.processors.lock().unwrap();
        processors.insert(name.to_string(), processor);
    }

    // Fetch and process JSON data using the registered processor
    pub async fn process_json(&self, json_data: &str) -> Result<String, String> {
        let processors = self.processors.lock().unwrap();
        if let Some(processor) = processors.get("simple_processor") {
            processor.process(json_data)
        } else {
            Err("Processor not found".to_string())
        }
    }
}

// Asynchronous test execution with atomic file system operations
#[tokio::test]
async fn test_json_parser() -> Result<(), Box<dyn std::error::Error>> {
    // Create a temporary directory for testing
    let temp_dir = tempfile::tempdir()?;
    let dir_path = temp_dir.path();

    // Initialize the JsonParser and register a processor
    let parser = JsonParser::new();
    parser.register_processor("simple_processor", Box::new(SimpleJsonProcessor)).await;

    // Create test data
    let json_data = r#"{"key": "value"}"#;

    // Process JSON data using the registered processor
    let result = parser.process_json(json_data).await?;
    assert_eq!(result, "Processed: {\"key\": \"value\"}");

    // Clean up the temporary directory atomically
    std::fs::remove_dir_all(dir_path)?;
    Ok(())
}
