// Function to create a semaphore and initialize it with the given value
sem_t* create_semaphore(int initial_value) {
    sem_t *sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to open semaphore");
        return NULL;
    }
    return sem;
}

// Function to delete a semaphore
void delete_semaphore(sem_t* sem) {
    if (sem_close(sem) != 0) {
        perror("Failed to close semaphore");
    }
    if (sem_unlink("/my_semaphore") != 0) {
        perror("Failed to unlink semaphore");
    }
}

// Function to convert images to PDF
int convert_images_to_pdf(const char* directory_path, const char* output_file_name, const char** image_filenames, int num_images, const char* output_format, int concurrency_limit) {
    sem_t *sem = create_semaphore(concurrency_limit);
    if (sem == NULL) {
        return 1;
    }

    // Directory handling and PDF conversion logic here

    delete_semaphore(sem);
    return 0;
}

