```php
<?php

class PasswordManager {
    private $hashedPassword = '';
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
    private $saltRoundCount = 12;
    private $policyServiceUrl = 'https://password-policy-service.com/check';

    public function generateRandomString($length, $characterSet) {
        if ($length < 1 || strlen($characterSet) < 4) {
            throw new InvalidArgumentException('Invalid length or character set');
        }

        $this->validateCharacterSet($characterSet);

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characterSet[rand(0, strlen($characterSet) - 1)];
        }

        return $randomString;
    }

    public function hashPassword($password, $saltRoundCount = null) {
        if ($saltRoundCount === null) {
            $saltRoundCount = $this->saltRoundCount;
        }

        if ($saltRoundCount < 8 || $saltRoundCount > 31) {
            throw new InvalidArgumentException('Invalid salt round count');
        }

        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $saltRoundCount]);
    }

    public function checkPassword($providedPassword) {
        if (empty($this->hashedPassword)) {
            throw new RuntimeException('No password to verify');
        }

        return password_verify($providedPassword, $this->hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (!preg_match('/[A-Z]/', $characterSet) || !preg_match('/[a-z]/', $characterSet) ||
            !preg_match('/\d/', $characterSet) || !preg_match('/[^A-Za-z0-9]/', $characterSet)) {
            throw new InvalidArgumentException('Character set must include at least one uppercase letter, one lowercase letter, one digit, and one special character');
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 8 || $rounds > 31) {
            throw new InvalidArgumentException('Invalid salt round count');
        }

        $this->saltRoundCount = $rounds;
    }

    public function externalPolicyCheck($characterSet) {
        $options = [
            'http' => [
                'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                'method'  => 'POST',
                'content' => http_build_query(['charset' => $characterSet]),
            ],
        ];

        $context  = stream_context_create($options);
        $response = file_get_contents($this->policyServiceUrl, false, $context);

        if ($response === FALSE) {
            throw new RuntimeException('Failed to check external password policy service');
        }

        return json_decode($response)->compliant;
    }

    public function resetPassword() {
        $newPassword = $this->generateRandomString(12, $this->characterSet);
        $this->hashPassword($newPassword);

        // Log the new password for security review
        error_log('New Password: ' . $newPassword);
    }
}
?>
