    NamedSemaphore *ns = (NamedSemaphore*)malloc(sizeof(NamedSemaphore));
    if (!ns) return NULL;

    snprintf(ns->name, SEM_NAME_MAX_LEN, "/%s", name);
    ns->sem = sem_open(ns->name, O_CREAT | O_EXCL, 0644, initial_value);
    if (ns->sem == SEM_FAILED) {
        free(ns);
        return NULL;
    }

    return ns;
}

void delete_semaphore(NamedSemaphore *ns) {
    if (!ns || !ns->sem) return;

    sem_close(ns->sem);
    sem_unlink(ns->name);
    free(ns);
}

int acquire_semaphore(NamedSemaphore *ns, struct timespec *timeout) {
    if (!ns || !ns->sem) return -1;

    int ret = sem_wait(ns->sem);
    if (ret == -1 && errno == ETIMEDOUT && timeout) {
        ret = sem_timedwait(ns->sem, timeout);
    }

    return ret;
}

int release_semaphore(NamedSemaphore *ns) {
    if (!ns || !ns->sem) return -1;

    return sem_post(ns->sem);
}

void log_semaphore_info(NamedSemaphore *ns, int acquire_result) {
    printf("Semaphore %s: ", ns->name);
    if (acquire_result == 0) {
        printf("Acquired successfully\n");
    } else {
        printf("Failed to acquire with error %d\n", errno);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments and environment variables
    const char *sem_name = "example_semaphore";
    int initial_value = 1;
    struct timespec timeout;

    // Create semaphore
    NamedSemaphore *ns = create_semaphore(sem_name, initial_value);
    if (!ns) {
        fprintf(stderr, "Failed to create semaphore\n");
        return EXIT_FAILURE;
    }

    // Acquire semaphore
    int result = acquire_semaphore(ns, &timeout);
    log_semaphore_info(ns, result);

    // Release semaphore
    release_semaphore(ns);

    // Delete semaphore
    delete_semaphore(ns);

    return EXIT_SUCCESS;
}
