async function establishDatabaseConnectionTest(moduleLabel, testSuites, config) {
  const pool = await createPool({
    host: config.database.host,
    user: config.database.user,
    password: config.database.password,
    database: config.database.database,
    waitForConnections: true,
    connectionLimit: config.resourceLimits.maxConnections
  });

  for (const suite of testSuites) {
    console.log(`Starting test suite for ${moduleLabel}:`);
    const startTime = performance.now();

    for (const testCase of suite) {
      try {
        await testCase(pool);
        console.log(`Test case passed: ${testCase.name}`);
      } catch (error) {
        console.error(`Test case failed: ${testCase.name}. Error:`, error.message);
      }
      blueslip.reset(); // Reset mocking library after each test
    }

    const endTime = performance.now();
    console.log(`Test suite completed in ${endTime - startTime} ms for ${moduleLabel}`);
  }

  pool.end();
}
