// module-loader.js
const fs = require('fs');
const path = require('path');

class ModuleLoader {
  constructor(config) {
    this.config = config;
    this.modules = {};
    this.moduleCache = new Map();
  }

  loadModule(moduleName, dependencies = []) {
    return new Promise((resolve, reject) => {
      if (this.moduleCache.has(moduleName)) {
        resolve(this.moduleCache.get(moduleName));
        return;
      }

      const modulePath = path.join(__dirname, 'modules', moduleName);

      fs.readFile(modulePath, 'utf8', (err, data) => {
        if (err) {
          reject(`Module ${moduleName} not found`);
          return;
        }

        try {
          const module = eval(data); // eslint-disable-line no-eval
          this.moduleCache.set(moduleName, module);

          Promise.all(dependencies.map(dep => this.loadModule(dep)))
            .then(deps => {
              resolve(module.initialize(...deps));
            })
            .catch(error => reject(`Failed to load dependencies for ${moduleName}: ${error}`));
        } catch (error) {
          reject(`Error loading module ${moduleName}: ${error}`);
        }
      });
    });
  }

  hotReloadModule(moduleName) {
    if (this.moduleCache.has(moduleName)) {
      this.moduleCache.delete(moduleName);
      return this.loadModule(moduleName, this.config.modules[moduleName].dependencies);
    }
    return Promise.resolve();
  }

  invalidateCache(moduleName) {
    if (this.moduleCache.has(moduleName)) {
      this.moduleCache.delete(moduleName);
    }
  }

  validateConfig(config) {
    // Implement validation logic for the config object
  }

  start() {
    this.validateConfig(this.config);

    const modulePromises = Object.keys(this.config.modules).map(moduleName => 
      this.loadModule(moduleName, this.config.modules[moduleName].dependencies)
    );

    return Promise.all(modulePromises);
  }
}

module.exports = ModuleLoader;
