                if (_semaphore.WaitOne())
                {
                    Process process = StartImageToPdfConversion(directoryPath, fileName, outputFileName, outputFormat);
                    processes.Add(process);

                    // Check for concurrency limit
                    if (processes.Count >= ConcurrencyLimit)
                    {
                        WaitForAnyProcess(processes);
                    }
                }
            }

            WaitForAllProcesses(processes);

            DeleteSemaphore();
        }
        catch (Exception ex)
        {
            LogError(ex);
        }
    }

    private static void InitializeSemaphore()
    {
        _semaphore = new Semaphore(ConcurrencyLimit, ConcurrencyLimit);
    }

    private static Process StartImageToPdfConversion(string directoryPath, string fileName, string outputFileName, string outputFormat)
    {
        // Example command for a third-party tool
        string command = $"thirdpartytool convert \"{directoryPath}\\{fileName}\" \"{outputFileName}.pdf\" -format {outputFormat}";
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c {command}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        Process process = Process.Start(startInfo);
        return process;
    }

    private static void WaitForAnyProcess(List<Process> processes)
    {
        while (processes.Count > 0 && !processes.Any(p => p.HasExited))
        {
            Thread.Sleep(100);
        }
    }

    private static void WaitForAllProcesses(List<Process> processes)
    {
        foreach (var process in processes)
        {
            if (!process.HasExited)
            {
                process.WaitForExit();
            }
        }
    }

    private static void DeleteSemaphore()
    {
        _semaphore.Close();
    }

    private static void LogError(Exception ex)
    {
        string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
        string errorLog = $"[{timestamp}] Error: {ex.Message} - Code: {ex.HResult}\n";
        File.AppendAllText("errorlog.txt", errorLog);
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        if (args.Length < 3)
        {
            Console.WriteLine("Usage: ImageToPdfConverter directoryPath outputFileName imageFileNames outputFormat");
            return;
        }

        string directoryPath = args[0];
        string outputFileName = args[1];
        List<string> imageFileNames = args.Skip(2).ToList();
        string outputFormat = "PDF";

        ImageToPdfConverter.convert_images_to_pdf(directoryPath, outputFileName, imageFileNames, outputFormat);
    }
}
