<?php

use Psr\Container\ContainerInterface;
use Doctrine\ORM\EntityManager;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Routing\Annotation\Route;
use Symfony\Component\Security\Core\Encoder\UserPasswordEncoderInterface;
use Symfony\Component\Validator\Validation;

class DynamicImageCrawler extends AbstractMicroservice
{
    private $entityManager;
    private $passwordEncoder;
    private $validator;
    private $rateLimiter;
    private $config;

    public function __construct(ContainerInterface $container)
    {
        $this->entityManager = $container->get(EntityManager::class);
        $this->passwordEncoder = $container->get(UserPasswordEncoderInterface::class);
        $this->validator = Validation::createValidatorBuilder()->enableAnnotationMapping()->build();
        $this->rateLimiter = new RateLimiter($container->getParameter('rate_limit'));
        $this->config = $container->getParameter('user_management_config');
    }

    /**
     * @Route("/users", methods={"POST"})
     */
    public function createUser(Request $request): Response
    {
        $data = json_decode($request->getContent(), true);

        if (!$this->rateLimiter->allowRequest()) {
            return new Response(json_encode(['status' => 'error', 'message' => 'Too many requests', 'data' => null]), 429);
        }

        $user = new User();
        $user->setName($data['name']);
        $user->setEmail($data['email']);
        $user->setPassword($this->passwordEncoder->encodePassword($user, $data['password']));

        $errors = $this->validator->validate($user);

        if (count($errors) > 0) {
            return new Response(json_encode(['status' => 'error', 'message' => 'Validation failed', 'data' => null]), 400);
        }

        $this->entityManager->persist($user);
        $this->entityManager->flush();

        return new Response(json_encode(['status' => 'success', 'message' => 'User account created successfully', 'data' => ['id' => $user->getId(), 'name' => $user->getName(), 'email' => $user->getEmail()]]), 201);
    }

    // Add update and delete routes here...
}
