use std::sync::{Arc, Mutex};
use reqwest::{Client, RequestBuilder, Error};
use serde_json::Value;
use tokio::sync::Mutex as AsyncMutex;

#[derive(Clone)]
struct Config {
    base_url: String,
    disable_certificate_validation: bool,
    custom_headers: Option<Vec<(String, String)>>,
    enable_redirects: bool,
}

impl Config {
    fn from_file(file_path: &str) -> Result<Self, Error> {
        let config_text = std::fs::read_to_string(file_path)?;
        let value: Value = serde_json::from_str(&config_text)?;

        Ok(Config {
            base_url: value["base_url"].as_str().unwrap_or("").to_string(),
            disable_certificate_validation: value["disable_certificate_validation"]
                .as_bool()
                .unwrap_or(false),
            custom_headers: value["custom_headers"]
                .as_array()
                .map(|headers| headers.iter().map(|header| (header[0].as_str().unwrap().to_string(), header[1].as_str().unwrap().to_string())).collect())
                .ok(),
            enable_redirects: value["enable_redirects"].as_bool().unwrap_or(true),
        })
    }
}

struct HttpClient {
    client: Arc<Mutex<Client>>,
    config: Arc<Config>,
    rate_limiter: Option<RateLimiter>,
}

impl HttpClient {
    async fn new(config_path: &str, rate_limiter: Option<RateLimiter>) -> Result<Self, Error> {
        let config = Config::from_file(config_path)?;
        let client = Client::builder()
            .danger_accept_invalid_certs(config.disable_certificate_validation)
            .build()?;

        Ok(HttpClient {
            client: Arc::new(Mutex::new(client)),
            config: Arc::new(config),
            rate_limiter,
        })
    }

    async fn request(&self, method: reqwest::Method, url: &str) -> Result<RequestBuilder, Error> {
        let mut builder = self.client.lock().unwrap().request(method, url);
        if let Some(headers) = &self.config.custom_headers {
            for (key, value) in headers {
                builder = builder.header(key, value);
            }
        }
        if self.config.enable_redirects {
            builder = builder.redirect(reqwest::redirect::Policy::default());
        }

        Ok(builder)
    }

    async fn send_request<B>(&self, request: RequestBuilder, body: Option<B>) -> Result<reqwest::Response, Error>
    where
        B: reqwest::Body,
    {
        if let Some(rate_limiter) = &self.rate_limiter {
            rate_limiter.acquire().await?;
        }

        match body {
            Some(body) => request.body(body).send().await,
            None => request.send().await,
        }
    }
}

