        if (protocol_) {
            protocol_->connect(host, port);
        }
    }

    void disconnect() {
        if (protocol_) {
            protocol_->disconnect();
        }
    }

    bool sendData(const std::string& data) {
        if (protocol_) {
            return protocol_->sendData(data);
        }
        return false;
    }

    std::string receiveData() {
        if (protocol_) {
            return protocol_->receiveData();
        }
        return "";
    }

private:
    std::shared_ptr<NetworkProtocol> protocol_;
};

int main() {
    NetworkManager manager("TCP");
    manager.connect("example.com", 80);
    // Use manager to send and receive data
    manager.disconnect();
    return 0;
}
