class SecurePasswordManager {
    private $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+';
    private $minEntropy = 128;

    public function generateRandomString($length) {
        $result = '';
        while (strlen($result) < $this->minEntropy / 8) {
            $result .= substr(str_shuffle($this->charset), 0, $length);
        }
        return substr($result, 0, $length);
    }

    public function hashPassword($password, $salt, $algorithm = 'bcrypt') {
        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password . $salt, PASSWORD_BCRYPT);
            case 'argon2':
                return password_hash($password . $salt, PASSWORD_ARGON2I);
            default:
                throw new Exception("Unsupported hashing algorithm");
        }
    }

    public function verifyPassword($hashedPassword, $password, $salt) {
        return password_verify($password . $salt, $hashedPassword);
    }
}
