using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class CsvFileProcessor
{
    private readonly Dictionary<string, List<object>> _cache = new Dictionary<string, List<object>>();
    private readonly string _filePath;
    private readonly ILoggingSystem _logger;

    public CsvFileProcessor(string filePath, ILoggingSystem logger)
    {
        _filePath = filePath;
        _logger = logger;
    }

    public List<T> GetColumnData<T>(string columnName)
    {
        if (_cache.ContainsKey(columnName))
            return _cache[columnName].Cast<T>().ToList();

        lock (_cache)
        {
            if (!_cache.ContainsKey(columnName))
            {
                var columnValues = ReadColumnFromCsv(columnName);
                _cache[columnName] = columnValues;
            }
        }

        return _cache[columnName].Cast<T>().ToList();
    }

    public Dictionary<string, object> GetRowData(int rowIndex)
    {
        if (rowIndex < 0 || !File.Exists(_filePath))
            return null;

        lock (_cache)
        {
            var rowData = ReadRowFromCsv(rowIndex);
            _cache[rowIndex.ToString()] = rowData.Select(x => x.Value).ToList();
            return rowData;
        }
    }

    public void ExportToCsv(string outputFilePath, Dictionary<string, List<T>> data)
    {
        using (var writer = new StreamWriter(outputFilePath))
        {
            var headers = string.Join(",", data.Keys);
            writer.WriteLine(headers);

            for (int i = 0; i < data.Values.First().Count; i++)
            {
                var rowValues = data.Select(kvp => kvp.Value[i]).ToArray();
                writer.WriteLine(string.Join(",", rowValues));
            }
        }
    }

    private Dictionary<string, object> ReadRowFromCsv(int rowIndex)
    {
        try
        {
            using (var reader = new StreamReader(_filePath))
            {
                for (int i = 0; i <= rowIndex; i++)
                {
                    var line = reader.ReadLine();
                    if (i == rowIndex)
                    {
                        return line.Split(',').ToDictionary((header, index) => header.Trim(), value => value.Trim());
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error reading row from CSV");
            throw;
        }

        return null;
    }

    private List<object> ReadColumnFromCsv(string columnName)
    {
        try
        {
            using (var reader = new StreamReader(_filePath))
            {
                var headers = reader.ReadLine().Split(',');
                int columnIndex = Array.IndexOf(headers, columnName);

                if (columnIndex == -1)
                    throw new ColumnNotFoundException($"Column '{columnName}' not found");

                var columnValues = new List<object>();
                while (!reader.EndOfStream)
                {
                    var line = reader.ReadLine();
                    var values = line.Split(',');
                    if (values.Length > columnIndex)
                        columnValues.Add(values[columnIndex]);
                }

                return columnValues;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error reading column from CSV");
            throw;
        }
    }
}

public class ColumnNotFoundException : Exception
{
    public ColumnNotFoundException(string message) : base(message) { }
}

public interface ILoggingSystem
{
    void LogError(Exception ex, string message);
}
