use std::fs;
use std::time::{Instant, Duration};
use std::collections::HashMap;

fn compile_rust_directory(directory_path: &str) -> Result<String, String> {
    let start_time = Instant::now();
    let mut total_memory_used = 0;
    let mut log_messages = Vec::new();

    for entry in fs::read_dir(directory_path).map_err(|e| e.to_string())? {
        let path = entry?.path();
        if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("rs") {
            match compile_rust_file(&path) {
                Ok(memory_used) => {
                    total_memory_used += memory_used;
                    log_messages.push(format!("Compiled {} successfully", path.display()));
                }
                Err(e) => return Err(e),
            }
        }
    }

    let end_time = Instant::now();
    let duration = end_time.duration_since(start_time);
    log_messages.push(format!("Total compilation time: {:?}", duration));
    log_messages.push(format!("Peak memory usage: {} bytes", total_memory_used));

    Ok(log_messages.join("\n"))
}

