        {
            throw new ArgumentException("Invalid input parameters.");
        }

        if (!await _configurationService.ConfigurationExistsAsync(userId, configName))
        {
            throw new InvalidOperationException("Configuration does not exist for the given user.");
        }

        await _cacheManager.RecycleThemeBitmapAsync();

        var updated = await _configurationService.UpdateConfigurationAsync(userId, configName, newValue);
        if (updated)
        {
            var pngFile = _cacheManager.GetPngFileFromCacheRoot();
            await _themeCache.IncorporatePngIntoCache(pngFile);
        }

        var apiResponse = await ExternalApi.VersionControlAndLogChange(configName, newValue);
        Console.WriteLine(apiResponse);
    }
