const axios = require('axios');
const { Worker, isMainThread, parentPort } = require('worker_threads');

class TextAnalysisModule {
  constructor(settings) {
    this.settings = settings;
    this.referenceRegexes = {
      bible: /(\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Moses|Ruth|Samuel|Kings|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum-Habakkuk-Haggai-Zechariah-Malachi)\b)/gi,
      quran: /(\b(Sura|Ayah)\b)/gi,
      torah: /(\b(Deuteronomy|Exodus|Genesis|Leviticus|Numbers|Ruth)\b)/gi,
      vedas: /(\b(Rig Veda|Sama Veda|Yajur Veda|Mundaka Upanishad)\b)/gi
    };
  }

  async extractReferences(text, religiousType) {
    if (!this.referenceRegexes[religiousType]) {
      throw new Error('Unsupported religious type');
    }

    const matches = text.match(this.referenceRegexes[religiousType]);
    if (!matches) {
      return [];
    }

    const verifiedReferences = await this.verifyReferences(matches, religiousType);
    return verifiedReferences;
  }

  async verifyReferences(references, religiousType) {
    const url = `https://api.example.com/verify/${religiousType}`;
    try {
      const response = await axios.post(url, references);
      return response.data.verifiedReferences;
    } catch (error) {
      throw new Error('Error verifying references');
    }
  }

  async processText(text, religiousTypes) {
    if (!Array.isArray(references)) {
      throw new Error('Invalid input: religiousTypes must be an array');
    }

    const results = [];
    for (const religiousType of religiousTypes) {
      try {
        const references = await this.extractReferences(text, religiousType);
        results.push({ religiousType, references });
      } catch (error) {
        console.error(`Error processing ${religiousType}:`, error.message);
      }
    }

    return results;
  }

  static async runConcurrently(texts, religiousTypes) {
    if (!Array.isArray(texts)) {
      throw new Error('Invalid input: texts must be an array');
    }

    const workers = [];
    for (const text of texts) {
      const worker = new Worker(__filename);
      worker.on('message', result => console.log(result));
      worker.on('error', error => console.error(error.message));
      worker.on('exit', code => {
        if (code !== 0)
          console.error(`Worker stopped with exit code ${code}`);
      });
      worker.postMessage({ text, religiousTypes });
      workers.push(worker);
    }

    return Promise.all(workers.map(worker => new Promise(resolve => worker.on('exit', resolve))));
  }
}

module.exports = TextAnalysisModule;
