import os
from concurrent.futures import ThreadPoolExecutor
import requests
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

# Configuration management system integration (simulated)
config = {
    'certificate_sources': {
        'source1': 'https://example.com/certificate.pem',
        'source2': 'https://backup.example.com/certificate.pem'
    },
    'cache_size': 50
}

# Cache for storing certificates
certificate_cache = {}
cert_lock = threading.Lock()

def fetch_certificate(source):
    try:
        response = requests.get(source)
        response.raise_for_status()
        return response.content
    except requests.RequestException as e:
        print(f"Error fetching certificate from {source}: {e}")
        return None

def get_private_key():
    # Simulate private key retrieval
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048,
        backend=default_backend()
    )
    return private_key

def generate_pem(private_key, certificate):
    with cert_lock:
        if not private_key or not certificate:
            print("Error: Private key or certificate is None")
            return None
        pem = private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.TraditionalOpenSSL,
            encryption_algorithm=serialization.NoEncryption()
        )
        pem += certificate
        return pem

def get_certificate(source):
    if source in certificate_cache:
        print(f"Cache hit for {source}")
        return certificate_cache[source]

    with cert_lock:
        if source in certificate_cache:
            print(f"Cache hit (double-checked) for {source}")
            return certificate_cache[source]

        pem = fetch_certificate(source)
        if not pem:
            print(f"Cache miss and fallback for {source}")
            for alt_source in config['certificate_sources'].values():
                if alt_source != source:
                    alt_pem = fetch_certificate(alt_source)
                    if alt_pem:
                        certificate_cache[source] = alt_pem
                        return alt_pem

        if not pem:
            print(f"Failed to fetch certificate for {source} and fallback sources")
            return None

        certificate_cache[source] = pem
        return pem

def get_certificate_async(request):
    executor = ThreadPoolExecutor(max_workers=10)
    future = executor.submit(get_certificate, request['certificate_source'])

    def on_done(future):
        try:
            pem = future.result()
            if pem:
                return generate_pem(get_private_key(), pem)
            else:
                print("Error: Unable to generate PEM from certificate")
                return None
        except Exception as e:
            print(f"Async error: {e}")
            return None

    future.add_done_callback(on_done)
    return future

def main():
    # Simulate OAuth request
    oauth_request = {
        'certificate_source': config['certificate_sources']['source1']
    }

    result = get_certificate_async(oauth_request).result()
    if result:
        print("Certificate generated successfully")
        with open('certificate.pem', 'wb') as f:
            f.write(result)
    else:
        print("Failed to generate certificate")

if __name__ == "__main__":
    main()
```

This code provides a high-level implementation of the task using Python. It includes asynchronous fetching, caching, and fallback mechanisms. The `ThreadPoolExecutor` is used for handling concurrent requests efficiently. The `cryptography` library is utilized for working with private keys and certificates.

To ensure the function can handle high-concurrency, thread-safe operations are employed when accessing shared resources like the cache. For asynchronous fetching, the `concurrent.futures` module is used to submit tasks to a thread pool.

Logging error messages and fallback mechanisms are implemented to provide detailed information about failures and attempts to recover from them.

For unit testing, you can create separate test cases that cover different scenarios, such as successful certificate generation, cache hits, cache misses, and fallbacks. You may use frameworks like `unittest` or `pytest` for this purpose.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <thread>

class ConfigurationSettings {
public:
    using SettingsMap = std::map<std::string, std::variant<int, double, std::string>>;
    using ObserverFunc = std::function<void(const std::string& key, const std::variant<int, double, std::string>& value)>;

    static std::shared_ptr<ConfigurationSettings> LoadFromFiles(const std::vector<std::string>& file_paths) {
        auto settings = std::make_shared<ConfigurationSettings>();
        for (const auto& path : file_paths) {
            settings->LoadFromFile(path);
        }
        return settings;
    }

    template <typename T>
    T GetSetting(const std::string& key, const T& default_value) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (auto it = settings_.find(key); it != settings_.end()) {
            if constexpr (std::is_same_v<T, int>) {
                if (it->second.index() == 0) return std::get<int>(it->second);
            } else if constexpr (std::is_same_v<T, double>) {
                if (it->second.index() == 1) return std::get<double>(it->second);
            } else if constexpr (std::is_same_v<T, std::string>) {
                if (it->second.index() == 2) return std::get<std::string>(it->second);
            }
        }
        return default_value;
    }

    template <typename T>
    bool SetSetting(const std::string& key, const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (auto it = settings_.find(key); it != settings_.end()) {
            if constexpr (std::is_same_v<T, int>) {
                if (it->second.index() == 0) {
                    it->second = value;
                    NotifyObservers(key, value);
                    return true;
                }
            } else if constexpr (std::is_same_v<T, double>) {
                if (it->second.index() == 1) {
                    it->second = value;
                    NotifyObservers(key, value);
                    return true;
                }
            } else if constexpr (std::is_same_v<T, std::string>) {
                if (it->second.index() == 2) {
                    it->second = value;
                    NotifyObservers(key, value);
                    return true;
                }
            }
        }
        return false;
    }

    void AddObserver(const ObserverFunc& observer) {
        observers_.push_back(observer);
    }

private:
    ConfigurationSettings() = default;

    void LoadFromFile(const std::string& path) {
        std::ifstream file(path);
        if (file.is_open()) {
            nlohmann::json json;
            file >> json;
            for (const auto& [key, value] : json.items()) {
                settings_[key] = value.get<std::variant<int, double, std::string>>();
            }
        } else {
            std::cerr << "Failed to load settings from " << path << std::endl;
        }
    }

    void NotifyObservers(const std::string& key, const std::variant<int, double, std::string>& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& observer : observers_) {
            observer(key, value);
        }
    }

    SettingsMap settings_;
    std::vector<ObserverFunc> observers_;
    mutable std::mutex mutex_;
};
