import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private ExecutorService executorService = Executors.newFixedThreadPool(5);
    private DatabaseConnector dbConnector;

    public CommandExecutor(DatabaseConnector dbConnector) {
        this.dbConnector = dbConnector;
    }

    public void executeCommands(String[] commands) {
        for (String command : commands) {
            executorService.submit(() -> {
                try {
                    Process process = Runtime.getRuntime().exec(command);
                    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                    String line;
                    while ((line = reader.readLine()) != null) {
                        System.out.println("Output: " + line);
                        dbConnector.saveCommandResult(line);
                    }
                    while ((line = errorReader.readLine()) != null) {
                        System.err.println("Error: " + line);
                        dbConnector.saveCommandResult(line, true);
                    }

                    int exitCode = process.waitFor();
                    System.out.println("Exit Code: " + exitCode);
                } catch (IOException | InterruptedException e) {
                    System.err.println("Execution failed for command: " + command);
                    e.printStackTrace();
                }
            });
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private class DatabaseConnector {
        // Simulated database connection
        public void saveCommandResult(String result, boolean isError) {
            if (isError) {
                System.err.println("Saving error to DB: " + result);
            } else {
                System.out.println("Saving output to DB: " + result);
            }
        }

        // Simulated database connection pool management
    }

    public static void main(String[] args) {
        DatabaseConnector dbConnector = new DatabaseConnector();
        CommandExecutor executor = new CommandExecutor(dbConnector);

        String[] commands = {"mkdir temp", "touch temp/file.txt", "ls"};
        executor.executeCommands(commands);
        executor.shutdown();
    }
}
