// Define the configuration retrieval function
function loadConfiguration() {
    $cmsUrl = "https://cms.example.com/api/config";
    $fallbackCmsUrls = ["https://cms1.example.com/api/config", "https://cms2.example.com/api/config"];

    // Attempt to retrieve configuration from primary CMS
    try {
        $response = file_get_contents($cmsUrl, false, stream_context_create([
            'http' => [
                'method'  => 'GET',
                'header'  => 'Accept: application/json'
            ]
        ]));

        if ($response === FALSE) {
            throw new Exception("Failed to retrieve configuration from primary CMS");
        }

        return json_decode($response, true);
    } catch (Exception $e) {
        // Fallback to secondary CMS instances
        foreach ($fallbackCmsUrls as $url) {
            try {
                $response = file_get_contents($url, false, stream_context_create([
                    'http' => [
                        'method'  => 'GET',
                        'header'  => 'Accept: application/json'
                    ]
                ]));

                if ($response === FALSE) {
                    throw new Exception("Failed to retrieve configuration from secondary CMS");
                }

                return json_decode($response, true);
            } catch (Exception $e) {
                // Log error and continue to next fallback
                error_log("CMS retrieval failed: " . $e->getMessage());
            }
        }

        // No successful CMS retrieval, use local fallback configuration
        return require_once 'config/local.php';
    }
}

