            $ivlen = openssl_cipher_iv_length('aes-256-cbc');
            $iv = substr($ciphertext, 0, $ivlen);
            $decrypted = openssl_decrypt(substr($ciphertext, $ivlen), 'aes-256-cbc', $key, OPENSSL_RAW_DATA, $iv);

            // Validate decrypted message (e.g., check for required fields)
            if ($this->validateDecryptedMessage($decrypted)) {
                return $decrypted;
            } else {
                throw new Exception("Invalid decrypted message");
            }
        } catch (Exception $e) {
