    public function enqueue($base64EncodedMessage, $contextIdentifier) {
        $this->queue[] = [
            'message' => $base64EncodedMessage,
            'contextIdentifier' => $contextIdentifier
        ];

        // Process the queue asynchronously (e.g., using a worker process)
        $this->processQueue();
    }

    private function processQueue() {
        while (!empty($this->queue)) {
            $item = array_shift($this->queue);

            try {
                $processor = new SecureMessageProcessor('masterKey');
                $decryptedMessage = $processor->decryptMessage($item['message'], $item['contextIdentifier']);

                // Process decrypted message (e.g., store in database)
