void processFSATransitions(std::vector<FSAState>* currentStateList, size_t stateCount, const FSA& fsa, const DataSourceConfig& dataSourceConfig) {
    static ConfigurablePoolAllocator poolAllocator;
    static ExternalDataSource* dataSource = nullptr;
    static DiagnosticInfo diagnosticInfo;

    std::mutex mutex;
    std::condition_variable cv;
    std::queue<std::function<void()>> taskQueue;
    std::atomic<bool> running(true);

    if (dataSourceConfig.useNetwork) {
        delete dataSource;
        dataSource = new NetworkDataSource();
    } else {
        delete dataSource;
        dataSource = new FileDataSource();
    }

    auto worker = [&]() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, []{ return !taskQueue.empty() || !running; });
                if (!running && taskQueue.empty()) break;
                task = std::move(taskQueue.front());
                taskQueue.pop();
            }
            task();
        }
    };

    std::thread workerThread(worker);

    auto fetchDataTask = [&]() {
        try {
            std::string data = dataSource->fetchData(dataSourceConfig);
            // Process fetched data and update state list
        } catch (const std::exception& e) {
            diagnosticInfo.addError("Failed to fetch data: " + std::string(e.what()));
        }
    };

    {
        std::unique_lock<std::mutex> lock(mutex);
        taskQueue.push(fetchDataTask);
    }
    cv.notify_one();

    workerThread.join();

    delete dataSource;
}

