// JavaScript code to dynamically load and execute multiple JavaScript files

// Import necessary modules
const fs = require('fs');
const path = require('path');

// Cache for loaded scripts
let scriptCache = {};

// Function to load and execute a script
function loadAndExecuteScript(scriptPath) {
    if (scriptCache[scriptPath]) {
        console.log(`Loading cached script: ${scriptPath}`);
        return new Promise((resolve, reject) => resolve(scriptCache[scriptPath]));
    }

    return new Promise((resolve, reject) => {
        fs.readFile(scriptPath, 'utf8', (err, content) => {
            if (err) {
                console.error(`Failed to load script: ${scriptPath}`);
                return reject(err);
            }

            try {
                const func = new Function(content); // Evaluate the script content
                scriptCache[scriptPath] = func;
                resolve(func());
                console.log(`Successfully loaded and executed script: ${scriptPath}`);
            } catch (execErr) {
                console.error(`Failed to execute script: ${scriptPath}`);
                reject(execErr);
            }
        });
    });
}

// Function to manage file list and dependencies
async function manageFiles(fileList, dependencyMap) {
    for (const file of fileList) {
        if (!dependencyMap[file]) {
            await loadAndExecuteScript(file);
        } else {
            const requiredFiles = dependencyMap[file];
            for (const depFile of requiredFiles) {
                await loadAndExecuteScript(depFile);
            }
            await loadAndExecuteScript(file);
        }
    }
}

// Example usage
const fileList = ['script1.js', 'script2.js'];
const dependencyMap = {
    'script2.js': ['script1.js']
};

manageFiles(fileList, dependencyMap).catch(console.error);

// Periodically check for file list updates from a RESTful API
setInterval(() => {
    // Fetch updated file list and dependencies from the API
    fetch('https://api.example.com/filelist')
        .then(response => response.json())
        .then(data => {
            manageFiles(data.fileList, data.dependencyMap);
        })
        .catch(console.error);
}, 60000); // Check every minute
```

