use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};
use reqwest::Error as ReqwestError;

#[derive(Debug)]
enum RepositoryType {
    Git,
    S3,
}

#[derive(Debug)]
enum Error {
    ConfigExists(String),
    Network(ReqwestError),
    FileSystem(fs::Error),
    Resource(String),
    VersionControl(String),
    ConflictResolution(String),
}

struct ConfigManager {
    repository: Arc<Mutex<Repository>>,
    config_dir: PathBuf,
}

impl ConfigManager {
    fn new(repository_type: RepositoryType, remote_url: String) -> Result<Self, Error> {
        let repository = match repository_type {
            RepositoryType::Git => Repository::Git(GitRepository::new(remote_url)?),
            RepositoryType::S3 => Repository::S3(S3Repository::new(remote_url)?),
        };

        let config_dir = PathBuf::from("config");

        Ok(ConfigManager {
            repository: Arc::new(Mutex::new(repository)),
            config_dir,
        })
    }

    fn create_or_sync_directory(&self) -> Result<(), Error> {
        if self.config_dir.exists() {
            return Err(Error::ConfigExists(self.config_dir.to_string_lossy().into_owned()));
        }

        fs::create_dir_all(&self.config_dir)?;

        let repository = self.repository.lock().unwrap();
        repository.sync_directory(&self.config_dir)?;

        Ok(())
    }
}

enum Repository {
    Git(GitRepository),
    S3(S3Repository),
}

impl Repository {
    fn sync_directory(&self, local_path: &Path) -> Result<(), Error> {
        match self {
            Repository::Git(repo) => repo.sync(local_path),
            Repository::S3(repo) => repo.sync(local_path),
        }
    }
}

