        if not 1 <= weight <= 100:
            raise ValueError("Weight must be between 1 and 100")
        return weight

    def add_config(self, server_id, port_number, weight):
        with self.lock:
            unique_id = self.generate_unique_id()
            config = {
                'ServerID': server_id,
                'PortNumber': port_number,
                'Weight': self.assign_weight(weight)
            }
            if unique_id in self.configurations:
                raise ValueError("Unique ID conflict")
            self.configurations[unique_id] = config
        return unique_id

    def get_config(self, unique_id):
        with self.lock:
            return self.configurations.get(unique_id, None)

    def update_config(self, unique_id, port_number=None, weight=None):
        with self.lock:
            if unique_id not in self.configurations:
                raise ValueError("Configuration not found")
            config = self.configurations[unique_id]
            if port_number is not None:
                config['PortNumber'] = port_number
            if weight is not None:
                config['Weight'] = self.assign_weight(weight)
        return unique_id

    def delete_config(self, unique_id):
        with self.lock:
            if unique_id in self.configurations:
