import java.net.*;
import java.util.concurrent.*;

public class NetworkPacketProcessor {
    private final BlockingQueue<NetworkPacket> packetQueue;
    private final int slidingWindowSize;
    private long totalPacketCount = 0;
    private long filteredPacketCount = 0;
    private double averagePacketSize;

    public NetworkPacketProcessor(int slidingWindowSize) {
        this.slidingWindowSize = slidingWindowSize;
        this.packetQueue = new ArrayBlockingQueue<>(slidingWindowSize);
    }

    public void processPacket(NetworkPacket packet) {
        if (packetQueue.size() >= slidingWindowSize) {
            NetworkPacket oldestPacket = packetQueue.poll();
            updateMetrics(oldestPacket, false);
        }
        packetQueue.offer(packet);
        updateMetrics(packet, true);
    }

    private void updateMetrics(NetworkPacket packet, boolean isFiltered) {
        totalPacketCount++;
        if (isFiltered) {
            filteredPacketCount++;
        }
        averagePacketSize = (averagePacketSize * (totalPacketCount - 1) + packet.getSize()) / totalPacketCount;
    }

    public double getAveragePacketSize() {
        return averagePacketSize;
    }

    public long getTotalPacketCount() {
        return totalPacketCount;
    }

    public long getFilteredPacketCount() {
        return filteredPacketCount;
    }

    public static void main(String[] args) {
        NetworkPacketProcessor processor = new NetworkPacketProcessor(100);
        // Simulate packet processing
        for (int i = 0; i < 200; i++) {
            NetworkPacket packet = new NetworkPacket(i, "192.168.1." + i, 8080 + i % 10, System.currentTimeMillis());
            processor.processPacket(packet);
        }
        System.out.println("Total Packets: " + processor.getTotalPacketCount());
        System.out.println("Filtered Packets: " + processor.getFilteredPacketCount());
        System.out.println("Average Packet Size: " + processor.getAveragePacketSize() + " bytes");
    }
}

class NetworkPacket {
    private int size;
    private String sourceIP;
    private int destinationPort;
    private long arrivalTime;

    public NetworkPacket(int size, String sourceIP, int destinationPort, long arrivalTime) {
        this.size = size;
        this.sourceIP = sourceIP;
        this.destinationPort = destinationPort;
        this.arrivalTime = arrivalTime;
    }

    public int getSize() {
        return size;
    }

    // Getters for other properties as needed
}
