// C++ Octree Implementation
#include <vector>
#include <mutex>

struct Vector3 {
    float x, y, z;
};

class Node {
public:
    Vector3 bounds[2];
    std::vector<Node*> children;
    std::mutex mutex;

    Node(Vector3 min, Vector3 max) {
        bounds[0] = min;
        bounds[1] = max;
    }

    ~Node() {
        for (auto child : children) delete child;
    }

    void insert(Vector3 point) {
        std::lock_guard<std::mutex> lock(mutex);
        if (isLeaf()) {
            if (children.size() < 8) {
                subdivide();
                for (auto child : children) child->insert(point);
            } else {
                // Handle overflow
            }
        } else {
            findChild(point)->insert(point);
        }
    }

    Node* findChild(Vector3 point) const {
        int index = 0;
        if (point.x > bounds[0].x + (bounds[1].x - bounds[0].x) / 2) index |= 1;
        if (point.y > bounds[0].y + (bounds[1].y - bounds[0].y) / 2) index |= 2;
        if (point.z > bounds[0].z + (bounds[1].z - bounds[0].z) / 2) index |= 4;
        return children[index];
    }

    bool isLeaf() const {
        return children.empty();
    }

private:
    void subdivide() {
        float x = (bounds[0].x + bounds[1].x) / 2.0f, y = (bounds[0].y + bounds[1].y) / 2.0f, z = (bounds[0].z + bounds[1].z) / 2.0f;
        children.push_back(new Node({bounds[0], {x, y, z}}));
        children.push_back(new Node({{x, y, z}, {bounds[1].x, y, z}}));
        children.push_back(new Node({{x, y, z}, {x, bounds[1].y, z}}));
        children.push_back(new Node({{x, y, z}, {x, y, bounds[1].z}}));
        children.push_back(new Node({{x, y, z}, {bounds[1].x, bounds[1].y, z}}));
        children.push_back(new Node({{x, y, z}, {bounds[1].x, y, bounds[1].z}}));
        children.push_back(new Node({{x, y, z}, {x, bounds[1].y, bounds[1].z}}));
        children.push_back(new Node({{x, y, z}, {bounds[1].x, bounds[1].y, bounds[1].z}}));
    }
};

class Octree {
public:
    Node* root;

    Octree(Vector3 min, Vector3 max) {
        root = new Node(min, max);
    }

    ~Octree() {
        delete root;
    }

    void insert(Vector3 point) {
        root->insert(point);
    }
};
