class ScriptLoader {
  constructor(dependencies) {
    this.dependencies = dependencies;
    this.cache = new Map();
    this.attempts = new Map();
  }

  async loadFile(filename) {
    if (this.cache.has(filename)) return this.cache.get(filename);

    let attempt = this.attempts.get(filename) || 0;
    const maxAttempts = 3;

    while (attempt < maxAttempts) {
      try {
        if (this.isLocal(filename)) {
          await this.loadLocalScript(filename);
        } else {
          await this.loadRemoteScript(filename);
        }
        break;
      } catch (error) {
        attempt++;
        if (attempt >= maxAttempts) throw error;
        const delay = Math.pow(2, attempt - 1) * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }

    this.attempts.set(filename, attempt);
    return this.cache.get(filename);
  }

  async loadLocalScript(filename) {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = filename;
      script.onload = resolve;
      script.onerror = () => reject(new Error(`Failed to load local file: ${filename}`));
      document.head.appendChild(script);
    });
  }

  async loadRemoteScript(filename) {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = `https://example.com/scripts/${filename}`;
      script.onload = resolve;
      script.onerror = () => reject(new Error(`Failed to load remote file: ${filename}`));
      document.head.appendChild(script);
    });
  }

  isLocal(filename) {
    // Implement logic to determine if the file should be loaded locally or remotely
    return filename.startsWith('local/');
  }

  async loadAll() {
    const orderedFiles = this.getOrderedFiles();
    for (const file of orderedFiles) {
      await this.loadFile(file);
    }
  }

  getOrderedFiles() {
    // Implement logic to determine the order of files based on dependencies
    // This might involve using a topological sort algorithm
    return [];
  }
}

// Example usage:
const dependencies = {
  'fileA.js': ['fileB.js', 'fileC.js'],
  'fileB.js': ['fileD.js'],
  'fileC.js': [],
  'fileD.js': []
};

const scriptLoader = new ScriptLoader(dependencies);
scriptLoader.loadAll().then(() => console.log('All scripts loaded successfully'));
