import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CommandExecutor {

    private static final int MAX_CONCURRENT_COMMANDS = 10;

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_COMMANDS);

        String command = "your_command_here";
        String filePath = "path_to_your_file";

        File fileToDelete = new File(filePath);
        if (fileToDelete.exists()) {
            fileToDelete.delete();
        }

        try {
            Process process = Runtime.getRuntime().exec(command);
            executor.submit(() -> executeCommand(process, command));
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }

    private static void executeCommand(Process process, String command) {
        try (
            InputStream inputStream = process.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))
        ) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("Output: " + line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        try (
            InputStream errorStream = process.getErrorStream();
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(errorStream))
        ) {
            String line;
            while ((line = errorReader.readLine()) != null) {
                System.err.println("Error: " + line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        try {
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Process interrupted");
        }
    }
}
