class UserAccountManager {
    private $db;
    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db; // Assume a PDO or similar database connection object
        $this->cache = $cache; // Assume a caching mechanism like Redis or Memcached
    }

    public function handleRequest($_REQUEST) {
        if (!isset($_REQUEST['action'])) {
            return json_encode(['message' => 'error', 'status_code' => 400]);
        }

        $action = $_REQUEST['action'];

        switch ($action) {
            case 'create':
                return $this->createUserAccount($_REQUEST);
            case 'update':
                return $this->updateUserAccount($_REQUEST);
            case 'delete':
                return $this->deleteUserAccount($_REQUEST);
            default:
                return json_encode(['message' => 'error', 'status_code' => 400]);
        }
    }

    private function createUserAccount($_REQUEST) {
        if (isset($_REQUEST['id'])) {
            return json_encode(['message' => 'error', 'status_code' => 400]);
        }

        $data = $this->validateData($_REQUEST);
        if ($data['valid'] === false) {
            return json_encode(['message' => 'error', 'status_code' => 400, 'details' => $data['errors']]);
        }

        try {
            $userId = $this->saveUserAccount($data);
            return json_encode(['message' => 'success', 'status_code' => 201]);
        } catch (Exception $e) {
            error_log("Error saving user account: " . $e->getMessage());
            return json_encode(['message' => 'error', 'status_code' => 500]);
        }
    }

    private function updateUserAccount($_REQUEST) {
        if (!isset($_REQUEST['id'])) {
            return json_encode(['message' => 'error', 'status_code' => 400]);
        }

        $data = $this->validateData($_REQUEST);
        if ($data['valid'] === false) {
            return json_encode(['message' => 'error', 'status_code' => 400, 'details' => $data['errors']]);
        }

        try {
            $userId = $this->saveUserAccount($data);
            return json_encode(['message' => 'success', 'status_code' => 200]);
        } catch (Exception $e) {
            error_log("Error updating user account: " . $e->getMessage());
            return json_encode(['message' => 'error', 'status_code' => 500]);
        }
    }

    private function deleteUserAccount($_REQUEST) {
        if (!isset($_REQUEST['id'])) {
            return json_encode(['message' => 'error', 'status_code' => 400]);
        }

        $userId = $_REQUEST['id'];

        try {
            $this->db->beginTransaction();
            $stmt = $this->db->prepare("DELETE FROM users WHERE id = ?");
            $stmt->execute([$userId]);

            if ($stmt->rowCount() === 0) {
                return json_encode(['message' => 'error', 'status_code' => 404]);
            }

            $this->cache->delete("user_$userId");
            $this->db->commit();
            return json_encode(['message' => 'success', 'status_code' => 200]);
        } catch (Exception $e) {
            error_log("Error deleting user account: " . $e->getMessage());
            $this->db->rollBack();
            return json_encode(['message' => 'error', 'status_code' => 500]);
        }
    }

    private function validateData($_REQUEST) {
        // Implement validation logic here
        // Check for valid name, email, password, confirm_password
        // Ensure unique email and username within organization if applicable
        // Return an array with 'valid' key set to true or false
        // and 'errors' key containing error messages if not valid
    }

    private function saveUserAccount($data) {
        $userId = isset($data['id']) ? $data['id'] : null;
        try {
            $this->db->beginTransaction();
            if ($userId) {
                $stmt = $this->db->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
                $stmt->execute([$data['name'], $data['email'], password_hash($data['password'], PASSWORD_DEFAULT), $userId]);
            } else {
                $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
                $stmt->execute([$data['name'], $data['email'], password_hash($data['password'], PASSWORD_DEFAULT)]);
                $userId = $this->db->lastInsertId();
            }

            if ($stmt->rowCount() === 0) {
                throw new Exception("Failed to save/update user account");
            }

            $this->cache->set("user_$userId", $data);
            $this->db->commit();
            return $userId;
        } catch (Exception $e) {
            error_log("Error saving/updating user account: " . $e->getMessage());
            $this->db->rollBack();
            throw $e;
        }
    }

    private function get($id) {
        // Implement logic to retrieve user account data from cache or database
        // If not in cache, fetch from database and store in cache
        return $this->cache->get("user_$id");
    }
}
