from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache
import os
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class BatchFileProcessor:
    def __init__(self, max_workers=5, max_file_size_for_compression=None):
        self.executor = ThreadPoolExecutor(max_workers=max_workers)
        self.cache = lru_cache(maxsize=None)(self._process_file)
        self.max_file_size_for_compression = max_file_size_for_compression
        self.start_time = time.time()

    def _process_file(self, file_path):
        # Placeholder for actual file processing logic
        time.sleep(1)  # Simulate I/O operation
        return f"Processed {file_path}"

    @lru_cache(maxsize=None)
    def process_file(self, file_path):
        if os.path.getsize(file_path) > self.max_file_size_for_compression:
            return self.cache(file_path)
        else:
            result = self._process_file(file_path)
            return result

    def batch_process_files(self, file_paths, on_progress=None):
        results = []
        for i, future in enumerate(self.executor.map(self.process_file, file_paths)):
            if on_progress:
                on_progress(i + 1, len(file_paths), "Processing")
            results.append(future)
        self.executor.shutdown(wait=True)
        total_time = time.time() - self.start_time
        logging.info(f"Batch processing completed in {total_time:.2f} seconds")

    def __del__(self):
        self.executor.shutdown(wait=True)

# Example usage
def progress_callback(completed, total, operation):
    print(f"{completed}/{total} files processed ({operation})")

processor = BatchFileProcessor(max_workers=3, max_file_size_for_compression=1024 * 1024 * 5)
file_paths = ["path/to/file1.txt", "path/to/file2.txt"]  # Add more file paths as needed
processor.batch_process_files(file_paths, on_progress=progress_callback)
