void log_error(sec_error_t error_code);

// Global variables
crypto_primitive_t **supported_primitives;
int num_supported_primitives;
pthread_mutex_t primitives_mutex;

// Main initialization function
sec_error_t init_secure_comm_library() {
    sec_error_t result = load_config_files();
    if (result != SEC_OK) {
        return result;
    }

    // Initialize the library with supported primitives
    for (int i = 0; i < num_supported_primitives; i++) {
        crypto_primitive_t *primitive = supported_primitives[i];
        if (add_primitive(*primitive, NULL) != 0) {
            log_error(SEC_ERR_PRIMITIVE_ADD);
        }
    }

    return SEC_OK;
}

// Load configuration files and determine supported primitives
sec_error_t load_config_files() {
    // Implementation details depend on the specific configuration management system
    // For example, using a JSON or INI file parser to read environment settings

    // Example:
    // supported_primitives = parse_config_file("/path/to/config_file.json");
    // num_supported_primitives = count_entries(supported_primitives);

    return SEC_OK;  // Replace with actual error handling
}

// Free allocated resources for cryptographic primitives
void free_crypto_primitives() {
    pthread_mutex_lock(&primitives_mutex);
    for (int i = 0; i < num_supported_primitives; i++) {
        free(supported_primitives[i]);
    }
    free(supported_primitives);
    supported_primitives = NULL;
    num_supported_primitives = 0;
    pthread_mutex_unlock(&primitives_mutex);
}

// Find a cryptographic primitive by name
crypto_primitive_t* find_primitive(const char *name) {
    pthread_mutex_lock(&primitives_mutex);
    for (int i = 0; i < num_supported_primitives; i++) {
        if (strcmp(supported_primitives[i]->name, name) == 0) {
            pthread_mutex_unlock(&primitives_mutex);
            return supported_primitives[i];
        }
    }
    pthread_mutex_unlock(&primitives_mutex);
    return NULL;
}

// Add a cryptographic primitive to the library
int add_primitive(crypto_primitive_t primitive, int (*backend_function)()) {
    pthread_mutex_lock(&primitives_mutex);

    // Check for duplicates and unsupported configurations
    if (find_primitive(primitive.name)) {
        pthread_mutex_unlock(&primitives_mutex);
        return -1;  // Duplicate name found
    }

    // Cache the result of successful addition
    // ...

    pthread_mutex_unlock(&primitives_mutex);
    return 0;
}

// Log an error message based on the error code
void log_error(sec_error_t error_code) {
    switch (error_code) {
        case SEC_OK:
            printf("Operation successful\n");
            break;
        case SEC_ERR_CONFIG_LOAD:
            printf("Failed to load configuration file\n");
            break;
        case SEC_ERR_PRIMITIVE_ADD:
            printf("Failed to add cryptographic primitive\n");
            break;
        default:
            printf("Unknown error\n");
    }
}
