// Asynchronous XML Reduction in C#
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using HtmlAgilityPack;

public class AsyncXmlReduce {
    private readonly HttpClient _httpClient;
    private readonly SemaphoreSlim _semaphore;

    public AsyncXmlReduce() {
        _httpClient = new HttpClient();
        _httpClient.Timeout = TimeSpan.FromSeconds(30); // Timeout for API calls
        _semaphore = new SemaphoreSlim(Environment.ProcessorCount, Environment.ProcessorCount);
    }

    public async Task<List<string>> ReduceXmlAsync(string xmlContent, string xpathExpression, IEnumerable<string> namespaces) {
        await _semaphore.WaitAsync(); // Limit concurrent operations
        try {
            var doc = new HtmlDocument();
            doc.LoadXml(xmlContent);

            var nodes = doc.DocumentNode.SelectNodes(xpathExpression, namespacesToNameTable(namespaces));
            if (nodes == null || !nodes.Any()) throw new Exception("No data found");

            return nodes.Cast<HtmlNode>().Select(node => node.InnerText).ToList();
        } finally {
            _semaphore.Release(); // Release semaphore
        }
    }

    private NameTable namespacesToNameTable(IEnumerable<string> namespaces) {
        var nameTable = new NameTable();
        foreach (var ns in namespaces) {
            nameTable.Add(ns);
        }
        return nameTable;
    }

    public async Task<List<string>> ReduceXmlAsync(string xmlContent, string xpathExpression) {
        return await ReduceXmlAsync(xmlContent, xpathExpression, Enumerable.Empty<string>());
    }

    public async Task<List<string>> ValidateDataAsync(List<string> data, string apiUrl, string token) {
        var tasks = data.Select(async item => {
            try {
                var response = await _httpClient.GetAsync(apiUrl + "?data=" + Uri.EscapeDataString(item), HttpCompletionOption.ResponseHeadersRead);
                if (!response.IsSuccessStatusCode) throw new Exception("API call failed");
                return await response.Content.ReadAsStringAsync();
            } catch (Exception ex) {
                // Handle exceptions gracefully
                Console.WriteLine(ex.Message);
                return null;
            }
        }).ToList();

        var results = await Task.WhenAll(tasks);
        return results.Where(result => result != null).ToList();
    }

    public void SetLoggingLevel(LogLevel level) {
        // Configure logging level (DEBUG, INFO, ERROR)
        Console.WriteLine($"Log level set to {level}");
    }

    public enum LogLevel {
        DEBUG,
        INFO,
        ERROR
    }
}
