Resource* updateResource(int id, const char *name, float value1, float value2) {
    // Logic to retrieve resource from database using id
    Resource *resource = getResourceFromDatabase(id);

    if (resource == NULL) {
        // Handle error for non-existent resource
        return NULL;
    }

    // Update resource values with new data provided in request body
    resource->name = strdup(name);
    resource->value1 = value1;
    resource->value2 = value2;

    // Logic to update resource in database and return updated resource
    Resource *updatedResource = updateResourceInDatabase(resource);

    if (updatedResource == NULL) {
        // Handle error for failed update operation
        free(updatedResource);
        return NULL;
    }

    return updatedResource;
}

// Function to delete existing resource using DELETE method and return new resource with default values
Resource* deleteResource(int id) {
    // Logic to retrieve resource from database using id
    Resource *resource = getResourceFromDatabase(id);

    if (resource == NULL) {
        // Handle error for non-existent resource
        return NULL;
    }

    // Set default values for deleted resource fields
    free(resource->name);
    memset(resource, 0, sizeof(Resource));

    // Logic to update resource in database and return updated resource
    Resource *updatedResource = updateResourceInDatabase(resource);

    if (updatedResource == NULL) {
        // Handle error for failed update operation
        free(updatedResource);
        return NULL;
    }

    return updatedResource;
}

// Function to read text file line by line, dynamically allocate memory for each line, and print in comma-separated format with average of last two fields
void readTextFileAndPrint(const char *filename) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        // Handle error for failed file open operation
        return;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        float value1, value2;

        if (sscanf(line, "%*[^,],%f,%f", &value1, &value2) == 2) {
            // Print line in comma-separated format with average of last two fields
            printf("%s,%.2f\n", line, (value1 + value2) / 2);
        } else {
            // Handle error for incorrect data format
        }
    }

    free(line);
    fclose(file);
}

