```rust
use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;
use std::sync::{Arc, Mutex};
use tokio::task;
use reqwest::get;
use backoff::{retry_notify, ExponentialBackoff};

#[derive(Debug)]
enum Error {
    Io(std::io::Error),
    Http(reqwest::Error),
    Custom(String),
}

impl From<std::io::Error> for Error {
    fn from(err: std::io::Error) -> Self {
        Error::Io(err)
    }
}

impl From<reqwest::Error> for Error {
    fn from(err: reqwest::Error) -> Self {
        Error::Http(err)
    }
}

fn create_log_directory(name: &str) -> Result<(), Error> {
    let path = Path::new(&name);
    if path.exists() && path.is_dir() {
        return Ok(());
    }

    DirBuilder::new()
        .recursive(true)
        .create(path)
        .map_err(|err| Error::Io(err))?;

    Ok(())
}

async fn download_data(url: &str, log_directory: &str) -> Result<(), Error> {
    let client = reqwest::Client::new();
    let response = retry_notify(
        ExponentialBackoff::default(),
        || async move { client.get(url).send().await },
        |error, delay| {
            println!("Error downloading data from {}: {:?}", url, error);
            std::thread::sleep(delay);
        }
    ).map_err(|err| Error::Http(err))?;

    let content_type = response.headers().get("Content-Type").and_then(|v| v.to_str()).unwrap_or("");
    if !content_type.contains("json") && !content_type.contains("xml") && !content_type.contains("csv") {
        return Err(Error::Custom(format!("Unsupported content type: {}", content_type)));
    }

    let file_path = format!("{}/{}", log_directory, url.split('/').last().unwrap_or(url));
    fs::write(&file_path, response.bytes().await?).map_err(|err| Error::Io(err))?;

    println!("Downloaded data from {} to {}", url, file_path);

    Ok(())
}

fn fetch_and_process_data(log_directory: &str) -> Result<(), Error> {
    create_log_directory(log_directory)?;

    let urls = vec![
        "https://example.com/data1.json",
        "https://example.com/data2.xml",
        "https://example.com/data3.csv",
    ];

    let log_directory = Arc::new(Mutex::new(log_directory.to_string()));
    let handles: Vec<_> = urls
        .iter()
        .map(|url| {
            let log_directory = log_directory.clone();
            task::spawn(async move {
                if let Err(err) = download_data(url, &log_directory.lock().unwrap()) {
                    eprintln!("Failed to download data from {}: {:?}", url, err);
                }
            })
        })
        .collect();

    for handle in handles {
        handle.await.expect("Task failed");
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_fetch_and_process_data() {
        let log_directory = "test_logs";
        fs::remove_dir_all(log_directory).unwrap_or(());
        assert!(fetch_and_process_data(log_directory).is_ok());
        fs::remove_dir_all(log_directory).unwrap_or(());
    }

    #[tokio::test]
    async fn test_download_data_failure() {
        let log_directory = "test_logs";
        fs::create_dir(log_directory).unwrap();
        let url = "https://example.com/invalid";
        assert!(download_data(url, log_directory).is_err());
        fs::remove_dir_all(log_directory).unwrap();
