#define MAX_RNTI 256

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char **)userp)[0] = realloc(((char **)userp)[0], strlen((char *)contents) + 1);
    if (((char **)userp)[0] == NULL) return 0;
    strcat(((char **)userp)[0], (char *)contents);
    return size * nmemb;
}

int fetch_data(const char *url, char **data) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)data);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);

        if(res != CURLE_OK) {
            printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }
    }

    return 0;
}

int processNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int log_level, const char *external_data_source_url, int max_memory_usage_kb) {
    if (num_structures <= 0 || crc_flag_rules == NULL || external_data_source_url == NULL || max_memory_usage_kb <= 0) return -1;

    *nfalist = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) return -1;

    char *data = NULL;
    if (fetch_data(external_data_source_url, &data) != 0) {
        free(*nfalist);
        return -1;
    }

    // Process the data and populate structures
    // ...

    free(data);

    return 0;
}
