#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

// Define supported file types and their corresponding digit counts
typedef struct {
    char *type;
    int digits;
} FileType;

FileType supportedTypes[] = {
    {"txt", 5},
    {"jpg", 3},
    {"png", 3},
    {"pdf", 5},
    {NULL, 0}
};

// Function to parse the original filename
void ParseFilename(const char *filename, char **basename, char **extension) {
    const char *dot = strrchr(filename, '.');
    if (dot == NULL) {
        *basename = strdup(filename);
        *extension = NULL;
    } else {
        size_t len = dot - filename + 1;
        *basename = strndup(filename, len);
        *extension = strdup(dot);
    }
}

// Function to determine the appropriate number of digits based on the file type
int DetermineDigits(const char *filename) {
    for (FileType *ft = supportedTypes; ft->type != NULL; ft++) {
        if (strstr(filename, ft->type) != NULL) {
            return ft->digits;
        }
    }
    return -1; // Unsupported file type
}

// Function to validate the file type against the predefined list of supported types
int ValidateFileType(const char *filename) {
    for (FileType *ft = supportedTypes; ft->type != NULL; ft++) {
        if (strstr(filename, ft->type) != NULL) {
            return 0; // Supported file type
        }
    }
    return -1; // Unsupported file type
}

// Function to update the file extension based on the specified file type
void SetFileType(char *filename, const char *newType) {
    size_t len = strlen(filename);
    if (len > 0 && filename[len - 1] == '.') {
        filename[--len] = '\0';
    }
    strcat(filename, newType);
}

// Function to construct the new filename using the parsed base name, determined digits, and updated file type
void CreateNewFilename(char *newFilename, const char *basename, int digits, const char *extension) {
    snprintf(newFilename, MAX_FILENAME_LENGTH, "%s.%0*d%s", basename, digits, digits, extension);
}

// Function to handle errors and provide appropriate feedback to the caller
int ErrorHandling(int errorCode, ...) {
    va_list args;
    va_start(args, errorCode);
    vfprintf(stderr, "Error: ", args);
    va_end(args);
    return errorCode;
}

// Main function to modify the file extension based on command-line arguments
int ModifyFileExtension(const char *filename, const char *newType) {
    if (filename == NULL || newType == NULL) {
        return ErrorHandling(-1, "Invalid filename or new type");
    }

    char *basename = NULL;
    char *extension = NULL;
    ParseFilename(filename, &basename, &extension);

    if (extension != NULL && ValidateFileType(extension) != 0) {
        free(basename);
        free(extension);
        return ErrorHandling(-1, "Unsupported file type");
    }

    int digits = DetermineDigits(filename);
    if (digits == -1) {
        free(basename);
        free(extension);
        return ErrorHandling(-1, "Unsupported file type");
    }

    SetFileType(filename, newType);
    CreateNewFilename(filename, basename, digits, extension);

    free(basename);
    free(extension);
    return 0;
}
