class FileStorageManager {
    private $storagePath;
    private $allowedFileTypes = ['image/jpeg', 'image/png', 'application/pdf', 'application/msword', 'application/vnd.ms-excel', 'application/zip'];
    private $maxFileSize = 10 * 1024 * 1024; // 10 MB

    public function __construct($storagePath) {
        $this->storagePath = $storagePath;
    }

    public function uploadFile($filePath, $destinationPath, $userId, $fileType, $fileSize, $chunkNumber = null, $totalChunks = 1) {
        // Validate file type and size
        if (!$this->validateFileType($fileType)) return 'Invalid file type';
        if ($fileSize > $this->maxFileSize) return 'File size exceeds limit';

        // Sanitize destination path
        $destinationPath = $this->sanitizeFileName($destinationPath);

        // Handle multipart uploads
        if ($totalChunks > 1) {
            if (!is_dir($this->storagePath . '/' . $userId)) mkdir($this->storagePath . '/' . $userId);
            copy($filePath, $this->storagePath . '/' . $userId . '/' . $destinationPath . '.part' . $chunkNumber);
        } else {
            move_uploaded_file($filePath, $this->storagePath . '/' . $userId . '/' . $destinationPath);
        }

        // Log upload activity
        $this->logUploadAndDownloadActivity($userId, $destinationPath, 'upload');

        return 'File uploaded successfully';
    }

    public function downloadFile($fileId, $userId) {
        // Retrieve file metadata
        $fileMetadata = $this->getFileMetadata($fileId);
        if (!$fileMetadata || $fileMetadata['user_id'] != $userId) return 'Unauthorized access';

        // Set headers for file download
        header('Content-Description: File Transfer');
        header('Content-Type: application/octet-stream');
        header('Content-Disposition: attachment; filename=' . basename($fileMetadata['filename']));
        header('Expires: 0');
        header('Cache-Control: must-revalidate');
        header('Pragma: public');
        header('Content-Length: ' . $fileMetadata['size']);

        // Read and output the file in chunks
        readfile($this->storagePath . '/' . $fileMetadata['user_id'] . '/' . $fileMetadata['filename']);
    }

    private function validateFileType($fileType) {
        return in_array($fileType, $this->allowedFileTypes);
    }

    private function sanitizeFileName($fileName) {
        $safeName = preg_replace('/[^a-zA-Z0-9.-]/', '', $fileName);
        return basename($safeName);
    }

    public function listUserFiles($userId, $page = 1, $pageSize = 10) {
        // Retrieve user files from storage
        $files = glob($this->storagePath . '/' . $userId . '/*');
        usort($files, function($a, $b) use ($userId) {
            return filemtime($a) - filemtime($b);
        });

        // Apply pagination
        $startIndex = ($page - 1) * $pageSize;
        $endIndex = min($startIndex + $pageSize, count($files));
        $userFiles = array_slice($files, $startIndex, $pageSize);

        // Fetch metadata for each file
        $fileMetadata = [];
        foreach ($userFiles as $file) {
            $filename = basename($file);
            $fileMetadata[] = [
                'id' => md5($userId . $filename),
                'filename' => $filename,
                'size' => filesize($file),
                'upload_date' => date('Y-m-d H:i:s', filemtime($file))
            ];
        }

        return $fileMetadata;
    }

    public function deleteFile($fileId, $userId) {
        // Retrieve file metadata
        $fileMetadata = $this->getFileMetadata($fileId);
        if (!$fileMetadata || $fileMetadata['user_id'] != $userId) return 'Unauthorized access';

        // Delete the file
        unlink($this->storagePath . '/' . $fileMetadata['user_id'] . '/' . $fileMetadata['filename']);

        // Log deletion activity
        $this->logUploadAndDownloadActivity($userId, $fileMetadata['filename'], 'delete');

        return 'File deleted successfully';
    }

    private function generateDownloadLink($fileId) {
        // Generate a secure download link with token-based authentication
        // Implement logic to create and validate the token
        return 'https://example.com/download?token=abc123';
    }

    public function manageFilePermissions($fileId, $permissions) {
        // Manage file permissions using role-based access control (RBAC)
        // Implement logic to update user permissions
        return 'Permissions updated successfully';
    }

    private function logUploadAndDownloadActivity($userId, $fileId, $activityType) {
        // Log each upload and download activity for audit purposes
        // Implement logic to store the log entry
        return 'Log entry created successfully';
    }

    private function getFileMetadata($fileId) {
        // Retrieve file metadata from storage based on file ID
        // Implement logic to fetch the file metadata
        return ['id' => $fileId, 'user_id' => 123, 'filename' => 'example.pdf', 'size' => 5 * 1024 * 1024];
    }
