```python
import os
import shutil
import logging
from datetime import datetime
from argparse import ArgumentParser

def setup_log_directory(log_dir):
    if not os.path.exists(log_dir):
        os.makedirs(log_dir)
    return log_dir

def configure_logging(log_dir):
    log_file = os.path.join(log_dir, 'app.log')
    logging.basicConfig(filename=log_file, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def rotate_logs(log_dir, max_backup_files):
    now = datetime.now()
    backup_pattern = f'app-{now.strftime("%Y-%m-%d")}.log'
    backup_path = os.path.join(log_dir, backup_pattern)

    if os.path.exists(backup_path):
        for _ in range(max_backup_files - 1):
            file_to_move = backup_path
            backup_path = file_to_move.replace(f'-{now.strftime("%Y-%m-%d")}', f'-{datetime.now().strftime("%Y-%m-%d")}')
            shutil.move(file_to_move, backup_path)

    log_file = os.path.join(log_dir, 'app.log')
    if os.path.exists(log_file):
        os.rename(log_file, backup_path)

def parse_arguments():
    parser = ArgumentParser(description='Log Rotation Manager')
    parser.add_argument('--log-dir', default='./logs', help='Path to the log directory')
    parser.add_argument('--rotation-type', choices=['daily', 'size'], default='daily', help='Type of rotation (daily or size)')
    parser.add_argument('--max-backups', type=int, default=3, help='Maximum number of backup files')
    return parser.parse_args()

def main():
    args = parse_arguments()
    log_dir = setup_log_directory(args.log_dir)
    configure_logging(log_dir)

    if args.rotation_type == 'daily':
        rotate_logs(log_dir, args.max_backups)

if __name__ == '__main__':
    main()
