```java
// DynamicImageOptimization.java

package com.example.imageoptimization;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.commons.io.FileUtils;
import net.coobird.thumbnailator.Thumbnails;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DynamicImageOptimization {
    private static final Logger logger = LoggerFactory.getLogger(DynamicImageOptimization.class);
    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void optimizeImages(String inputDirectory, String outputDirectory, int targetFileSize) {
        try {
            File[] imageFiles = new File(inputDirectory).listFiles((dir, name) -> name.endsWith(".jpg") || name.endsWith(".png") || name.endsWith(".webp"));

            for (File inputFile : imageFiles) {
                executorService.submit(() -> compressImage(inputFile, outputDirectory, targetFileSize));
            }
        } catch (IOException e) {
            logger.error("Error reading files from directory: " + inputDirectory, e);
        }
    }

    private void compressImage(File inputFile, String outputDirectory, int targetFileSize) {
        try {
            BufferedImage image = ImageIO.read(inputFile);
            File outputFile = new File(outputDirectory, inputFile.getName());

            Thumbnails.of(image)
                .scale(1.0)
                .outputQuality(0.8)
                .outputFormat("jpg")
                .toFile(outputFile);

            int actualSize = (int) FileUtils.sizeOf(outputFile);
            if (actualSize > targetFileSize) {
                double qualityFactor = Math.sqrt(targetFileSize / (double) actualSize);
                Thumbnails.of(image)
                    .scale(1.0)
                    .outputQuality((float) qualityFactor)
                    .outputFormat("jpg")
                    .toFile(outputFile);
            }

            logger.info("Compressed image: " + inputFile.getName() + ", size: " + FileUtils.sizeOf(outputFile) + " bytes");
        } catch (IOException e) {
            logger.error("Error compressing image: " + inputFile.getName(), e);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
