            this.cache.set(type, jwt);
            return jwt;
        } catch (error) {
            console.error(`Failed to retrieve ${type} token:`, error);
            throw error;
        }
    }

    async refreshJWT() {
        try {
            const jwt = await this.getJWT('access');
            // 检查并刷新JWT
            if (jwt.expiry < Date.now()) {
                const response = await fetch('/api/jwt/refresh', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ refreshToken: jwt.refresh })
                });
                const newJwt = await response.json();
                this.cache.set('access', newJwt);
            }
        } catch (error) {
            console.error('Failed to refresh JWT:', error);
            throw error;
        }
    }

    clearCache() {
        this.cache.clear();
    }
}

// 其他功能实现（如事件系统、多语言支持等）
// 这些功能需要根据具体需求进一步开发和实现
