#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_DESCRIPTION_LENGTH 256

typedef struct {
    int key;
    long timestamp;
    char* description;
    double value;
} record;

int fetch_record_count() {
    // Simulate fetching the number of records from an external SQL database
    return rand() % 1000 + 1; // Random number between 1 and 1000
}

record** initialize_records(int *record_count) {
    int count = fetch_record_count();
    *record_count = count;

    record **records = (record **)malloc(count * sizeof(record *));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(records[j]->description);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->key = rand() % 10001; // Random number between 0 and 10000
        records[i]->timestamp = time(NULL) + (rand() % (365 * 24 * 60 * 60)); // Current time to 1 year ahead
        records[i]->description = (char *)malloc(MAX_DESCRIPTION_LENGTH);
        if (!records[i]->description) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; j++) {
                free(records[j]->description);
                free(records[j]);
            }
            free(records);
            return NULL;
        }
        snprintf(records[i]->description, MAX_DESCRIPTION_LENGTH, "Record %d", records[i]->key);

        records[i]->value = ((double)(rand()) / RAND_MAX) * 20000.0 - 10000.0; // Random double between -10000.0 and 10000.0
    }

    return records;
}

void free_records(record **records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]->description);
        free(records[i]);
    }
    free(records);
}
