public class ConfigManager
{
    private readonly string _connectionString;
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly SemaphoreSlim _cacheLock = new SemaphoreSlim(1, 1);

    public ConfigManager(string connectionString, HttpClient httpClient)
    {
        _connectionString = connectionString;
        _httpClient = httpClient;
    }

    public async Task UpdateConfigurationAsync(string userId, string configName, string newValue)
    {
        if (!IsValidConfigValue(configName, newValue))
        {
            throw new ArgumentException("Invalid configuration value.");
        }

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var transaction = await connection.BeginTransactionAsync();

            try
            {
                // Check user role and authorization
                if (!await IsUserAuthorizedAsync(userId, configName))
                {
                    throw new UnauthorizedAccessException("Unauthorized access.");
                }

                // Get old value for history logging
                string oldValue = null;
                using (var cmd = new SqlCommand("SELECT Value FROM Configurations WHERE UserId = @UserId AND ConfigName = @ConfigName", connection, transaction))
                {
                    cmd.Parameters.AddWithValue("@UserId", userId);
                    cmd.Parameters.AddWithValue("@ConfigName", configName);
                    oldValue = await cmd.ExecuteScalarAsync() as string;
                }

                // Update configuration in database
                using (var cmd = new SqlCommand("UPDATE Configurations SET Value = @Value WHERE UserId = @UserId AND ConfigName = @ConfigName", connection, transaction))
                {
                    cmd.Parameters.AddWithValue("@Value", newValue);
                    cmd.Parameters.AddWithValue("@UserId", userId);
                    cmd.Parameters.AddWithValue("@ConfigName", configName);
                    await cmd.ExecuteNonQueryAsync();
                }

                // Update cache
                _cache[userId + "_" + configName] = newValue;

                // Log configuration change
                await LogConfigurationChangeAsync(userId, configName, oldValue, newValue);

                // Notify users if necessary
                await NotifyUsersAsync(configName);

                // Commit transaction
                await transaction.CommitAsync();
            }
            catch (Exception)
            {
                // Rollback transaction in case of error
                await transaction.RollbackAsync();
                throw;
            }
        }
