```rust
use clap::{App, Arg};
use reqwest::Client;
use tokio;

#[tokio::main]
async fn main() {
    let matches = App::new("Weather Forecast")
        .version("1.0")
        .author("Your Name")
        .about("Fetches weather data for a specified city and displays it.")
        .arg(
            Arg::with_name("city")
                .short('c')
                .long("city")
                .value_name("CITY")
                .help("City to fetch weather for")
                .takes_value(true)
                .required(true),
        )
        .get_matches();

    let city = matches.value_of("city").unwrap();
    let client = Client::new();
    let response = client
        .get(&format!("https://api.openweathermap.org/data/2.5/weather?q={}&appid=YOUR_API_KEY", city))
        .send()
        .await
        .expect("Failed to make request");

    if response.status().is_success() {
        let weather_data = response.json::<WeatherData>().await.expect("Failed to parse JSON");
        println!("Current Weather: {}", weather_data.main.temp);
    } else {
        eprintln!("Failed to fetch weather data");
    }
}

#[derive(serde::Deserialize)]
struct WeatherData {
    main: Main,
}

#[derive(serde::Deserialize)]
struct Main {
    temp: f32,
}
