        {
            // Load tile size from XML
            int tileSize = Convert.ToInt32(xmlDoc.SelectSingleNode("//tileSize").InnerText);

            // Load game world dimensions from XML
            int worldWidth = Convert.ToInt32(xmlDoc.SelectSingleNode("//worldWidth").InnerText);
            int worldHeight = Convert.ToInt32(xmlDoc.SelectSingleNode("//worldHeight").InnerText);

            // Load camera speed from XML
            float cameraSpeed = Convert.ToSingle(xmlDoc.SelectSingleNode("//cameraSpeed").InnerText);

            Console.WriteLine($"Tile Size: {tileSize}");
            Console.WriteLine($"World Width: {worldWidth}, World Height: {worldHeight}");
            Console.WriteLine($"Camera Speed: {cameraSpeed}");
