```python
import requests
from collections import deque
from heapq import heappush, heappop
from threading import Thread
import time

class DataAggregationService:
    def __init__(self, api_urls):
        self.api_urls = api_urls
        self.data_queues = {url: deque() for url in api_urls}
        self.priority_queue = []
        self.lock = threading.Lock()

    def fetch_data(self, url):
        try:
            response = requests.get(url)
            response.raise_for_status()
            return int(response.text.strip())
        except Exception as e:
            print(f"Error fetching data from {url}: {e}")
            return None

    def process_data(self):
        while True:
            with self.lock:
                if not self.priority_queue:
                    time.sleep(0.1)
                    continue
                priority, url = heappop(self.priority_queue)
                data = self.fetch_data(url)
                if data is not None:
                    heappush(self.data_queues[url], (-priority, data))
            self.merge_data()

    def merge_data(self):
        with self.lock:
            while self.data_queues and all(queue for queue in self.data_queues.values()):
                min_priority = float('inf')
                min_url = None
                for url, queue in self.data_queues.items():
                    if queue[0][0] < min_priority:
                        min_priority = queue[0][0]
                        min_url = url
                _, data = heappop(self.data_queues[min_url])
                print(f"Merged data: {data}")

    def start(self):
        threads = [Thread(target=self.process_data) for _ in range(len(self.api_urls))]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

# Example usage
api_urls = [
    "https://api.example.com/data1",
    "https://api.example.com/data2",
    # Add more API URLs here
]

service = DataAggregationService(api_urls)
service.start()
```

This code provides a basic structure for the data aggregation service. It defines a `DataAggregationService` class with methods to fetch data from APIs, process and merge the data, and start the service. The service uses threading to handle multiple API requests concurrently. The merging of data streams is done using a priority queue to ensure that high-priority data streams are processed first. Error handling is implemented to manage potential failures in fetching data from APIs. This example can be expanded with additional features such as caching mechanisms, fault-tolerance strategies, distributed system architecture, and monitoring and logging systems.

