<?php
class SecureWebFileManager {
    private $hashedPassword = '';
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
    private $saltRoundCount = 12;
    private $cache = [];

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        $characters = str_split($this->characterSet);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[array_rand($characters)];
        }
        $this->cache[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        $salt = $this->generateSecureRandomString(22);
        $this->hashedPassword = password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        return password_verify($password . substr($this->hashedPassword, -22), $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^a-zA-Z\d]).+$/', $characterSet)) {
            return true;
        } else {
            // Fallback mechanism to suggest a corrected character set
            $this->characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
            return false;
        }
    }

    public function setSaltRoundCount($rounds) {
        if (is_numeric($rounds) && $rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            // Default to minimum salt round count
            $this->saltRoundCount = 12;
        }
    }

    public function resetPassword() {
        $newCharacterSet = $this->characterSet; // Assume the character set remains the same
        $newSaltRoundCount = $this->saltRoundCount; // Assume the salt round count remains the same

        $this->hashPassword($this->generateSecureRandomString(10)); // Generate a new hash with current settings
        $this->invalidateCache(strlen($this->hashedPassword) - 22); // Invalidate cache for previous password length
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement database or file-based logging system here
        // Example using file logging:
        error_log("IP: {$ipAddress}, Result: {$result}", 3, 'password_attempts.log');
    }

    public function sanitizeInput($input) {
        // Provide a utility method to sanitize user inputs
        return filter_var($input, FILTER_SANITIZE_STRING);
    }

    public function validateFileExtension($file, $allowedExtensions) {
        $extension = pathinfo($file['name'], PATHINFO_EXTENSION);
        return in_array(strtolower($extension), array_map('strtolower', $allowedExtensions));
    }

    public function resizeImage($file, $maxWidth, $maxHeight) {
        // Resize an image file to fit within the specified maximum dimensions while maintaining the aspect ratio
        list($width, $height) = getimagesize($file['tmp_name']);
        $ratio = min($maxWidth / $width, $maxHeight / $height);
        $newWidth = $width * $ratio;
        $newHeight = $height * $ratio;

        $srcImage = getimagesize($file['tmp_name'], $info);
        $dstImage = imagecreatetruecolor($newWidth, $newHeight);

        switch ($info[2]) {
            case IMAGETYPE_JPEG:
                imagecopyresampled($dstImage, $srcImage, 0, 0, 0, 0, $newWidth, $newHeight, $width, $height);
                header('Content-Type: image/jpeg');
                imagejpeg($dstImage);
                break;
            case IMAGETYPE_PNG:
                imagecopyresampled($dstImage, $srcImage, 0, 0, 0, 0, $newWidth, $newHeight, $width, $height);
                header('Content-Type: image/png');
                imagepng($dstImage);
                break;
            default:
                // Handle other image types if necessary
                break;
        }

        imagedestroy($srcImage);
        imagedestroy($dstImage);
    }

    private function invalidateCache($length) {
        unset($this->cache[$length]);
    }
}
