```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_SEMAPHORES 100
#define MAX_NAME_LENGTH 50

typedef struct {
    sem_t semaphore;
    int value;
} Semaphore;

typedef struct {
    char name[MAX_NAME_LENGTH];
    Semaphore sem;
} NamedSemaphore;

NamedSemaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t semaphore_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* operation, const char* semaphore_name) {
    time_t now = time(NULL);
    printf("%s: %s on semaphore '%s'\n", ctime(&now), operation, semaphore_name);
}

int create_semaphore(const char* name, int initial_value) {
    pthread_mutex_lock(&semaphore_mutex);
    if (semaphore_count >= MAX_SEMAPHORES) {
        log_operation("Error", "Too many semaphores");
        pthread_mutex_unlock(&semaphore_mutex);
        return -1;
    }
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            log_operation("Error", "Semaphore already exists");
            pthread_mutex_unlock(&semaphore_mutex);
            return -2;
        }
    }
    strcpy(semaphores[semaphore_count].name, name);
    sem_init(&semaphores[semaphore_count].sem.semaphore, 0, initial_value);
    semaphores[semaphore_count].sem.value = initial_value;
    semaphore_count++;
    log_operation("Created", name);
    pthread_mutex_unlock(&semaphore_mutex);
    return 0;
}

int delete_semaphore(const char* name) {
    pthread_mutex_lock(&semaphore_mutex);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_destroy(&semaphores[i].sem.semaphore);
            memmove(&semaphores[i], &semaphores[i + 1], sizeof(NamedSemaphore) * (semaphore_count - i - 1));
            semaphore_count--;
            log_operation("Deleted", name);
            pthread_mutex_unlock(&semaphore_mutex);
            return 0;
        }
    }
    log_operation("Error", "Semaphore not found");
    pthread_mutex_unlock(&semaphore_mutex);
    return -3;
}

int increment_semaphore(const char* name) {
    pthread_mutex_lock(&semaphore_mutex);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_post(&semaphores[i].sem.semaphore);
            semaphores[i].sem.value++;
            log_operation("Incremented", name);
            pthread_mutex_unlock(&semaphore_mutex);
            return 0;
        }
    }
    log_operation("Error", "Semaphore not found");
    pthread_mutex_unlock(&semaphore_mutex);
    return -3;
}

int decrement_semaphore(const char* name, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }
    pthread_mutex_lock(&semaphore_mutex);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            int result = sem_timedwait(&semaphores[i].sem.semaphore, &ts);
            if (result == 0) {
                semaphores[i].sem.value--;
                log_operation("Decremented", name);
                pthread_mutex_unlock(&semaphore_mutex);
                return 0;
            } else if (result == ETIMEDOUT) {
                log_operation("Timeout", name);
                pthread_mutex_unlock(&semaphore_mutex);
                return -4;
            } else {
                log_operation("Error", "Semaphore operation failed");
                pthread_mutex_unlock(&semaphore_mutex);
                return -3;
            }
        }
    }
    log_operation("Error", "Semaphore not found");
    pthread_mutex_unlock(&semaphore_mutex);
    return -3;
}
