import java.util.*;
import java.util.concurrent.*;
import org.apache.kafka.clients.producer.*;
import javax.sql.DataSource;

public class ServiceManager {
    private int numServices;
    private int maxMessagesPerService;
    private int delayMin;
    private int delayMax;
    private BlockingQueue<String> messageQueue;
    private ExecutorService executorService;
    private KafkaProducer<String, String> kafkaProducer;
    private DataSource dataSource;

    public ServiceManager(int numServices, int maxMessagesPerService, int delayMin, int delayMax) {
        this.numServices = numServices;
        this.maxMessagesPerService = maxMessagesPerService;
        this.delayMin = delayMin;
        this.delayMax = delayMax;
        this.messageQueue = new ArrayBlockingQueue<>(1000);
        this.executorService = Executors.newFixedThreadPool(numServices + 1);
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        this.kafkaProducer = new KafkaProducer<>(props);
        // Initialize database connection and other resources
    }

    public void startServicePool() {
        for (int i = 0; i < numServices; i++) {
            executorService.submit(new ServiceTask(maxMessagesPerService, kafkaProducer));
        }
        executorService.submit(new MessageProcessor());
    }

    public void stopAllServices() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
        kafkaProducer.close();
    }

    public void sendMessage(String message) {
        messageQueue.offer(message);
    }

    // Inner class for service tasks
    private static class ServiceTask implements Runnable {
        private int maxMessages;
        private KafkaProducer<String, String> kafkaProducer;

        public ServiceTask(int maxMessages, KafkaProducer<String, String> kafkaProducer) {
            this.maxMessages = maxMessages;
            this.kafkaProducer = kafkaProducer;
        }

        @Override
        public void run() {
            try {
                Random random = new Random();
                int messagesProcessed = 0;
                while (messagesProcessed < maxMessages) {
                    // Simulate processing time
                    Thread.sleep(random.nextInt(100));
                    // Process message from queue
                    String message = "Message-" + messagesProcessed++;
                    // Simulate delay
                    Thread.sleep(random.nextInt(delayMax - delayMin + 1) + delayMin);
                }
                // Stop service and send stop message to Kafka
                kafkaProducer.send(new ProducerRecord<>("service-stop-topic", "Service stopped"));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    // Inner class for message processor
    private static class MessageProcessor implements Runnable {
        @Override
        public void run() {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    String message = messageQueue.take();
                    // Process message (e.g., update database, log, etc.)
                    System.out.println("Processing: " + message);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager(5, 10, 1000, 5000);
        manager.startServicePool();

        // Simulate sending messages
        for (int i = 0; i < 50; i++) {
            manager.sendMessage("Message-" + i);
        }

        try {
            Thread.sleep(30000); // Run for 30 seconds
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        manager.stopAllServices();
    }
}
