using System;
using UnityEngine;

public class RandomValueGenerator : MonoBehaviour
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public Vector3 GenerateRandomVector3(float minRange, float maxRange)
    {
        return new Vector3(
            UnityEngine.Random.Range(minRange, maxRange),
            UnityEngine.Random.Range(minRange, maxRange),
            UnityEngine.Random.Range(minRange, maxRange)
        );
    }

    public Quaternion GenerateRandomQuaternion(float angle, Vector3 axis)
    {
        var rotation = Quaternion.Euler(angle, 0, 0);
        rotation *= Quaternion.Euler(0, angle, 0);
        rotation *= Quaternion.Euler(0, 0, angle);
        return rotation;
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }
}
