```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdlib.h>
#include <string.h>

#define SALT_LENGTH 16
#define KEY_ITERATIONS 50000

EVP_CIPHER_CTX *init_aes_cbc_cipher(const char *password, size_t password_len, const unsigned char *iv, size_t iv_len, unsigned char **salt) {
    if (!password || !password_len || !iv || !iv_len) {
        return NULL;
    }

    unsigned char derived_key[32];
    unsigned char salt_value[SALT_LENGTH];

    if (RAND_bytes(salt_value, SALT_LENGTH) != 1) {
        return NULL;
    }

    if (PBKDF2_HMAC_SHA512(password, password_len, salt_value, SALT_LENGTH, KEY_ITERATIONS, derived_key, sizeof(derived_key)) != 1) {
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    *salt = malloc(SALT_LENGTH);
    if (!*salt) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    memcpy(*salt, salt_value, SALT_LENGTH);

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx, unsigned char *salt) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }

    if (salt) {
        free(salt);
    }
}
