    api_responses = {
        'email': {'email_enabled': True, 'sms_enabled': False, 'push_enabled': False},
        'SMS': {'email_enabled': False, 'sms_enabled': True, 'push_enabled': False},
        'Push Notifications': {'email_enabled': False, 'sms_enabled': False, 'push_enabled': True}
    }

    return api_responses.get(subscription_type, None)
