from flask import Flask, request, jsonify
import hashlib
import os
import boto3
from functools import wraps

app = Flask(__name__)

# Mock authentication service
def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header or auth_header != 'Bearer valid_token':
            return jsonify({'error': 'Unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

# Mock external storage service
s3_client = boto3.client('s3', aws_access_key_id='access_key', aws_secret_access_key='secret_key')

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

@app.route('/update_resource', methods=['PUT'])
@requires_auth
def update_resource():
    data = request.json
    resource_id = data.get('id')
    new_data = data.get('data')

    # Simulate updating a resource
    if resource_id == '123':
        return jsonify({'message': f'Resource {resource_id} updated successfully.'}), 200
    else:
        return jsonify({'error': f'Resource {resource_id} not found.'}), 404

@app.route('/calculate_md5', methods=['GET'])
def calculate_md5_route():
    file_path = request.args.get('file_path')

    if not file_path or not os.path.exists(file_path):
        return jsonify({'error': 'Invalid file path.'}), 400

    try:
        md5_hash = calculate_md5(file_path)
        return jsonify({'md5_hash': md5_hash}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
