import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.concurrent.CompletableFuture;
import java.util.List;

public class PaymentProcessor {

    private static final String HMAC_KEY = "your_secret_key";
    private static final String AES_KEY = "your_aes_key";

    public void processTransactions(List<PaymentTransaction> transactions) {
        CompletableFuture.allOf(transactions.stream()
                .map(this::processTransaction)
                .toArray(CompletableFuture[]::new))
                .join();
    }

    private CompletableFuture<Void> processTransaction(PaymentTransaction transaction) {
        return CompletableFuture.runAsync(() -> {
            try {
                if (validatePaymentToken(transaction.getPaymentToken())) {
                    String decryptedPayload = decryptPayload(transaction.getEncryptedPayload());
                    if (isValidDecryptedPayload(decryptedPayload)) {
                        // Proceed with payment processing logic here
                    }
                }
            } catch (Exception e) {
                handleTransactionError(e);
            }
        });
    }

    private boolean validatePaymentToken(String paymentToken) throws NoSuchAlgorithmException, InvalidKeyException {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec secretKeySpec = new SecretKeySpec(HMAC_KEY.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
        mac.init(secretKeySpec);
        byte[] hmacResult = mac.doFinal(paymentToken.getBytes(StandardCharsets.UTF_8));
        String calculatedSignature = Base64.getEncoder().encodeToString(hmacResult);
        return paymentToken.equals(calculatedSignature);
    }

    private String decryptPayload(String encryptedPayload) throws NoSuchAlgorithmException, InvalidKeyException {
        Cipher cipher = Cipher.getInstance("AES");
        SecretKeySpec secretKeySpec = new SecretKeySpec(AES_KEY.getBytes(StandardCharsets.UTF_8), "AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);
        byte[] decodedBytes = Base64.getDecoder().decode(encryptedPayload);
        byte[] decryptedBytes = cipher.doFinal(decodedBytes);
        return new String(decryptedBytes, StandardCharsets.UTF_8);
    }

    private boolean isValidDecryptedPayload(String payload) {
        // Implement validation logic here
        return true;
    }

    private void handleTransactionError(Exception e) {
        // Log error and metrics here
        System.err.println("Transaction processing failed: " + e.getMessage());
    }
}

class PaymentTransaction {
    private String paymentToken;
    private String encryptedPayload;

    // Getters and setters

    public String getPaymentToken() {
        return paymentToken;
    }

    public void setPaymentToken(String paymentToken) {
