function renderScriptsFooter(scripts) {
    const footerContainer = document.createElement('div');
    footerContainer.id = 'scripts-footer';

    // Clear previous scripts
    if (document.getElementById('scripts-footer')) {
        document.body.removeChild(document.getElementById('scripts-footer'));
    }

    // Validate input array
    if (!Array.isArray(scripts)) {
        console.error('Invalid input. Expected an array of script objects.');
        return '';
    }

    // Render each script
    scripts.forEach(script => {
        if (typeof script !== 'object' || !script) {
            console.error('Invalid script object in the array.');
            return;
        }

        const scriptTag = document.createElement('script');
        scriptTag.key = Math.random().toString(36).substr(2, 9);
        scriptTag.innerHTML = script.code;

        // Load external scripts
        if (script.src) {
            scriptTag.src = script.src;
            scriptTag.onload = () => console.log(`Script loaded: ${script.src}`);
            scriptTag.onerror = () => console.error(`Failed to load script: ${script.src}`);
        }

        footerContainer.appendChild(scriptTag);
    });

    // Append the container to the body
    document.body.appendChild(footerContainer);

    return footerContainer.outerHTML;
}

// Example usage:
const scripts = [
    { code: 'console.log("Inline script");' },
    { src: 'https://example.com/external-script.js' }
];

renderScriptsFooter(scripts);
```

This function creates a container for the footer scripts, clears any previous instances of this container, and then iterates over the array of script objects to create `<script>` tags. It handles both inline and external scripts, provides error handling for invalid input or failed script loading, and ensures efficient DOM manipulation by appending all scripts at once.

