const axios = require('axios');

async function asyncReduce(pokemonArray, callback) {
  let combinedWeaknesses = '';
  try {
    await pokemonArray.reduce(async (prevPromise, currPokemon) => {
      const response = await prevPromise;
      const pokemonData = await axios.get(`https://pokeapi.co/api/v2/pokemon/${currPokemon.name}`);
      const weaknesses = determineWeaknesses(pokemonData.data.types);
      if (currPokemon.level > 10) {
        weaknesses += ' Extra Weakness';
      }
      combinedWeaknesses += weaknesses;
    }, Promise.resolve());
    return combinedWeaknesses;
  } catch (error) {
    if (error.response) {
      console.error(`Error: ${error.response.status} - ${error.response.data.message}`);
    } else if (error.request) {
      console.error('Error: No response received');
    } else {
      console.error(`Error: ${error.message}`);
    }
    return 'An error occurred during processing';
  }
}

function determineWeaknesses(types) {
  let weaknesses = '';
  types.forEach(type => {
    switch (type.name) {
      case 'normal':
        weaknesses += ' Fire Water Rock Ghost Dragon Steel Fairy';
        break;
      case 'fire':
        weaknesses += ' Water Ground Rock Fire Ice Electric Bug Flying Grass Poison Dark Steel Fairy';
        break;
      // Add cases for other Pokemon types
      default:
        weaknesses += '';
    }
  });
  return weaknesses.trim();
}

// Test cases
