  { name: 'Pikachu', type: 'Electric', level: 5 },
  { name: 'Eevee', type: 'Normal', level: 10 },
  // Add more Pokemon objects as needed
];

asyncReduce(pokemonArray, (combinedWeaknesses) => {
  console.log(combinedWeaknesses);
});
