#include <time.h>

#define MAX_LOG_SIZE 1024
#define BUFFER_SIZE 8192

typedef struct {
    char ip_address[16];
    time_t request_time;
    int response_status_code;
} LogEntry;

typedef struct {
    LogEntry *logs;
    int count;
    int capacity;
} LogBuffer;

typedef struct {
    int total_requests;
    int unique_ips;
    double average_response_time;
    float error_rate;
} Statistics;

void init_log_buffer(LogBuffer *buffer) {
    buffer->logs = (LogEntry *)malloc(BUFFER_SIZE * sizeof(LogEntry));
    buffer->count = 0;
    buffer->capacity = BUFFER_SIZE;
}

void add_log_entry(LogBuffer *buffer, LogEntry entry) {
    if (buffer->count == buffer->capacity) {
        buffer->capacity *= 2;
        buffer->logs = (LogEntry *)realloc(buffer->logs, buffer->capacity * sizeof(LogEntry));
    }
    buffer->logs[buffer->count++] = entry;
}

void process_log_line(char *line, LogEntry *entry) {
    // Parse log line and populate entry structure
    // Example parsing logic:
    sscanf(line, "%s %ld %d", entry->ip_address, &entry->request_time, &entry->response_status_code);
}

void update_statistics(LogBuffer *buffer, Statistics *stats) {
    stats->total_requests += buffer->count;
    for (int i = 0; i < buffer->count; i++) {
        if (!strchr(buffer->logs[i].ip_address, ':')) {
            stats->unique_ips++;
        }
        // Calculate average response time and error rate
    }
}

void free_log_buffer(LogBuffer *buffer) {
    free(buffer->logs);
}

int main() {
    LogBuffer log_buffer;
    Statistics stats;
    char buffer[BUFFER_SIZE];

    init_log_buffer(&log_buffer);

    while (fgets(buffer, BUFFER_SIZE, stdin)) {
        if (strlen(buffer) > 0 && buffer[strlen(buffer) - 1] == '\n') {
            buffer[strlen(buffer) - 1] = '\0';
        }

        LogEntry entry;
        process_log_line(buffer, &entry);
        add_log_entry(&log_buffer, entry);

        if (log_buffer.count % 500 == 0) { // Aggregate statistics every 500 entries
            update_statistics(&log_buffer, &stats);
            printf("Total Requests: %d\n", stats.total_requests);
            printf("Unique IPs: %d\n", stats.unique_ips);
            printf("Average Response Time: %.2f ms\n", stats.average_response_time);
            printf("Error Rate: %.2f%%\n", stats.error_rate * 100);

            // Call external monitoring API with aggregated statistics
        }
    }

    free_log_buffer(&log_buffer);

    return 0;
}
