using System.Threading.Tasks;
using Newtonsoft.Json;
using StackExchange.Redis;

public class DataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private static readonly string CacheKey = "ProcessedData";

    public DataProcessor(HttpClient httpClient, IDistributedCache cache)
    {
        _httpClient = httpClient;
        _cache = cache;
    }

    public async Task<string> ProcessDataAsync(byte[] data)
    {
        try
        {
            var cachedResult = await _cache.GetStringAsync(CacheKey);
            if (cachedResult != null)
            {
                return cachedResult;
            }

            var jsonString = JsonConvert.SerializeObject(data);

            using (var content = new StringContent(jsonString, Encoding.UTF8, "application/json"))
            {
                var response = await _httpClient.PostAsync("https://externalapi.com/Process", content);
                response.EnsureSuccessStatusCode();
                var apiResponse = await response.Content.ReadAsStringAsync();

                await _cache.SetStringAsync(CacheKey, apiResponse, new DistributedCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) // Cache expiration time
                });

                return apiResponse;
            }
        }
        catch (HttpRequestException e)
        {
            Console.WriteLine($"Request exception: {e.Message}");
            throw; // Rethrow or handle as needed
        }
        catch (RedisConnectionException e)
        {
            Console.WriteLine($"Redis connection error: {e.Message}");
            return await FallbackProcessingAsync(data); // Fallback mechanism
        }
    }

    private async Task<string> FallbackProcessingAsync(byte[] data)
    {
        // Implement fallback logic here, e.g., processing locally or using a different service
        var jsonString = JsonConvert.SerializeObject(data);
        return $"Fallback result for {jsonString}";
    }
}
