void Character::updateState(int health, int energy) {
    std::lock_guard<std::mutex> lock(mutex);
    this->health = health;
    this->energy = energy;
}

void Character::addAttackProfile(std::shared_ptr<AttackProfile> profile) {
    std::lock_guard<std::mutex> lock(mutex);
    attackProfiles.push_back(profile);
}

void Character::selectOptimalAttack() {
    std::lock_guard<std::mutex> lock(mutex);

    if (enemies.empty() || energy < 0) return;

    auto optimalAttack = std::min_element(attackProfiles.begin(), attackProfiles.end(),
        [&](const std::shared_ptr<AttackProfile>& a, const std::shared_ptr<AttackProfile>& b) {
            if (a->cost <= b->cost && !a->targetPrioritization(*enemies.front()) &&
                (b->targetPrioritization(*enemies.front()) || a->damage < b->damage)) return true;
            if (a->cost == b->cost && a->targetPrioritization(*enemies.front())) return true;
            return false;
        });

    if (optimalAttack != attackProfiles.end() && optimalAttack->get()->cost <= energy) {
        // Execute the attack
        std::cout << "Executing attack with profile: " << (*optimalAttack)->effect << std::endl;
        energy -= (*optimalAttack)->cost;
    }
}

