import json
from abc import ABC, abstractmethod
from typing import Dict, Any, Callable

class ResourceConfig:
    def __init__(self, type: str, config: Dict[str, Any]):
        self.type = type
        self.config = config

class CloudResource(ABC):
    @abstractmethod
    def allocate(self) -> None:
        pass

    @abstractmethod
    def deallocate(self) -> None:
        pass

class CloudProviderFactory(ABC):
    @abstractmethod
    def create_resource(self, config: ResourceConfig) -> CloudResource:
        pass

    @abstractmethod
    def validate_config(self, config: Dict[str, Any]) -> None:
        pass

class AWSFactory(CloudProviderFactory):
    def create_resource(self, config: ResourceConfig) -> CloudResource:
        # Implement AWS-specific resource creation logic
        pass

    def validate_config(self, config: Dict[str, Any]) -> None:
        # Implement AWS-specific configuration validation logic
        pass

class AzureFactory(CloudProviderFactory):
    def create_resource(self, config: ResourceConfig) -> CloudResource:
        # Implement Azure-specific resource creation logic
        pass

    def validate_config(self, config: Dict[str, Any]) -> None:
        # Implement Azure-specific configuration validation logic
        pass

class GCPFactory(CloudProviderFactory):
    def create_resource(self, config: ResourceConfig) -> CloudResource:
        # Implement GCP-specific resource creation logic
        pass

    def validate_config(self, config: Dict[str, Any]) -> None:
        # Implement GCP-specific configuration validation logic
        pass

class CloudResourceOrchestrator:
    factories = {
        'aws': AWSFactory(),
        'azure': AzureFactory(),
        'gcp': GCPFactory()
    }

    def __init__(self):
        self.resource_registry = {}

    def allocate_resource(self, resource_id: str, config: ResourceConfig) -> None:
        provider_factory = self.factories.get(config.config['provider'])
        if not provider_factory:
            raise ValueError(f"Unsupported cloud provider: {config.config['provider']}")

        provider_factory.validate_config(config.config)
        resource = provider_factory.create_resource(config)
        resource.allocate()
        self.resource_registry[resource_id] = resource

    def deallocate_resource(self, resource_id: str) -> None:
        resource = self.resource_registry.get(resource_id)
        if not resource:
            raise ValueError(f"Resource with ID {resource_id} not found")

        resource.deallocate()
        del self.resource_registry[resource_id]

    def get_resource_config_json(self, resource_id: str) -> str:
        resource = self.resource_registry.get(resource_id)
        if not resource:
            raise ValueError(f"Resource with ID {resource_id} not found")

        return json.dumps(resource.config)

    @staticmethod
    def create_resource_from_json(json_str: str) -> CloudResource:
        config = json.loads(json_str)
        provider_factory = CloudResourceOrchestrator.factories.get(config['provider'])
        if not provider_factory:
            raise ValueError(f"Unsupported cloud provider: {config['provider']}")

        resource_config = ResourceConfig(config['type'], config['config'])
        return provider_factory.create_resource(resource_config)

# Example usage
orchestrator = CloudResourceOrchestrator()
aws_config = {
    'provider': 'aws',
    'type': 'ec2',
    'config': {
        'instance_type': 't2.micro',
        'image_id': 'ami-12345678'
    }
}
orchestrator.allocate_resource('aws-resource', ResourceConfig('aws-config', aws_config))
