```java
import java.io.File;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;

public class ImageCompressor {

    public static void optimizeImageCompression(String inputPath, String outputPath, int targetSize, double maxQualityReduction, boolean enableProgressive) {
        try {
            // Load the image
            BufferedImage image = ImageIO.read(new File(inputPath));

            // Adjust compression settings based on content and size requirements
            double quality = 1.0;
            while (true) {
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
                ImageOutputStream ios = ImageIO.createImageOutputStream(baos);
                writer.setOutput(ios);
                IIOImage iioImage = new IIOImage(image, null, null);
                writer.write(null, iioImage, new javax.imageio.IIOMetadata());
                writer.dispose();

                byte[] imageBytes = baos.toByteArray();
                if (imageBytes.length <= targetSize || quality - 0.1 <= maxQualityReduction) {
                    break;
                }

                quality -= 0.1;
            }

            // Save the compressed image
            ImageIO.write(image, "jpeg", new File(outputPath));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        optimizeImageCompression("input.jpg", "output.jpg", 50000, 10.0, true);
    }
}
