# Custom logging system with support for different levels and Prometheus integration
class CustomLogger:
    def __init__(self, level="INFO", log_file=None):
        self.level = level
        self.log_file = log_file if log_file else "server.log"
        self.lock = Lock()

    def _log(self, message, level):
        with self.lock:
            if self.level in ["DEBUG", "INFO"] or (self.level == "WARNING" and level != "ERROR"):
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_entry = f"{timestamp} [{level}] {message}\n"
                print(log_entry, end="")
                if self.log_file:
                    with open(self.log_file, "a") as file:
                        file.write(log_entry)

    def debug(self, message):
        self._log(message, "DEBUG")

    def info(self, message):
        self._log(message, "INFO")

    def warning(self, message):
        self._log(message, "WARNING")

    def error(self, message):
        self._log(message, "ERROR")

# Decorator for rate limiting
def rate_limit(max_requests_per_minute=10):
    client_request_times = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            request = args[0]
            client_ip = request.client_address[0]
            current_time = datetime.datetime.now()

            if client_ip not in client_request_times:
                client_request_times[client_ip] = [current_time]
                return func(*args, **kwargs)

            request_times = client_request_times[client_ip]
            expired_times = [t for t in request_times if (current_time - t).seconds > 60]
            request_times = [t for t in request_times if t not in expired_times]

            if len(request_times) >= max_requests_per_minute:
                raise Exception("Rate limit exceeded")

            request_times.append(current_time)
            client_request_times[client_ip] = request_times
            return func(*args, **kwargs)

        return wrapper

    return decorator

# Custom HTTP server class with SSL support and basic authentication
