import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {
    private ExecutorService executorService;

    public CommandExecutor() {
        this.executorService = Executors.newFixedThreadPool(10);
    }

    public void executeCommands(String[] commands) {
        for (String command : commands) {
            executorService.submit(() -> {
                try {
                    Process process = Runtime.getRuntime().exec(command);
                    logOutput(process.getInputStream());
                    logError(process.getErrorStream());
                    int exitCode = process.waitFor();
                    System.out.println("Command executed: " + command + ", Exit Code: " + exitCode);
                } catch (IOException | InterruptedException e) {
                    handleException(e, command);
                }
            });
        }
    }

    private void logOutput(InputStream inputStream) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("Output: " + line);
            }
        }
    }

    private void logError(InputStream errorStream) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(errorStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.err.println("Error: " + line);
            }
        }
    }

    private void handleException(Exception e, String command) {
        // Implement retry mechanism with exponential backoff
        // Log error and attempt to execute the command again after a delay
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        CommandExecutor executor = new CommandExecutor();
        String[] commands = {"rm -f example.txt", "mkdir testdir", "touch testfile.txt", "ls"};
        executor.executeCommands(commands);
        executor.shutdown();
    }
}
