import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;

public class SecurePasswordManager {
    private Map<Integer, SecurePasswordFactory> factoryRegistry = new HashMap<>();
    private int saltRoundCount = 10;

    public void registerFactory(int id, SecurePasswordFactory factory) {
        factoryRegistry.put(id, factory);
    }

    public SecurePassword createInstance(int id, String version) {
        return factoryRegistry.get(id).create(version);
    }

    public String generateRandomString() {
        // Generate a random string
        return java.util.UUID.randomUUID().toString();
    }

    public String hashPassword(String password) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashedBytes = md.digest(password.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashedBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public boolean verifyPassword(String password, String hash) throws Exception {
        return hash.equals(hashPassword(password));
    }

    public boolean validateCharacterSet(String password) {
        // Validate character set
        return !password.isEmpty() && 
               (password.matches(".*[a-z].*") && 
                password.matches(".*[A-Z].*") && 
                password.matches(".*\\d.*"));
    }

    public void setSaltRoundCount(int count) {
        this.saltRoundCount = count;
    }

    public void resetPassword(String userId, String newPassword) throws Exception {
