function renderScriptsFooter(scripts) {
  return `
    <footer>
      ${scripts.map(script => 
        script.src ? 
          `<script key="${Date.now()} + Math.random()}" src="${script.src}" onload="errorHandler(this)" onerror="fallbackScript(this)"></script>` : 
          `<script key="${Date.now()} + Math.random()"}>${script.code}</script>`
      ).join('')}
    </footer>
  `;
}

function errorHandler(scriptTag) {
  console.error('Failed to load script:', scriptTag.src);
  fallbackScript(scriptTag);
}

function fallbackScript(scriptTag) {
  const fallbackMessage = 'An error occurred while loading the script. Please try again later.';
  scriptTag.outerHTML = `<p>${fallbackMessage}</p>`;
}
