```csharp
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class LogAggregationSystem : IDisposable
{
    private readonly ILogger _logger;
    private readonly List<LogSource> _logSources;
    private readonly Queue<LogEvent> _logQueue;
    private readonly Dictionary<string, string> _dataFormats;
    private bool _isRunning = true;

    public LogAggregationSystem(ILoggerFactory loggerFactory)
    {
        _logger = loggerFactory.CreateLogger<LogAggregationSystem>();
        _logSources = new List<LogSource>
        {
            new FileLogSource("logs/file1.log"),
            new SyslogLogSource("syslog-server:514"),
            new ApiLogSource("api-endpoint")
        };
        _logQueue = new Queue<LogEvent>();
        _dataFormats = new Dictionary<string, string>
        {
            { "json", "application/json" },
            { "csv", "text/csv" },
            { "plaintext", "text/plain" }
        };

        foreach (var source in _logSources)
        {
            source.LogReceived += OnLogReceived;
        }

        Task.Run(ProcessLogsAsync);
    }

    public void Dispose()
    {
        _isRunning = false;

        foreach (var source in _logSources)
        {
            source.LogReceived -= OnLogReceived;
            source.Dispose();
        }
    }

    private async Task ProcessLogsAsync()
    {
        while (_isRunning)
        {
            if (_logQueue.Count > 0)
            {
                LogEvent logEvent = _logQueue.Dequeue();
                await HandleLogEvent(logEvent);
            }
            else
            {
                await Task.Delay(100); // Check every 100ms if there are new logs
            }
        }
    }

    private void OnLogReceived(object sender, LogEvent logEvent)
    {
        _logQueue.Enqueue(logEvent);
    }

    private async Task HandleLogEvent(LogEvent logEvent)
    {
        string formattedLog = FormatLog(logEvent);

        foreach (var dataFormat in _dataFormats.Values)
        {
            await SendToLoggingProvider(formattedLog, dataFormat);
        }
    }

    private string FormatLog(LogEvent logEvent)
    {
        switch (_dataFormats[logEvent.Format])
        {
            case "application/json":
                return JsonConvert.SerializeObject(logEvent);
            case "text/csv":
                return $"{logEvent.Timestamp},{logEvent.Level},{logEvent.Message}";
            default:
                return logEvent.Message;
        }
    }

    private async Task SendToLoggingProvider(string log, string format)
    {
        // Code to send formatted log to a third-party logging provider
    }

    public void AddLogSource(LogSource source)
    {
        _logSources.Add(source);
        source.LogReceived += OnLogReceived;
    }

    public void RemoveLogSource(LogSource source)
    {
        _logSources.Remove(source);
        source.LogReceived -= OnLogReceived;
        source.Dispose();
    }
}

public abstract class LogSource : IDisposable
{
    public event EventHandler<LogEvent> LogReceived;

    protected virtual void OnLogReceived(LogEvent logEvent)
    {
        LogReceived?.Invoke(this, logEvent);
    }

    public abstract void Start();
    public abstract void Stop();

    public void Dispose()
    {
        Stop();
    }
}

