use std::path::Path;

fn create_config_dir_and_set_env_var(dir_name: &str) -> Result<(), &'static str> {
    if env::var_os(dir_name).is_some() {
        println!("Environment variable {} already set", dir_name);
    } else {
        let path = Path::new(env::current_dir().unwrap()).join(dir_name);
        create_dir_all(&path).map_err(|_| "Failed to create directory")?;
        env::set_var(dir_name, path.to_str().unwrap());
        println!("Created directory {} and set environment variable", dir_name);
    }

    Ok(())
}

fn main() {
    if let Err(e) = create_config_dir_and_set_env_var("MY_CONFIG_DIR") {
        eprintln!("{}", e);
    }
}
