DateInfo parseAndFormatDate(const char *dateStr, const char *formatStr, const char *outputFormat, Logger logger) {
    DateInfo result;
    result.date = NULL;
    result.format = NULL;
    result.output_format = outputFormat;

    if (dateStr == NULL || formatStr == NULL) {
        logMessage("Input date or format string is null.", LOG_ERROR);
        return result;
    }

    // Validate the input date string
    struct tm parsedTime = {0};
    if (strptime(dateStr, "%Y-%m-%d", &parsedTime) == NULL) {
        logMessage("Invalid date format.", LOG_ERROR);
        return result;
    }

    // Allocate memory for the output string
    size_t maxLength = strlen(outputFormat) + 1;
    result.date = (char*)malloc(maxLength);
    if (result.date == NULL) {
        logMessage("Memory allocation failed.", LOG_ERROR);
        return result;
    }

    // Format the date according to the specified output format
    if (strftime(result.date, maxLength, outputFormat, &parsedTime) == 0) {
        free(result.date);
        logMessage("Failed to format date.", LOG_WARNING);
        result.date = NULL;
        return result;
    }

    return result;
}

void freeDateInfo(DateInfo *info) {
    if (info->date != NULL) {
        free(info->date);
        info->date = NULL;
    }
