// Import necessary libraries and initialize variables
const axios = require('axios');
const cache = new Map();

// Regular expressions for Old Testament books (case-insensitive)
const oldTestamentRegex = /(genesis|exodus|leviticus|numbers|deuteronomy|joshua|judges|ruth|1\s*corinthians|2\s*corinthians|galatians|ephesians|philippians|colossians|1\s*thessalonians|2\s*thessalonians|1\s*timothy|2\s*timothy|titus|philemon|hebrews|james|1\s*peter|2\s*peter|1\s*john|2\s*john|3\s*john|judges|revelation)/gi;

// Regular expressions for New Testament books (case-insensitive)
const newTestamentRegex = /(matthew|mark|luke|john|acts|romans|1\s*corinthians|2\s*corinthians|galatians|ephesians|philippians|colossians|1\s*thessalonians|2\s*thessalonians|1\s*timothy|2\s*timothy|titus|philemon|hebrews|james|1\s*peter|2\s*peter|1\s*john|2\s*john|3\s*john|revelation)/gi;

async function extractBooks(text) {
    // Log the start of processing
    console.time('extractBooks');

    // Convert text to lowercase for case-insensitivity
    text = text.toLowerCase();

    // Initialize an object to store book counts
    let bookCounts = {};

    // Check if result is already cached
    if (cache.has(text)) {
        return cache.get(text);
    }

    // Loop through the regular expressions to find matches
    [oldTestamentRegex, newTestamentRegex].forEach(regex => {
        const matches = text.match(regex);
        if (matches) {
            matches.forEach(match => {
                bookCounts[match] = (bookCounts[match] || 0) + 1;
            });
        }
    });

    // Store result in cache
    cache.set(text, bookCounts);

    // Log the end of processing and time taken
    console.timeEnd('extractBooks');

    return bookCounts;
}

// Example usage:
(async () => {
    try {
        const text = "Genesis 1:1, Revelation 22:20";
        const result = await extractBooks(text);
        console.log(result); // { 'genesis': 1, 'revelation': 1 }
    } catch (error) {
        console.error('Error extracting books:', error);
    }
})();
```

