```python
from flask import Flask, request, jsonify
import hashlib
import os

app = Flask(__name__)

# Simulated database for resource storage
resource_db = {}

def update_resource(resource_id, data):
    if resource_id not in resource_db:
        return None
    resource_db[resource_id].update(data)
    return resource_db[resource_id]

@app.route('/update_resource', methods=['PUT'])
def put_resource():
    try:
        resource_id = request.json['id']
        data = request.json.get('data', {})
        updated_resource = update_resource(resource_id, data)
        if updated_resource is None:
            return jsonify({"error": "Resource not found"}), 404
        return jsonify(updated_resource), 200
    except KeyError as e:
        return jsonify({"error": f"Missing key: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"error": str(e)}), 500

def calculate_md5(file_path, chunk_size=8192):
    hash_object = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hash_object.update(data)
    return hash_object.hexdigest()

@app.route('/calculate_md5', methods=['GET'])
def get_md5():
    try:
        file_path = request.args.get('path')
        if not file_path or not os.path.isfile(file_path):
            return jsonify({"error": "Invalid file path"}), 400
        md5_hash = calculate_md5(file_path)
        return jsonify({"md5_hash": md5_hash}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
```

This Flask application provides two endpoints: `/update_resource` for updating a resource using the PUT method and `/calculate_md5` for calculating the MD5 hash of a file. The code includes error handling, input validation, and resource management to ensure scalability, performance optimization, and maintainability.

