#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define NUM_THREADS 4

typedef struct {
    char *line;
    double sum, average;
} LineData;

void parse_line(LineData *data) {
    char *token = strtok(data->line, " ");
    data->sum = 0.0;
    int count = 0;

    while (token != NULL) {
        if (isnumeric(token)) {
            data->sum += atof(token);
            count++;
        }
        token = strtok(NULL, " ");
    }

    if (count < 3) {
        data->average = -1.0; // Indicate error
    } else {
        data->average = data->sum / count;
    }
}

int isnumeric(const char *str) {
    while (*str != '\0') {
        if (!isdigit((unsigned char)*str)) return 0;
        str++;
    }
    return 1;
}

void* process_lines(void *arg) {
    pthread_t thread_id = (pthread_t)arg;
    int start_line, end_line;
    LineData data[MAX_LINE_LENGTH];

    // Initialize your range and read lines here
    // ...

    for (int i = start_line; i <= end_line; i++) {
        parse_line(&data[i]);
        printf("%d,%f\n", i, data[i].average);
    }

    return NULL;
}

void setup_logging() {
    // Setup logging configuration here
    // ...
}

void read_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    pthread_t threads[NUM_THREADS];
    int lines_per_thread = 100; // Adjust based on the number of lines in the file

    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, process_lines, (void *)(long)i) != 0) {
            perror("Error creating thread");
            fclose(file);
            return;
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    setup_logging();
    read_file(argv[1]);

    return EXIT_SUCCESS;
}
