#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>

void print_hex(const unsigned char *data, size_t len) {
    for (size_t i = 0; i < len; ++i)
        printf("%02x", data[i]);
}

int aes_encrypt(const unsigned char *key, const unsigned char *plaintext, int plaintext_len,
                unsigned char *ciphertext, int *ciphertext_len) {
    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL))
        goto err;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto err;
    *ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto err;
    *ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;

err:
    EVP_CIPHER_CTX_free(ctx);
    ERR_print_errors_fp(stderr);
    return -1;
}

int aes_decrypt(const unsigned char *key, const unsigned char *ciphertext, int ciphertext_len,
                unsigned char *plaintext, int *plaintext_len) {
    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL))
        goto err;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        goto err;
    *plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        goto err;
    *plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;

err:
    EVP_CIPHER_CTX_free(ctx);
    ERR_print_errors_fp(stderr);
    return -1;
}

int main() {
    unsigned char key[32], iv[16];
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[128], decryptedtext[128];
    int len, ciphertext_len;

    if (RAND_bytes(key, sizeof(key)) != 1) {
        fprintf(stderr, "Error generating key\n");
        return -1;
    }

    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        fprintf(stderr, "Error generating IV\n");
        return -1;
    }

    if (aes_encrypt(key, iv, plaintext, sizeof(plaintext), ciphertext, &ciphertext_len) != 0) {
        fprintf(stderr, "Encryption failed\n");
        return -1;
    }

    printf("Ciphertext: ");
    print_hex(ciphertext, ciphertext_len);
    printf("\n");

    if (aes_decrypt(key, iv, ciphertext_len, decryptedtext, &len) != 0) {
        fprintf(stderr, "Decryption failed\n");
        return -1;
    }

    decryptedtext[len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

    return 0;
}
