import requests
from time import sleep, time
from functools import wraps
from database import Database
from metrics import Metrics

class PaymentGateway:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = "https://third-party-payment-gateway.com/api"
        self.db = Database()
        self.metrics = Metrics()

    def rate_limit(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start_time = time()
            while True:
                if time() - start_time >= 1:
                    return func(*args, **kwargs)
                sleep(0.1)
        return wrapper

    def retry_on_failure(max_retries=5, backoff_factor=2):
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                retries = 0
                while retries < max_retries:
                    try:
                        response = func(*args, **kwargs)
                        if response.status_code == 200:
                            return response.json()
                        else:
                            raise Exception(f"API request failed with status code {response.status_code}")
                    except Exception as e:
                        retries += 1
                        sleep(backoff_factor * retries)
                raise Exception("Max retries exceeded")
            return wrapper
        return decorator

    @rate_limit
    @retry_on_failure
    def process_transaction(self, amount):
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        data = {
            "amount": amount
        }
        response = requests.post(f"{self.base_url}/transactions", headers=headers, json=data)
        return response

    def filter_transactions(self, transactions):
        current_time = time()
        filtered_transactions = []
        for transaction in transactions:
            if (current_time - transaction['timestamp']) <= 3 and transaction['age'] > 0:
                weighted_sum = transaction['amount'] * transaction['weight']
                transaction['weighted_sum'] = weighted_sum
                filtered_transactions.append(transaction)
        return sorted(filtered_transactions, key=lambda x: x['weighted_sum'], reverse=True)

    def update_metrics(self, transactions):
        for transaction in transactions:
            self.metrics.update(transaction)

    def get_max_weighted_sum_and_id(self, transactions):
        filtered_transactions = self.filter_transactions(transactions)
        if filtered_transactions:
            max_transaction = filtered_transactions[0]
            self.db.store_token(max_transaction['token'])
            return max_transaction['weighted_sum'], max_transaction['id']
        else:
            return None, None

    def validate_response(self, response):
        if 'error' in response:
            raise Exception(f"Validation failed: {response['error']}")
