const fetch = require('node-fetch');
const Semaphore = require('semaphore-async-await');
const { rateLimit } = require('async-sema');

class AsyncArrayReducer {
  constructor(apiUrl, authToken, maxConcurrency = 5, timeout = 5000) {
    this.apiUrl = apiUrl;
    this.authToken = authToken;
    this.maxConcurrency = maxConcurrency;
    this.timeout = timeout;
    this.semaphore = new Semaphore(maxConcurrency);
    this.rateLimiter = rateLimit(10); // Adjust as needed
    this.cache = {};
  }

  async fetchWordList() {
    const cacheKey = `${this.apiUrl}-${this.authToken}`;
    if (this.cache[cacheKey]) {
      return this.cache[cacheKey];
    }

    try {
      const response = await this.rateLimiter(() =>
        fetch(this.apiUrl, {
          headers: { Authorization: `Bearer ${this.authToken}` },
          timeout: this.timeout,
        })
      );

      if (!response.ok) {
        throw new Error(`API request failed with status ${response.status}`);
      }

      const wordList = await response.json();
      this.cache[cacheKey] = wordList;
      return wordList;
    } catch (error) {
      console.error('Failed to fetch word list:', error);
      throw error;
    }
  }

  async reduceArray(accumulator, initialValue) {
    try {
      const wordList = await this.fetchWordList();
      let result = initialValue;

      for (const word of wordList) {
        await this.semaphore.acquire();
        try {
          result = accumulator(result, word);
          progressCallback(wordList.indexOf(word) + 1, wordList.length, result);
        } catch (error) {
          console.error('Error during reduction:', error);
        } finally {
          this.semaphore.release();
        }
      }

      return result;
    } catch (error) {
      console.error('Failed to reduce array:', error);
      throw error;
    }
  }
}

// Usage example
const reducer = new AsyncArrayReducer(
  'https://api.example.com/words',
  'your_auth_token',
  3,
  10000
);

function customAccumulator(currentValue, word) {
  return currentValue + word.length; // Example custom accumulator function
}

async function progressCallback(completed, total, result) {
  console.log(`Progress: ${completed}/${total}, Current Result: ${result}`);
}

(async () => {
  try {
    const finalResult = await reducer.reduceArray(customAccumulator, 0);
    console.log('Final Reduced Value:', finalResult);
  } catch (error) {
    console.error('Error:', error.message);
  }
})();
