# json_base.py
import json
from functools import singledispatchmethod
from pathlib import Path
from typing import Any, Dict, Optional

class JSONBase:
    @singledispatchmethod
    def to_json(self, data: Any) -> str:
        raise NotImplementedError("Subclasses must implement this method")

    @to_json.register
    def _(self, data: Dict[str, Any]) -> str:
        return json.dumps(data)

    @staticmethod
    def from_json(json_string: str) -> Any:
        try:
            return json.loads(json_string)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {e}")

# registry.py
import importlib
from typing import Type, Dict

class Registry:
    _registry: Dict[str, Type] = {}

    @classmethod
    def register(cls, subclass: Type) -> None:
        if not hasattr(subclass, 'register_factory'):
            raise ValueError(f"{subclass.__name__} must have a 'register_factory' decorator")
        cls._registry[subclass.__name__] = subclass

    @classmethod
    def get_subclass(cls, name: str) -> Optional[Type]:
        return cls._registry.get(name)

# subclasses.py
from json_base import JSONBase
from registry import register

@register
class MyClass(JSONBase):
    def __init__(self, data: Dict[str, Any]):
        self.data = data

    def to_json(self, data: Any) -> str:
        # Custom implementation if needed
        return super().to_json(data)

# factory.py
import importlib.util
from typing import Callable

class Factory:
    @staticmethod
    def create_instance(class_name: str, *args, **kwargs) -> object:
        subclass = Registry.get_subclass(class_name)
        if not subclass:
            raise ValueError(f"Class {class_name} is not registered")
        return subclass(*args, **kwargs)

# main.py
from factory import Factory

def register_factory(func):
    def wrapper(*args, **kwargs):
        func(*args, **kwargs)
        Registry.register(func.__qualname__)
    return wrapper

@register_factory
def my_subclass_factory():
    pass

if __name__ == "__main__":
    instance = Factory.create_instance("MyClass", {"key": "value"})
    print(instance.to_json({"data": "test"}))
