#include <zlib.h>
#endif

#define MAX_RECORDS 1000000
#define MIN_KEY 0
#define MAX_KEY 10000
#define DESCRIPTION_SIZE 256
#define MIN_VALUE -10000.0
#define MAX_VALUE 10000.0
#define ONE_YEAR_SECONDS (365 * 24 * 60 * 60)

typedef struct {
    int key;
    long timestamp;
    char description[DESCRIPTION_SIZE];
    double value;
} record;

record* records;
int* keys;
long* timestamps;
char** descriptions;
double* values;
int record_count;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

#ifdef ZLIB_ENABLED
z_stream compress_stream;
#endif

void initialize_record(record* r) {
    r->key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    r->timestamp = time(NULL) + rand() % ONE_YEAR_SECONDS;
    int desc_length = rand() % (DESCRIPTION_SIZE - 1) + 1;
    for (int i = 0; i < desc_length; i++) {
        r->description[i] = 'a' + rand() % 26;
    }
    r->description[desc_length] = '\0';
    r->value = MIN_VALUE + (double)(rand()) / RAND_MAX * (MAX_VALUE - MIN_VALUE);
}

void* fetch_record_count(void* arg) {
    // Simulate database query to fetch record count
    record_count = rand() % MAX_RECORDS + 1;
    return NULL;
}

int init_records(int compression_level) {
#ifdef ZLIB_ENABLED
    if (compression_level > 0) {
        deflateInit(&compress_stream, compression_level);
    }
#endif

    keys = malloc(record_count * sizeof(*keys));
    timestamps = malloc(record_count * sizeof(*timestamps));
    descriptions = malloc(record_count * sizeof(*descriptions));
    values = malloc(record_count * sizeof(*values));

    if (!keys || !timestamps || !descriptions || !values) {
        perror("Memory allocation failed");
        return -1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, fetch_record_count, NULL);
    pthread_join(thread, NULL);

    records = malloc(record_count * sizeof(*records));
    if (!records) {
        perror("Memory allocation failed");
        free(keys);
        free(timestamps);
        free(descriptions);
        free(values);
#ifdef ZLIB_ENABLED
        deflateEnd(&compress_stream);
#endif
        return -1;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        initialize_record(&records[i]);
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

#ifdef ZLIB_ENABLED
void compress_records() {
    compress_stream.next_in = (Bytef*)records;
    compress_stream.avail_in = record_count * sizeof(record);
    compress_stream.next_out = (Bytef*)malloc(compress_stream.avail_in + 12);
    compress_stream.avail_out = compress_stream.total_out;

    deflate(&compress_stream, Z_FINISH);

    free(records);
    records = (record*)malloc(compress_stream.total_out);
    memcpy(records, compress_stream.next_out, compress_stream.total_out);

    free(compress_stream.next_out);
}
#endif

void decompress_records() {
#ifdef ZLIB_ENABLED
    uncompress((Bytef*)records, &record_count * sizeof(record), compress_stream.next_in, compress_stream.avail_in);
#endif
}

void cleanup() {
    free(keys);
    free(timestamps);
    free(descriptions);
    free(values);
    if (records) {
        #ifdef ZLIB_ENABLED
        decompress_records();
        #endif
        free(records);
    }
#ifdef ZLIB_ENABLED
    deflateEnd(&compress_stream);
#endif
}

int main() {
    srand(time(NULL));
    int compression_level = 9; // Example compression level

    if (init_records(compression_level) == -1) {
        fprintf(stderr, "Failed to initialize records\n");
        return 1;
    }

#ifdef ZLIB_ENABLED
    compress_records();
#endif

    // Simulate using the records...

    cleanup();
    return 0;
}
