#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SEMAPHORES 1000
#define MAX_NAME_LENGTH 50
#define MAX_WORD_LIST_SIZE 200

typedef struct {
    char name[MAX_NAME_LENGTH];
    sem_t semaphore;
    int value;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t semaphore_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void init_semaphore_system() {
    log_file = fopen("semaphore.log", "a");
}

void* create_semaphore(void* arg) {
    char name[51];
    int value = *(int*)arg;

    pthread_mutex_lock(&semaphore_lock);
    if (semaphore_count >= MAX_SEMAPHORES) {
        fprintf(log_file, "Error: Semaphore limit reached\n");
        pthread_mutex_unlock(&semaphore_lock);
        return NULL;
    }
    strncpy(semaphores[semaphore_count].name, name, 50);
    sem_init(&semaphores[semaphore_count].semaphore, 1, value);
    semaphores[semaphore_count].value = value;
    semaphore_count++;
    pthread_mutex_unlock(&semaphore_lock);

    return (void*)&semaphores[semaphore_count-1];
}

int delete_semaphore(char* name) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_destroy(&semaphores[i].semaphore);
            pthread_mutex_lock(&semaphore_lock);
            for (; i < semaphore_count-1; i++) {
                semaphores[i] = semaphores[i+1];
            }
            semaphore_count--;
            pthread_mutex_unlock(&semaphore_lock);
            return 0;
        }
    }

    fprintf(log_file, "Error: Semaphore not found\n");
    return -1;
}

void increment_semaphore(char* name) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_post(&semaphores[i].semaphore);
            semaphores[i].value++;
            return;
        }
    }

    fprintf(log_file, "Error: Semaphore not found\n");
}

void decrement_semaphore(char* name) {
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(semaphores[i].name, name) == 0) {
            if (semaphores[i].value > 0) {
                sem_wait(&semaphores[i].semaphore);
                semaphores[i].value--;
            }
            return;
        }
    }

    fprintf(log_file, "Error: Semaphore not found\n");
}

