import json
import boto3
from botocore.exceptions import ClientError
from functools import lru_cache
from threading import Lock

class ConfigManager:
    def __init__(self, local_config_path, ssm_client=None):
        self.local_config_path = local_config_path
        self.ssm_client = ssm_client or boto3.client('ssm', region_name='us-east-1')
        self.config_cache = {}
        self.lock = Lock()

    @lru_cache(maxsize=100)
    def _load_local_config(self):
        with open(self.local_config_path, 'r') as file:
            return json.load(file)

    def get_config_value(self, key):
        if key in self.config_cache:
            return self.config_cache[key]
        local_config = self._load_local_config()
        remote_config = self._get_remote_config(key)
        config_value = local_config.get(key, remote_config.get(key))
        with self.lock:
            self.config_cache[key] = config_value
        return config_value

    def _get_remote_config(self, key):
        try:
            response = self.ssm_client.get_parameter(Name=key)
            return json.loads(response['Parameter']['Value'])
        except ClientError as e:
            if e.response['Error']['Code'] == 'ParameterNotFound':
                return None
            raise

    def update_local_config(self, key, value):
        with open(self.local_config_path, 'r+') as file:
            config = json.load(file)
            config[key] = value
            file.seek(0)
            json.dump(config, file, indent=4)
            file.truncate()
        self.config_cache.clear()

    def validate_config(self, rules_file):
        with open(rules_file, 'r') as file:
            rules = yaml.safe_load(file)
        for key, value in self.get_all_configs().items():
            rule = next((r for r in rules if r['key'] == key), None)
            if not rule:
                continue
            data_type_check = isinstance(value, eval(rule['data_type']))
            range_check = (rule.get('min', float('-inf')) <= value <= rule.get('max', float('inf')))
            dependency_check = all(self.get_config_value(d) for d in rule.get('dependencies', []))
            if not (data_type_check and range_check and dependency_check):
                raise ValueError(f"Invalid configuration: {key} does not meet validation rules.")
