#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>

EVP_CIPHER_CTX *initialize_aes_cipher(const char *password, int password_len, int iteration_count) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    // Generate a random IV
    unsigned char iv[16];
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive the key using PBKDF2 with SHA-256
    unsigned char key[32];
    if (PKCS5_PBKDF2_HMAC(password, password_len, iv, 16, iteration_count, EVP_sha256(), sizeof(key), key) != 1) {
        fprintf(stderr, "PBKDF2 derivation failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher with AES-256-CBC
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
