import json
from datetime import datetime
from uuid import UUID
from decimal import Decimal
from threading import Lock

class JSONSerializable:
    def to_json(self):
        raise NotImplementedError("Subclasses must implement this method")

    @classmethod
    def from_json(cls, json_str):
        raise NotImplementedError("Subclasses must implement this method")

class FinancialDataModel(JSONSerializable):
    def __init__(self, data):
        self.data = data

    def to_json(self):
        return json.dumps({
            "data": self.data,
            "@type": type(self).__name__
        })

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        if data["@type"] == cls.__name__:
            return cls(data["data"])
        else:
            raise ValueError("Invalid JSON type")

class FinancialDataFactory:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register(cls, cls_name, cls_type):
        with cls._lock:
            if cls_name in cls._registry:
                raise ValueError(f"Class {cls_name} is already registered")
            cls._registry[cls_name] = cls_type

    @classmethod
    def create_instance(cls, json_str):
        data = json.loads(json_str)
        cls_name = data["@type"]
        if cls_name not in cls._registry:
            raise ValueError(f"Class {cls_name} is not registered")
        return cls._registry[cls_name].from_json(json.dumps(data))

# Usage example
FinancialDataFactory.register("FinancialDataModel", FinancialDataModel)
instance = FinancialDataFactory.create_instance('{"@type": "FinancialDataModel", "data": {"price": 100.5, "time": "2023-04-01T12:00:00"}}')
print(instance.data)
