public class WeatherAggregator {

    private Map<String, String> apiTokens = new HashMap<>();
    private Map<String, String> cachedData = new HashMap<>();
    private long cacheExpiryTime;

    public WeatherAggregator(String openWeatherMapToken, String weatherAPIToken, long cacheExpiryTime) {
        this.apiTokens.put("openweathermap", openWeatherMapToken);
        this.apiTokens.put("weatherapi", weatherAPIToken);
        this.cacheExpiryTime = cacheExpiryTime;
    }

    public CompletableFuture<WeatherData> getWeather(String location) {
        return CompletableFuture.supplyAsync(() -> {
            WeatherData cachedWeather = getCachedWeather(location);
            if (cachedWeather != null && isCacheValid(cachedWeather.getTimestamp())) {
                return cachedWeather;
            }
            return fetchWeatherFromAPIs(location).thenCompose(data -> {
                cacheWeatherData(location, data);
                return CompletableFuture.completedFuture(data);
            }).join();
        });
    }

    private WeatherData getCachedWeather(String location) {
        String cachedJson = cachedData.get(location);
        if (cachedJson != null) {
            try {
                return WeatherData.fromJson(cachedJson);
            } catch (Exception e) {
                logger.error("Error parsing cached weather data", e);
            }
        }
        return null;
    }

    private boolean isCacheValid(long timestamp) {
        return System.currentTimeMillis() - timestamp < cacheExpiryTime;
    }

    private CompletableFuture<WeatherData> fetchWeatherFromAPIs(String location) {
        CompletableFuture<WeatherData>[] futures = new CompletableFuture[]{
            fetchWeatherFromOpenWeatherMap(location),
            fetchWeatherFromWeatherAPI(location)
        };

        return CompletableFuture.anyOf(futures).thenApply(data -> data.orElseGet(() -> WeatherData.EMPTY));
    }

    private CompletableFuture<WeatherData> fetchWeatherFromOpenWeatherMap(String location) {
        String token = apiTokens.get("openweathermap");
        return fetchWeatherFromService(location, "http://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=" + token);
    }

    private CompletableFuture<WeatherData> fetchWeatherFromWeatherAPI(String location) {
        String token = apiTokens.get("weatherapi");
        return fetchWeatherFromService(location, "http://api.weatherapi.com/v1/current.json?key=" + token + "&q=" + location);
    }

    private CompletableFuture<WeatherData> fetchWeatherFromService(String location, String url) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                // Simulate network request
                Thread.sleep(500);
                return WeatherData.fromJSON(new URL(url).openStream());
            } catch (Exception e) {
                logger.error("Error fetching weather data from " + url, e);
                return WeatherData.EMPTY;
            }
        });
    }

    private void cacheWeatherData(String location, WeatherData data) {
        try {
            String json = data.toJson();
            cachedData.put(location, json);
        } catch (Exception e) {
            logger.error("Error caching weather data", e);
        }
    }

    // TODO: Add comprehensive logging
    private static final Logger logger = LoggerFactory.getLogger(WeatherAggregator.class);

    // Unit tests to be added
}
