```javascript
async function asyncArrayReduce(arr, initialValue, callback) {
    let accumulator = initialValue;

    for (let i = 0; i < arr.length; i++) {
        try {
            const result = await new Promise((resolve, reject) => {
                setTimeout(() => {
                    try {
                        resolve(callback(accumulator, arr[i]));
                    } catch (error) {
                        reject(error);
                    }
                }, 100); // Simulate asynchronous operation with a delay
            });
            accumulator = result;
        } catch (error) {
            console.error("Error during reduction:", error);
            return Promise.reject(error);
        }
    }

    return accumulator;
}
