import stripe
import paypalrestsdk
from braintree import Configuration, Environment, Transaction

def process_payment(amount, currency, payment_method, gateway_name='stripe'):
    try:
        if gateway_name == 'stripe':
            stripe.api_key = 'your_stripe_secret_key'
            charge = stripe.Charge.create(
                amount=int(amount * 100),
                currency=currency,
                source=payment_method
            )
        elif gateway_name == 'paypal':
            paypalrestsdk.configure({
                "mode": "sandbox", # sandbox or live
                "client_id": "your_paypal_client_id",
                "client_secret": "your_paypal_client_secret"
            })
            payment = paypalrestsdk.Payment({
                "intent": "sale",
                "payer": {
                    "payment_method": "credit_card",
                    "funding_instruments": [{
                        "credit_card": {
                            "number": payment_method,
                            "type": "visa",
                            "expire_month": 12,
                            "expire_year": 2025
                        }
                    }]
                },
                "transactions": [{
                    "amount": {
                        "total": str(amount),
                        "currency": currency
                    }
                }],
                "redirect_urls": {
                    "return_url": "http://localhost:3000/payment/execute",
                    "cancel_url": "http://localhost:3000"
                }
            })
            payment.create()
        elif gateway_name == 'braintree':
            Configuration.configure(Environment.Sandbox, 'your_braintree_merchant_id', 'your_braintree_public_key', 'your_braintree_private_key')
            result = Transaction.sale({
                "amount": str(amount),
                "payment_method_nonce": payment_method,
                "options": {
                    "submit_for_settlement": True
                }
            })
        else:
            raise ValueError("Unsupported payment gateway")

        return charge or payment or result
    except Exception as e:
        print(f"Error processing payment: {e}")
        return None

# Example usage
payment_response = process_payment(10.99, 'USD', 'credit_card_token', gateway_name='stripe')
if payment_response and payment_response.status == 'succeeded':
    print("Payment successful")
else:
    print("Payment failed")
