import json
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from collections import OrderedDict
from functools import lru_cache
from datetime import datetime
import redis
import ssl

class ConfigManager:
    def __init__(self, local_file_path, ssm_service_url, redis_host, max_thread_count=10, cache_max_size=50):
        self.local_file_path = local_file_path
        self.ssm_service_url = ssm_service_url
        self.redis_host = redis_host
        self.max_thread_count = max_thread_count
        self.cache_max_size = cache_max_size
        self.thread_pool = ThreadPoolExecutor(max_workers=self.max_thread_count)
        self.cache = lru_cache(maxsize=self.cache_max_size)(self.compute_hash)
        self.redis_client = redis.Redis(host=self.redis_host, ssl_verify=True)

    def load_config(self):
        try:
            with open(self.local_file_path, 'r') as file:
                config = json.load(file)
                return self.update_with_remote_config(config)
        except FileNotFoundError:
            return self.get_from_ssm_service()

    def update_with_remote_config(self, local_config):
        ssm_config = self.get_from_ssm_service()
        for key, value in local_config.items():
            if key in ssm_config:
                ssm_config[key] = value
        return ssm_config

    def get_from_ssm_service(self):
        try:
            response = requests.get(self.ssm_service_url, verify=True)
            response.raise_for_status()
            return response.json()
        except (requests.RequestException, ValueError) as e:
            print(f"Error fetching config from SSM service: {e}")
            return {}

    def compute_hash(self, input_string):
        if not input_string or len(input_string) > 1024 * 1024:
            raise ValueError("Input string cannot be null and should not exceed 1MB")

        md5_hash = self.md5_cache(input_string)
        sha256_hash = self.sha256_cache(input_string)

        return {
            'md5': md5_hash,
            'sha256': sha256_hash
        }

    @lru_cache(maxsize=100)  # Cache for MD5 computations with a limited size
    def md5_cache(self, input_string):
        import hashlib
        return hashlib.md5(input_string.encode()).hexdigest()

    @lru_cache(maxsize=100)  # Cache for SHA-256 computations with a limited size
    def sha256_cache(self, input_string):
        import hashlib
        return hashlib.sha256(input_string.encode()).hexdigest()

    def get_hash_from_redis(self, hash_type, input_string):
        hash_key = f"{hash_type}:{input_string}"
        return self.redis_client.get(hash_key)

    def set_hash_in_redis(self, hash_type, input_string, hash_value):
        hash_key = f"{hash_type}:{input_string}"
        self.redis_client.setex(hash_key, 3600, hash_value)  # Cache for 1 hour

    def handle_rate_limiting(self):
        # Implement rate limiting logic here
        pass

    def log_error(self, error_message):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        print(f"[{timestamp}] ERROR: {error_message}")

    def run_tests(self):
        # Implement unit tests here
        pass
