from typing import List, Tuple
import time
import random
import requests

class PaymentGateway:
    def process_transaction(self, transaction: dict) -> dict:
        pass

class ThirdPartyPaymentGateway(PaymentGateway):
    def __init__(self, name: str):
        self.name = name

    def process_transaction(self, transaction: dict) -> dict:
        try:
            response = requests.post('https://api.' + self.name + '.com/transaction', json=transaction)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error processing transaction with {self.name}: {e}")
            raise

class DistributedDatabase:
    def store_transaction_token(self, token: str) -> None:
        pass

class TransactionFilter:
    def filter_transactions(self, transactions: List[dict]) -> List[dict]:
        pass

class TransactionAgeFilter(TransactionFilter):
    def __init__(self, max_age: int):
        self.max_age = max_age

    def filter_transactions(self, transactions: List[dict]) -> List[dict]:
        return [t for t in transactions if time.time() - t['timestamp'] <= self.max_age]

class TransactionIPFilter(TransactionFilter):
    def __init__(self, ip_address: str, window_size: int):
        self.ip_address = ip_address
        self.window_size = window_size

    def filter_transactions(self, transactions: List[dict]) -> List[dict]:
        return [t for t in transactions if t['ip_address'] == self.ip_address and len([x for x in transactions if x['timestamp'] >= time.time() - self.window_size and x['ip_address'] == self.ip_address]) <= 5]

class TransactionWeightSumFilter(TransactionFilter):
    def __init__(self, max_weight_sum: float):
        self.max_weight_sum = max_weight_sum

    def filter_transactions(self, transactions: List[dict]) -> List[dict]:
        return [t for t in transactions if sum(t['weights']) <= self.max_weight_sum]

class PaymentProcessor:
    def __init__(self, gateways: List[PaymentGateway], database: DistributedDatabase, filters: List[TransactionFilter]):
        self.gateways = gateways
        self.database = database
        self.filters = filters

    def process_transactions(self, transactions: List[dict]) -> Tuple[float, str]:
        filtered_transactions = self.filter_transactions(transactions)
        max_weight_sum = 0.0
        max_transaction_id = None

        for transaction in filtered_transactions:
            response = self.process_transaction(transaction)
            if response['weight_sum'] > max_weight_sum:
                max_weight_sum = response['weight_sum']
                max_transaction_id = response['id']

            self.database.store_transaction_token(response['token'])

        return (max_weight_sum, max_transaction_id)

    def filter_transactions(self, transactions: List[dict]) -> List[dict]:
        for f in self.filters:
            transactions = f.filter_transactions(transactions)
        return transactions

    def process_transaction(self, transaction: dict) -> dict:
        for i in range(len(self.gateways)):
            try:
                response = self.gateways[i].process_transaction(transaction)
                return response
            except requests.exceptions.RequestException as e:
                print(f"Error processing transaction with gateway {i}: {e}")
                time.sleep(2 ** i)  # Exponential backoff

        raise Exception("Failed to process transaction after multiple attempts")

    def update_metrics(self, success_rates: dict) -> None:
        pass

    def monitor_gateways(self) -> None:
        pass
