<?php
session_start();

function authenticateUser($oauthClient, $stateToken) {
    if (!isset($_SESSION['auth_state']) || $_SESSION['auth_state'] !== $stateToken) {
        throw new Exception("Invalid state token");
    }

    $accessToken = $oauthClient->getAccessToken('authorization_code', [
        'code' => $_GET['code'],
        'redirect_uri' => $oauthClient->getRedirectUri()
    ]);

    $_SESSION['access_token'] = $accessToken;
}

function updateClinicStatus($mysqli, $clinicIDs, $newStatus, $ipAddress) {
    if (!isset($_SESSION['access_token'])) {
        throw new Exception("User not authenticated");
    }

    // Validate clinic IDs
    $activeClinics = getActiveClinicsFromAPI();
    $validClinicIDs = array_intersect($clinicIDs, $activeClinics);
    if (count($validClinicIDs) !== count($clinicIDs)) {
        throw new Exception("Invalid clinic ID(s)");
    }

    // Validate IP address
    if (!validateIPAddress($ipAddress)) {
        throw new Exception("Invalid IP address");
    }

    foreach ($validClinicIDs as $clinicID) {
        $uniqueID = uniqid();
        $lastModified = date('Y-m-d H:i:s');

        $query = "START TRANSACTION;
                    INSERT INTO update_log (unique_id, clinic_id, status, ip_address, last_modified)
                    VALUES (?, ?, ?, ?, ?);
                    UPDATE clinics
                    SET status = ?, last_modified_ip = ?, last_modified_date = ?
                    WHERE id = ? AND access_token = ?;
                    COMMIT;";

        if (!$stmt = $mysqli->prepare($query)) {
            throw new Exception("Database error: " . $mysqli->error);
        }

        $stmt->bind_param("sssssii", $uniqueID, $clinicID, $newStatus, $ipAddress, $lastModified, $newStatus, $ipAddress, $lastModified, $clinicID, $_SESSION['access_token']);
        if (!$stmt->execute()) {
            throw new Exception("Database error: " . $stmt->error);
        }

        // Send notification
        sendNotification($uniqueID, $newStatus);

        // Log update
        logUpdate($uniqueID, $clinicID, $newStatus, $ipAddress);
    }
}

