public:
    ImageConverter(const std::string& inputPath, const std::string& outputPath, const std::string& format)
        : inputPath(inputPath), outputPath(outputPath), format(format) {}

    void setQuality(int quality) {
        this->quality = quality;
    }

    void logToConsole() {
        // Implementation for logging to console
    }

    void logToFile(const std::string& filename) {
        // Implementation for logging to file
    }

    void startBatchConversion(const std::vector<std::string>& inputFiles) {
        std::mutex mtx;
        std::condition_variable cv;
        bool done = false;

        auto worker = [&]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this, &done] { return !inputFiles.empty() || done; });

                if (done && inputFiles.empty()) break;

                std::string inputFile = inputFiles.back();
                inputFiles.pop_back();

                lock.unlock();
                convertImage(inputFile);
            }
        };

        std::thread t(worker);

        // Simulate batch conversion
        for (const auto& file : inputFiles) {
            cv.notify_one();
        }

        done = true;
        cv.notify_all();
        t.join();
    }

private:
    void convertImage(const std::string& inputFile) {
        // Implementation for converting image using third-party library
    }

    std::string inputPath;
    std::string outputPath;
    std::string format;
    int quality;
};

// Example usage in main function
int main() {
    ImageConverter converter("input.jpg", "output.png", "PNG");
    converter.setQuality(85);
    converter.logToConsole();
    converter.startBatchConversion({"image1.jpg", "image2.jpg", "image3.jpg"});

    return 0;
}
