#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define TIMEOUT_SECONDS 5

sem_t sem;

void* convert_image_to_pdf(void* arg) {
  int image_id = *(int*)arg;
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec += TIMEOUT_SECONDS;

  if (sem_timedwait(&sem, &ts) == -1) {
    printf("Timeout: Unable to acquire semaphore for image %d\n", image_id);
    return NULL;
  }

  // Logic to convert image to PDF
  printf("Converting image %d to PDF\n", image_id);

  sem_post(&sem);
  return NULL;
}

int main() {
  int num_images = 10;
  pthread_t threads[num_images];
  int image_ids[num_images];

  sem_init(&sem, 0, 2); // Initialize semaphore with a value of 2

  for (int i = 0; i < num_images; i++) {
    image_ids[i] = i + 1;
    pthread_create(&threads[i], NULL, convert_image_to_pdf, &image_ids[i]);
  }

  for (int i = 0; i < num_images; i++) {
    pthread_join(threads[i], NULL);
  }

  sem_destroy(&sem);

  return 0;
}
