from flask import Flask, request, jsonify
import os
import hashlib
import threading
from queue import Queue
from collections import OrderedDict

app = Flask(__name__)

class Cache(OrderedDict):
    def __init__(self, maxsize):
        self.maxsize = maxsize

    def __setitem__(self, key, value):
        if len(self) >= self.maxsize:
            self.popitem(last=False)
        super().__setitem__(key, value)

class FileProcessor:
    def __init__(self, max_threads=10, cache_size=100):
        self.max_threads = max_threads
        self.cache = Cache(cache_size)
        self.queue = Queue()
        self.threads = [threading.Thread(target=self.worker) for _ in range(max_threads)]
        for thread in self.threads:
            thread.start()

    def worker(self):
        while True:
            file_path, callback = self.queue.get()
            try:
                md5_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
                sha256_hash = hashlib.sha256(open(file_path, 'rb').read()).hexdigest()
                if file_path not in self.cache:
                    self.cache[file_path] = (md5_hash, sha256_hash)
                callback(md5_hash, sha256_hash)
            except Exception as e:
                print(f"Error processing file: {e}")
            finally:
                self.queue.task_done()

    def update_metadata(self, file_path):
        # Placeholder for metadata update logic
        pass

    def calculate_and_compare_hashes(self, file_path, expected_md5, expected_sha256):
        if len(file_path) > 1000:
            return jsonify({"error": "File path exceeds 1000 characters"}), 400

        if not os.path.isfile(file_path):
            return jsonify({"error": "Invalid file path"}), 400

        def callback(md5_hash, sha256_hash):
            if md5_hash == expected_md5 and sha256_hash == expected_sha256:
                print(f"File {file_path} hashes match.")
            else:
                print(f"File {file_path} hashes do not match.")

        self.queue.put((file_path, callback))
        return jsonify({"message": "Hash calculation initiated"}), 202

@app.route('/update_metadata', methods=['PUT'])
def update_file_metadata():
    file_path = request.form.get('file_path')
    metadata = request.form.get('metadata')
    FileProcessor().update_metadata(file_path)
    return jsonify({"message": "Metadata updated successfully"})

@app.route('/calculate_hashes', methods=['POST'])
def calculate_hashes():
    file_path = request.form.get('file_path')
    expected_md5 = request.form.get('expected_md5')
    expected_sha256 = request.form.get('expected_sha256')
    return FileProcessor().calculate_and_compare_hashes(file_path, expected_md5, expected_sha256)

if __name__ == '__main__':
    app.run(debug=True)
