#include <openssl/evp.h>
#include <openssl/rand.h>
#include <json-c/json.h>
#include <stdio.h>
#include <stdlib.h>

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB
} EncryptionMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    EncryptionMode mode;
} CipherState;

CipherState* getEncryptionCipher(EncryptionMode mode, const unsigned char* key, const unsigned char* iv) {
    CipherState* state = malloc(sizeof(CipherState));
    state->mode = mode;

    switch (mode) {
        case ECB:
            state->ctx = EVP_CIPHER_CTX_new();
            if (!state->ctx || !EVP_EncryptInit_ex(state->ctx, EVP_des_ecb(), NULL, key, iv)) {
                fprintf(stderr, "Failed to initialize DES ECB cipher\n");
                free(state);
                return NULL;
            }
            break;
        case EDE:
            state->ctx = EVP_CIPHER_CTX_new();
            if (!state->ctx || !EVP_EncryptInit_ex(state->ctx, EVP_des_ede(), NULL, key, iv)) {
                fprintf(stderr, "Failed to initialize DES EDE cipher\n");
                free(state);
                return NULL;
            }
            break;
        case EDE3:
            state->ctx = EVP_CIPHER_CTX_new();
            if (!state->ctx || !EVP_EncryptInit_ex(state->ctx, EVP_des_ede3(), NULL, key, iv)) {
                fprintf(stderr, "Failed to initialize DES EDE3 cipher\n");
                free(state);
                return NULL;
            }
            break;
        case CFB:
            state->ctx = EVP_CIPHER_CTX_new();
            if (!state->ctx || !EVP_EncryptInit_ex(state->ctx, EVP_des_cfb(), NULL, key, iv)) {
                fprintf(stderr, "Failed to initialize DES CFB cipher\n");
                free(state);
                return NULL;
            }
            break;
        default:
            fprintf(stderr, "Unsupported encryption mode\n");
            free(state);
            return NULL;
    }

    return state;
}

void encryptData(CipherState* state, const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
    int len, ciphertext_len;
    if (!EVP_EncryptUpdate(state->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption failed\n");
        return;
    }
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(state->ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Final encryption failed\n");
        return;
    }
    ciphertext_len += len;

    // Zero out the plaintext
    memset((unsigned char*)plaintext, 0, plaintext_len);
}

void decryptData(CipherState* state, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
    int len, plaintext_len;
    if (!EVP_DecryptUpdate(state->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption failed\n");
        return;
    }
    plaintext_len = len;

    if (!EVP_DecryptFinal_ex(state->ctx, plaintext + len, &len)) {
        fprintf(stderr, "Final decryption failed\n");
        return;
    }
    plaintext_len += len;

    // Zero out the ciphertext
    memset((unsigned char*)ciphertext, 0, ciphertext_len);
}

void freeCipherState(CipherState* state) {
    if (state->ctx) EVP_CIPHER_CTX_free(state->ctx);
    free(state);
}
