/**
 * Copies a specified number of bytes from a list of buffered data chunks.
 * @param {Array<ArrayBuffer>} chunks - The array of buffered data chunks.
 * @param {number} start - The starting byte index for copying.
 * @param {number} length - The number of bytes to copy.
 * @returns {Promise<ArrayBuffer>} A promise that resolves with the copied data in a new buffer.
 */
async function copyBytesFromChunks(chunks, start = 0, length) {
    const totalLength = chunks.reduce((acc, chunk) => acc + chunk.byteLength, 0);

    if (start < 0 || start >= totalLength) {
        throw new Error(`Start index ${start} is out of bounds for the provided data.`);
    }

    if (length == null || length > totalLength - start) {
        throw new Error(`Requested length ${length} exceeds available data or is invalid.`);
    }

    const result = new ArrayBuffer(length);
    const resultView = new Uint8Array(result);
    let copiedBytes = 0;

    for (const chunk of chunks) {
        if (copiedBytes >= start && copiedBytes < start + length) {
            const view = new Uint8Array(chunk);
            const offset = copiedBytes - start;
            resultView.set(view, offset);
        }
        copiedBytes += chunk.byteLength;
        if (copiedBytes >= start + length) break;
    }

    return result;
}

// Example usage:
(async () => {
    try {
        const chunks = [new ArrayBuffer(10), new ArrayBuffer(20), new ArrayBuffer(30)];
        const data = await copyBytesFromChunks(chunks, 5, 15);
        console.log(data); // Output will be a buffer of the copied bytes
    } catch (error) {
        console.error(`Error copying bytes: ${error.message}`);
    }
})();
