```c
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_LOG_LEVEL 3

typedef enum {
    DEBUG = 0,
    INFO = 1,
    WARNING = 2,
    ERROR = 3
} LogLevel;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    // Implementation of the write callback function for CURL
}

int log_to_server(const char *url, int level, const char *message, va_list args) {
    if (level > MAX_LOG_LEVEL || level < 0) {
        fprintf(stderr, "Invalid log level\n");
        return -1;
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return -1;
    }

    char formatted_message[1024];
    vsnprintf(formatted_message, sizeof(formatted_message), message, args);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    CURLcode res;
    int retries = 3;
    while (retries > 0) {
        char payload[1024];
        snprintf(payload, sizeof(payload), "{\"level\": \"%d\", \"message\": \"%s\"}", level, formatted_message);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            break;
        } else {
            fprintf(stderr, "HTTP request failed: %s\n", curl_easy_strerror(res));
            retries--;
        }
    }

    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);

    return 0;
}
