```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <fstream>
#include <chrono>
#include <filesystem>

class ImageConverter {
public:
    ImageConverter(int quality = 90, bool enableLogging = true)
        : quality(quality), enableLogging(enableLogging) {}

    void addConversionTask(const std::string& inputPath, const std::string& outputPath, const std::string& format) {
        tasks.emplace_back(inputPath, outputPath, format);
    }

    void startConversion() {
        if (enableLogging) {
            log("Starting image conversion...");
        }
        auto startTime = std::chrono::high_resolution_clock::now();

        std::vector<std::thread> threads;
        for (auto& task : tasks) {
            threads.emplace_back(&ImageConverter::convertTask, this, std::ref(task));
        }

        for (auto& thread : threads) {
            thread.join();
        }

        auto endTime = std::chrono::high_resolution_clock::now();
        if (enableLogging) {
            log("Conversion completed in " + std::to_string(std::chrono::duration_cast<std::chrono::seconds>(endTime - startTime).count()) + " seconds.");
        }
    }

private:
    struct ConversionTask {
        std::string inputPath;
        std::string outputPath;
        std::string format;
    };

    std::vector<ConversionTask> tasks;
    int quality;
    bool enableLogging;

    void convertTask(const ConversionTask& task) {
        if (enableLogging) {
            log("Converting " + task.inputPath + " to " + task.outputPath + "." + task.format);
        }
        // Simulate image conversion
        std::this_thread::sleep_for(std::chrono::seconds(1));
        if (enableLogging) {
            log("Converted " + task.inputPath + " to " + task.outputPath + "." + task.format);
        }
    }

    void log(const std::string& message) {
        if (!enableLogging) return;
        std::cout << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) << "] " << message << std::endl;
    }
};

int main(int argc, char* argv[]) {
    ImageConverter converter(80);
    converter.addConversionTask("input1.jpg", "output1.png", "png");
    converter.addConversionTask("input2.jpeg", "output2.jpg", "jpg");

    // Parse command-line arguments and configure the converter accordingly

    converter.startConversion();

    return 0;
}
